```c
#include <stdlib.h>

// Define your finite state automaton (FSA) and selector function here
typedef struct FSA {
    int id;
    // other properties...
} FSA;

int matchSelector(char* classOrId, char* selector);

// The recursive function to traverse the DOM tree represented as an FSA
int *traverseFSA(FSA *fsaList, int numStates, int (*matchFunc)(char*, char*), 
                 int lastStateNextPtr, int *numMatched) {
    if (numStates <= 0 || fsaList == NULL) {
        return NULL; // Base case: no more states to traverse
    }

    // Check if the current state matches the selector
    char* classOrId = getClassOrId(fsaList);  // Replace with actual function for retrieving class or ID from FSA
    char* selector = "your-selector";          // Replace with your selector
    int isMatch = matchFunc(classOrId, selector);

    if (isMatch) {
        (*numMatched)++;

        // Dynamically allocate memory for the matched state
        int *matchedState = malloc((*numMatched) * sizeof(int));

        if (!matchedState) return NULL;  // Insufficient memory

        // Store the current state in the matched state list and update 'next' pointer
        matchedState[(*numMatched)-1] = fsaList->id;
        lastStateNextPtr = &(matchedState[(*numMatched)-1]); 
    }

    // Recursively traverse remaining states in the FSA
    int *remainingStates = traverseFSA(&fsaList[1], numStates-1, matchFunc, lastStateNextPtr, numMatched);

    if (isMatch) {
        // Update 'next' pointer of current state to point to the matched state list
        *lastStateNextPtr = remainingStates;
    } else {
        return remainingStates;  // No match in this state, so just return the remaining states
    }

    return matchedState;
}
```
Note: This code assumes you have a function `getClassOrId` that retrieves the class or ID from an FSA. You'll need to implement your own version of `matchSelector` and replace "your-selector" with the actual selector you want to match. Also, this implementation allocates memory for each matched state individually, which might not be efficient if there are many matches. A more optimal solution would require a more complex data structure that can grow dynamically as needed.

