#include <openssl/ssl.h>
#include <stdlib.h>
#include <string.h>

typedef struct State {
  char *name;
  struct State *next;
} State;

typedef struct CipherObject {
  SSL *ssl;
  State *stateList;
} CipherObject;

CipherObject* performOperation(char *option, const char *automaton) {
    if (strcmp(option, "AES") == 0) {
        SSL_CTX *ctx = SSL_CTX_new(TLS_method());
        if (!ctx) return NULL;

        CipherObject *obj = malloc(sizeof(CipherObject));
        if (obj == NULL) return NULL;

        obj->ssl = SSL_new(ctx);
        if (obj->ssl == NULL) {
            free(obj);
            return NULL;
        }

        // Find list of states in automaton and create stateList
        State *currentState, *nextState = NULL;
        for (int i = 0; automaton[i] != '\0'; i++) {
            currentState = malloc(sizeof(State));
            if (currentState == NULL) return NULL;

            // populate state with data from automaton
            char *name = malloc(2); 
            name[0] = automaton[i];
            name[1] = '\0';
            currentState->name = name;

            if (obj->stateList == NULL) {
                obj->stateList = currentState;
            } else {
                nextState->next = currentState;
            }

            nextState = currentState;
        }

        return obj;
    }

    // Add more options and operations here...

    return NULL;  // Return NULL for unsupported options
}
