#include <iostream>
#include <fstream>
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"

struct Node {
    int key;
    std::string value;
};

// Helper function to resize the array dynamically
Node* resizeArray(Node *nodes, size_t &size) {
    size_t newSize = size + 10; // Increase by 10 each time
    Node *newNodes = new Node[newSize];

    for (size_t i = 0; i < size; ++i) {
        newNodes[i] = nodes[i];
    }
    delete[] nodes;
    size = newSize;

    return newNodes;
}

// Function to initialize and manage the dynamic array of Nodes.
Node* initArrayFromFile(const std::string &filename) {
    const int threshold = 1000; // Adjust as needed
    Node *nodes = new Node[threshold];
    size_t size = threshold, index = 0;

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file." << std::endl;
        return nullptr;
    }

    int key;
    std::string value;
    while (file >> key && getline(file, value)) {
        if (index >= size) {
            nodes = resizeArray(nodes, size);
        }

        nodes[index].key = key;
        nodes[index].value = value;
        ++index;
    }

    file.close();
    return nodes;
}

// Function to serialize the Node array into a JSON string using RapidJSON
std::string serializeToJson(Node *nodes, size_t size) {
    rapidjson::Document doc;
    doc.SetArray();

    for (size_t i = 0; i < size; ++i) {
        rapidjson::Value nodeVal(rapidjson::kObjectType);
        nodeVal.AddMember("key", nodes[i].key, doc.GetAllocator());
        nodeVal.AddMember("value", rapidjson::StringRef(nodes[i].value.c_str()), doc.GetAllocator());

        doc.PushBack(nodeVal, doc.GetAllocator());
    }

    rapidjson::StringBuffer buffer;
    rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
    doc.Accept(writer);

    return buffer.GetString();
}
```
Note: This code is assuming that the file format is a space-separated list of integer key and string value pairs, each on a new line. It's also assuming that the Node array won't grow beyond `size_t` limit. Please make sure to add error checking for such cases according to your specific use case.

