```csharp
using System;
using UnityEngine;

public static class CustomRandomGenerator
{
    private static System.Random rand = new System.Random();

    public static void Seed(int seed)
    {
        rand = new System.Random(seed);
    }

    public static float CustomRange(float min, float max, bool isExclusive, bool seeded, int? seed)
    {
        if (seeded && seed != null) Seed((int)seed);

        double range = rand.NextDouble() * (max - min) + min;
        return (float)(isExclusive ? Math.NextDouble(range) : range);
    }

    public static int CustomRange(int min, int max, bool isExclusive, bool seeded, int? seed)
    {
        if (seeded && seed != null) Seed((int)seed);

        double range = rand.NextDouble() * (max - min) + min;
        return (isExclusive ? Math.CeilingToInt(range) : Math.FloorToInt(range));
    }

    public static override string ToString()
    {
        return $"CustomRandomGenerator: Seeded with {rand.GetHashCode()}";
    }
}
```
