```python
import os
import importlib
import inspect
import json
from typing import List, Dict, Any, Type

def load_protocol_config(filepath: str) -> Dict[str, Any]:
    with open(filepath, "r") as f:
        return json.load(f)

class ProtocolLoader():

    def __init__(self):
        self._cache = {}  # cache for loaded protocols

    def check_protocol(self, protocol: Dict[str, Any]) -> bool:
        try:
            mod = importlib.import_module(protocol["implementation"])
        except ModuleNotFoundError as e:
            print(f"Module {e} not found")
            return False

        if hasattr(mod, protocol["class"]):
            cls = getattr(mod, protocol["class"])
            if inspect.isclass(cls) and issubclass(cls, ProtocolImplementationBaseClass):
                self._cache[protocol["name"]] = cls
                return True
        return False

    def load_protocols(self, path: str, configfile: str) -> Dict[str, Dict[str, Any]]:

        protocols = load_protocol_config(os.path.join(path, configfile))
        results = {}  # dictionary to store protocol details

        for protocol in protocols:
            try:
                if self.check_protocol(protocol):
                    cls = self._cache[protocol["name"]]

                    results[protocol["name"]] = {
                        "name": protocol["name"],
                        "implementation_class": cls,
                        "description": protocol.get("description", ""),
                        "supported_features": protocol.get("supported_features", [])
                    }
            except Exception as e:
                print(f"Error loading {protocol['name']}: {e}")

        return results
```
You should replace `ProtocolImplementationBaseClass` with the actual base class or interface that all your protocol classes are supposed to implement. 

