Here is a simplified example in C that implements DNS resolution using the standard library functions:

```c
#include <stdio.h>
#include <netdb.h> 

void getip(const char* hostname) { 
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo(hostname, NULL, &hints, &res);

    if (errcode != 0) {
        perror("getaddrinfo");
        return;
    }

    printf("\nFor host %s, IP addresses are: \n\n", hostname); 
    while(res) { 
        inet_ntop(res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *)res->ai_addr)->sin_addr;
                break;

            case AF_INET6:
                ptr = &((struct sockaddr_in6 *)res->ai_addr)->sin6_addr;
                char ip6str[128];
                inet_ntop(res->ai_family, ptr, ip6str, sizeof ip6str);
                printf("%s: IPv%d with address %s\n", res->ai_canonname, res->ai_family == PF_INET ? 4 : 6, addrstr);
        } 

        res = res->ai_next; 
    } 
} 
```

