public class GameCharacter {
    private static final long ATTACK_COOLDOWN = 9000L; // 9 seconds in milliseconds
    private static final int MAX_CONCURRENT_REQUESTS = 10; // Limit of concurrent requests

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Transient
    private Random randomAttackGenerator = new Random();
    @Transient
    private AtomicBoolean canUseSpecialUltimate = new AtomicBoolean(true); // Thread safe Boolean

    @Column
    private Date lastAttackTime;

    @Column
    private Channel channel; 

    public void connectToServer() {
        // Establish a connection to the server using Java NIO or Netty library.
    }

    synchronized public boolean canUseAttack() {
        long now = System.currentTimeMillis();
        return (now - lastAttackTime.getTime()) > ATTACK_COOLDOWN; 
    }

    public void useAttack() throws InterruptedException {
        if(canUseSpecialUltimate.compareAndSet(true, false)) {
            // Start a new thread to perform the attack
            Thread attackThread = new Thread(() -> {
                try{
                    selectRandomAttack();
                    canUseSpecialUltimate.set(true); // Re-enable special attack after cooldown period
                }catch (Exception e){
                    System.err.println("Error in performing the attack: " + e);
                }
            });
            attackThread.start();
        } else {
            System.out.println("Attack not ready yet.");
        }
    }

    synchronized private void selectRandomAttack() throws InterruptedException {
        int attackSelected = randomAttackGenerator.nextInt(2); // Choose between 0 and 1

        if (attackSelected == 0) {
            performFirstTypeOfAttack();
        } else if (attackSelected == 1) {
            performSecondTypeOfAttack();
        }
        lastAttackTime = new Date(); // Record the time of the attack
    }

    private void performFirstTypeOfAttack() throws InterruptedException {
        System.out.println("Performing first type of attack.");
    }

    private void performSecondTypeOfAttack() throws InterruptedException {
        System.out.println("Performing second type of attack.");
    }

    public double getCooldownRemainingTime() {
        long now = System.currentTimeMillis();
        return ((lastAttackTime.getTime() + ATTACK_COOLDOWN - now) / 1000D);
    }
