Here is the Java code for the class `FileChunkProcessor` that incorporates all the features and constraints you specified:

```java
import java.io.*;
import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

interface LoggingCallback {
    void logMessage(String message);
}

public class FileChunkProcessor {

    private final ReentrantLock lock = new ReentrantLock();
    private final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private LoggingCallback loggingCallback;

    public void readProcessWriteFile(String filePath, int chunkSize, int bufferSize, boolean useParallelProcessing) {
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("File path cannot be null or empty.");
        }

        if (chunkSize <= 0 || bufferSize <= 0) {
            throw new IllegalArgumentException("Chunk size and buffer size must be greater than 0.");
        }

        try {
            File file = new File(filePath);
            long length = file.length();

            if (!file.exists() || !file.isFile()) {
                throw new FileNotFoundException("The specified path does not exist or is not a file.");
            }

            try (RandomAccessFile raf = new RandomAccessFile(file, "rw")) {

                long position = 0;
                while (position < length) {
                    byte[] chunkData = readChunkFromFile(raf, Math.min((int)chunkSize, (int)(length - position)), bufferSize);

                    if (useParallelProcessing) {
                        executorService.execute(() -> processAndWriteChunk(raf, position, chunkData));
                    } else {
                        processAndWriteChunk(raf, position, chunkData);
                    }

                    position += chunkSize;
                }

                if (useParallelProcessing) {
                    executorService.shutdown();
                    executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
                }
            } 
        } catch (IOException | InterruptedException e) {
            logErrorMessage("An error occurred while processing the file: " + e.getMessage());
        }
    }

    private byte[] readChunkFromFile(RandomAccessFile raf, int chunkSize, int bufferSize) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(bufferSize);
        raf.getChannel().read(buffer);

        return Arrays.copyOfRange(buffer.array(), 0, chunkSize);
    }

    private void processAndWriteChunk(RandomAccessFile raf, long position, byte[] data) {
        try {
            lock.lock();

            // Process the chunk
            byte[] processedData = processChunk(data);

            // Write back to file
            raf.seek(position);
            raf.write(processedData);

            logMessage("Processed and wrote a chunk at position: " + position);
        } catch (IOException e) {
            logErrorMessage("An error occurred while processing and writing the chunk: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

    private byte[] processChunk(byte[] data) {
        // Replace this with your actual processing logic
        return data;
    }

    public void setLoggingCallback(LoggingCallback callback) {
        this.loggingCallback = callback;
    }

    private void logMessage(String message) {
        if (loggingCallback != null) {
            loggingCallback.logMessage(message);
        } else {
            System.out.println(message);
        }
    }

    private void logErrorMessage(String errorMessage) {
        if (loggingCallback != null) {
            loggingCallback.logMessage("ERROR: " + errorMessage);
        } else {
            System.err.println("ERROR: " + errorMessage);
        }
    }
}
```
This class uses a `ReentrantLock` for thread safety during file operations, and an `ExecutorService` to manage parallel processing. The `readProcessWriteFile` method reads a chunk of data from the file, processes it, and writes it back to the same position in the file. If `useParallelProcessing` is true, the processing and writing are done concurrently using multiple threads managed by the executor service.

