using System;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using NUnit.Framework;

public class CipherService 
{
    private readonly string _tokenUrl;

    public CipherService(string tokenUrl)
    {
        this._tokenUrl = tokenUrl;
    }

    public async Task<byte[]> DecryptMessageAsync(byte[] ciphertext, byte[] key, byte[] iv) 
    {
        if (ciphertext == null || ciphertext.Length <= 0) 
            throw new ArgumentNullException("Ciphertext cannot be empty.");

        if (key == null || key.Length != 32) 
            throw new ArgumentOutOfRangeException("Key must be a byte array of exactly 32 bytes for AES-256 encryption/decryption.");

        if (iv == null || iv.Length != 16) 
            throw new ArgumentOutOfRangeException("IV must be a byte array of exactly 16 bytes for CBC mode.");

        string token = await RetrieveTokenAsync();

        using var aesAlg = NewRijndaelManaged(key, iv);

        ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
        using var msDecrypt = new MemoryStream(ciphertext);
        using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
        using var srDecrypt = new StreamReader(csDecrypt);

        return Encoding.UTF8.GetBytes(srDecrypt.ReadToEnd());
    }

    private async Task<string> RetrieveTokenAsync() 
    {
        using HttpClient client = new();
        var response = await client.GetStringAsync(_tokenUrl);

        if (response == null)
            throw new Exception("Failed to retrieve a token from the authentication service.");

        return response;
    }

    private static RijndaelManaged NewRijndaelManaged(byte[] key, byte[] iv) 
    {
        var rijAlg = new RijndaelManaged();
        rijAlg.Key = key;
        rijAlg.IV = iv;

        return rijAlg;
    }
}
