```cpp
#include <forward_list>
#include <string>
#include <iostream>

void insertAfterString(std::forward_list<std::string>& fwdList, const std::string& targetStr, const std::string& toInsert, size_t times = 1) {
    bool found = false;
    auto prevIt = fwdList.before_begin();
    for (auto it = fwdList.begin(); it != fwdList.end(); ++it) {
        if (*it == targetStr) {
            found = true;
            // Insert the second string argument after each occurrence of the first string argument 'times' times
            for(size_t i = 0; i < times; ++i) { 
                it = fwdList.insert_after(it, toInsert);
                ++it;
            }
        }
        prevIt = it; // Keep track of the previous iterator to insert at the end if necessary
    }

    if(!found) {
        // If first string argument is not found in the list, insert second string argument at the end.
        fwdList.insert_after(prevIt, toInsert); 
    }
}
```
