```javascript
class ScriptManager {
  constructor() {
    this.scriptCache = new Map();
    this.loadingSpinner = document.querySelector('#loading-spinner');
  }

  async fetchScripts(scripts) {
    const promises = scripts.map(({ url }) => {
      if (this.scriptCache.has(url)) return Promise.resolve(this.scriptCache.get(url));

      this.loadingSpinner.style.display = 'block';
      const response = fetch(url)
        .then((res) => res.text())
        .catch((err) => { console.error('Error fetching script:', err); });

      this.scriptCache.set(url, response);
      return response;
    });

    const results = await Promise.allSettled(promises);
    this.loadingSpinner.style.display = 'none';

    return scripts.map(({ url }, index) => {
      if (results[index].status === 'fulfilled') {
        return { code: results[index].value, type: 'text/javascript' };
      } else {
        console.error('Failed to fetch script:', results[index].reason);
        return {};
      }
    });
  }

  renderScripts(scripts) {
    const container = document.querySelector('#footer');
    scripts.forEach((script, index) => {
      if (script.code && script.type) {
        const tag = document.createElement('script');
        tag.textContent = script.code;
        tag.setAttribute('type', script.type);

        // remove old or unused scripts
        Array.from(container.children).forEach((child, childIndex) => {
          if (childIndex !== index) container.removeChild(child);
        });

        container.appendChild(tag);
      } else {
        console.error('Missing script properties:', script);
      }
    });
  }
}
```

