// Cache for already loaded scripts to reduce redundant network requests
const loadedScripts = new Map();

async function loadExternalScript(script) {
    if (!script || !script.code || !script.type) {
        console.error('Invalid script object');
        return;
    }

    // Check if script is already loaded or being loaded
    if (loadedScripts.has(script)) {
        console.info('Script already loaded', script);
        return;
    } else {
        loadedScripts.set(script, 'loading');
    }

    try {
        // Here you can perform any API call to fetch the actual script 
        const mockResponse = await new Promise((resolve) => setTimeout(() => resolve({ code: script.code, type: script.type }), 2000));

        loadedScripts.set(script, 'loaded'); // Update cache
        return mockResponse;
    } catch (error) {
        console.error('Error loading script', error);
        loadedScripts.delete(script); // Remove from cache on error
    }
}

async function renderFooterWithScripts(scripts) {
    const footer = document.querySelector('#footer');

    scripts.forEach((script, index) => {
        loadExternalScript(script).then(response => {
            if (response && response.code) {
                const scriptTag = document.createElement('script');
                scriptTag.key = `script-${index}`; // Add unique key for each script tag
                scriptTag.type = response.type;
                scriptTag.innerHTML = response.code;

                footer.appendChild(scriptTag);  // Append the new script to the footer
            } else {
                console.error('Error rendering script', script);
            }
        });
    });
}
