```csharp
using Azure;
using Azure.Storage.Blobs;
using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;

[ApiController]
[Route("api/[controller]")]
public class ContentController : ControllerBase
{
    private readonly BlobServiceClient _blobServiceClient;
    private readonly IMemoryCache _cache;

    public ContentController(BlobServiceClient blobServiceClient, IMemoryCache memoryCache)
    {
        _blobServiceClient = blobServiceClient;
        _cache = memoryCache;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateContentAsync([FromBody]UpdateRequest request)
    {
        if (!ModelState.IsValid) return BadRequest(ModelState);

        var cacheKey = $"{request.PageSectionId}_{request.ElementId}";
        BlobContainerClient container = _blobServiceClient.GetBlobContainerClient("your-container");
        PageBlockBlob blob;

        try
        {
            if (!_cache.TryGetValue(cacheKey, out blob))
            {
                blob = container.GetBlobClient($"{request.PageSectionId}/{request.ElementId}") as PageBlockBlob;
                _cache.Set(cacheKey, blob);
            }

            await blob.UploadHtmlAsync(request.Content);
        }
        catch (RequestFailedException e) when (e.Status == 404)
        {
            return NotFound();
        }
        catch (RequestFailedException)
        {
            return StatusCode(503, "Unable to communicate with storage service.");
        }
        catch (Exception)
        {
            return BadRequest();
        }

        return NoContent();
    }
}
```
