Here's a basic implementation of `DynamicRandomNumberGenerator` in C#:

```csharp
using System;
using System.Threading;
using System.Collections.Generic;

public enum RangeType { Closed, Open, HalfOpen }

public delegate bool ConfigUpdateCallback(Dictionary<string, object> config);

public class DynamicRandomNumberGenerator
{
    private Random _random;
    private ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();
    private Dictionary<string, object> _configCache = new Dictionary<string, object>();

    public DynamicRandomNumberGenerator(int seed)
    {
        _random = new Random(seed);
    }

    public int GenerateCustomRandomInteger(RangeType type, int min, int max, bool isSeeded)
    {
        if (min > max) throw new ArgumentException("Min value can't be greater than Max");

        _lock.EnterWriteLock();
        try 
        {
            switch(type)
            {
                case RangeType.Closed:
                    return isSeeded ? _random.Next(min, max + 1) : new Random().Next(min, max + 1);

                // Similar logic for other range types can be implemented here.

                default: 
                    throw new NotImplementedException("This type of range is not yet supported.");
            }
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public double GenerateCustomRandomDouble(RangeType type, double min, double max, bool isSeeded)
    {
        if (min > max) throw new ArgumentException("Min value can't be greater than Max");

        _lock.EnterWriteLock();
        try 
        {
            switch(type)
            {
                case RangeType.Closed:
                    return isSeeded ? (max - min) * _random.NextDouble() + min : (max - min) * new Random().NextDouble() + min;

                // Similar logic for other range types can be implemented here.

                default: 
                    throw new NotImplementedException("This type of range is not yet supported.");
            }
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public bool UpdateConfiguration(Dictionary<string, object> config)
    {
        ConfigUpdateCallback callback;

        _lock.EnterUpgradeableReadLock();
        try 
        {
            if (_configCache != config)
            {
                _lock.EnterWriteLock();
                try 
                {
                    // Update the configuration and return true for success.
                    _configCache = config;
                    return true;
                }
                finally
                {
                    _lock.ExitWriteLock();
                }
            }
        }
        finally
        {
            _lock.ExitUpgradeableReadLock();
        }

        return false; // Return false for failure if there are no new changes in the configuration.
    }
}
```
