Here is an implementation of your request using C++11 features. In this example I will use `std::chrono` for timing and concurrent execution management, `std::mutex` for thread safety and `std::random_device` for random number generation:

```cpp
#include <iostream>
#include <thread>
#include <chrono>
#include <mutex>
#include <random>

// Global Variables
const int ATTACK_1_COOLDOWN = 9; // in seconds
const int ATTACK_2_COOLDOWN = 15; // in seconds
std::chrono::time_point<std::chrono::system_clock> lastAttackTime;
std::mutex mtx;

void useAttack() {
    std::lock_guard<std::mutex> lock(mtx);

    auto currentTime = std::chrono::system_clock::now();
    auto elapsedSeconds = std::chrono::duration_cast<std::chrono::seconds>(currentTime-lastAttackTime).count();

    int attackNum;
    if (elapsedSeconds >= ATTACK_1_COOLDOWN) { // Use Attack 1
        lastAttackTime = currentTime;
        attackNum = 1;
    } else if (elapsedSeconds >= ATTACK_2_COOLDOWN){ // Use Attack 2
        lastAttackTime = currentTime;
        attackNum = 2;
    } else { // Cooldown period not over
        std::cout << "Cooldown period not over. Please try again later." << std::endl;
        return;
    }

    std::random_device rd;  //Will be used to obtain a seed for the random number engine
    std::mt19937 gen(rd()); //Standard mersenne_twister_engine seeded with rd()
    std::uniform_real_distribution<> dis(-0.5, 0.5);

    try {
        double networkLatency = dis(gen); // Randomly generate a latency between -0.5 and 0.5 seconds

        if (networkLatency < 0) {
            throw std::runtime_error("Network Error: Negative Latency Detected!");
        } else {
            // Simulate network latency by sleeping thread
            std::this_thread::sleep_for(std::chrono::duration<double>(networkLatency)); 

            std::cout << "Attack " << attackNum << " used." << std::endl;
        }
    } catch (const std::runtime_error& e) { // Catch and print any exception during execution
        std::cerr << "Exception: " << e.what() << '\n';
    }
}
```
This function works as described by generating a random latency between -0.5 and 0.5 seconds, simulating network delay. The cooldown period is also taken into account before selecting an attack to be used. If there's an error with the latency or if the cooldown period hasn't elapsed, appropriate messages are printed.

```rust
use std::env;
use std::fs::{self, DirEntry};
use std::path::PathBuf;
use std::sync::Mutex;
use std::thread;
use std::time::Duration;
use chrono::prelude::*;
use log::{info, warn, error};
use env_logger;
use failure::Error;

// Struct for handling environment variables and directories
pub struct EnvManager {
    mutex: Mutex<String>, // to handle concurrency
}

impl EnvManager {
    pub fn new(var: &str) -> Self {
        let var = env::var("HOME").unwrap_or("/".into());
        EnvManager {
            mutex: Mutex::new(var),
        }
    }

    pub fn set_env(&self, dir: String) {
        *self.mutex.lock().unwrap() = dir;
    }
}

pub fn create_dir_with_timestamp(name: &str, retries: i32, delay: u64) -> Result<String, Error> {
    let mut path = PathBuf::from(env::current_dir()?);
    path.push("test");

    for _ in 0..retries {
        match fs::create_dir(&path) {
            Ok(_) => return Ok(path),
            Err(e) => {
                warn_log(&format_error("Directory creation failed", e));
                thread::sleep(Duration::from_secs(delay))
            }
        };
    }

    let timestamp = Utc::now().timestamp();
    path.set_file_name(format_str(&format_str(&name, &timestamp)));
    match fs::create_dir(&path) {
        Ok(_) => return Ok(path),
        Err(e) => error_log(&format_error("Directory creation failed after all retries", e))
    };
}

fn format_str(name: &str, timestamp: &i64) -> String {
    format_str(&name, &timestamp.to_string())
}

fn format_error(msg: &str, e: std::io::Error) -> String {
    format_str(&msg, &e.to_string())
}

pub fn warn_log(s: &str) {
    warn_log(&format_str("Warning: ", s))
}

fn error_log(s: &str) {
    error_log(&format_str("Error: ", s));
}

// Function to validate directory name and create a new one if needed
pub fn validate_and_create(name: &str, parent_dir: Option<&PathBuf>) -> Result<(), Error> {
    let env = EnvManager::new(&format_str("DIRECTORY", name));
    let current_path = PathBuf::from(env::current_dir()?);

    if parent_dir.is_some() {
        let path = parent_dir.unwrap();
        create_dir_with_timestamp(&name, 3, 5)?;
        env.set_env(path);
    } else {
        create_dir_with_timestamp(&name, 3, 5)?;
        env.set_env(current_path)
    }

    Ok(())
}
```
