```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using Microsoft.AspNetCore.DataProtection;

public class FileEncryptionService
{
    private readonly IDataProtector _dataProtector;

    public FileEncryptionService(IDataProtectionProvider dataProtectionProvider)
    {
        _dataProtector = dataProtectionProvider.CreateProtector("FileEncryption");
    }

    private const int KeySize = 256; // 128, 192 or 256 bits
    private const int BlockBitSize = 128; // Can be 128, 192, or 256 (and must match at the other end)
    private const int MacBitSize = 128; // Can be 0 - no integrity check, and requires padding scheme to support full block bit size

    public byte[] EncryptFile(string inputFileName, string outputFileName, byte[] key, byte[] salt)
    {
        using var cipher = CreateCipher(key, salt);
        using FileStream inputStream = new FileStream(inputFileName, FileMode.Open),
            outputStream = new FileStream(outputFileName, FileMode.Create);

        var iv = cipher.IV; // Must be available for decryption
        var tag = EncryptData(cipher, inputStream, outputStream);
        return CombineIvAndTag(iv, tag); // Return combined nonce and tag to allow integrity check later
    }

    public void DecryptFile(string inputFileName, string outputFileName, byte[] key, byte[] combined) 
        => DecryptFile(inputFileName, outputFileName, key, SplitIvAndTag(combined));

    private void DecryptFile(string inputFileName, string outputFileName, byte[] key, (byte[], byte[]) split)
    {
        var (iv, tag) = split;
        using var cipher = CreateCipherForDecryption(key, iv);
        using FileStream inputStream = new FileStream(inputFileName, FileMode.Open), 
            outputStream = new FileStream(outputFileName, FileMode.Create);

        DecryptDataAndVerify(cipher, tag, inputStream, outputStream); // Throws if fails to verify
    }

    private AesGcm CreateCipher(byte[] key, byte[] salt) 
        => new AesGcm(KeyDerivation.Pbkdf2(key, salt, KeyDerivationPrf.HMACSHA256, 10000, KeySize / 8));

    private static (byte[], byte[]) SplitIvAndTag(byte[] combined) 
        => (combined.AsSpan(0, BlockBitSize / 8).ToArray(), combined.AsSpan((BlockBitSize + 7) / 8, MacBitSize / 8).ToArray());

    private static byte[] CombineIvAndTag(byte[] iv, byte[] tag)
        => new byte[iv.Length + tag.Length].JoinArrays(iv, tag);
}
```
