#include <mutex>
#include <vector>
#include <functional>
#include <unordered_map>
#include <stdexcept>

typedef std::function<void(int)> SeedCallback;

struct Octree {
    float featureSize;
    int numLeafNodes, dataCapacity;
};

class AdvancedOctreeInitializer {
public:
    void InitializeOctree(float featureSize, int numLeafNodes, 
                          int dataCapacity, bool seeded = false, 
                          int* seed = nullptr, SeedCallback callback = nullptr) {
        if (numLeafNodes <= 0 || dataCapacity < 0) {
            throw std::invalid_argument("Invalid arguments for initialization");
        }

        // Apply customization and seeding logic
        if (callback != nullptr && seed != nullptr) {
            std::lock_guard<std::mutex> lock(m); 
            callback(*seed);
        }

        // Check cache first
        OctreeKey key = GetOctreeKey(featureSize, numLeafNodes, dataCapacity);
        if (cache.count(key) > 0) {
            return;
        }

        Octree* octree = new Octree();
        octree->featureSize = featureSize;
        octree->numLeafNodes = numLeafNodes;
        octree->dataCapacity = dataCapacity;

        // Update cache with new object
        cache[key] = octree;
    }

private:
    typedef std::tuple<float, int, int> OctreeKey;
    std::mutex m;
    std::unordered_map<OctreeKey, Octree*> cache;

    // Helper function to create Octree Key from initialization parameters
    OctreeKey GetOctreeKey(float featureSize, int numLeafNodes, int dataCapacity) {
        return std::make_tuple(featureSize, numLeafNodes, dataCapacity);
    }
};
