```C
#include <stdio.h>
#include <string.h>
#include <jansson.h>
#include <curl/curl.h>

typedef struct {
    CURL *curl;
    bool disableSslVerify;
} RequestBuilder;

bool verifyToken(const char* jsonStr) {
    json_error_t error;
    json_t *root = json_loads(jsonStr, 0, &error);

    if(!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return false;
    }

    json_t *accessToken = json_object_get(root, "access_token");
    json_t *expiresIn = json_object_get(root, "expires_in");
    json_t *tokenType = json_object_get(root, "token_type");

    if(!json_is_string(accessToken) || !json_is_integer(expiresIn) 
       || !json_is_string(tokenType)) {
        fprintf(stderr, "Invalid format for fields\n");
        json_decref(root);
        return false;
    }

