    if(!json_is_string(refreshToken)) {
        fprintf(stderr, "Invalid format for refresh token\n");
        json_decref(root);
        return false;
    }

    // If all checks pass, proceed to create RequestBuilder.
    RequestBuilder builder = {curl_easy_init(), true};
    curl_easy_setopt(builder.curl, CURLOPT_URL, "https://example.com");
    if (builder.disableSslVerify) {
        /* Skip SSL certificate verification */ 
        curl_easy_setopt(builder.curl, CURLOPT_SSL_VERIFYPEER, 0L);
        curl_easy_setopt(builder.curl, CURLOPT_SSL_VERIFYHOST, 0L);
    }

    json_decref(root);
    return true;
}
```
