Below is a simplified version of such function using C# .NET 5.0 and System.Security.Cryptography namespace to encrypt/decrypt data with Triple DES and storing/retrieving key/IV from a configuration file. It assumes that all logging errors, multi-threading issues are handled at the higher level where this method is being used:

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;

public class DecryptionService 
{
    private readonly string _key;
    private readonly string _iv;
    private readonly ILogger<DecryptionService> _logger;

    public DecryptionService(IConfiguration config, ILogger<DecryptionService> logger) 
    {
        this._key = config.GetValue<string>("Encryption:Key"); // assuming key is stored in appsettings under Encryption:Key section
        this._iv = config.GetValue<string>("Encryption:IV"); // assuming IV is stored in appsettings under Encryption:IV section
        this._logger = logger; 
    }

    public string Decrypt(string encryptedMessage) 
    {
        try
        {
            using (TripleDES tripleDes = TripleDES.Create())
            {
                byte[] inputBuffer = Convert.FromBase64String(encryptedMessage);
                byte[] outputBuffer = new byte[inputBuffer.Length];

                // decryption
                ICryptoTransform encryptor = CreateDecryptor(tripleDes, this._key, this._iv);
                encryptor.TransformBlock(inputBuffer, 0, inputBuffer.Length, outputBuffer, 0);

                string message = Encoding.UTF8.GetString(outputBuffer).TrimEnd('\0'); // remove padding from end

                // validate here or throw exception if check fails

                return message;
            }
        }
        catch (CryptographicException e) 
        {
            this._logger.LogError("Decryption failed: " + e.Message);
            throw new Exception("Failed to decrypt the message.", e);
        }
        catch (Exception e)
        {
            // handle other types of exceptions
            _logger.LogError(e, "Unexpected error during decryption");
            throw; 
        }
    }

    private static ICryptoTransform CreateDecryptor(SymmetricAlgorithm symmetricAlgorithm, string key, string iv)
    {
        var keyBytes = Encoding.UTF8.GetBytes(key);
        var ivBytes = Encoding.UTF8.GetBytes(iv);

        using (var rfc2898DeriveBytes = new Rfc2898DeriveBytes(keyBytes, ivBytes))
        {
            symmetricAlgorithm.Key = keyBytes;
            symmetricAlgorithm.IV = ivBytes;

            return symmetricAlgorithm.CreateDecryptor();
        }
    }
}
```
