Here's how you could implement this task in C using pthread library for multithreading and libcurl for downloading URL content:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/stat.h>
#include <curl/curl.h>

typedef struct DownloadResult {
    size_t downloadedBytes;
    pthread_t* threadIds;
    int successFlag;
} DownloadResult;

static size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

DownloadResult* downloadURL(char* url, char* outputFilePath, int numThreads) {
    DownloadResult* result = malloc(sizeof(DownloadResult));
    if (result == NULL) {
        return NULL;  // Insufficient memory for the structure.
    }

    result->threadIds = calloc(numThreads, sizeof(pthread_t));
    if (result->threadIds == NULL) {
        free(result);
        return NULL;  // Insufficient memory for the thread pool.
    }

    CURL *curl;
    FILE *fp;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        fp = fopen(outputFilePath,"wb");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            // Network failure. Set the successFlag to 0 and return.
            result->successFlag = 0;
            goto cleanup;
        } else {
            struct stat st;
            stat(outputFilePath, &st);

            // Download was successful. Update the structure fields accordingly.
            result->downloadedBytes = st.st_size;
            result->successFlag = 1;
        }

    cleanup:
        fclose(fp);
        curl_easy_cleanup(curl);
    } else {
        // Couldn't initialize libcurl, set the successFlag to 0 and return.
        result->successFlag = 0;
    }

    return result;
}
```
