Here is a basic implementation using Node.js's built-in module 'require'. This does not handle circular dependencies or logging errors in detail as it would be quite complex to implement without a good understanding of your exact requirements and the specifics of your use case. However, this should give you a starting point for dynamically loading modules:

```javascript
const fs = require('fs');
const EventEmitter = require('events');
const async = require('async');

class ModuleLoader extends EventEmitter {
    constructor() {
        super();
        this.loadedModules = {};
    }

    loadModule(modulePath) {
        if (this.loadedModules[modulePath]) {
            return this.loadedModules[modulePath];
        }

        try {
            const moduleContents = fs.readFileSync(`${__dirname}/${modulePath}`, 'utf8');
            let moduleFn = new Function('exports', 'module', 'require', '__filename', '__dirname', moduleContents);

            let exports = {};
            let requireFn = this.loadModule.bind(this);
            moduleFn.call({}, exports, { exports }, requireFn, __filename, __dirname);

            this.loadedModules[modulePath] = exports;
            return exports;
        } catch (err) {
            console.error(`Error loading module '${modulePath}': ${err}`);
        }
    }

    loadConfig(configFile, concurrency) {
        let config = JSON.parse(fs.readFileSync(configFile, 'utf8'));

        async.eachLimit(config.modules, concurrency || 5, (modulePath, callback) => {
            this.loadModule(modulePath);
            callback();
        }, err => {
            if(err) console.error('Failed to load modules:', err);
            else this.emit('complete');
        });
    }
}

let loader = new ModuleLoader();
loader.on('complete', () => console.log('All modules loaded'));
loader.loadConfig('./config.json');
```
In the above code:
- The `ModuleLoader` class extends EventEmitter to provide an interface for handling loading completion events and errors.
- The `loadModule()` function loads a module file synchronously, executing it within a new Function context to create a closure over exports and require functions. This ensures that each module is executed in its own isolated context.
- Modules are loaded concurrently using async's `eachLimit()` method, which limits the maximum number of modules being loaded at any one time based on the 'concurrency' parameter from your configuration file or a default value of 5 if not specified.
- The external package manager integration would require additional work and is not covered in this basic example. You might use npm packages such as `require` to handle dependency resolution, but it would greatly depend on the specifics of your use case. Please consider that using third-party dependencies can introduce security risks if they are unreliable or have known vulnerabilities.

