```C
#include <stdio.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/err.h>

void handleErrors(void) { /* Error handling not implemented in this simple version */ }

const EVP_CIPHER* getCipher(char *cipherName, char *modeName)
{
    OpenSSL_add_all_algorithms();

    return EVP_get_cipherbyname(cipherName);
}

void doCrypt(FILE *infile, FILE *outfile, int doEncrypt, const EVP_CIPHER *cipher)
{ 
    /* Encryption/decryption buffer */
    unsigned char inbuf[1024], outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
    int inlen, outlen;
    EVP_CIPHER_CTX *ctx;

    /* Create and initialise the context */
    ctx = EVP_CIPHER_CTX_new();

    if(!EVP_CipherInit_ex(ctx, cipher, NULL, NULL, NULL, doEncrypt)) handleErrors();

    for (;;) {
        inlen = fread(inbuf, 1, 1024, infile);
        if (inlen <= 0) break; /* EOF */

        if(!EVP_CipherUpdate(ctx, outbuf, &outlen, inbuf, inlen)) handleErrors();

        fwrite(outbuf, 1, outlen, outfile);
    }

    /* Finalise the encryption/decryption */
    if(!EVP_CipherFinal_ex(ctx, outbuf, &outlen)) handleErrors();

    fwrite(outbuf, 1, outlen, outfile);

    EVP_CIPHER_CTX_free(ctx);
}

void cryptFile(char *inFileName, char *outFileName, int doEncrypt, const EVP_CIPHER *cipher)
{
    FILE *infile = fopen(inFileName, "rb"); 
    if (infile == NULL) handleErrors();

    FILE *outfile = fopen(outFileName, "wb"); 
    if (outfile == NULL) handleErrors();

    doCrypt(infile, outfile, doEncrypt, cipher);

    fclose(infile);
    fclose(outfile);
}
```

