```cpp
#include <forward_list>
#include <algorithm>
#include <string>
#include <mutex>
#include <stdexcept>
#include <iostream>
#include "Database.h"  // Hypothetical Database class for storing the modified list
#include "Logger.h"    // Hypothetical Logger class for logging each insertion operation

class StringList {
public:
    static std::mutex mtx;

    static void insertAfter(std::forward_list<std::string>& flist, const std::string& target, const std::string& replacement, bool caseInsensitive = false) {
        if (target.empty() || replacement.empty()) throw std::invalid_argument("Target and Replacement cannot be empty");

        // Ensure thread safety
        std::lock_guard<std::mutex> lock(mtx);

        auto it = caseInsensitive ? 
            std::find_if(flist.begin(), flist.end(), [&](const std::string & s){ return toLowerCase(s) == toLowerCase(target); }) :
            std::find(flist.begin(), flist.end(), target);

        if (it != flist.end()) {  // If found, insert the replacement string after it
            ++it;
            flist.insert_after(it, replacement);
        } else {  // Otherwise, append the replacement to the end of the list
            flist.push_front(replacement);
        }

        Logger::log("Insertion operation performed");

        Database db;
        db.storeList(flist);
    }

private:
    static std::string toLowerCase(std::string data) {
        std::transform(data.begin(), data.end(), data.begin(), ::tolower);
        return data;
    }
};
```
