```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

double calculate_average(char *line) {
    char *token = strtok(line, " ");
    double sum = 0;
    int count = 0;
    double num1 = 0.0, num2 = 0.0;

    while (token != NULL) {
        if (strtod(token, NULL)) {
            num2 = num1;
            num1 = atof(token);
            count++;
        }

        token = strtok(NULL, " ");
    }

    if (count < 2) {
        printf("Not enough numerical fields in line.\n");
        return 0.0;
    } else {
        return (num1 + num2) / 2.0;
    }
}

void read_file(const char *filename) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Could not open file %s.\n", filename);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        double average = calculate_average(line);
        printf("The average of the last two numerical fields in line is %.2lf.\n", average);
    }

    fclose(file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: ./program <filename>\n");
        return 1;
    }

    read_file(argv[1]);

    return 0;
}
```
