using System.Threading.Tasks;

public class FileTransferService
{
    private readonly IAuthService _authService; // External authentication service
    private readonly ICloudStorageProvider _cloudStorageProvider; // Cloud storage provider

    public FileTransferService(IAuthService authService, ICloudStorageProvider cloudStorageProvider) 
    {
        _authService = authService;
        _cloudStorageProvider = cloudStorageProvider;
    }

    public async Task<UploadResult> UploadFileAsync(string filePath, byte[] encryptionKey, byte[] iv)
    {
        try
        {
            // Authenticate with the external token-based service before accessing upload permissions.
            var authToken = await _authService.Authenticate(); 

            if (authToken == null)
                return new UploadResult(UploadStatus.Failure, "Authentication failed");

            using var fileStream = File.OpenRead(filePath);

            // Encrypt the file before uploading
            byte[] encryptedData;
            using (var aesAlg = Aes.Create())
            {
                aesAlg.Key = encryptionKey;
                aesAlg.IV = iv;

                var encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);
                using (var msEncrypt = new MemoryStream())
                {
                    using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        await fileStream.CopyToAsync(csEncrypt); // Encrypt the file and save it to memory stream
                    }
                    encryptedData = msEncrypt.ToArray();
                }
            }

            var uploadResult = await _cloudStorageProvider.UploadFileAsync(encryptedData, authToken); 
            return new UploadResult(UploadStatus.Success, "File uploaded successfully");
        }
        catch (Exception ex) // General exception handling for edge cases
        {
            return new UploadResult(UploadStatus.Failure, $"An error occurred: {ex.Message}");
        }
    }
}

