```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading;

public class FileChunkProcessor
{
    private readonly ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();
    private Action<string> _loggingCallback;

    public void SetLoggingCallback(Action<string> callback)
    {
        _lock.EnterWriteLock();
        try
        {
            _loggingCallback = callback;
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    public string DecryptFileChunk(string filePath, byte[] key, byte[] iv)
    {
        if (filePath == null || !File.Exists(filePath))
        {
            throw new ArgumentException("Invalid file path");
        }

        // Validate the buffer size and chunk size before proceeding with decryption
        const int bufferSize = 4096; 
        const int chunkSize = bufferSize * 1024;

        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            using (var fsCypher = new FileStream(filePath, FileMode.Open))
            {
                byte[] key = new byte[tripleDes.KeySize / 8]; // Use your actual key
                byte[] iv = new byte[tripleDes.IV.Length]; // Use your actual IV

                ICryptoTransform decryptor = tripleDes.CreateDecryptor(key, iv);
                using (var cs = new CryptoStream(fsCypher, decryptor, CryptoStreamMode.Read))
                {
                    var buffer = new byte[bufferSize];
                    var memory = new MemoryStream();

                    int bytesRead;
                    while ((bytesRead = cs.Read(buffer, 0, chunkSize)) > 0)
                    {
                        memory.Write(buffer, 0, bytesRead);

                        // Log progress using the logging callback if available
                        _loggingCallback?.Invoke($"Decrypted {memory.Length} bytes");
                    }

                    return System.Text.Encoding.UTF8.GetString(memory.ToArray());
                }
            }
        }
    }
}
```
