} DNSResolverArgs;

void *dns_resolver(void *args) {
    DNSResolverArgs *a = (DNSResolverArgs *)args;
    struct hostent *host;

    if ((host = gethostbyname(a->ip)) == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    char ip[INET6_ADDRSTRLEN];
    memset(ip, 0, sizeof ip);

