    for(int i = 0; addr_list[i] != NULL; i++) {
        //Return the first one;
        strcpy(ip , inet_ntoa(*addr_list[i]) );
        break;
    }

    printf("IP address: %s\n", ip);
}

int main() {
    pthread_t threads[5];
    DNSResolverArgs args[5] = {{"www.google.com"}, {"www.amazon.com"}, {"www.facebook.com"}, {"www.microsoft.com"}, {"www.apple.com"}};

    for (int i = 0; i < 5; ++i) {
        if(pthread_create(&threads[i], NULL, dns_resolver, &args[i]) != 0 ){
            perror("Failed to create the thread");
            return 1;
        }
