```java
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Random;

public class SerializationHelper {
    private static final String DEFAULT_HASHING_ALGORITHM = "SHA-256";

    public static String deserializeAndGenerate(byte[] serializedObject, int length, String charset, String password) throws Exception {
        ObjectInputStream ois;

        try {
            ByteArrayInputStream bais = new ByteArrayInputStream(serializedObject);
            ois = new ObjectInputStream(bais);

            // deserialize the object
            Object obj = ois.readObject();

            // generate a random string of specified length with given charset
            String generatedString = generateRandomString(length, charset);

            // hash the password
            String hashedPassword = hashPassword(password);

            return generatedString + " " + hashedPassword;
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Class not found for deserialized object.", e);
        } catch (IOException e) {
            throw new RuntimeException("Failed to deserialize the byte array.", e);
        }
    }

    private static String generateRandomString(int length, String charset) throws Exception{
        Random random = new Random();
        StringBuilder sb = new StringBuilder(length);

        for (int i = 0; i < length; i++) {
            int index = random.nextInt(charset.length());
            char chr = charset.charAt(index);

            // avoid some characters if necessary
            while ((chr >= '0' && chr <= '9') || (chr >= 'A' && chr <= 'Z') || (chr >= 'a' && chr <= 'z')) {
                index = random.nextInt(charset.length());
                chr = charset.charAt(index);
            }

            sb.append(chr);
        }

        return sb.toString();
    }

    private static String hashPassword(String password) throws Exception {
        MessageDigest md = MessageDigest.getInstance(DEFAULT_HASHING_ALGORITHM);
        byte[] hashedBytes = md.digest(password.getBytes(StandardCharsets.UTF_8));

        StringBuilder sb = new StringBuilder();
        for (byte b : hashedBytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }
}
```
This method first attempts to deserialize the input byte array using `ObjectInputStream`. If any of these steps fail (due to an unfound class or a general I/O error), it throws a `RuntimeException` with an appropriate message. After deserializing the object, it generates a random string and hashes a password. The hash function can be changed by replacing the constant `DEFAULT_HASHING_ALGORITHM` with another supported algorithm.

