import javax.xml.bind.DatatypeConverter;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.LoadingCache;
import org.apache.commons.codec.digest.DigestUtils;

public class FileHashCalculator {
    private static final LoadingCache<String, String> cache = CacheBuilder.newBuilder()
            .maximumSize(10_000) // Adjust the maximum size as needed
            .build(key -> calculateMd5(key));

    public static void main(String[] args) {
        System.out.println("MD5 Hash: " + getFileChecksum(new File("/path/to/file")));
    }

    private static String getFileChecksum(File file) {
        try {
            return cache.getUnchecked(file.getAbsolutePath()); // This will either load from the cache or compute it
        } catch (Exception e) {
            System.err.println("Failed to calculate checksum for " + file.getName() + ". Error: " + e);
            return "";
        }
    }

    private static String calculateMd5(String path) throws Exception {
        try (InputStream is = new FileInputStream(new File(path))) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192]; // Adjust this based on your specific use case
            int bytesRead;

            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            return DatatypeConverter.printHexBinary(md.digest()).toLowerCase();
        } catch (IOException | NoSuchAlgorithmException e) {
            throw new Exception("Failed to calculate checksum", e);
        }
