}

pub fn compile_files(file_paths: Vec<String>) -> Result<Vec<Metrics>, &'static str> {
    let hook = SyncLazy::new(|| install_hook());

    let mut results = vec![];

    for path in file_paths {
        let pre_compile_usage = getrusage();
        let start_time = Instant::now();

        let exit_code = catch_with_exit_code(|| {
