using System;
using System.Collections.Generic;
using System.Data;
using System.Threading.Tasks;
using Dapper;
using System.Runtime.Caching;

public class SomeObject
{
    // define properties here...
}

public static class DataAccess
{
    private static readonly ObjectCache cache = MemoryCache.Default;

    public static async Task<IEnumerable<SomeObject>> ExecuteStoredProcedure(IDbConnection connection, List<SqlMapper.IParam> parameters, string procedureName)
    {
        // Create cache key
        var cacheKey = $"{procedureName}-{string.Join("_", parameters)}";

        // Check if data is in the cache
        IEnumerable<SomeObject> result;
        if (cache[cacheKey] != null)
        {
            result = cache[cacheKey] as IEnumerable<SomeObject>;
        } 
        else
        {
            // Fetch data from DB
            using (var multi = await connection.QueryMultipleAsync(procedureName, parameters))
            {
                result = await multi.ReadAsync<SomeObject>();

                // Add to cache
                CacheItemPolicy policy = new CacheItemPolicy();
                policy.AbsoluteExpiration = DateTimeOffset.Now.AddMinutes(10);
                cache.Set(cacheKey, result, policy);
            }
        }

        return result;
    }
}
