```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Threading.Tasks;
using Dapper;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class YourService
{
    private readonly IDbConnection _dbConnection;
    private readonly ILogger<YourService> _logger;
    private readonly IMemoryCache _cache;

    public YourService(IDbConnection dbConnection, ILogger<YourService> logger, IMemoryCache cache)
    {
        _dbConnection = dbConnection ?? throw new ArgumentNullException(nameof(dbConnection));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _cache = cache;
    }

    public async Task<IEnumerable<YourObject>> ExecuteStoredProcedureAsync(string storedProcName, IEnumerable<SqlParameter> parameters)
    {
        if (parameters is null) throw new ArgumentNullException(nameof(parameters));

        var cacheKey = $"{storedProcName}_{JsonConvert.SerializeObject(parameters)}";

        if (!_cache.TryGetValue<IEnumerable<YourObject>>(cacheKey, out var cachedResult))
        {
            try
            {
                var queryParams = new DynamicParameters();
                foreach (var param in parameters)
                    queryParams.Add(param.Name, param.Value);

                using var multi = await _dbConnection.QueryMultipleAsync(storedProcName, queryParams, commandType: CommandType.StoredProcedure);

                cachedResult = await multi.ReadAsync<YourObject>();

                // You can modify cache expiration policy here based on input parameters if needed.
                _cache.Set(cacheKey, cachedResult, new MemoryCacheEntryOptions().SetAbsoluteExpiration(TimeSpan.FromMinutes(5))); 
            }
            catch (Exception ex)
            {
                _logger.LogError("Failed to execute stored procedure: {StoredProcName}, Exception details: {Ex}", storedProcName, ex);
                throw;
            }
        }

        return cachedResult;
    }
}
```
