void progressCallback(int status, void *userData) {
    printf("Progress: %d\n", status);
}

// The main encryption function
CipherObject* encryptFile(const char *filePath, const EVP_CIPHER *cipher, ProgressCallback callback, void *callbackUserData) {
    // Initialize cipher object
    CipherObject *cipherObj = malloc(sizeof(CipherObject));
    if (!EVP_EncryptInit_ex(cipherObj->ctx, cipher, NULL, NULL, NULL)) {
        free(cipherObj);
        return NULL;
    }

    // Open file for reading
    FILE *inputFile = fopen(filePath, "rb");
    if (inputFile == NULL) {
        EVP_CIPHER_CTX_free(cipherObj->ctx);
        free(cipherObj);
        return NULL;
    }

    // Initialize buffer for file reading and encryption
    unsigned char buffer[4096];
    int bytesRead, bytesWritten;
    size_t totalBytes = 0;

    while ((bytesRead = fread(buffer, 1, sizeof(buffer), inputFile)) > 0) {
        // Perform encryption in chunks to avoid loading the entire file into memory at once
        if (!EVP_EncryptUpdate(cipherObj->ctx, buffer, &bytesWritten, buffer, bytesRead)) {
            free(cipherObj);
            fclose(inputFile);
            return NULL;
        }

        // Write encrypted data to file
        if (fwrite(buffer, 1, bytesWritten, outputFile) != bytesWritten) {
            EVP_CIPHER_CTX_free(cipherObj->ctx);
            free(cipherObj);
            fclose(inputFile);
            return NULL;
        }

        totalBytes += bytesRead;

        // Call the progress callback function to notify the user about encryption status
        if (callback != NULL) {
            callback((int)(totalBytes * 100 / fileSize), callbackUserData);
        }
    }

    // Finalize encryption and write remaining data to file
    EVP_EncryptFinal_ex(cipherObj->ctx, buffer, &bytesWritten);
    fwrite(buffer, 1, bytesWritten, outputFile);

    // Clean up resources
    fclose(inputFile);
    return cipherObj;
}
