```csharp
using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Diagnostics;
using System.Security.Cryptography;

public interface ILogger
{
    void LogError(Exception ex);
    void LogTimeTaken(string message, Stopwatch stopWatch);
}

public class FileHasher
{
    private const int BUFFER_SIZE = 4096; // 4KB chunk size as a good default

    private readonly ILogger _logger;

    public FileHasher(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> ComputeSHA256Async(string path, bool chunked = false)
    {
        var stopWatch = Stopwatch.StartNew();

        try
        {
            using (var sourceStream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.None, BUFFER_SIZE, true))
            {
                byte[] hashBytes;

                if (chunked)
                    hashBytes = await ComputeChunkedHashAsync(sourceStream);
                else
                    hashBytes = await ComputeFullFileHashAsync(sourceStream);

                return BitConverter.ToString(hashBytes).Replace("-", string.Empty);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex);
            throw;
        }
        finally
        {
            stopWatch.Stop();

            _logger.LogTimeTaken($"Hashing of file '{path}' completed.", stopWatch);
        }
    }

    private async Task<byte[]> ComputeFullFileHashAsync(Stream source)
    {
        using (var hashAlgorithm = SHA256.Create())
            return await hashAlgorithm.ComputeHashAsync(source);
    }

    private static async Task<byte[]> ComputeChunkedHashAsync(Stream source)
    {
        var buffer = new byte[BUFFER_SIZE];

        using (var hashAlgorithm = SHA256.Create())
        {
            int bytesRead;

            while ((bytesRead = await source.ReadAsync(buffer, 0, buffer.Length)) > 0)
                hashAlgorithm.TransformBlock(buffer, 0, bytesRead, null, 0);

            hashAlgorithm.TransformFinalBlock(buffer, 0, 0);

            return hashAlgorithm.Hash;
        }
    }
}
```
