extern Logger logger;  // Assuming logger object is defined externally

// Function to read file synchronously and return its content as string
std::string readFile(const fs::path& path) {
    if (!fs::exists(path)) throw std::runtime_error("Path does not exist");
    std::ifstream file;
    file.exceptions (std::ifstream::failbit | std::ifstream::badbit); // enabling exceptions on fail or bad bit
    try {
        file.open(path);
        return std::string((std::istreambuf_iterator<char>(file)), 
                           std::istreambuf_iterator<char>());
    } catch (const std::ifstream::failure& e) {
        throw std::runtime_error("Cannot read from file");
    }
}

// Function to insert replacement string after first occurrence of target string
void insertAfterTarget(std::forward_list<std::string>& list, const std::string& target, 
                       const std::string& replacement) {

    // Locking the mutex to ensure thread safety during concurrent modifications
    std::lock_guard<std::mutex> lock(mtx);

    auto it = std::find(list.begin(), list.end(), target);
    if (it != list.end()) {
        list.insert_after(it, replacement);

        // Logging insertion operation for debugging and auditing purposes
        logger.log("Inserted string: " + replacement + ", after: " + target);

    } else {
        list.insert_after(list.before_begin(), replacement);

        // Logging insertion operation for debugging and auditing purposes
        logger.log("Target not found, inserted at the end: " + replacement);
    }
}
