```javascript
function copyBytes(dataChunks, byteCount) {
    if (!Array.isArray(dataChunks)) throw new Error("Invalid data chunks");
    let totalSize = dataChunks.reduce((sum, chunk) => sum + chunk.length, 0);
    if (byteCount > totalSize) throw new Error("Requested byte count exceeds available data");

    let resultBuffer = Buffer.allocUnsafe(byteCount), offset = 0;

    for (let i = 0; i < dataChunks.length && byteCount > 0; ++i) {
        const chunkSize = dataChunks[i].length;

        if (!Number.isInteger(chunkSize)) throw new Error("Invalid chunk size");
        if (offset + chunkSize > totalSize || offset + chunkSize < totalSize) throw new Error("Chunk sizes do not match expectations");
        dataChunks[i].copy(resultBuffer, offset, 0, Math.min(chunkSize, byteCount));

        offset += chunkSize;
        byteCount -= chunkSize;
    }

    return resultBuffer;
}
```
This function takes an array of data chunks (each represented as a Buffer object in Node.js) and a byte count, then copies the specified number of bytes from these chunks into a new buffer. It throws errors if any chunk size does not match expectations or if the requested byte count exceeds available data. 

