Here is a C implementation of the requested function `renameFileWithDigits`:

```c
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdio.h>

char* renameFileWithDigits(const char* filename, const char* new_extension) {
    char buffer[256];
    strncpy(buffer, filename, sizeof(buffer) - 1);
    buffer[sizeof(buffer)-1] = '\0';   // Ensure null termination.

    char* dot = strrchr(buffer, '.');  // Find last occurrence of '.' in filename.

    size_t extLength;
    if (dot == NULL) {               // If no extension exists.
        extLength = 0;
    } else {                       
        extLength = strlen(dot + 1);   // Length of existing extension.
    }

    char* dotWithoutExt = strrchr(buffer, '.');  // Find last occurrence of '.' without the extension.

    if (isdigit((unsigned char)*(dot - 1))) {        // If filename ends with a number.
        int number;
        sscanf(dot - 1, "%d", &number);              // Read the number at the end of filename.
        snprintf(dot - extLength - 1, sizeof(buffer) - (dot - buffer), "%d.", ++number);   // Increment and append to new extension.
    } else {                    // If filename doesn't end with a number.
        size_t numWithoutExt = dot == NULL ? strlen(filename) : dot - filename;  // Length of filename without extension.
        snprintf(buffer + numWithoutExt, sizeof(buffer) - numWithoutExt, "1.");    // Append '1' to new extension.
    }

    if (extLength > 0 && strcmp(dot + 1, new_extension)) {  // If existing extension is not the same as new extension.
        snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), "%s", new_extension);   // Append new extension.
    } else if (extLength == 0) {     // If no existing extension and no new extension given.
        snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ".%s", new_extension);  // Append '.' followed by new extension.
    }

    char* renamed = malloc(strlen(buffer) + 1);   // Allocate memory for the modified filename.
    if (renamed == NULL) {                        // Check if allocation was successful.
        return NULL;
    }

    strcpy(renamed, buffer);                      // Copy the modified filename to allocated memory.

    return renamed;                               // Return the new filename string.
}
```

This function operates by first copying the input filename into a local buffer. It then locates the last occurrence of '.' in the filename and checks if the character preceding it is a number, indicating versioning or a number at the end of the filename. If so, it increments this number and appends to the new extension; otherwise, it appends '1' to the new extension. It also handles cases where the original filename includes multiple extensions or no extension at all. The modified filename is returned as a newly allocated string, making sure to check for allocation errors before returning the result.

