import os
import json
from collections import defaultdict
import asyncio
import logging

class JsonObjectFactory(object):
    _registry = {}

    def __init__(self, id, cls):
        self._id = id
        self._cls = cls

    @classmethod
    async def create_from_file(cls, filepath, id):
        try:
            with open(filepath) as f:
                data = json.load(f)
            return await cls.create(id, data)
        except Exception as e:
            logging.error("Failed to load JSON from file {}: {}".format(filepath, str(e)))

    @classmethod
    async def create_from_files(cls, id_to_file):
        tasks = [cls.create_from_file(f, i) for i, f in id_to_file.items()]
        return await asyncio.gather(*tasks, return_exceptions=True)

    @classmethod
    async def create(cls, id, data):
        obj = cls._registry[id](**data)
        logging.info("Created {} from JSON".format(obj))
        return obj

    @classmethod
    def register(cls, id, subcls):
        if id in cls._registry:
            raise ValueError("Duplicate ID '{}'".format(id))

        cls._registry[id] = subcls

    @staticmethod
    def to_json(obj):
        return json.dumps(obj.__dict__)
``` 

