class DynamicRandomStringGenerator {
    private $length = 16;
    private $charset = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    private $configUpdateCallback;

    public function GenerateCustomRandomString($length = null, $charset = null, $seeded = true) {
        $this->validateInputs($length, $charset);

        if ($seeded) {
            srand();
        }

        $randomString = '';
        $maxIndex = strlen($charset ?: $this->charset) - 1;

        for ($i = 0; $i < ($length ?: $this->length); ++$i) {
            $randomString .= $charset[rand(0, $maxIndex)];
        }

        return $randomString;
    }

    public function HashPassword($password) {
        return password_hash($password, PASSWORD_BCRYPT);
    }

    public function setConfigUpdateCallback(\Closure $callback){
        $this->configUpdateCallback = $callback;
    }

    private function validateInputs($length = null, $charset = null) {
        if (isset($length) && (!is_numeric($length) || $length < 1)) {
            throw new \InvalidArgumentException('Length must be a positive number.');
        }

        if (isset($charset) && !is_string($charset)) {
            throw new \InvalidArgumentException('Charset must be a string.');
        }
    }
}
