#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>

int resolveHostWithTimeout(const char *hostname, struct in_addr *ipAddress, size_t ipAddressLength, int timeout) {
    if (timeout < 0 || hostname == NULL || ipAddress == NULL) return -1; // Invalid input parameter

    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;     // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo* result = NULL;
    int res = getaddrinfo(hostname, "80", &hints, &result);
    if (res != 0) { // Failure in DNS query
        printf("Error: %s\n", gai_strerror(res));
        return -3;
    }

    struct addrinfo* ptr = NULL;
    for(ptr=result; ptr != NULL; ptr=ptr->ai_next) { 
        if (ptr->ai_family == AF_INET && ptr->ai_addrlen <= ipAddressLength) {
            memcpy(ipAddress, &((struct sockaddr_in *)ptr->ai_addr)->sin_addr, sizeof(struct in_addr)); // copy address
        } else if (ptr->ai_family == AF_INET6 && ptr->ai_addrlen <= ipAddressLength) {
            memcpy(ipAddress, &((struct sockaddr_in6 *)ptr->ai_addr)->sin6_addr, sizeof(struct in_addr)); // copy address
        } else {
            return -4; // insufficient buffer size in the `ipAddress` array
        }
    }

    freeaddrinfo(result);
    return 0; // Success
}
```

