```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    double value;
} record_t;

// Use a mutex to handle possible data races when multiple threads initialize simultaneously
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initArrays(const char* configFile, long **offsetsPtr, int **keysPtr, record_t **recordsPtr) {
    FILE *file = fopen(configFile, "r");
    if (file == NULL) {
        printf("Failed to open file\n");
        return;
    }

    // Read initial offset and key values from config file
    long initOffset;
    int initKey;
    if (fscanf(file, "%ld %d", &initOffset, &initKey) != 2) {
        printf("Failed to read initial offset or key\n");
        fclose(file);
        return;
    }

    // Ensure data types match those specified in the file
    if (fscanf(file, "%ld %d", &initOffset, &initKey) != 2 || initOffset < 0 || initKey < 0) {
        printf("Data type mismatch or negative values detected\n");
        fclose(file);
        return;
    }

    // Allocate memory for arrays
    *offsetsPtr = malloc(3 * sizeof(long));
    *keysPtr = malloc(3 * sizeof(int));
    *recordsPtr = malloc(3 * sizeof(record_t));

    if (*offsetsPtr == NULL || *keysPtr == NULL || *recordsPtr == NULL) {
        printf("Failed to allocate memory\n");
        fclose(file);
        return;
    }

    // Initialize arrays
    pthread_mutex_lock(&lock);

    (*offsetsPtr)[0] = initOffset;
    (*keysPtr)[0] = initKey;

    for (int i = 1; i < 3; ++i) {
        (*offsetsPtr)[i] = (*offsetsPtr)[i - 1] + 1;
        (*keysPtr)[i] = (*keysPtr)[i - 1] + 1;
    }

    for (int i = 0; i < 3; ++i) {
        // Assuming a double value range of [minValue, maxValue]
        const double minValue = 0.0;
        const double maxValue = 1.0;
        (*recordsPtr)[i].offset = (*offsetsPtr)[i];
        (*recordsPtr)[i].key = (*keysPtr)[i];
        (*recordsPtr)[i].value = minValue + ((double)rand() / RAND_MAX) * (maxValue - minValue);
    }

    pthread_mutex_unlock(&lock);

    fclose(file);
}
```
This code locks a mutex before accessing the configuration file, which ensures that only one thread can access it at a time. It then reads the initial offset and key values from the file, allocates memory for the arrays, and initializes them accordingly. Note that the function assumes that each subsequent record's double value should be set to a random value within the range [0.0, 1.0].

