```c
#include <stdlib.h>
#include <pthread.h>
#define ERR_INVALID_PARAM 1
#define ERR_ALLOCATION_FAILURE 2

typedef struct {
    /* RX_UE_INFORMATION_TAG fields */
} RX_UE_INFORMATION_TAG;

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG RX_UE_INFORMATION;
    int RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int generateNFAPduList(int num_pdus, NFAPI_CRC_INDICATION_PDU_T **pdu_list, uint32_t *checksum) {
    int i, rc = 0;

    if (num_pdus <= 0 || pdu_list == NULL || checksum == NULL)
        return ERR_INVALID_PARAM;

    // Lock the mutex before accessing shared resource to ensure thread safety
    pthread_mutex_lock(&mutex);

    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *) malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*pdu_list == NULL) {
        rc = ERR_ALLOCATION_FAILURE;
    } else {
        *checksum = 0;
        for (i = 0; i < num_pdus; ++i) {
            // Assuming the fields are correctly filled in here. Randomize CRCFLAG if required.
            (*pdu_list)[i].CRC_INDICATION.CRCFLAG = rand() % 256; 
            *checksum += (*pdu_list)[i].CRC_INDICATION.CRCFLAG;
        }
    }

    pthread_mutex_unlock(&mutex); // Release the lock after all critical operations are done

    return rc;
}
```
