```csharp
using System;
using UnityEngine;
using NUnit.Framework;

public enum DistributionType { Uniform, Gaussian }

public class DynamicRandomValueGenerator
{
    private int minValue, maxValue;
    private DistributionType distribution = DistributionType.Uniform;

    public DynamicRandomValueGenerator(int minValue, int maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float NextFloat()
    {
        if (distribution == DistributionType.Gaussian)
            return GaussianRandom(minValue + ((float)(maxValue - minValue)) / 2, Mathf.Abs((float)(maxValue - minValue))/4);

        // uniform distribution by default
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    public int NextInt()
    {
        if (distribution == DistributionType.Gaussian)
            return Mathf.RoundToInt(GaussianRandom(minValue + ((float)(maxValue - minValue)) / 2, Mathf.Abs((float)(maxValue - minValue))/4));

        // uniform distribution by default
        return UnityEngine.Random.Range(minValue, maxValue + 1);
    }

    private float GaussianRandom(float mean = 0.5F, float stddev = .25f)
    {
        float u, v, S;

        do
        {
            u = 2f * UnityEngine.Random.value - 1f;
            v = 2f * UnityEngine.Random.value - 1f;
            S = u * u + v * v;
        }
        while (S >= 1f);

        float fac = Mathf.Sqrt(-2f * Mathf.Log(S) / S);

        return u * fac * stddev + mean;
    }

    public override string ToString() => $"Range: [{minValue}, {maxValue}] (Distribution: {distribution})";
}

public class DynamicRandomValueGeneratorTests
{
    [Test]
    public void TestNextFloatWithinRange()
    {
        var generator = new DynamicRandomValueGenerator(1, 10);

        for (int i = 0; i < 100; i++)
        {
            float value = generator.NextFloat();

            Assert.GreaterOrEqual(value, 1f);
            Assert.Less(value, 10f);
        }
    }

    [Test]
    public void TestNextIntWithinRange()
    {
        var generator = new DynamicRandomValueGenerator(1, 10);

        for (int i = 0; i < 100; i++)
        {
            int value = generator.NextInt();

            Assert.GreaterOrEqual(value, 1);
            Assert.Less(value, 10);
        }
    }
}
```

JavaScript function to find elements without recursion could look like this:

```javascript
function FindElementsBySelector(rootNode, selector) {
    let selected = [];

    // use stack for depth-first search (DFS) over DOM tree
    let stack = [rootNode]; 

    while (stack.length > 0) {
        let node = stack.pop(); // retrieve and remove the last element of array 

        if(node && node.classList && node.classList.contains(selector)) selected.push(node);

        let children = Array.from(node.children);
        stack.push(...children); // push all child nodes to stack for further traversing 
    }

    return selected;
}
```

