```C#
using System;
using System.Linq;
using System.Xml.XPath;
using System.Net;
// other necessary imports

public class XmlParserService : IXmlParserService
{
    private readonly IXPathSchemaValidator _schemaValidator;
    private readonly ICache<string, string> _cache;
    private readonly ILogger _logger;

    public XmlParserService(IXPathSchemaValidator schemaValidator, ICache<string, string> cache, ILogger logger)
    {
        // injected dependencies for schema validation, caching and logging
        _schemaValidator = schemaValidator;
        _cache = cache;
        _logger = logger;
    }

    public XPathNavigator ParseXml(string xmlDocumentUrl, string xpathQuery)
    {
        // Check if document is cached. If not, fetch it from the API and validate against a schema. 
        string fetchedXmlString = _cache.GetOrAdd(xmlDocumentUrl, () => FetchAndValidateFromApi(xmlDocumentUrl));

        var xmlDocNavigator = new XPathDocument(new StringReader(fetchedXmlString)).CreateNavigator();

        // Execute the XPath query and return first matched element
        var iterator = xmlDocNavigator.Select(xpathQuery);

        iterator.MoveNext();
        if (iterator.Current == null)
            throw new Exception("No elements found with given name.");

        // If next element exists, this means multiple nodes matched the query -> error
        if (iterator.MoveNext()) 
            throw new Exception("Multiple elements found with given name");

        return iterator.Current;
    }

    private string FetchAndValidateFromApi(string xmlDocumentUrl) {

        try {
            HttpWebRequest request = (HttpWebRequest)WebRequest.Create(xmlDocumentUrl);
            using (var response = (HttpWebResponse)request.GetResponse()) {
                if (response.StatusCode != HttpStatusCode.OK)
                    throw new Exception("Failed to fetch XML document from API."); 

                var xmlString = new StreamReader(response.GetResponseStream()).ReadToEnd();

                // Validate fetched XML against a schema using _schemaValidator
                if (!_schemaValidator.IsValidAgainstSchema(xmlString)) {
                    throw new Exception("Fetched XML does not match expected schema."); 
                }

                return xmlString;
            }
        } catch (Exception e) {
            // Log the exception and rethrow to handle it upstream
            _logger.Log(e);
            throw;
        }
    }
}
```
