using System;
using UnityEngine;

public class ValueGenerator : MonoBehaviour
{
    private int minInt;
    private int maxInt;
    private float minFloat;
    private float maxFloat;

    public ValueGenerator(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Min cannot be greater than Max");

        this.minInt = min;
        this.maxInt = max;
    }

    public ValueGenerator(float min, float max, bool isInclusive = false) : this((int)min, (int)(isInclusive ? Math.Ceiling(max) : Math.Floor(max))) 
    {
        if (min > max)
            throw new ArgumentException("Min cannot be greater than Max");

        this.minFloat = min;
        this.maxFloat = max;
    }

    public int GenerateInt()
    {
        return UnityEngine.Random.Range(minInt, maxInt);
    }

    public float GenerateFloat()
    {
        return UnityEngine.Random.Range(minFloat, maxFloat);
    }

    public int[] GenerateIntArray(int size)
    {
        if (size <= 0 || size > Int32.MaxValue) 
            throw new ArgumentOutOfRangeException("Invalid size");

        var result = new int[size];

        for(int i = 0; i < size; i++) 
        {
           result[i] = GenerateInt();
        }
        return result;
    }

    public float[] GenerateFloatArray(int size)
    {
        if (size <= 0 || size > Int32.MaxValue) 
            throw new ArgumentOutOfRangeException("Invalid size");

        var result = new float[size];

        for(int i = 0; i < size; i++) 
        {
           result[i] = GenerateFloat();
        }
        return result;
    }

    public override string ToString()
    {
        if (minInt != 0 && maxInt != 0)
            return $"Integer range: {minInt} - {maxInt}";

        if (minFloat != 0f && maxFloat != 0f)
            return $"Float range: {minFloat} - {maxFloat}";

        return "No range set";
    }
}
