typedef struct {
    uint16 bitsPerSample;
    uint16 sampleFormat;
    int extraSamples;
} TIFFInfo;

TIFFInfo parse_tiff(const char* filename) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Could not open file %s for reading\n", filename);
        return;
    }

    TIFFInfo info = {0};
    uint16 bps, sf;
    short compr;
    if (!TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bps) || !TIFFGetField(tif, TIFFTAG_SAMPLEFORMAT, &sf)) {
        fprintf(stderr, "Could not read BitsPerSample or SampleFormat from file %s\n", filename);
    } else if (bps != 1 && bps != 2 && bps != 4 && bps != 8 && bps != 16) {
        fprintf(stderr, "Unsupported BitsPerSample: %d. Must be 1, 2, 4, 8, or 16\n", bps);
    } else if (!TIFFGetField(tif, TIFFTAG_COMPRESSION, &compr)) {
        fprintf(stderr, "Could not read Compression from file %s\n", filename);
    } else {
        info.bitsPerSample = bps;
        info.sampleFormat = sf;
        TIFFClose(tif);
        return info;
    }

    uint16 count, type;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &count) && count > 0) {
        void* data = _TIFFmalloc(count * sizeof(uint16));
        if (data != NULL && TIFFGetField(tif, TIFFTAG_EXTRASAMPLETYPES, &type)) {
            info.extraSamples = count;
            printf("Extra samples: %d\n", count);
            for (int i = 0; i < count; ++i) {
                uint16 sampleType = ((uint16*)data)[i];
                // Do something with the extra sample type...
            }
        } else {
            fprintf(stderr, "Could not read ExtraSampleTypes from file %s\n", filename);
        }
    } else if (compr == COMPRESSION_CCITTRLE || compr == COMPRESSION_CCITTFAX3 || compr == COMPRESSION_CCITTFAX4) {
        info.extraSamples = 1;
        printf("Extra samples: %d\n", 1);
    } else {
        fprintf(stderr, "Unsupported compression scheme for ExtraSamples: %d\n", compr);
    }

    TIFFClose(tif);
    return info;
}
