Here is a C# solution that follows all the mentioned requirements:

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;

public class ProductLoader
{
    private readonly BinaryFormatter _formatter = new BinaryFormatter();
    private readonly ConcurrentBag<Product> _mergedProducts = new ConcurrentBag<Product>();

    public async Task LoadAndMergeAsync(string[] filePaths)
    {
        var tasks = new List<Task>();

        foreach (var filePath in filePaths)
        {
            tasks.Add(LoadFileAsync(filePath));
        }

        await Task.WhenAll(tasks);
    }

    private async Task LoadFileAsync(string filePath)
    {
        try
        {
            using (var stream = new FileStream(filePath, FileMode.Open))
            {
                Product product;

                while ((product = (Product)_formatter.Deserialize(stream)) != null)
                {
                    _mergedProducts.Add(product);
                }
            }
        }
        catch (SerializationException ex)
        {
            // Log error: file is corrupted or contains invalid data.
            Console.WriteLine($"Failed to deserialize from file {filePath}. Error: {ex.Message}");
        }
        catch (IOException ex)
        {
            // Log error: failed to read the file due to IO issues.
            Console.WriteLine($"Failed to open or close the file {filePath}. Error: {ex.Message}");
        }
    }

    public Product[] GetMergedProducts() => _mergedProducts.ToArray();
}
```
This code uses `ConcurrentBag` from `System.Collections.Concurrent` to safely merge data from multiple sources without locking, improving performance. It also wraps each file operation in a try-catch block to handle exceptions that might occur during deserialization or when reading the files. Note that this example assumes that the binary files contain serialized instances of `Product` separated by some kind of delimiter (like a sentinel value). 

