```javascript
const { Writable } = require('stream');
const loggerDB = require("./logger_db"); // An imaginary database for logging purposes
const streamSources = [ /* ... */ ]; // Source data chunks from different streams or networks
let currentOperationID;

async function copyBytes(chunkCount) {
    if (chunkCount > streamSources.reduce((a, b) => a + b.length, 0)) throw new Error('Requested byte count exceeds total available data');

    const outputStream = new Writable({
        write: function(chunk, encoding, next) {
            loggerDB.logOperation(currentOperationID, chunk); // Log the operation in database
            next(); 
        },
    });

    let bytesCopied = 0;

    return new Promise((resolve, reject) => {
        outputStream.on('error', reject);

        const writeChunk = (chunk) => {
            if (!outputStream.write(chunk)) {
                outputStream.once('drain', writeChunk.bind(null, chunk));
            } else {
                bytesCopied += chunk.length; 
                if (bytesCopied >= chunkCount) resolve();
            }
        };

        try {
            currentOperationID = loggerDB.initializeNewOperation(); // Initialize operation in the database

            streamSources.forEach((streamSource, index) => {
                for(let i = 0; i < Math.min(chunkCount - bytesCopied, streamSource.length); i++){
                    writeChunk({ sourceID: index, data: streamSource[i] });  // Write chunk to output stream
                }
            });
        } catch (err) {
            reject(err);
        }  
    });
}
```
This function uses Node.js streams with backpressure and promises for efficient handling of large data chunks from multiple sources. It logs each operation's metadata into a database using `loggerDB`, which is a hypothetical module representing your external database system. 

