```C
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct SubNode {
    char *str;
    double value;
    struct SubNode *next;
} SubNode;

typedef struct Node {
    int value;
    SubNode *head;
} Node;

char* generate_random_string(int length) {
    static char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *str = malloc((length + 1) * sizeof(char));
    if (str == NULL) exit(EXIT_FAILURE);

    for (int i = 0; i < length; i++) {
        int key = rand() % (int)(sizeof charset - 1);
        str[i] = charset[key];
    }
    str[length] = '\0';

    return str;
}

Node* initialize_nodes(int node_count, int subnode_count) {
    srand((unsigned int) time(NULL));
    Node *nodes = malloc(node_count * sizeof(Node));
    if (nodes == NULL) exit(EXIT_FAILURE);

    for (int i = 0; i < node_count; i++) {
        nodes[i].value = rand();

        SubNode *head = NULL, *tail = NULL;
        for (int j = 0; j < subnode_count; j++) {
            SubNode *newNode = malloc(sizeof(SubNode));
            if (newNode == NULL) exit(EXIT_FAILURE);

            newNode->str = generate_random_string(5);
            newNode->value = ((double) rand() / (RAND_MAX)) * 10.0;
            newNode->next = NULL;

            if (head == NULL) {
                head = tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }
        }

        nodes[i].head = head;
    }

    return nodes;
}

void free_nodes(Node *nodes, int node_count) {
    for (int i = 0; i < node_count; i++) {
        SubNode *current = nodes[i].head;

        while (current != NULL) {
            SubNode *temp = current;
            current = current->next;
            free(temp->str);
            free(temp);
        }
    }

    free(nodes);
}
```
In the above code, `initialize_nodes` function is used to initialize the array of `Node` structures with random integer values and linked lists. The `free_nodes` function should be called after using the nodes to free all allocated memory.

