    off_t size;
    char *mmappedData;
} LogFile;

// Globals
Directory directories[500]; // Assuming 500 as max limit
LogFile logFiles[100][500]; // Assuming 100 logs per directory, 500 directories.
int numDirectories = 0;
int numLogFiles = 0;
pthread_t threads[256];
int currThreadIdx = 0;
void *queue[256]; // Message queue
volatile int head = 0, tail = 0;
pthread_mutex_t lock;

// Function prototypes
void enqueue(void *);
void *dequeue();
int isQueueFull() {return (tail + 1) % 256 == head;}
int isQueueEmpty() {return tail == head;}

// Adding directories to be monitored
void addDirectory(char *path){
    if(numDirectories >= 500){
        printf("Maximum limit of 500 directories reached.");
        return;
    }
    strcpy(directories[numDirectories++].path, path);
}

// Function to enqueue message into queue
void enqueue(void *msg) {
    if(!isQueueFull()){
        queue[tail] = msg;
        tail = (tail + 1) % 256;
    } else printf("Queue full.\n");
}

// Function to dequeue message from queue
void *dequeue() {
    void *msg = NULL;
    if(!isQueueEmpty()){
        msg = queue[head];
        head = (head + 1) % 256;
    } else printf("Queue empty.\n");
    return msg;
}

// Thread routine to handle processing of log files
void *logFileProcessing(void *arg) {
    LogFile *lf = (LogFile *)arg;

    // Memory map the file
    int fd = open(lf->path, O_RDONLY);
    if(fd == -1){
        printf("Could not open file: %s\n", lf->path);
        return NULL;
    }

    void *mmappedData = mmap(NULL, lf->size, PROT_READ, MAP_PRIVATE, fd, 0);
    if(mmappedData == MAP_FAILED){
        printf("Failed to map file: %s\n", lf->path);
        close(fd);
        return NULL;
    }

    // TODO: Parse the log data and calculate metrics.

    munmap(mmappedData, lf->size);
    close(fd);
    return NULL;
}

// Function to read log files from directories. 
void readLogFiles() {
    for(int i = 0; i < numDirectories; ++i) {
        // Assuming the directory contains files only and not subdirectories
        DIR *dir = opendir(directories[i].path);
        if(!dir){
            printf("Could not open directory: %s\n", directories[i].path);
            continue;
        }

        struct dirent *entry;
        while((entry = readdir(dir)) != NULL) {
            // Skip "." and ".." directories 
            if(!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;

            if(numLogFiles >= 100){
                printf("Maximum limit of 100 log files per directory reached.");
                break;
            }

            strcpy(logFiles[i][numLogFiles].path, directories[i].path);
            strcat(logFiles[i][numLogFiles].path, "/");
            strcat(logFiles[i][numLogFiles].path, entry->d_name);

            struct stat st;
            if(stat(logFiles[i][numLogFiles].path, &st) == 0){
                logFiles[i][numLogFiles].size = st.st_size;
            } else {
                printf("Could not get file size: %s\n", logFiles[i][numLogFiles].path);
                ++numLogFiles;
                continue;
            }

            // Enqueue the log file for processing by a worker thread.
            enqueue(&logFiles[i][numLogFiles]);
            ++numLogFiles;
