            Arguments = $"/path:\"{directoryPath}\" /port:{GetNextAvailablePort(8080)}",
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        Process process;
        lock (_lock)  // Lock to prevent concurrent access to the same directory
        {
            process = Process.Start(startInfo);
        }

        if (process == null)
            throw new Exception("Could not start the site");

        try
        {
            var completedTask = await Task.WhenAny(process.WaitForExitAsync(), Task.Delay(TimeSpan.FromSeconds(60)));  // timeout after 1 minute
            if (completedTask == process.WaitForExitAsync())
                return process;

