Here is an example implementation using C++17 standard features including JSON parsing from Nlohmann's Json library, as well as `std::mt19937` as the underlying random number generator. This code does not include actual file operations or handling for different distributions but can be extended to cover those:

```cpp
#include <random>
#include <ctime>
#include <fstream>
#include <mutex>
#include "json.hpp"

using json = nlohmann::json;

namespace CustomRandom {
    class RandomGenerator{
        public:
            explicit RandomGenerator(const std::string& configFilePath){
                try{
                    std::ifstream ifs(configFilePath);
                    if(!ifs.good()){
                        throw std::runtime_error("Configuration file not found");
                    }

                    json j;
                    ifs >> j;

                    mtx.lock(); // lock mutex to ensure thread safety 

                    seed = getSeed(j["seed"]);

                    if (j.contains("distribution")){
                        distribution = j["distribution"];
                    }else{
                        throw std::runtime_error("Distribution type not provided");
                    }

                    mtx.unlock(); // unlock mutex
                }catch(std::exception& e){
                    std::cerr << "Exception caught: " << e.what() << "\n";
                }
            }

            ~RandomGenerator(){

            }

            float generateNumber(){
                mtx.lock(); // lock mutex to ensure thread safety 

                if(distribution == "uniform"){
                    std::uniform_real_distribution<float> dist(0,1);
                    auto number = dist(gen);

                    mtx.unlock(); // unlock mutex
                    return number;
                }else if (distribution == "normal"){
                    std::normal_distribution<float> dist(0,1);
                    auto number = dist(gen);

                    mtx.unlock(); // unlock mutex
                    return number;
                }else if (distribution == "exponential") {
                    std::exponential_distribution<float> dist(1);
                    auto number = dist(gen);

                    mtx.unlock(); // unlock mutex
                    return number;
                }else{
                    throw std::runtime_error("Invalid distribution");
                }
            }
        private:
            unsigned int seed; 
            std::string distribution;
            std::mt19937 gen; 
            std::mutex mtx; // mutex for thread safety

            unsigned int getSeed(json j){
                if (j == "time"){
                    return static_cast<unsigned int>(std::time(nullptr));
                } else if (j == "system entropy") {
                    std::random_device rd;
                    return rd();
                } else {
                   throw std::runtime_error("Invalid seed type"); 
                }
            }    
    };
}
```
