```csharp
using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;

public class UploadResult
{
    public bool Success { get; set; }
    public string ErrorMessage { get; set; }
}

public class FileTransferService
{
    private const int ChunkSize = 1024 * 1024; // 1MB chunks
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly string _tokenServiceUrl;
    private string _uploadToken;

    public FileTransferService(string tokenServiceUrl)
    {
        _tokenServiceUrl = tokenServiceUrl;
    }

    private async Task AuthenticateAsync()
    {
        if (_uploadToken == null || /* Token is expired */) // Implement your own logic to check token validity
        {
            var response = await _httpClient.GetStringAsync(_tokenServiceUrl);
            _uploadToken = response; // Implement your own token extraction process
        }
    }

    public async Task<UploadResult> UploadFileAsync(string filePath, byte[] encryptionKey, byte[] iv)
    {
        await AuthenticateAsync();

        try
        {
            using (var stream = File.OpenRead(filePath))
                return await PerformChunkedUploadAsync(stream, encryptionKey, iv);
        }
        catch (IOException ex)
        {
            return new UploadResult { Success = false, ErrorMessage = "File IO error: " + ex.Message };
        }
    }

    public async Task<UploadResult> UploadFileAsync(byte[] fileBytes, byte[] encryptionKey, byte[] iv)
    {
        await AuthenticateAsync();

        using (var stream = new MemoryStream(fileBytes))
            return await PerformChunkedUploadAsync(stream, encryptionKey, iv);
    }

    private async Task<UploadResult> PerformChunkedUploadAsync(Stream fileStream, byte[] encryptionKey, byte[] iv)
    {
        var aes = new AesCryptoServiceProvider();
        aes.Key = encryptionKey;
        aes.IV = iv;

        using (var cryptoStream = new CryptoStream(fileStream, aes.CreateEncryptor(), CryptoStreamMode.Read))
        {
            byte[] buffer = new byte[ChunkSize];

            for (int bytesRead = 0; (bytesRead = await cryptoStream.ReadAsync(buffer, 0, ChunkSize)) > 0;)
            {
                var chunkToUpload = bytesRead == ChunkSize ? buffer : buffer.AsSpan(0, bytesRead).ToArray(); // Make sure to handle the last chunk properly

                using (var content = new ByteArrayContent(chunkToUpload))
                {
                    var response = await _httpClient.PutAsync(_uploadToken, content);

                    if (!response.IsSuccessStatusCode)
                        return new UploadResult { Success = false, ErrorMessage = $"Cloud storage error: HTTP {(int)response.StatusCode}" };
                }
            }
        }

        return new UploadResult { Success = true };
    }
}
```
