Here is a simple implementation of the `loadResourceBundle` function using POSIX threads. This code does not include validating the resource file against a predefined schema, as this would be highly dependent on the specifics of that schema and the provided example was too general for an exact implementation to be given.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

enum ResourceType { IMAGE, TEXT, AUDIO, NUM_TYPES };
typedef struct ResourceItem {
    enum ResourceType type;
    void* data;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem* items;
    size_t itemCount[NUM_TYPES];
    size_t totalItemCount;
    pthread_mutex_t mutex;  // For thread safety
} ResourceBundle;

ResourceBundle* loadResourceBundle(const char* filePath) {
    FILE* fp = fopen(filePath, "rb");
    if (fp == NULL) {
        perror("Error opening file: ");
        return NULL;
    }

    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        perror("Error allocating memory for resource bundle");
        fclose(fp);
        return NULL;
    }

    // initialize the mutex and counts
    pthread_mutex_init(&bundle->mutex, NULL);
    for (int i = 0; i < NUM_TYPES; ++i) {
        bundle->itemCount[i] = 0;
    }
    bundle->totalItemCount = 0;

    size_t dataSize;
    while (fread(&dataSize, sizeof(size_t), 1, fp)) {
        ResourceType type;
        if (fread(&type, sizeof(ResourceType), 1, fp) != 1 || type >= NUM_TYPES) {
            fprintf(stderr, "Error reading resource item\n");
            freeResourceBundle(bundle);
            return NULL;
        }

        // allocate memory for the data and read it
        void* data = malloc(dataSize);
        if (fread(data, 1, dataSize, fp) != dataSize) {
            fprintf(stderr, "Error reading resource item data\n");
            freeResourceBundle(bundle);
            return NULL;
        }

        // add the item to the bundle and update counts
        pthread_mutex_lock(&bundle->mutex);
        bundle->items = realloc(bundle->items, sizeof(ResourceItem) * (bundle->totalItemCount + 1));
        bundle->items[bundle->totalItemCount].type = type;
        bundle->items[bundle->totalItemCount].data = data;
        ++bundle->itemCount[type];
        ++bundle->totalItemCount;
        pthread_mutex_unlock(&bundle->mutex);
    }

    fclose(fp);
    return bundle;
}
```

The `freeResourceBundle` function can be implemented as follows:

```c
void freeResourceBundle(ResourceBundle* bundle) {
    if (bundle == NULL) return;

    for (size_t i = 0; i < bundle->totalItemCount; ++i) {
        free(bundle->items[i].data);
    }

    free(bundle->items);
    pthread_mutex_destroy(&bundle->mutex);
    free(bundle);
}
```

