public class Game {
    private static final Logger logger = Logger.getLogger(Game.class.getName());
    private final Selector selector;
    private final SocketChannel channel;
    private final ScheduledExecutorService executor;

    public Game() throws IOException {
        this.selector = Selector.open();
        this.channel = SocketChannel.open(new InetSocketAddress("remote_address", 1234));
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT | SelectionKey.OP_READ | SelectionKey.OP_WRITE);
        this.executor = Executors.newSingleThreadScheduledExecutor();
    }

    public void handleConnectionStateChanges() throws IOException {
        while (true) {
            if (selector.selectNow() > 0) { // Non-blocking I/O operation
                Set<SelectionKey> keys = selector.selectedKeys();
                Iterator<SelectionKey> iterator = keys.iterator();

                while (iterator.hasNext()) {
                    SelectionKey key = iterator.next();

                    if (key.isConnectable()) { // Connection state change detected
                        handleConnect(key);
                    } else if (key.isReadable()) { // Data received from server
                        handleRead(key);
                    } else if (key.isWritable()) { // Ready to send data to server
                        handleWrite(key);
                    }

                    iterator.remove();
                }
            }
        }
    }

    private void handleConnect(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();

        if (channel.isConnectionPending()) { // Connection established
            channel.finishConnect();
        }

        channel.register(selector, SelectionKey.OP_READ);
    }

    private void handleRead(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        int numRead = -1;
        while ((numRead = channel.read(buffer)) != -1) { // Read data from server
            byte[] data = new byte[numRead];
            System.arraycopy(buffer.array(), 0, data, 0, numRead);

            // Process received data...
        }
    }

    private void handleWrite(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();

        // Send data to server...
    }
}
