```java
import java.io.IOException;
import java.net.*;
import java.nio.channels.SocketChannel;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import javax.net.ssl.*;
import static java.lang.Runtime.getRuntime;

public class ConnectionPool {
    private final SSLContext sslContext;
    private ConcurrentLinkedQueue<SocketChannel> pool = new ConcurrentLinkedQueue<>();

    public ConnectionPool(int initialSize, Properties properties) throws NoSuchAlgorithmException {
        this.sslContext = SSLContext.getDefault();

        for (int i = 0; i < initialSize; i++) {
            pool.add(createChannel(properties));
        }
    }

    private SocketChannel createChannel(Properties properties) throws NoSuchAlgorithmException {
        try {
            SocketChannel channel = SocketChannel.open();

            String host = properties.getProperty("server_host");
            int port = Integer.parseInt(properties.getProperty("server_port"));

            SSLSocketFactory sslSocketFactory = sslContext.getSocketFactory();

            InetSocketAddress address = new InetSocketAddress(host, port);
            ((SSLSocket)sslSocketFactory.createSocket()).connect(address);

            return channel;
        } catch (IOException e) {
            throw new RuntimeException("Cannot create channel", e);
        }
    }

    public SocketChannel acquire() throws InterruptedException {
        return pool.poll();
    }

    public void release(SocketChannel socketChannel) {
        if (socketChannel != null) {
            this.pool.offer(socketChannel);
        }
    }
}
```
This class uses the NIO library to establish SSL connections with a remote server and maintains a pool of these connections. The `acquire()` method returns an available connection from the pool, while the `release()` method takes back a used connection into the pool for reuse.

