using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

public class SiteManager
{
    private static readonly Regex nameRegex = new Regex("^[a-zA-Z0-9_-]*$");
    private static SemaphoreSlim semaphore = new SemaphoreSlim(1, 1); // One concurrent operation allowed.

    public async Task AddSiteAsync(string directoryPath, string siteName, int basePort)
    {
        if (!Directory.Exists(directoryPath))
            throw new ArgumentException("Invalid directory path", nameof(directoryPath));

        if(!nameRegex.IsMatch(siteName))
            throw new ArgumentException("Site name contains invalid characters");

        await semaphore.WaitAsync(); 

        try
        {
            // Ensure exclusive access to the directory.
            var fileLock = new FileStream(directoryPath + ".lock", FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None);

            string webConfigPath = $"{directoryPath}/web.config";
            if (!File.Exists(webConfigPath)) 
            {
                // Retrieve default settings from external config system. For the sake of simplicity let's assume this method exists and is async.
                await IntegrateWithExternalSystemAsync();
            }

            int port = await GetAvailablePortAsync(basePort);

            var startInfo = new ProcessStartInfo
            {
                FileName = "dotnet", // Or any other command to start your site
                Arguments = $"YourSite.dll --urls http://localhost:{port}", 
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true
            };

            using (var exeProcess = Process.Start(startInfo))
            {
                var timeoutCts = new CancellationTokenSource(TimeSpan.FromSeconds(60)); // Timeout after 60 seconds.

                string output = await exeProcess.StandardOutput.ReadToEndAsync();
                string err = await exeProcess.StandardError.ReadToEndAsync();
                bool processExited = exeProcess.WaitForExit(timeoutCts.Token); // Will throw if the process times out.

                if (!processExited) 
                    Console.WriteLine("Site start timed out");

                // Log output and errors.
            }
        }
        catch (Exception e)
        {
            Console.WriteLine($"Error occurred while adding site: {e}");
        }
        finally
        {
            semaphore.Release(); 
        }
    }

    // Assuming there is an existing method that gets available port, which we should call asynchronously to avoid blocking other operations.
    private Task<int> GetAvailablePortAsync(int basePort) => Task.FromResult(basePort);

    // Assuming this external system integration process takes a while and doesn't block the main thread.
    private Task IntegrateWithExternalSystemAsync() => Task.CompletedTask;
}
