public class DynamicResourcePoolManager {
    private ReadWriteLock lock = new ReentrantReadWriteLock();
    private Map<Integer, List<Connection>> resourcePools = new HashMap<>();

    public interface ConnectionConfigCallback {
        ConnectionConfig modify(ConnectionConfig config);
    }

    public interface ConnectionHealthChecker {
        boolean isHealthy(Connection conn);
