    private void initializeResourcePool(int minConnections, int maxConnections, long timeout) {
        if (minConnections < 0 || maxConnections < minConnections) {
            throw new IllegalArgumentException("Invalid connection values");
        }

        lock.writeLock().lock();
        try {
            for(int i = 0; i < minConnections; i++) {
                Connection conn = createConnection(timeout);
                List<Connection> pool = resourcePools.getOrDefault(minConnections, new ArrayList<>());
                pool.add(conn);
                resourcePools.putIfAbsent(minConnections, pool);
            }
        } finally {
            lock.writeLock().unlock();
        }
