```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.*;

public class NonBlockingIOConnectionPool {
    private final int poolSize;
    private final ExecutorService executorService;
    private AsynchronousChannelGroup channelGroup;

    public NonBlockingIOConnectionPool(int poolSize) throws IOException {
        this.poolSize = poolSize;
        this.executorService = Executors.newFixedThreadPool(poolSize);

        try {
            this.channelGroup = AsynchronousChannelGroup.withCachedThreadPool(this.executorService, 1);
        } catch (IOException e) {
            throw new IllegalStateException("Failed to create channel group", e);
        }
    }

    public CompletableFuture<AsynchronousSocketChannel> acquireConnection(String host, int port) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                AsynchronousSocketChannel socketChannel = AsynchronousSocketChannel.open(channelGroup);
                InetSocketAddress address = new InetSocketAddress(host, port);

                Future<Void> connectFuture = socketChannel.connect(address);
                while (!connectFuture.isDone()) {
                    // This is a blocking call but we're in a different thread so it won't block the whole system
                    Thread.sleep(10); 
                }

                return socketChannel;
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException("Failed to acquire connection", e);
            }
        }, executorService);
    }

    public void releaseConnection(AsynchronousSocketChannel channel) {
        try {
            channel.close();
        } catch (IOException e) {
            // Handle error if needed
        }
    }
}
