        string iv = await FetchIvFromApi("ivEndpoint");

        // Decrypt ciphertext with the provided key and IV
        string decryptedText = Decrypt(Convert.FromBase64String(cipherText), Convert.FromBase64String(key), Convert.FromBase64String(iv));
    }

    private static async Task<string> FetchCipherFromApi(string endpoint)
    {
        HttpResponseMessage response = await client.GetAsync(baseUri + "/" + endpoint);
        if (!response.IsSuccessStatusCode)
            throw new Exception("API request failed");

        return await response.Content.ReadAsStringAsync();
    }

    private static async Task<string> FetchKeyFromApi(string endpoint)
    {
        HttpResponseMessage response = await client.GetAsync(baseUri + "/" + endpoint);
        if (!response.IsSuccessStatusCode)
            throw new Exception("API request failed");

        return await response.Content.ReadAsStringAsync();
    }

    private static async Task<string> FetchIvFromApi(string endpoint)
    {
        HttpResponseMessage response = await client.GetAsync(baseUri + "/" + endpoint);
        if (!response.IsSuccessStatusCode)
            throw new Exception("API request failed");

        return await response.Content.ReadAsStringAsync();
    }

    private static string Decrypt(byte[] cipherText, byte[] Key, byte[] IV)
    {
        using (AesCryptoServiceProvider aes = new AesCryptoServiceProvider())
        {
            aes.KeySize = 256;
            aes.BlockSize = 128;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            aes.Key = Key;
            aes.IV = IV;

            using (ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            {
                return Encoding.Default.GetString(ProcessData(cipherText, decryptor));
            }
        }
    }

    private static byte[] ProcessData(byte[] data, ICryptoTransform cryptoTransform)
    {
        using (MemoryStream memoryStream = new MemoryStream())
        using (CryptoStream cryptoStream = new CryptoStream(memoryStream, cryptoTransform, CryptoStreamMode.Write))
        {
            cryptoStream.Write(data, 0, data.Length);
            cryptoStream.FlushFinalBlock();

            return memoryStream.ToArray();
        }
    }
}
```

