async function fetchScripts(scripts) {
    let loadedScriptPromises = scripts.map((script, index) => {
        if (!script || !script.src && !script.code) throw new Error('Missing essential properties');

        return new Promise((resolve, reject) => {
            // Check cache before fetching script

            let cachedScript = getCachedScript(script);

            if (cachedScript) {
                resolve(cachedScript);
                return;
            } 

            // Fetch and load scripts asynchronously

            const scriptElement = document.createElement('script');

            scriptElement.onload = () => {
                console.log(`Script ${index} loaded successfully`)
                resolve(script);
            };

            scriptElement.onerror = (e, src) => {
                console.error(`Error loading script ${src}: ${e}`);
                reject(e);
            }

            if (script.type) scriptElement.type = script.type;
            if (script.code) scriptElement.innerHTML = script.code;
            else {
                // Fetch and load scripts from an external API endpoint

                scriptElement.src = script.src;
                document.head.appendChild(scriptElement);
            }
        });
    });

    return await Promise.allSettled(loadedScriptPromises); 
}
