import json
import asyncio
from concurrent.futures import ThreadPoolExecutor
from collections import defaultdict
import logging as log

class JsonObject:
    _factories = {}

    @classmethod
    def add_factory(cls, id, factory):
        cls._factories[id] = factory

    @classmethod
    async def create_from_file(cls, filename):
        loop = asyncio.get_event_loop()
        with open(filename) as f:
            data = await loop.run_in_executor(ThreadPoolExecutor(), json.load, f)
        return cls(data)

    def __init__(self, data):
        self._data = data

    def to_json(self):
        return json.dumps(self._data)

    @classmethod
    async def create_from_id(cls, id):
        factory = cls._factories[id]
        return await factory()
