const express = require('express');
const app = express();
app.use(express.json());

let resources = {}; // In-memory storage for demonstration purposes

// PUT method to update a resource
app.put('/resource/:id', (req, res) => {
    const id = req.params.id;
    const version = req.query.version;
    const newData = req.body;

    if (!resources[id]) return res.status(404).send('Resource not found');
    if (version && resources[id].version !== version) 
        return res.status(412).send('Version mismatch, please fetch the latest resource and try again');

    // Update the resource
    newData.version = (resources[id].version || 0) + 1;
    resources[id] = Object.assign({}, resources[id], newData);

    console.log(`Resource ${id} updated`);
    res.send('Resource updated successfully');
});

// DELETE method to delete a resource
app.delete('/resource/:id', (req, res) => {
    const id = req.params.id;

    if (!resources[id]) return res.status(404).send('Resource not found');
    if (new Date() < resources[id].lastFetchTime) 
        return res.status(409).send('Resource has been modified, please fetch the latest resource and try again');

    delete resources[id];

    console.log(`Resource ${id} deleted`);
    res.send('Resource deleted successfully');
});

app.listen(3000, () => console.log('Server listening on port 3000'));
```
