```C#
using System;
using Microsoft.AspNetCore.Mvc;
using HtmlSanitizer;
using Microsoft.Extensions.Logging;
using AspNetCoreRateLimit;
using System.Threading.Tasks;
using Serilog;
using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Identity;
using IdentityServer4.Services;
using Microsoft.EntityFrameworkCore;

public class UpdateController : Controller
{
    private readonly IHtmlSanitizer _htmlSanitizer;
    private readonly IRateLimitProcessor _rateLimitProcessor;
    private readonly UserManager<ApplicationUser> _userManager;
    private readonly ILogger<UpdateController> _logger;
    private readonly ApplicationDbContext _dbContext;

    public UpdateController(IHtmlSanitizer htmlSanitizer, IRateLimitProcessor rateLimitProcessor, 
        UserManager<ApplicationUser> userManager, ILogger<UpdateController> logger, 
        ApplicationDbContext dbContext)
    {
        _htmlSanitizer = htmlSanitizer;
        _rateLimitProcessor = rateLimitProcessor;
        _userManager = userManager;
        _logger = logger;
        _dbContext = dbContext;
    }

    [HttpPost]
    public async Task<IActionResult> UpdateElement([Required] string sectionId, [Required] string elementId, 
        [Required] string htmlContent)
    {
        var user = await _userManager.GetUserAsync(User);
        if (user == null)
        {
            return Unauthorized();
        }

        // Rate limiting logic
        var ipAddress = HttpContext.Connection?.RemoteIpAddress?.ToString();
        var rateLimitResult = await _rateLimitProcessor.ProcessRequestAsync(ipAddress, "UpdateElement");
        if (!rateLimitResult.IsSuccessStatusCode)
        {
            return StatusCode((int) rateLimitResult.StatusCode, 
                "Too many requests. Please try again later.");
        }

        // Decrypting and sanitizing HTML content
        var decryptedContent = TripleDESService.Decrypt(htmlContent);
        var sanitizedContent = _htmlSanitizer.Sanitize(decryptedContent);

        if (sanitizedContent != decryptedContent)
        {
            return BadRequest("Provided HTML content is not valid.");
        }

        try
        {
            // Updating element in the database 
            var pageSection = await _dbContext.PageSections.FirstOrDefaultAsync(ps => ps.Id == sectionId);
            if (pageSection != null)
            {
                var element = pageSection.Elements.FirstOrDefault(e => e.Id == elementId);
                if (element != null)
                {
                    element.HtmlContent = sanitizedContent;
                    await _dbContext.SaveChangesAsync();

                    // Logging successful update 
                    _logger.LogInformation("Successfully updated HTML content of the element with ID: " +
                        + $"{elementId} by user {user.UserName} at {DateTime.Now}");
                }
            }
        }
        catch (Exception ex)
        {
            // Logging and returning error message 
            _logger.LogError(ex, "An error occurred while updating the element.");
            return StatusCode(500, "An unexpected error occurred on the server.");
        }

        return Ok("Element updated successfully!");
    }
}
```
