#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <stdexcept>

void process_file(const std::string& filename) {
    std::ifstream file(filename);

    if (!file.is_open()) {
        throw std::runtime_error("Could not open the file.");
    }

    int maxNum = INT32_MIN;  // smallest possible int
    long total = 0;
    int count = 0;
    try{
        while (true) {
            int number;
            if (!(file >> number)) {
                break;
            }
            maxNum = std::max(maxNum, number);
            total += number;
            ++count;
        }
    } catch (const std::ifstream::failure& e) {
        throw std::runtime_error("Error reading from file.");
    }

    if (!file.eof()) {
        throw std::runtime_error("Error reading from file.");
    }

    double average = static_cast<double>(total) / count;
    std::cout << "Largest number: " << maxNum << "\n";
    std::cout << "Average: " << average << "\n";
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <filename>\n";
        return EXIT_FAILURE;
    }

    try{
       process_file(argv[1]);
    } catch (const std::exception& e) {
        std::cerr << e.what() << "\n";
        return EXIT_FAILURE;
    }
}
