from typing import Any, Dict, Optional

class JsonFactoryObject(object):
    _registry = {}  # A registry mapping factory functions to their IDs.

    def __init__(self, **kwargs: Any) -> None:
        self.__dict__ = kwargs

    @staticmethod
    def add_factory(id: str, func: 'function') -> None:
        JsonFactoryObject._registry[id] = func

    @classmethod
    def from_json(cls, json_str: str) -> 'JsonFactoryObject':
        return cls(**json.loads(json_str))

    def to_json(self) -> str:
        return json.dumps(self.__dict__)

class JsonFactorySubObject(JsonFactoryObject):
    pass

def load_files(*filenames: str, password: str = None) -> Dict[str, Any]:
    """Loads and executes multiple JSON files in a web application context."""

    def _load_file(filename: str) -> Optional[JsonFactoryObject]:
        try:
            with open(filename, 'r') as file:
                json_data = json.load(file)

            # Detect circular dependency.
            if filename in loaded_files:
                raise Exception("Circular dependency detected.")

            loaded_files.add(filename)

            # Parallel loading... (Not shown here)

            obj = JsonFactorySubObject.from_json(json.dumps(json_data))
            if password:
                hasher = hashlib.sha256()
                hasher.update(password.encode('utf-8'))
                random_string = ''.join(random.choice(string.ascii_letters) for _ in range(10))

                obj.hashed_pw = hasher.hexdigest()
                obj.random_str = random_string

            return obj
        except Exception as e:
            print(f"Error loading {filename}: {e}")
            return None

    loaded_files = set()

    # Parallel execution... (Not shown here)

    results = {}
    for filename in filenames:
        obj = _load_file(filename)
        if obj is not None:
            print(f"Loaded {filename}.")
            results[filename] = obj.to_json()

    return results
