```csharp
using System;
using System.Collections.Generic;
using System.Text;
using System.Linq;
using HtmlAgilityPack; // Consider this library to parse and manipulate DOM tree

public class DataPointGenerator
{
    private readonly Random _random = new Random();
    private int _min, _max;
    private readonly object _lockObject = new object();

    public DataPointGenerator(int min, int max)
    {
        if (min > max) throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        this._min = min;
        this._max = max;
    }

    public float GenerateRandomFloat()
    {
        lock (_lockObject)
        {
            return (float)(_random.NextDouble() * (_max - _min) + _min);
        }
    }

    public int GenerateRandomInt()
    {
        lock (_lockObject)
        {
            return _random.Next(_min, _max + 1);
        }
    }

    public IEnumerable<float> GenerateManyFloats(int count)
    {
        float[] values = new float[count];

        lock (_lockObject)
        {
            for (var i = 0; i < count; ++i)
                values[i] = GenerateRandomFloat();
        }

        return values.AsEnumerable();
    }

    public IEnumerable<int> GenerateManyInts(int count)
    {
        int[] values = new int[count];

        lock (_lockObject)
        {
            for (var i = 0; i < count; ++i)
                values[i] = GenerateRandomInt();
        }

        return values.AsEnumerable();
    }

    public override string ToString()
    {
        lock (_lockObject)
        {
            return $"Range: [{_min}, {_max}]";
        }
    }
}
```
