public IEnumerable<HtmlNode> SelectMatchingElements(HtmlDocument document, string selector)
{
    var stack = new Stack<HtmlNode>();
    stack.Push(document.DocumentNode);

    while (stack.Count > 0)
    {
        HtmlNode currentNode = stack.Pop();

        if (TestSelector(currentNode, selector)) yield return currentNode; // Test with callback function

        foreach (HtmlNode child in currentNode.ChildNodes)
            stack.Push(child);
    }
}
```
