<?php
require 'vendor/autoload.php'; // include OAuth library

use League\OAuth2\Client\Provider\GenericProvider;
use Symfony\Component\HttpFoundation\Session\Session;
use Monolog\Logger;
use Monolog\Handler\StreamHandler;

class Authentication {
    private $provider; // instance of OAuth provider
    private $session; // instance of session manager
    private $logger; // logger instance

    public function __construct() {
        $this->provider = new GenericProvider([
            'clientId'                => 'YOUR_CLIENT_ID', 
            'clientSecret'            => 'YOUR_SECRET',
            'redirectUri'             => 'http://yourwebsite.com/callback',
            'urlAuthorize'            => 'https://oauthserver.example.com/authorization',
            'urlAccessToken'          => 'https://oauthserver.example.com/token',
            'urlResourceOwnerDetails' => 'https://oauthserver.example.com/resource',
        ]);

        $this->session = new Session(); // initialize session

        $this->logger = new Logger('Authentication'); // logger instance
        $this->logger->pushHandler(new StreamHandler(__DIR__.'/logs/auth.log', Logger::DEBUG));
    }

    public function authenticateUser() {
        if (!isset($_GET['code'])) {
            $authorizationUrl = $this->provider->getAuthorizationUrl();
            header('Location: '.$authorizationUrl);
            exit;
        } elseif (empty($_GET['state']) || $_GET['state'] !== $this->session->get('oauth2state')) {
            $this->logger->error('Invalid state'); // log error
            unset($_SESSION['oauth2state']); // remove invalid session state
            exit('Invalid state');
        } else {
            try {
                $accessToken = $this->provider->getAccessToken('authorization_code', [
                    'code' => $_GET['code']
                ]);

                $resourceOwner = $this->provider->getResourceOwner($accessToken); // get user info

                // sanitize and store user data
                $userData = htmlspecialchars(json_encode($resourceOwner->toArray()), ENT_QUOTES, 'UTF-8');

                // securely store the token in a session variable
                $this->session->set('accessToken', $accessToken);

                return true; // authentication successful
            } catch (Exception $e) {
                $this->logger->error($e->getMessage()); // log error
                exit('Failed to authenticate user');
            }
        }
    }
}
?>
```

