```cpp
void NodeManager::serializeToJSON(rapidjson::Document& doc) const {
    // Clear the document if it's not empty to start with a fresh slate
    doc.SetArray();

    for (size_t i = 0; i < size_; ++i) {
        rapidjson::Value node(rapidjson::kObjectType);

        node.AddMember("key", nodes_[i].key, doc.GetAllocator());
        node.AddMember("value", rapidjson::StringRef(nodes_[i].value.c_str()), doc.GetAllocator());

        doc.PushBack(node, doc.GetAllocator());
    }
}
