Deserialization is a bit more complex since you're creating nodes from JSON:
```cpp
void NodeManager::deserializeFromJSON(const rapidjson::Document& doc) {
    // Clear existing data before adding new
    delete[] nodes_;

    size_ = doc.Size();
    capacity_ = 2 * size_;  // Start with twice the number of nodes for future resizing
    nodes_ = new Node[capacity_];

    for (rapidjson::SizeType i = 0; i < size_; ++i) {
        nodes_[i].key = doc[i]["key"].GetInt();
        nodes_[i].value = doc[i]["value"].GetString();
    }
}
