```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "jansson.h" // JSON library

typedef struct {
    char* key;
    union {
        int i;
        double d;
        char* s;
    } value;
} Item;

int loadBundle(const char *filepath, Item **bundle) {
    FILE *fp = fopen(filepath, "r"); // Open the file for reading
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    json_error_t error;
    json_t *root = json_loadf(fp, 0, &error); // Load the JSON data from file
    fclose(fp);

    if(!root) {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        return -1;
    }

    if (!json_is_object(root)) {
        fprintf(stderr, "Error: root is not an object\n");
        json_decref(root);
        return -1;
    }

    const char *key;
    json_t *value;

    int numItems = json_object_size(root);
    *bundle = malloc(numItems * sizeof(Item)); // Allocate memory for the bundle
    int i = 0;
    json_object_foreach(root, key, value) {
        (*bundle)[i].key = strdup(key);

        if (json_is_integer(value)) {
            (*bundle)[i].value.i = json_integer_value(value);
        } else if (json_is_real(value)) {
            (*bundle)[i].value.d = json_real_value(value);
        } else if (json_is_string(value)) {
            (*bundle)[i].value.s = strdup(json_string_value(value));
        } else {
            fprintf(stderr, "Error: unsupported item type\n");
            json_decref(root);
            free(*bundle); // Clean up the bundle
            return -1;
        }
        ++i;
    }

    json_decref(root);
    return numItems;
}
```
This code opens a file, reads JSON data from it using Jansson library, and populates an array of Items with the extracted data. Each item is identified by a key and can contain either an integer, double or string as its value. Error handling is implemented in case of invalid files, corrupted data, missing files, incorrect formats etc. The function will return -1 if any error occurs, else it will return the number of items loaded from file.

