lock = Lock()
tmp_dirs = []  # a list to store paths of directories created by this process for cleanup later.
env_var = ""   # a variable to hold environment variable name.

def create_directory(name, parent=None):
    global env_var

    while True:
        try:
            if lock.acquire(blocking=False):  # attempt to acquire the mutex lock for exclusive access
                path = os.path.join(parent or ".", name)

                # create directory
                os.makedirs(path, exist_ok=True)
                tmp_dirs.append(path)

                # set environment variable
                env_var = f"{name}_PATH" 
                os.environ[env_var] = path

            return True
        except Exception as e:  # handle specific exceptions or general exception to retry on transient errors
            print(f"Failed to create directory due to {e}. Retrying...")
            time.sleep(1)  # sleep for a while before retrying
        finally:
            if lock.locked():
                lock.release()

def filter_transactions(*args, **kwargs):
