Here's an example of how you might write such a method in C#. For simplicity, it assumes that all parameters are strings, but could be generalized to support other types as needed. It also uses a simple schema validation mechanism to check input parameter names against a predefined list and logs any invalid parameter names:

```csharp
public async Task<List<CustomObject>> ExecuteStoredProcedureAsync(SqlConnection connection, List<KeyValuePair<string, string>> parameters, string procedureName)
{
    // Validate input parameters against a predefined schema
    var validParameterNames = new[] { "param1", "param2", /* other expected parameter names */ };
    foreach (var param in parameters)
    {
        if (!validParameterNames.Contains(param.Key))
            throw new ArgumentException($"Invalid parameter name: {param.Key}");
    }

    // Set up a command and its parameters, based on the input
    using (var cmd = connection.CreateCommand())
    {
        cmd.CommandType = CommandType.StoredProcedure;
        cmd.CommandText = procedureName;

        foreach (var param in parameters)
        {
            var sqlParam = new SqlParameter(param.Key, param.Value);
            cmd.Parameters.Add(sqlParam);
        }

        try
        {
            // Execute the stored procedure asynchronously and retrieve its results
            connection.Open();
            using (var reader = await cmd.ExecuteReaderAsync())
            {
                var results = new List<CustomObject>();
                while (await reader.ReadAsync())
                {
                    var customObj = new CustomObject() 
                    { 
                        Property1 = reader["ColumnName1"].ToString(),
                        Property2 = Convert.ToInt32(reader["ColumnName2"])
                        // Populate other properties as needed
                    };
                    results.Add(customObj);
                }

                Logger.LogInformation("Stored procedure {0} executed successfully", procedureName);
                return results;
            }
        }
        catch (Exception e)
        {
            // Handle and log any exceptions that occur during execution
            Logger.LogError(e, "Failed to execute stored procedure {0}", procedureName);
            throw;
        }
    }
}
```
