class WeatherMonitor:
    def __init__(self, cities):
        self.cities = cities
        self.apis = [OpenWeatherMap(), WeatherAPI(), AccuWeather()] # list of available APIs
        self.cache = {}

    def get_weather(self, city):
        for api in self.apis:
            if api.is_available():
                key = (city, api)

                if key not in self.cache or time() - self.cache[key]['time'] > api.get_ttl():
                    self.cache[key] = {'data': api.get_weather(city), 'time': time()}

                return self.cache[key]['data']

    def start_monitoring(self):
        threads = []

        for city in self.cities:
            thread = Thread(target=self.get_weather, args=(city,))
            thread.start()
            threads.append(thread)

        for thread in threads:
            thread.join()
