```rust
use std::{env, fs, io, path::PathBuf};
use std::sync::Mutex;
use std::thread;
use std::time::Duration;
use rand::Rng;
use once_cell::sync::Lazy;
use log::LevelFilter;
use env_logger::Builder;
use lazy_static::lazy_static;

// Initialize logger
pub static LOGGER: Lazy<Mutex<Option<()>>> = Lazy::new(|| Mutex::new(None));

fn init_logger() -> Result<(), io::Error> {
    Builder::new().filter_level(LevelFilter::Info).init();
    Ok(())
}

// Fetch or create the work dir 
pub fn get_workdir() -> PathBuf {
    lazy_static::lazy_static ref WORKDIR: Mutex<Option<PathBuf>> = Mutex::new(None);

    if let Some(work_dir) = *WORKDIR.lock().unwrap() {
        work_dir
    } else {
        let mut rng = rand::thread_rng();
        let random_string: String = (0..16).map(|_| rng.gen_range('a'..='z') as char).collect();
        let tmp_dir = PathBuf::from("/tmp").join(&random_string);
        fs::create_dir_all(&tmp_dir).expect("Unable to create work directory");
        *WORKDIR.lock().unwrap() = Some(tmp_dir);
        tmp_dir
    }
}

// Clean up the directory 
fn cleanup_workdir() {
    let mutex_guard = WORKDIR.lock().unwrap();
    if let Some(ref workdir) = *mutex_guard {
        thread::spawn(move || -> io::Result<()>{
            thread::sleep(Duration::from_secs(10));  // sleep for 10 seconds
            fs::remove_dir_all(&workdir).expect("Failed to remove work directory");
            Ok(())
        });
    }
}
```
In this code, we first initialize a logger using the `env_logger` crate. Next, we create a thread-safe `WORKDIR` that holds an optional PathBuf. If it's None (meaning we haven't created our directory yet), we generate a random string and create a directory under `/tmp` with this name. 

The `cleanup_workdir()` function will spawn a new thread that waits for 10 seconds before deleting the workdir, allowing your pipeline to still access it during this time. This is just an example of what you might do and doesn't cover all the points you mentioned. For a full implementation, you would need to build out models for CI/CD systems, handle errors more gracefully, create unit tests, etc.

