import logging
from abc import ABC, abstractmethod

class JsonSerializable(ABC):
    @abstractmethod
    def to_json(self):
        pass

    @staticmethod
    @abstractmethod
    def from_json(data):
        pass

def register(cls):
    if not hasattr(register, 'registry'):
        register.registry = {}
    register.registry[cls.__name__] = cls

class User(JsonSerializable):
    def __init__(self, name, email):
        self.name = name
        self.email = email

    @staticmethod
    def from_json(data):
        return User(**json.loads(data))

    def to_json(self):
        return json.dumps(self.__dict__)

class Product(JsonSerializable):
    # Similar to the User class but different attributes

register(User)
# Register other classes similarly...

async def load_file(path, factory):
    try:
        with open(path, 'r') as f:
            data = await asyncio.sleep(10)  # Simulating IO operation
            return factory.from_json(data)
    except Exception as e:
        logging.error(f"Failed to load file {path}: {e}")

async def main():
    paths = [...]  # List of paths to JSON files here
    factories = [User for _ in paths]  # List of corresponding factory functions here

    tasks = [load_file(p, f) for p, f in zip(paths, factories)]
    results = await asyncio.gather(*tasks, return_exceptions=True)

    instances = [r for r in results if isinstance(r, JsonSerializable)]
