Here is a Python solution using queue.Queue to store incoming data points, threading.Thread to process these data in parallel, and built-in collections.deque for moving average calculation. For API authentication and rate limiting, requests library is used. Logging mechanism will be implemented with logging module. To ensure thread safety when updating the cache, a lock (threading.Lock) is used. 

```python
import queue
import threading
import collections
from time import sleep
import requests
import logging

# Set up logger
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DataProcessor:
    def __init__(self):
        self.data_queue = queue.Queue()
        self.cache = collections.defaultdict(collections.deque)
        self.lock = threading.Lock()

    # Add stock data to the queue
    def add_stock_data(self, data):
        self.data_queue.put(data)

    # Process each incoming data point in a separate thread
    def process_data(self):
        while True:
            try:
                data = self.data_queue.get()

                if 'symbol' not in data or 'closingPrice' not in data:
                    logger.warning('Data is missing symbol or closing price')
                    continue

                # Calculate moving average of the closing price over past 10 minutes
                with self.lock:
                    self.cache[data['symbol']].append(data['closingPrice'])
                    if len(self.cache[data['symbol']]) > 600:
                        self.cache[data['symbol']].popleft()

            except Exception as e:
                logger.error('Error processing data', exc_info=True)

    # Start a new thread for each incoming data point
    def start(self):
        while True:
            t = threading.Thread(target=self.process_data)
            t.start()

class FinancialAPI:
    def __init__(self, auth, rate_limit):
        self.auth = auth
        self.rate_limit = rate_limit

    # Retrieve historical stock prices from API
    def get_historical_prices(self, symbol):
        try:
            response = requests.get('https://api.financial/data', headers={'Authorization': 'Bearer {}'.format(self.auth)}, params={'symbol': symbol})

            if response.status_code != 200:
                logger.error('Failed to retrieve historical prices for %s' % symbol)
                return []

            self.rate_limit -= 1
            sleep(self.rate_limit > 0) # Sleep if rate limit is reached

            return response.json()['data']

        except Exception as e:
            logger.error('Failed to connect to API', exc_info=True)
            return []

    # Initialize the cache with historical stock prices from API
    def initialize_cache(self, symbols):
        for symbol in symbols:
            self.processor.add_stock_data({'symbol': symbol, 'closingPrice': self.get_historical_prices(symbol)})
```
Note: The above code is a rough sketch and might not work as expected due to the nature of real-time data processing. Actual implementation requires more detailed design and careful consideration for error handling, thread safety, performance optimization, and other factors.

```rust
use std::collections::HashMap;
use tokio::sync::RwLock;
use tokio_postgres::{NoTls, Error};
use futures::FutureExt;
use std::time::Duration;
use rand::seq::SliceRandom;
use dotenv::dotenv;
use std::env;

struct DatabaseConnectionManager {
    connections: HashMap<String, Vec<RwLock<Option<NoTls>>>>,
}

impl DatabaseConnectionManager {
    async fn get_connection(&self, provider: &str, connection_string: &str) -> Result<NoTls, Error> {
        let mut rng = rand::thread_rng();
        let connections = self.connections.get(provider).unwrap();
        if !connections.is_empty() {
            match connections[rng.gen_range(0..connections.len())].read().await.as_ref().unwrap() {
                Some(conn) => Ok(*conn),
                None => Err(Error::ConnectionError("No connection available".into()))
            }
        } else {
            match NoTls::connect(&connection_string, NoTls).await {
                Ok((_, conn)) => {
                    connections.push(RwLock::new(Some(conn)));
                    Ok(conn)
                },
                Err(e) => Err(Error::ConnectionError(formatargs![e])),
            }
        }
    }

    async fn release_connection(&self, provider: &str, connection: NoTls) {
        let connections = self.connections.get(provider).unwrap();
        for lock in connections {
            if let Some(conn) = lock.read().await.as_ref() {
                if conn == &connection {
                    lock.write().await.take();
                    break;
                }
            }
        }
    }

    fn to_string(&self) -> String {
        let mut result = String::new();
        for (provider, connections) in &self.connections {
            result += &formatargs![provider, ":\n"];
            for connection in connections {
                match connection.read().await {
                    Some(conn) => result += &formatargs![conn],
                    None => result += "Not connected\n",
                }
            }
        }
        result
    }

    fn initialize_from_configuration(&mut self) {
        dotenv().ok();
        for provider in ["mysql", "postgresql", "sqlite"] {
            let connection_string = env::var(provider).unwrap_or("localhost".to_owned());
            match self.get_connection(provider, &connection_string).await {
                Ok(_) => (),
                Err(e) => eprintln![e],
            }
        }
    }

    fn configure_pooling(&mut self, min_size: usize, max_size: usize, idle_timeout: Duration) {
        for provider in &self.connections.keys() {
            let connections = self.connections.get(provider).unwrap();
            if connections.len() < min_size {
                for _ in 0..min_size - connections.len() {
                    match self.get_connection(provider, "localhost").await {
                        Ok(_) => (),
                        Err(e) => eprintln![e],
                    }
                }
            } else if connections.len() > max_size {
                for _ in 0..connections.len() - max_size {
                    match self.get_connection(provider, "localhost").await {
                        Ok(_) => (),
                        Err(e) => eprintln![e],
                    }
                }
            }
        }
    }

    fn get_performance_metrics(&self) -> String {
        let mut result = String::new();
        for (provider, connections) in &self.connections {
            result += &formatargs![provider, ":\n"];
            result += &formatargs![connections.len()];
            let idle_count = connections.iter().filter(|conn| conn.read().await.is_none()).count();
            result += &formatargs![idle_count];
        }
        result
    }
}
```

