        $randomBytes = random_bytes(ceil($length / 2)); // Cryptographically secure
        return substr(bin2hex($randomBytes), 0, $length);
    } catch (Exception $e) {
        error_log("Error generating salt: " . $e->getMessage());
        throw new Exception('Failed to generate a salt');
    }
