        $token = '';
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = random_int(0, strlen($availableChars) - 1);
            $token .= $availableChars[$randomIndex];
        }

        return $token;
    }

    public function getAvailableCharactersFor($charset) {
        $selectedCharsets = array_filter($this->charsets, function ($key) use ($charset) {
            return in_array($key, $charset);
        }, ARRAY_FILTER_USE_KEY);

        return implode('', $selectedCharsets);
    }

    public function hashPassword($password, $algorithm = PASSWORD_BCRYPT) {
        return password_hash($password, $algorithm);
    }
}
