function readDirectoryContents (directoryPath) {
  const files = fs.readdirSync(directoryPath);
  let resultStrings = '';

  for (let i = 0; i < files.length; ++i) {
    const filePath = path.join(directoryPath, files[i]);
    if (fs.lstatSync(filePath).isDirectory()) {
      resultStrings += readDirectoryContents(filePath);  // recursively reading subdirectories
    } else {
      const contentBuffer = fs.readFileSync(filePath);
      resultStrings += contentBuffer.toString();
    }
  }

  return resultStrings;
}
