```java
import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousFileChannel;
import java.nio.file.Paths;
import java.util.concurrent.Future;
import java.util.logging.Logger;

public class GameClient {
    private static final Logger LOGGER = Logger.getLogger(GameClient.class.getName());
    // Simplified game server API, replace with your actual API interface
    private GameServerAPI gameServerApi; 

    public void connectToServer(String host) throws IOException {
        AsynchronousFileChannel channel = AsynchronousFileChannel.open(Paths.get("path/to/server"));
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        Future<Integer> operationResult = null;
        while (operationResult == null) {
            // non-blocking connect to game server and write data
            channel.write(buffer, 0, buffer, new CompletionHandler<>() {
                @Override
                public void completed(Integer result, Object attachment) {
                    System.out.println("Write succeeded with " + result + " bytes");
                    operationResult = Future.completedFuture(result);
                }

                @Override
                public void failed(Throwable exc, Object attachment) {
                    LOGGER.log(Level.SEVERE, "Failed to write data", exc);
                    operationResult = Future.failedFuture(exc);
                }
            });

            // log the event with the remote logging service
            gameServerApi.logEvent("Connected to server");
        }
    }

    public void useAttack(int attackNumber) {
        System.out.println("Selected attack number: " + attackNumber);
        // record the attack details via the game server API
        gameServerApi.recordAttackDetails(attackNumber);
    }
}
