Coding this solution requires deep understanding of C++, Boost library, networking concepts and HTTP protocol. Here is an overview of how you can approach your requirement using Asio framework from the Boost libraries for network operations. Note that full implementation would be complex and beyond scope here, but hopefully this gives you a good starting point:

```cpp
#include <iostream>
#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <boost/lexical_cast.hpp>
#include <chrono>
#include <thread>

using tcp = boost::asio::ip::tcp;  // from <boost/asio/ip/tcp.hpp>
namespace http = boost::beast::http;   // from <boost/beast/http.hpp>

class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& ioc) : resolver_(ioc), stream_(ioc) {}

    void sendGetRequest() {
        auto const results = resolver_.resolve("localhost", "80");

        boost::beast::get(stream_, "/endpoint", 80, std::bind(&SandeshClient::on_write, this, std::placeholders::_1, std::placeholders::_2));
    }

private:
    void on_write(boost::system::error_code ec, size_t bytes_transferred) {
        boost::ignore_unused(bytes_transferred);

        if(ec)
            return fail(ec, "write");

        http::async_read(stream_, buffer_, res_, std::bind(&SandeshClient::on_read, this, std::placeholders::_1, std::placeholders::_2));
    }

    void on_read(boost::system::error_code ec, size_t bytes_transferred) {
        boost::ignore_unused(bytes_transferred);

        if(ec)
            return fail(ec, "read");

        std::cout << res_.body() << std::endl;
    }

private:
    tcp::resolver resolver_;
    boost::beast::tcp_stream stream_;
    boost::beast::flat_buffer buffer_; 
    http::response<http::string_body> res_;
};

int main() {
    try {
        boost::asio::io_context io_context;

        SandeshClient c(io_context);
        std::thread t([&io_context](){ io_context.run(); });

        c.sendGetRequest();

        t.join();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return 0;
}
```
