Here is the C++ code implementing a method that randomly selects an attack for a video game character with a cooldown period between attacks and limits usage of each attack to 100 times. It also includes error handling and concurrency control through std::mutex. Note that this solution assumes that you have already implemented logging functions, otherwise use printf or similar standard library methods.

```cpp
#include <random>
#include <chrono>
#include <thread>
#include <mutex>

class GameCharacter {
public:
    std::mt19937 rng_;  // random number generator
    int attack_counts_[2] = {0};   // counts of usage for each attack
    std::chrono::steady_clock::time_point last_attack_times_[2];  // time of the last attack for each character
    std::mutex mtx_;  // mutex to handle concurrent calls

    void selectAttack() {
        std::lock_guard<std::mutex> lock(mtx_);  // acquire a unique lock on the mutex

        int attack;
        do {
            if (std::chrono::steady_clock::now() - last_attack_times_[0] > std::chrono::seconds(9) &&
                std::chrono::steady_clock::now() - last_attack_times_[1] > std::chrono::seconds(9)) {

                // if both attacks are available, select a random one
                std::uniform_int_distribution<int> attack_dist(0, 1);
                attack = attack_dist(rng_);
            } else if (std::chrono::steady_clock::now() - last_attack_times_[0] > std::chrono::seconds(9)) {

                // if only the first attack is available, select it
                attack = 0;
            } else if (std::chrono::steady_clock::now() - last_attack_times_[1] > std::chrono::seconds(9)) {

                // if only the second attack is available, select it
                attack = 1;
            } else {

                // neither attack is available, wait for the cooldown period to end and try again later
                return;
            }
        } while (attack_counts_[attack] >= 100);  // if the chosen attack has been used more than 100 times, select another one

        std::cout << "Attack selected: " << attack+1 << std::endl;  
        ++attack_counts_[attack];
        last_attack_times_[attack] = std::chrono::steady_clock::now();  // update the time of the last attack for this character
    }
};
```
