Here is a simplified example of how you might begin building such a system using C with POSIX threads (pthread). This code doesn't account for all the engineering focus areas mentioned but it should give you an idea of what such a program could look like. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define MAX_RESOURCES 5

int available_resources = MAX_RESOURCES;
pthread_mutex_t mutex;
sem_t semaphore;

void* resource_manager(void* param) {
    int thread_id = *((int*)param);

    while (1) {
        // Acquire lock
        pthread_mutex_lock(&mutex);

        if (available_resources > 0) {
            available_resources--;

            printf("Thread %d consumed 1 resource. Remaining: %d\n", thread_id, available_resources);

            // Unlock resources and sleep to simulate work
            pthread_mutex_unlock(&mutex);
            sleep(rand() % 3);  
        } else {
            printf("Thread %d waiting for resource...\n", thread_id);

            // Release lock, wait for semaphore and re-acquire the lock
            pthread_mutex_unlock(&mutex);
            sem_wait(&semaphore);
            pthread_mutex_lock(&mutex);
        }
    }

    return NULL;
}

int main() {
    srand(time(NULL));  // Initialize random seed

    if (pthread_mutex_init(&mutex, NULL) != 0) {
        printf("\n mutex init failed\n");
        return 1;
    }

    sem_init(&semaphore, 0, MAX_RESOURCES);

    // Create threads
    pthread_t threads[5];
    int thread_args[5];
    for (int i = 0; i < 5; ++i) {
        thread_args[i] = i+1;
        pthread_create(&threads[i], NULL, resource_manager, &thread_args[i]);
    }

    // Join threads
    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphore);
    pthread_mutex_destroy(&mutex);

    return 0;
}
```
