int runCommandInBackgroundAndExecStoredProcedure(sql::Connection *conn, 
                                               const std::vector<std::string> &inputParams, 
                                               const std::string &spName) {
    // Step 1: Validate the input parameters against a predefined schema to prevent runtime errors.
    if (!validateInputParametersAgainstSchema(inputParams, Json::Value{})) {
        logError("Invalid input parameters");
        return 0;
    }

    std::map<std::string, sql::ResultSet *> cache;
    std::string cacheKey = getCacheKey(inputParams, spName);

    // Step 2: Cache mechanism to avoid redundant database calls.
    if (cache.find(cacheKey) != cache.end()) {
        logInfo("Result set retrieved from cache");
        return 1;
    }

    pid_t processId = fork();

    // Step 3: Error handling for failed fork system call.
    if (processId < 0) {
        logError("Fork failed!");
        return 0;
    } else if (processId == 0) {
        try {
            sql::Driver *driver = get_driver_instance();
            std::unique_ptr<sql::Connection> connection(driver->connect("tcp://127.0.0.1:3306", "user", "password"));

            // Step 4: Execute the stored procedure.
            std::unique_ptr<sql::Statement> stmt(connection->createStatement());
            std::string call = "CALL " + spName + "(";
            for (auto itr = inputParams.begin(); itr != inputParams.end() - 1; ++itr) {
                call += *itr + ", ";
            }
            call += *(inputParams.end() - 1) + ")";

            std::unique_ptr<sql::ResultSet> res(stmt->executeQuery(call));
            cache[cacheKey] = res.release(); // Cache the result set for later use.
        } catch (sql::SQLException &e) {
            logError(e);
            return 0;
        }

        exit(0);
    } else {
        int status = 0;
        wait(&status);
        if (WIFEXITED(status)) {
            // Step 5: Successful execution of stored procedure.
            logInfo("Stored procedure executed successfully");
            return 1;
        } else {
            // Step 6: Failed execution of stored procedure.
            logError("Stored procedure execution failed!");
            return 0;
        }
    }

