using System;
using BCrypt.Net;
using System.Security.Cryptography;
using System.Text;

public class PasswordManager 
{
    private string _salt { get; set; }
    private HashAlgorithmName _algorithm { get; set; }

    public PasswordManager()
    {
        this._algorithm = HashAlgorithmName.SHA256; //default hashing algorithm
    }

    public string CreateSalt(int length)
    {
        const string availableCharacters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";
        StringBuilder salt = new StringBuilder();

        using(var rng = RandomNumberGenerator.Create()) 
        {
            byte[] uintBuffer = new byte[sizeof(uint)];

            while (salt.Length < length) 
            {
                rng.GetBytes(uintBuffer);
                uint num = BitConverter.ToUInt32(uintBuffer, 0);

                salt.Append(availableCharacters[(int)(num % (uint)availableCharacters.Length)]);
            }
        }

        this._salt = salt.ToString();
        return _salt;
    }

    public string HashPassword(string password, HashAlgorithmName algorithm) 
    {
        if (!BCrypt.Net.Bcrypt.CheckVersion("$2a$"))
            throw new Exception("This version of bcrypt is not compatible with the current .NET runtime.");

        this._algorithm = algorithm;

        switch (algorithm.Name) 
        {
            case "SHA256":
                using (var sha256Hash = SHA256.Create())
                {
                    byte[] bytes = sha256Hash.ComputeHash(Encoding.UTF8.GetBytes(password + this._salt));  

                    StringBuilder builder = new StringBuilder();  

                    for (int i = 0; i < bytes.Length; i++) 
                        builder.Append(bytes[i].ToString("x2"));  

                    return "$SHA$" + this._salt + "$" + builder.ToString();
                }
            case "bcrypt":
                string salt = BCrypt.Net.BCrypt.GenerateSalt(10); //work factor is 10, increase for more secure password hashing
                return "$2a$" + BCrypt.Net.BCrypt.HashPassword(password + this._salt, salt);
            default: throw new Exception("Invalid hash algorithm name");
        }  
    }

    public bool VerifyPassword(string plainTextPassword, string storedHash) 
    {
        string[] parts = storedHash.Split('$'); //hash format is $HASH_TYPE$SALT$PASSWORD

        if (parts[0] != "2a" && parts[0] != "SHA")
            throw new Exception("Invalid hash type");

        switch (parts[0]) 
        {
            case "2a": //bcrypt
                return BCrypt.Net.BCrypt.Verify(plainTextPassword + this._salt, parts[2]);
            case "SHA": //SHA-256
                string newHash = HashPassword(plainTextPassword, HashAlgorithmName.SHA256);

                return parts[1] == _salt && parts[2] == newHash;
        }

        throw new Exception("Invalid hash type");
    }

    public void StorePassword(string userId, string hashedPassword) 
    {
        // This is just a placeholder. In reality, you'd likely be using an ORM to interact with your database or making calls to an API here.
    }

    public string RetrieveStoredPassword(string userId) 
    {
        return null; //This should also ideally retrieve the password from the DB/API and not just return null.
    }
}
