This problem is highly complex and requires careful planning and execution. Here's a high-level overview of how you might approach designing such a system in Java using Guava Cache, Apache ZooKeeper for coordination and handling distributed nodes, Spring Boot for managing API endpoints and interactions with multiple client connections:

```java
import com.google.common.cache.*;
import org.apache.curator.framework.CuratorFramework;
import org.apache.zookeeper.CreateMode;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Service;
import java.util.concurrent.TimeUnit;
import com.google.common.cache.CacheBuilder;

@Service
@ConfigurationProperties(prefix = "cache")
public class DistributedCache {
    @Autowired
    private CuratorFramework curatorFramework;

    LoadingCache<String, Object> cache;

    public DistributedCache() {
        this.cache =  CacheBuilder.newBuilder().maximumSize(10000)  // Set maximum size based on your needs
                .expireAfterWrite(24, TimeUnit.HOURS).recordStats()
                .removalListener((RemovalNotification notification) -> {
                    if (notification.wasEvicted()) {
                        System.out.println("Entry Removed: " + notification);
                    } else {
                        System.out.println("Removal Notification: " + notification);
                    }
                })
            .build(new CacheLoader<String, Object>() {  // This is used for populating cache entries on-demand
                @Override
                public Object load(String key) throws Exception {
                     return curatorFramework.getData().forPath("/" + key); // Fetch data from ZooKeeper for the given key path
                }
            });
    }

    public void putCacheEntry(String key, String value) throws Exception {
        if (curatorFramework.checkExists().forPath("/" + key) == null) {
           curatorFramework.create().creatingParentsIfNeeded()
                                .withMode(CreateMode.PERSISTENT).forPath("/" + key, value.getBytes());  // Store data in ZooKeeper
        } else {
            curatorFramework.setData().forPath("/" + key, value.getBytes());  
        }
        cache.put(key,value);  // Put into the Guava Cache
    }

    public Object getCacheEntry(String key) throws Exception {
       return cache.getIfPresent(key);
    }

    public void removeFromCacheAndZookeeper(String key) throws Exception{
        curatorFramework.delete().forPath("/" + key); // Remove from ZooKeeper
        cache.invalidate(key);  // Invalidate in Guava Cache
    }
}
```

