Here's a basic implementation of your `PasswordManager` class in PHP using PDO for database interactions and Memcached for caching strategy. This example assumes that you already have some way of generating and validating usernames, but it doesn't implement any logic related to that aspect.

```php
<?php 
class PasswordManager {
    private $pdo;
    private $memcached;

    public function __construct($dsn, $username, $password) {
        $this->pdo = new PDO($dsn, $username, $password);
        $this->memcached = new Memcached();
        $this->memcached->addServer("localhost", 11211);
    }

    public function generateRandomString($length, $charset) {
        $str = '';
        while ($length > 0) {
            $index = random_int(0, strlen($charset)-1);
            if (strpos($str, $charset[$index]) === false) {
                $str .= $charset[$index];
                --$length;
            }
        }
        return $str;
    }

    public function hashPassword($password, $salt) {
        $options = [
            'cost' => 12,
        ];
        if (empty($salt)) {
            throw new Exception('Salt cannot be empty');
        }
        return password_hash($password . $salt, PASSWORD_BCRYPT, $options);
    }

    public function verifyPassword($hashedPassword, $password, $salt) {
        return password_verify($password . $salt, $hashedPassword);
    }

    public function retrieveSalt($username) {
        $stmt = $this->pdo->prepare('SELECT salt FROM users WHERE username = ?');
        $stmt->execute([$username]);
        $result = $stmt->fetch();
        if (!$result) {
            throw new Exception('Salt not found for the given username');
        }
        return base64_decode($result['salt']);
    }

    public function saveHashedPassword($username, $hashedPassword, $salt) {
        $stmt = $this->pdo->prepare('UPDATE users SET hashed_password = ?, salt = ? WHERE username = ?');
        if (!$stmt->execute([$hashedPassword, base64_encode($salt), $username])) {
            throw new Exception('Failed to save the hashed password');
        }
    }
}
