    public MoSTState loadStateFromFileWithIntegrityCheck(String filename) {
        CloseableHttpClient httpclient = HttpClients.custom()
            .setDefaultCredentialsProvider(provider)
            .build();

        // Attempt to download file up to 3 times with exponential backoff
        int retryCount = 0;
        while (retryCount < 3) {
            try (CloseableHttpResponse response = httpclient.execute(new HttpGet(EXTERNAL_SYSTEM_URL + "/" + filename))) {
                // Handle the response as needed, for example, save to a temporary file

                // Now attempt to load the state from the saved file
                try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filename))) {
                    MoSTState loadedState = (MoSTState) ois.readObject();

                    MessageDigest md = MessageDigest.getInstance("MD5");
                    byte[] checksum = md.digest((byte[]) loadedState);
                    String hexChecksum = Hex.encodeHexString(checksum);

                    // Here you would probably want to compare the hexChecksum with what's expected in some metadata file or something similar.
                    if (!isExpectedCheckSum(hexChecksum)) {
                        logger.log(Level.WARNING, "Integrity check failed for state object!");
                        return null;
                    }

                    return loadedState;
                } catch (IOException | ClassNotFoundException e) {
                    logger.log(Level.SEVERE, "Error loading state from file: ", e);
                    return null;
                }
            } catch (IOException e) {
                // If the download failed, retry with exponential backoff
                try {
                    Thread.sleep((long) Math.pow(2, retryCount) * 1000);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }

            retryCount++;
        }

        logger.log(Level.WARNING, "Failed to download state file after 3 attempts!");
        return null;
    }

