#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Global variables for semaphore and cloud service
sem_t sem;
int cloudServiceAvailable = 0; // Assume it's 1 if the cloud service is available, 0 otherwise
int dynamicLoadBalanceFactor = 1;

void* threadFunc(void *ptr) {
    char *msg = (char*) ptr;
    printf("%s\n", msg);

    while(!cloudServiceAvailable){
        if(sem_trywait(&sem)){
            // Handle cloud service error or fallback to local semaphore
            // For this example, we'll just print an error message and exit.
            fprintf(stderr, "Error: Cloud service unavailable, exiting...\n");
            return NULL;
        }

        // Handle interaction with cloud service API here
        // Assume that a network call to the cloud service is made here
        sleep(1);  // Simulate some work being done by the thread

        if (sem_post(&sem)){
            fprintf(stderr, "Failed to post semaphore\n");
            return NULL;
        }
    }

    printf("Thread done processing\n");
}

int main(){
    // Initialize the semaphore
    if (sem_init(&sem, 0, dynamicLoadBalanceFactor)){
        fprintf(stderr, "Failed to initialize semaphore: %s\n", strerror(errno));
        return -1;
    }

    pthread_t thread1, thread2;
    char *msg1 = "Thread 1";
    char *msg2 = "Thread 2";

    if (pthread_create(&thread1, NULL, threadFunc, (void*) msg1)){
        fprintf(stderr, "Failed to create thread: %s\n", strerror(errno));
        return -1;
    }

    if (pthread_create(&thread2, NULL, threadFunc, (void*) msg2)){
        fprintf(stderr, "Failed to create thread: %s\n", strerror(errno));
        return -1;
    }

    // Wait for threads to finish
    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    // Clean up the semaphore
    if (sem_destroy(&sem)){
        fprintf(stderr, "Failed to destroy semaphore: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}
