import java.io.*;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.net.ssl.SSLEngine;
import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.codec.string.StringDecoder;
import io.netty.handler.codec.string.StringEncoder;
import io.netty.util.CharsetUtil;

public class SecureClient {
    private final Channel channel;

    public SecureClient(final String host, final int port) throws InterruptedException {
        EventLoopGroup group = new NioEventLoopGroup();
        Bootstrap bootstrap = new Bootstrap()
            .group(group)
            .channel(NioSocketChannel.class)
            .handler(new SecureClientInitializer());

        channel = bootstrap.connect(new InetSocketAddress(host, port)).sync().channel();
    }

    public void sendMessageAndCloseConnection(String msg) {
        ChannelFuture lastWriteFuture = null;
        lastWriteFuture = channel.writeAndFlush(msg + "\r\n");

        if (lastWriteFuture != null) {
            lastWriteFuture.syncUninterruptibly();
        }
    }

    private class SecureClientInitializer extends ChannelInitializer<Channel> {
        @Override
        protected void initChannel(Channel ch) throws Exception {
            SSLEngine engine = SSLContextFactory.getSslEngine(true); //replace with your own implementation of creating an SSLEngine

            ch.pipeline().addLast("ssl", new SslHandler(engine));
            ch.pipeline().addLast("decoder", new StringDecoder(CharsetUtil.UTF_8));
            ch.pipeline().addLast("encoder", new StringEncoder(CharsetUtil.UTF_8));
        }
    }
}
```
