<?php
function generateSecureTokenAndHashPassword($length, $charset, $password, $algorithm = PASSWORD_BCRYPT) {
    // Validate Inputs 
    if (!is_int($length)) throw new Exception('Length must be an integer.');
    if (strlen(trim($password)) < 8) throw new Exception('Password should have at least 8 characters.');
    if (!in_array($algorithm, [PASSWORD_BCRYPT, PASSWORD_ARGON2ID])) throw new Exception('Invalid algorithm chosen for password hashing.');

    $token = '';
    while (($len = strlen($token)) < $length) { 
        $size = $length - $len;
        $bytes = random_bytes($size);
        $token .= substr(str_replace(['/', '+', '='], '', base64_encode($bytes)), 0, $size); 
    } 
    $salt = random_bytes(16); // generates a 22 character salt

    $hashedPassword = password_hash($password . bin2hex($salt), $algorithm);

    return [
        'token' => $token,
        'hashedPassword' => $hashedPassword,
    ];
}
?>
