// Define cache and loading indicator variables
let scriptCache = {};
let isLoadingScripts = false;

// Fetch scripts from API
const fetchScripts = async () => {
  try {
    if (isLoadingScripts) return; // Prevent redundant network requests

    isLoadingScripts = true;

    const response = await fetch('/api/scripts');

    if (!response.ok) throw new Error(`Error: ${response.status}`);

    scriptCache = await response.json();
  } catch (error) {
    console.log('Failed to fetch scripts', error);
  } finally {
    isLoadingScripts = false;
  }
};

// Render scripts
const renderFooterScripts = async () => {
  if (Object.keys(scriptCache).length === 0) await fetchScripts(); // Fetch scripts if not already cached

  const footerElement = document.querySelector('footer');

  // Clean up old script elements
  while (footerElement.firstChild) {
    footerElement.removeChild(footerElement.lastChild);
  }

  for (const script of scriptCache) {
    const code = script?.code || '';
    const type = script?.type || 'text/javascript'; // Default to JavaScript

    const scriptElement = document.createElement('script');
    scriptElement.type = type;
    scriptElement.appendChild(document.createTextNode(code));

    footerElement.appendChild(scriptElement);
  }
};
```
