Here's a simplified example using the `docker` Python SDK and `pyyaml` for YAML configuration parsing. Please note that error handling has been kept minimal in this example, and real-world implementations would be more complete.

```python
import docker
import yaml
from time import sleep

class DockerDeployer:
    def __init__(self, config_file):
        self.client = docker.from_env()
        with open(config_file) as file:
            self.config = yaml.load(file, Loader=yaml.FullLoader)
        self.containers = {}

    def deploy(self, app_id):
        if app_id in self.config and app_id not in self.containers:
            print(f"Deploying {app_id}")

            image = self.config[app_id]["image"]
            try:
                container = self.client.containers.run(image, detach=True)
                self.containers[app_id] = container
            except docker.errors.ImageNotFound as e:
                print(f"Failed to deploy {app_id}: {e}")

    def scale(self):
        for app in self.config:
            if "depends_on" in self.config[app] and self.config[app]["depends_on"] not in self.containers:
                print(f"{app} depends on {self.config[app]['depends_on']}, waiting...")
                while self.config[app]["depends_on"] not in self.containers:
                    sleep(10)  # wait for some time before checking again

            if app not in self.containers:
                self.deploy(app)

    def manage(self):
        while True:
            print("Checking status...")
            for container in self.client.containers.list():
                print(f"Container {container.short_id} is {container.status}")

            sleep(60)  # wait some time before checking again

if __name__ == "__main__":
    deployer = DockerDeployer("config.yaml")
    deployer.scale()
    deployer.manage()
```

