struct Vec3 { float x, y, z; };
typedef std::unique_lock<std::recursive_mutex> ScopedLock;

class OctreeNode
{
    friend class Octree;
public:
    OctreeNode(const Vec3& minBoundary, const Vec3& maxBoundary) : min(minBoundary), max(maxBoundary){}
    ~OctreeNode(){ for(auto child : children) delete child;}

private:
    std::vector<OctreeNode*> children;
    OctreeNode* parent = nullptr;

    Vec3 min, max;
    int depth = 0;
    bool isLeaf = true;
};

class Octree
{
public:
    explicit Octree(const Vec3& center, float halfSize, unsigned short maxDepth) : center(center), halfSize(halfSize), maxDepth(maxDepth){}
    ~Octree(){ delete root;}

    void insert(void* data, const Vec3& position);
    bool remove(const Vec3& position);
    void clear();
private:
    OctreeNode* createNode(const Vec3& minBoundary, const Vec3& maxBoundary){ return new OctreeNode(minBoundary, maxBoundary);}

    std::recursive_mutex mutex;
    OctreeNode* root = nullptr;
    unsigned short maxDepth = 0;
    Vec3 center;
    float halfSize = 0.f;
};

void Octree::insert(void* data, const Vec3& position)
{
    if(!data || !root){ return;}

    ScopedLock lock(mutex);
}

bool Octree::remove(const Vec3& position)
{
    if(!root){ return false;}

    ScopedLock lock(mutex);
    return true;
}

void Octree::clear()
{
    if(!root){ return;}

    ScopedLock lock(mutex);
    delete root;
    root = nullptr;
}
