        public ServerInfo(String hostname, int port) throws IOException, ExecutionException, InterruptedException {
            this.hostname = hostname;
            this.port = port;
            InetSocketAddress serverAddr = new InetSocketAddress(this.hostname, this.port);

            AsynchronousChannelGroup group =  AsynchronousChannelGroup.withThreadPool(Executors.newFixedThreadPool(5)); // Custom thread pool to handle IO operations
            socketChannel = AsynchronousSocketChannel.open(group);
            socketChannel.connect(serverAddr).get(); // This will block the calling thread until connection is established, or an error occurs
        }
    }

    public Future<TaskResult> submitTask(Callable<TaskResult> task) {
        return executor.submit(task);
    }
}
