import boto3
import os
from botocore.exceptions import BotoCoreError, ClientError

class ConfigLoader:
    def __init__(self):
        self.ssm = boto3.client('ssm')
        self.cache = {}

    def get_config(self, env=None):
        # Fall back to default configuration if no environment is provided
        if not env:
            env = os.getenv("ENV", "default")

        try:
            # Check the cache first
            if env in self.cache:
                return self.cache[env]

            response = self.ssm.get_parameter(Name=f'/{env}/my-app', WithDecryption=True)
            config = response['Parameter']['Value']  # Modify this according to your schema

            # Cache the configuration
            self.cache[env] = config
            return config
        except (BotoCoreError, ClientError) as error:
            print(f'Error getting parameter for {env}: {error}')
            return None  # Or fall back to default configuration here

    def update_config(self, env, new_config):
        try:
            self.ssm.put_parameter(Name=f'/{env}/my-app', Value=new_config, Type='String', Overwrite=True)

            # Invalidate cache for this environment
            if env in self.cache:
                del self.cache[env]
        except (BotoCoreError, ClientError) as error:
            print(f'Error updating parameter for {env}: {error}')
