import time
from functools import lru_cache

class RestaurantBackendSystem:
    def __init__(self):
        self.orders = {}  # Assume this is your database, for simplicity it's a dictionary
        self.audit_log = []  # This will simulate an external audit system
        self.rate_limits = {}

    @lru_cache(maxsize=10)
    def get_order(self, order_id):
        return self.orders.get(order_id)

    def can_process_order(self, ip):
        now = time.time()
        if ip in self.rate_limits:
            if now - self.rate_limits[ip] < 1:  # 1 second rate limit
                return False
            else:
                self.rate_limits[ip] = now  # Reset the timer
        else:
            self.rate_limits[ip] = now  # Add to the map if it doesn't exist yet
        return True

    def process_order(self, order_id, delivery_person_id):
        try:
            if not self.can_process_order(delivery_person_id):
                raise Exception('Rate limit exceeded')

            order = self.get_order(order_id)

            if not order:
                return {'success': False, 'message': f'Order {order_id} not found', 'updated': 0}

            # Validate the order status before proceeding with update (e.g., an order that has already been delivered)
            if order['status'] != 'pending':
                return {'success': False, 'message': f'Order {order_id} cannot be updated', 'updated': 0}

            # Assuming `update_order` function exists in your database model.
            self.orders[order_id] = order['status'] = 'delivered'  
            self.orders[order_id] = order['delivery_person_id'] = delivery_person_id 
            self.orders[order_id] = order['actual_delivery_time'] = time.time()

            return {'success': True, 'message': f'Order {order_id} updated successfully', 'updated': 1}
        except Exception as e:
            error_msg = str(e)
            self.audit_log.append({'error': error_msg})  # Add to the audit log

            return {'success': False, 'message': f'Error updating order {order_id}: {error_msg}', 'updated': 0}
