#include <stdio.h>
#include <semaphore.h>
#include <pthread.h>
#include <unistd.h>

sem_t sem;
int shared = 0;  // Our shared resource - a simple integer variable

void* thread(void *arg) {
    int num = *((int*) arg);

    while (1) {
        if (sem_wait(&sem) == 0) {  // Decrement semaphore
            printf("Thread %d accessing shared resource\n", num);

            /* Access to the shared resource here */

            sem_post(&sem);  // Increment semaphore
        } else {
            perror("Error decrementing semaphore");
            break;
        }
    }

    return NULL;
}

int main() {
    if (sem_init(&sem, 0, 1) == -1) { // Initialize the semaphore with a value of 1
        perror("Error initializing semaphore");
        return -1;
    }

    pthread_t tid[5];
    int thread_num[5] = {0,1,2,3,4};
    for (int i = 0; i < 5; i++) {  // Create 5 threads
        if (pthread_create(&(tid[i]), NULL, &thread, &thread_num[i])) {
            perror("Error creating thread");
            return -1;
        }
    }

    for (int i = 0; i < 5; i++) {  // Join all threads
        if(pthread_join(tid[i], NULL)) {
            perror("Error joining thread");
            return -1;
        }
    }

    sem_destroy(&sem);  // Cleanup

    return 0;
}
```
