            $stmt->execute([$status, $ipAddress, $clinicID]);

            // Commit transaction
            $this->db->commit();
        } catch (Exception $e) {
            if ($this->db->inTransaction()) {
                $this->db->rollBack();
            }
            $this->logger->logError($e);
            throw new Exception('Failed to update clinic status: ' . $e->getMessage());
        }
