        return true;
    }

    public function addFactoryFunction($id, $factoryFn) {
        $this->factoryRegistry[$id] = $factoryFn;
    }

    public function createClinicInstanceFromJSON($jsonString, $clinicID = null) {
        // Decode JSON string to associative array
        $data = json_decode($jsonString, true);

        if (!isset($this->factoryRegistry[$clinicID])) {
            throw new Exception('No factory function found for clinic ID: ' . $clinicID);
