    let fileStream = fs.createReadStream(url);
    const params = {
        Bucket: 'your_bucket_name', // Replace with your bucket name
        Key: url,
        Body: fileStream,
        ContentType: mimeType,
        Metadata: {
            originalUrl: url,
            contentLength: contentLength.toString()
        }
    };

    if (contentLength > chunkSize) params.PartSize = chunkSize; // Enable multipart upload for large files 
    else delete params.PartSize; // No need to enable for small/medium size files 

    try {
        let startTime = Date.now();
        let data = await s3.upload(params).promise(); // Upload the file  
