#include <sstream>
#include <thread>
#include "external_kms_service.h"

std::mutex mtx;
std::ofstream logfile;
bool isConfigured = false;
int progress = 0;

// Function to configure the OpenSSL library and logging file
void ConfigureOpenSSl(std::string config_path) {
  if (!isConfigured) {
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();
    isConfigured = true;
    logfile.open("audit_log.txt", std::ios_base::app);
  }
}

// Function to encrypt a file with the specified cipher and mode options
int EncryptFile(std::string filepath, const EVP_CIPHER* cipher, int bufferSize) {
  // OpenSSL setup
  ConfigureOpenSSl("");

  // Progress callback
  std::time_t start = std::time(nullptr);
  progress += 1;

  logfile << "Starting encryption of file " + filepath + "\n";

  // Load the key from external KMS service
  unsigned char* key = ExternalKMSService.LoadKey();

  FILE *in, *out;
  int inl, outl;
  unsigned char inbuf[bufferSize], outbuf[bufferSize + EVP_MAX_BLOCK_LENGTH];
  EVP_CIPHER_CTX ctx;

  // Initialize the encryption context and cipher
  EVP_CIPHER_CTX_init(&ctx);
  EVP_EncryptInit_ex(&ctx, cipher, NULL, key, NULL);

  in = fopen(filepath.c_str(), "rb");
  out = fopen((filepath + ".enc").c_str(), "wb");

  // Encryption loop
  while (1) {
    inl = fread(inbuf, 1, bufferSize, in);
    if (inl <= 0) break;
    if (!EVP_EncryptUpdate(&ctx, outbuf, &outl, inbuf, inl)) {
      /* Error */
      return -1;
    }
    fwrite(outbuf, 1, outl, out);
  }

  // Finalize the encryption and clean up
  if (!EVP_EncryptFinal_ex(&ctx, outbuf, &outl)) {
    /* Error */
    return -1;
  }
  fwrite(outbuf, 1, outl, out);

  EVP_CIPHER_CTX_cleanup(&ctx);
  free(key);
  std::time_t end = std::time(nullptr);
  logfile << "File " + filepath + " encrypted in " + std::to_string(end - start) + " seconds\n";

  return 0;
}

// Function to encrypt a list of files using multiple threads
std::vector<std::tuple<int, double>> EncryptFilesMultiThreaded(const std::vector<std::string>& filepaths, const EVP_CIPHER* cipher, int bufferSize) {
  logfile << "Starting multi-threaded encryption of files\n";

  std::vector<std::tuple<int, double>> results;
  std::vector<std::thread> threads;

  // Launch one thread per file to encrypt in parallel
  for (const auto& path : filepaths) {
    threads.push_back(std::thread([&results, &path, cipher, bufferSize](){
      int exitcode = EncryptFile(path, cipher, bufferSize);

      mtx.lock(); // Thread safety when logging
      results.push_back({exitcode, 0});
      mtx.unlock();
    }));
  }

  // Wait for all threads to finish
  std::for_each(threads.begin(), threads.end(), [](std::thread &t) { t.join(); });

  logfile << "Finished multi-threaded encryption of files\n";
  return results;
}
```
