```php
class ConfigManager {
    private $db; //Database object
    private $env; //Environment variable

    public function __construct($database, $environment) {
        $this->db = $database;
        $this->env = $environment;
        include_once 'vendor/autoload.php'; //Include autoloader for dependencies 
    }

    //Fetch configuration from the database and sets environment variables
    public function loadConfig() {
        try{
            $config = $this->db->getConfig($this->env);
            if(!empty($config)){
                foreach ($config as $key => $value) {
                    putenv("$key=$value"); //Set environment variables
                    $_ENV[$key] = $value; //Set PHP's superglobal for current script
                }
            } else{
                $this->fallBack();
            }
        } catch(Exception $e){
            $this->logger('Error', $e);
            $this->fallBack();
        }
    }

    //Fallback mechanism when the database is down or there's no configuration
    private function fallBack() {
        try{
            //Default settings hardcoded here
