#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#define MAX_COMMANDS 50
#define BUFFER_SIZE 1024
#define LOGFILE "/tmp/logfile"

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Implementation of signal handler and logger omitted for brevity

int executeBackgroundCommand(char* command, char** args) {
    if (command == NULL || strlen(command) == 0) {
        return 1;
    }

    pid_t childPid = fork();

    if (childPid < 0) {
        logError("fork failed");
        return 0;
    } else if (childPid == 0) { // Child process
        char* argv[MAX_COMMANDS + 1];
        argv[0] = command;

        for(int i = 2; args[i-2] != NULL && i < MAX_COMMANDS; ++i){
            argv[i-1] = args[i-2];
        }

        argv[MAX_COMMANDS] = NULL;

        execve(command, argv, environ); 
    } else { // Parent process
        int status;
        pid_t waitPid = waitpid(-1, &status, WNOHANG);

        if (waitPid == -1) {
            logError("wait failed");
            return 0;
        } else if(WIFEXITED(status)) {
            int exit_status = WEXITSTATUS(status);

            if(exit_status == 0){
                logSuccess(command, "successfully executed in background with code: ", exit_status);
                return 1;
            }else{
                logError(command, "finished unexpectedly with error code: ", exit_status);
                return 0;
            }
        }
    }
}
