```csharp
using System;
using System.Xml;
using System.Xml.Xsl;
using System.Xml.Schema;
using System.IO;
using System.Linq;
using System.Net;
using System.Collections.Generic;

public class XPathParser
{
    private Dictionary<string, XmlDocument> _cache = new Dictionary<string, XmlDocument>();
    private string _apiUrl;
    private int _maxCacheSize = 100; // set a max cache size limit

    public XPathParser(string apiUrl)
    {
        _apiUrl = apiUrl;
    }

    public XmlNode GetFirstMatchingElement(string xmlDocumentName, string xpathQuery)
    {
        if (_cache.ContainsKey(xmlDocumentName))
        {
            var doc = _cache[xmlDocumentName];
            return doc.SelectSingleNode(xpathQuery);
        }
        else
        {
            using (WebClient client = new WebClient())
            {
                try
                {
                    // Fetch the XML document from external API
                    string xmlContent = client.DownloadString(_apiUrl + "?document=" + xmlDocumentName);

                    XmlTextReader reader = null;

                    try
                    {
                        reader = new XmlTextReader(new StringReader(xmlContent));
                        reader.Namespaces = false; // disable namespace support for simplicity

                        XmlDocument doc = new XmlDocument();
                        doc.Load(reader);

                        var node = doc.SelectSingleNode(xpathQuery);

                        if (_cache.Count >= _maxCacheSize)
                        {
                            // If the cache is full, remove the least recently used item (LRU)
                            var lruKey = _cache.First().Key;
                            _cache.Remove(lruKey);
                        }

                        _cache[xmlDocumentName] = doc; // add document to cache

                        return node;
                    }
                    finally
                    {
                        if (reader != null) reader.Close();
                    }
                }
                catch (WebException ex)
                {
                    throw new Exception("Failed to fetch XML document from external API", ex);
                }
            }
        }
    }
}
```
