#include <iostream>
#include <vector>
#include <fstream>
#include "rapidjson/document.h"
#include "rapidjson/writer.h"
#include "rapidjson/stringbuffer.h"

using namespace rapidjson;

struct Node {
    int key;
    std::string value;
};

std::vector<Node> nodes;
const int THRESHOLD = 1024;  // Adjust this threshold as per your requirement.

void readFromConfigFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open configuration file.");
    }

    std::string line;
    while (std::getline(file, line)) {
        auto pos = line.find('=');
        if (pos == std::string::npos) continue;

        Node node;
        node.key = std::stoi(line.substr(0, pos));
        node.value = line.substr(pos + 1);
        nodes.push_back(node);

        if (nodes.size() >= THRESHOLD) {
            nodes.reserve(THRESHOLD * 2);  // Dynamically resize the array.
        }
    }
}

std::string serializeToJson() {
    StringBuffer s;
    Writer<StringBuffer> writer(s);

    writer.StartArray();
    for (const auto& node : nodes) {
        writer.StartObject();

        writer.Key("key");
        writer.Int(node.key);

        writer.Key("value");
        writer.String(node.value.c_str());

        writer.EndObject();
    }
    writer.EndArray();

    return s.GetString();
}
```
This code will initialize a vector of nodes, read key-value pairs from a configuration file, serialize the node array into JSON format using RapidJSON library and dynamically resize the array if its size exceeds a certain threshold.

