    virtual Json::Value toJson() const;

    template <typename T>
    static void registerFactory(std::string id){
        factoryRegistry[id] = [](const Json::Value& jsonData) { return new T(jsonData); };
    }

    static MyClass* createFromJson(std::string id, const Json::Value &jsonData){
        if (factoryRegistry.find(id) != factoryRegistry.end()){
            return factoryRegistry[id](jsonData);
        } else {
            throw std::runtime_error("Factory not found for " + id);
        }
    }
