    if not response.ok:
        return False, "Failed to verify JWT."

    data = response.json()

    if data['status'] == 'invalid':
        return False, f"Invalid JWT: {data['message']}"
    elif data['status'] == 'expired':
        return False, "Token is expired."

    # Checking the user in database.  
    if not db_check(payload['sub']):
        return False, f"User with ID {payload['sub']} does not exist."

    return True, 'Valid JWT.'
