    pub fn new() -> Result<Self> {
        // Create a new instance of the manager.
        let mut mgr = Self {
            work_dir: Arc::new(Mutex::new(None)),
        };

        // Check if WORK_DIR is set and it exists, use that directory.
        let var = env::var("WORK_DIR");
        match var {
            Ok(work_dir) => {
                let path = PathBuf::from(work_dir);
                mgr.set_work_dir(path)?;
            }
            Err(_) => {
                // Otherwise, create a new temporary directory.
                let id = Uuid::new_v4();
                let work_dir = format_path("/tmp/{}", id);
                mgr.set_work_dir(work_dir)?;
            }
