As for the JavaScript function `FindElementsBySelector`:
```js
function FindElementsBySelector(startNode, selector, callback) {
    if (!startNode || typeof startNode !== 'object' || !('childNodes' in startNode)) {
        throw new Error("Invalid input. Expected DOM node");
    }

    if (typeof selector !== 'string') {
        throw new Error("Invalid selector. Expected a string.");
    }

    const result = [];
    const stack = [startNode];

    while(stack.length) {
        const node = stack.pop();

        for (let child of node.childNodes) {
            stack.push(child);
        }

        if (callback(node, selector)) {
            result.push(node);
        }
    }

    return result;
}
```
In the above code, `FindElementsBySelector` function takes a starting node, a CSS selector string and a callback function that tests each element against the provided selector. The function iteratively traverses the DOM tree by using stack for DFS traversal. This design avoids recursion and potential stack overflow issues.

Here is a high level C++ code that meets your requirements using the Octree Data structure with fine grained locking and condition variables for thread safety. Note that this is a simplified version and doesn't include all features mentioned in the problem but it gives an idea of how you can implement such a system:

```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>

// Octree Node structure
struct OctreeNode {
    std::recursive_mutex mtx;
    float x, y, z; // coordinates of node center
    float size;  // length of edge
    std::vector<OctreeNode*> children;
    bool isLeaf = true;

    OctreeNode(float _x, float _y, float _z, float _size): x(_x), y(_y), z(_z), size(_size) {}
};

class AdvancedOctreeManager {
private:
    OctreeNode* root;
    std::mutex mtx_insert;

public:
    AdvancedOctreeManager(float _x, float _y, float _z, float _size): 
        root(new OctreeNode(_x, _y, _z, _size)) {}

    void insertDataPoint(float x, float y, float z) {
        std::unique_lock<std::recursive_mutex> lock_root(root->mtx);

        if (checkAndInsertLeafNode(root, x, y, z)) return;

        // If the root node is not a leaf, we need to lock all nodes on the path from the root to the leaf
        std::unique_lock<std::recursive_mutex> lock1(mtx_insert);

        insertDataPointHelper(root, x, y, z);
    }

    bool checkAndInsertLeafNode(OctreeNode* node, float x, float y, float z) {
        std::unique_lock<std::recursive_mutex> lock(node->mtx);

        if (node->isLeaf && shouldBeHere(node, x, y, z)) {
            node->children.push_back(new OctreeNode(x, y, z, node->size / 2));

            return true;
        } else if (!node->isLeaf) {
            for (auto child : node->children) {
                if (checkAndInsertLeafNode(child, x, y, z)) return true;
            }
        }

        return false;
    }

    void insertDataPointHelper(OctreeNode* node, float x, float y, float z) {
        // If the root is not a leaf node and we have to go deeper
        if (!node->isLeaf) { 
            for (auto child : node->children) {
                std::unique_lock<std::recursive_mutex> lock(child->mtx);

                insertDataPointHelper(child, x, y, z);
            }
        } else if (shouldSplitNode(node)) { // If the node should be split
            for (int i = 0; i < 8; ++i)  {
                float newX = node->x + ((i & 4)?0.5f:-0.5f) * node->size,
                      newY = node->y + ((i & 2)?0.5f:-0.5f) * node->size,
                      newZ = node->z + ((i & 1)?0.5f:-0.5f) * node->size;

                node->children.push_back(new OctreeNode(newX, newY, newZ, node->size / 2));
            }

            // Recursively insert the data point to children nodes
            for (auto child : node->children) {
                std::unique_lock<std::recursive_mutex> lock(child->mtx);

                insertDataPointHelper(child, x, y, z);
            }

            node->isLeaf = false; // Node has been split. It's no longer a leaf node
        } else { // If the root should not be split and still can store new data point directly
            node->children.push_back(new OctreeNode(x, y, z, node->size / 2));
            node->isLeaf = false; // Node has been updated. It's no longer a leaf node
        }
    }

    bool shouldBeHere(OctreeNode* node, float x, float y, float z) {
        return isInBoundary(node->x, node->y, node->z, node->size, x, y, z);
    }

    // Condition to check if a node should be split
    bool shouldSplitNode(OctreeNode* node) { 
        return node->children.size() > MAX_CHILDREN * DYNAMIC_FACTOR;
    }

    // Check if point is in the cube boundary
    static bool isInBoundary(float _x, float _y, float _z, float size, float x, float y, float z) {
        return (_x - size <= x && x < _x + size) && 
               (_y - size <= y && y < _y + size) && 
               (_z - size <= z && z < _z + size);
    }
};
```
