string SessionIdGenerator::generateUniqueSessionId() {
    uniform_int_distribution<uint64_t> dis;
    string sessionIdBase64;

    do {
        uint64_t randomNumber = dis(gen);
        // Convert the number to base 64 and encode it as a string
        sessionIdBase64 = base64Encode(randomNumber);
    } while (find(usedIds.begin(), usedIds.end(), sessionIdBase64) != usedIds.end());

    usedIds.push_back(sessionIdBase64);
    return sessionIdBase64;
}

