Here is a high level solution in C language using OpenSSL library for cryptographic operations and MySQL library for state management:

```C
#include <openssl/evp.h>
#include <mysql.h>

typedef struct State {
    int id;
    char* name;
    struct State* next;  // Pointer to the next state in list, or NULL for last state
} State;

typedef struct CipherObject {
    EVP_CIPHER_CTX *ctx;  // OpenSSL cipher context
    State *stateList;     // Pointer to linked list of FSA states
} CipherObject;

MYSQL *gDB = NULL;   // Global MySQL database connection
State **cache = NULL; // Cache for previously computed state lists
int cacheSize = 0;  // Number of cached states

CipherObject* fsaOperation(char *string, int option) {
    CipherObject* cipherObj = malloc(sizeof(CipherObject));

    if (cipherObj == NULL) return NULL;   // Out of memory

    // Initialize OpenSSL context 
    EVP_CIPHER_CTX_init(&cipherObj->ctx);
    if(!EVP_CipherInit(cipherObj->ctx, EVP_aes_256_cbc(), NULL, string, option)) {
        free(cipherObj);
        return NULL;  // Cryptographic operation failed
    }

    // Connect to MySQL database
    if (gDB == NULL) gDB = mysql_init(NULL);
    if (!mysql_real_connect(gDB, "host", "user", "passwd", "dbname", 0, NULL, 0)) {
        free(cipherObj);
        return NULL; // Database connection failed
    }

    // Query the database for FSA states
    if (mysql_query(gDB, "SELECT id, name FROM fsa_states")) {
        free(cipherObj);
        return NULL; // Database query error
    }

    MYSQL_RES *result = mysql_store_result(gDB);
    int numRows = mysql_num_rows(result);

    cipherObj->stateList = malloc(sizeof(State) * numRows);  // Allocate memory for state list
    if (cipherObj->stateList == NULL) {
        free(cipherObj);
        return NULL; // Out of memory
    }

    MYSQL_ROW row;
    State *lastState = NULL;
    int i = 0;
    while ((row = mysql_fetch_row(result))) {
        cipherObj->stateList[i].id = atoi(row[0]);  // Convert string to integer
        cipherObj->stateList[i].name = row[1];
        if (lastState != NULL) lastState->next = &cipherObj->stateList[i];  // Set 'next' pointer
        lastState = &cipherObj->stateList[i++];  // Point to the newly created state
    }

    // Correctly set 'next' pointer of last state in list
    if (lastState != NULL) lastState->next = cipherObj->stateList;  

    mysql_free_result(result);  // Free MySQL result

    return cipherObj;
}

void cleanup() {
    EVP_CIPHER_CTX_cleanup(&cipherObj->ctx);  // Clean up OpenSSL context

    for (int i = 0; i < numRows; ++i) {  // Free dynamically allocated memory
        free(cipherObj->stateList[i].name);
    }
    free(cipherObj->stateList);
    cipherObj->stateList = NULL;

    mysql_close(gDB);  // Close MySQL connection
}
```

