For Rust, you can use `std::time` to measure the time taken for compilation and `get_resident_set_size` to get the resident set size of the process:
```rust
use std::process::Command;
use std::thread::sleep;
use std::time::{SystemTime, UNIX_EPOCH};
use std::os::unix::io::RawFd;
use libc;

fn measure_compilation() -> Result<(u128, u64), Box<dyn std::error::Error>> {
    let before = SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis();

    Command::new("rustc")
        .arg("yourfile.rs")
        .spawn()?
        .wait_with_output()?;

    let after = SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis();

    sleep(std::time::Duration::from_secs(1));  // Wait for process to release file handles

    let pid: libc::pid_t = unsafe { libc::getpid() };
    let path: String = format!["/proc/{}/stat", pid];
    let statfile = std::fs::File::open(&path)?;
    let mut buf = String::new();
    statfile.read_to_string(&mut buf)?;

    let rss = buf.split(' ').nth(21)
        .and_then(|s| s.parse().ok())
        .unwrap_or(0); // in pages, so multiply by 4096 to get bytes if needed

    Ok((after - before, rss))
}
