public class UserService : IUserService
{
    private readonly UserManager<ApplicationUser> _userManager;
    private readonly RoleManager<IdentityRole> _roleManager;
    private readonly IMemoryCache _cache;

    public UserService(
        UserManager<ApplicationUser> userManager,
        RoleManager<IdentityRole> roleManager,
        IMemoryCache cache)
    {
        _userManager = userManager;
        _roleManager = roleManager;
        _cache = cache;
    }

    public async Task<bool> ValidateUserAsync(ApplicationUser user)
    {
        var passwordValidators = _userManager.PasswordValidators;

        foreach (var validator in passwordValidators)
        {
            var result = await validator.ValidateAsync(_userManager, user, user.PasswordHash);

            if (!result.Succeeded) return false;
        }

        return true;
    }

    public async Task<bool> VerifyRoleAccessAsync(ApplicationUser user, string roleName)
    {
        var cacheKey = $"role_{user.Id}_{roleName}";
        if (!_cache.TryGetValue(cacheKey, out bool isInRole))
        {
            isInRole = await _userManager.IsInRoleAsync(user, roleName);

            // Set the cache options
            var cacheEntryOptions = new MemoryCacheEntryOptions()
                .SetSize(1) // Size of entry in bytes
                .SetSlidingExpiration(TimeSpan.FromMinutes(60)); // Slide expiration to 60 minutes

            _cache.Set(cacheKey, isInRole, cacheEntryOptions);
        }

        return isInRole;
    }

    public async Task<IdentityResult> UpdateUserPasswordAsync(ApplicationUser user, string newPassword)
    {
        var token = await _userManager.GeneratePasswordResetTokenAsync(user);
        var result = await _userManager.ResetPasswordAsync(user, token, newPassword);

        return result;
    }
}
```
