#include <stdio.h>
#include <string.h>
#include <cJSON.h>
#include <curl/curl.h>
#include <pthread.h>

typedef struct {
    char* json_string;
    pthread_mutex_t *lock;
} thread_data_t;

void *validateToken(void *arg) {
    thread_data_t *data = (thread_data_t *) arg;

    cJSON *json = cJSON_Parse(data->json_string);

    pthread_mutex_lock(data->lock);

    if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(json, "token_type")) 
        || strcmp(cJSON_GetObjectItemCaseSensitive(json, "token_type")->valuestring, "Bearer")) {
        printf("Invalid token type\n");
    } else if (!cJSON_IsNumber(cJSON_GetObjectItemCaseSensitive(json, "expires_in")) 
        || cJSON_GetObjectItemCaseSensitive(json, "expires_in")->valueint < 0) {
        printf("Invalid expires in\n");
    } else if (!cJSON_IsString(cJSON_GetObjectItemCaseSensitive(json, "access_token")) 
        || !strlen(cJSON_GetObjectItemCaseSensitive(json, "access_token")->valuestring)) {
        printf("Invalid access token\n");
    } else if (cJSON_IsString(cJSON_GetObjectItemCaseSensitive(json, "refresh_token")) 
        && !strlen(cJSON_GetObjectItemCaseSensitive(json, "refresh_token")->valuestring)) {
        printf("Invalid refresh token\n");
    } else {
        printf("Token is valid\n");
    }

    pthread_mutex_unlock(data->lock);

    cJSON_Delete(json);
}

int main() {
    // Assuming you have an array of JSON strings and a lock. 
    char* json_strings[] = {"json1", "json2", ...};
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < sizeof(json_strings) / sizeof(char*); ++i) {
        pthread_t thread;
        thread_data_t data = { json_strings[i], &lock };

        pthread_create(&thread, NULL, validateToken, (void *)&data);
    }

    // Wait for all threads to finish.
    pthread_exit(NULL);
}
