#include <iostream>
#include <fstream>
#include <filesystem>
#include <string>
#include <thread>
#include <mutex>
#include <vector>

namespace fs = std::filesystem;
std::mutex mtx;

void processFile(const fs::path& filePath, int& largestInteger, long long& sum, size_t& totalNumbers) {
    std::ifstream file(filePath);

    if (!file.is_open()) {
        std::cerr << "Unable to open: " << filePath << '\n';
        return;
    }

    int number, max = std::numeric_limits<int>::min();
    while (file >> number) {
        mtx.lock();
        ++totalNumbers;
        sum += number;
        if(number > max) max = number;
        if(max > largestInteger) largestInteger = max;  // update the largest integer across all files
        mtx.unlock();
    }

    file.close();
}

int main() {
    std::vector<std::thread> threads;

    fs::path inputPath("inputDirectory");  // replace with your actual directory path
    int largestInteger = std::numeric_limits<int>::min();
    long long sum = 0;
    size_t totalNumbers = 0;

    for (auto& file : fs::recursive_directory_iterator(inputPath)) {
        if (!fs::is_regular_file(file.status())) continue;  // skip directories

        threads.push_back(std::thread(processFile, file.path(), std::ref(largestInteger), std::ref(sum), std::ref(totalNumbers)));
    }

    for (auto& t : threads) {
        if(t.joinable()) t.join();  // wait for all threads to finish
    }

    double average = static_cast<double>(sum)/totalNumbers;

    std::cout << "Largest integer: " << largestInteger << '\n';
    std::cout << "Average of integers: " << average << '\n';
}
