use reqwest::header::{HeaderMap, AUTHORIZATION};

struct Config {
    function: String,
    settings: Value,
}

impl Config {
    fn new(args: &[String]) -> Result<Config, &str> {
        if args.len() < 3 {
            return Err("not enough arguments");
        }

        let config_file = match File::open(&args[1]) {
            Ok(f) => f,
            Err(_) => return Err("couldn't open file"),
        };

        let mut settings = String::new();
        match io::Read::read_to_string(&config_file, &mut settings) {
            Ok(_) => (),
            Err(_) => return Err("couldn't read from file"),
        }

        let function: Value = match serde_json::from_str(&settings) {
            Ok(f) => f,
            Err(_) => return Err("invalid JSON in config file"),
        };

        Ok(Config {
            function: args[2].clone(),
            settings: function,
        })
    }
}

