// Global variables to store fetched scripts and cache mechanism
let cachedScripts = {};
let isFetching = false;

// Function to fetch scripts from an external API endpoint
const fetchScripts = async () => {
  if (isFetching) return; // If already fetching, don't do it again

  isFetching = true;
  try {
    const response = await fetch('/api/scripts');
    const scripts = await response.json();

    // Update the cache
    for (const script of scripts) {
      cachedScripts[script.code] = script;
    }
  } catch(error) {
    console.log("Error fetching scripts: ", error);
  } finally {
    isFetching = false;
  }
};

// Function to render scripts asynchronously
const renderFooterScriptsAsync = async () => {
  // If not cached, fetch them first
  if (Object.keys(cachedScripts).length === 0) await fetchScripts();

  for (const script of Object.values(cachedScripts)) {
    const scriptElement = document.createElement('script');

    // Set default properties
    scriptElement.type = script.type || "text/javascript";
    scriptElement.src = script.src || "";
    scriptElement.innerHTML = script.code || "";

    // Append to the footer
    document.body.appendChild(scriptElement);
  }
};

// Function to handle spinner during fetching and rendering scripts
const renderFooterScripts = async () => {
  // Show a loading indicator or spinner

  await renderFooterScriptsAsync();

  // Hide the loading indicator or spinner
};
