```csharp
using System;
using System.Threading;
using System.Security.Cryptography;
using Org.Apache.Commons.Lang3.SemaphoreUtils;
using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.DataModel;
using Amazon.Runtime;

public class SemaphoreManager {
    private readonly string accessKey;
    private readonly string secretKey;
    private readonly AmazonDynamoDBClient client;
    private readonly DynamoDBContext context;
    private readonly Semaphore semaphore;

    public SemaphoreManager(string accessKey, string secretKey) {
        this.accessKey = accessKey;
        this.secretKey = secretKey;
        AWSCredentials credentials = new BasicAWSCredentials(accessKey, secretKey);
        client = new AmazonDynamoDBClient(credentials, RegionEndpoint.USEast1);
        context = new DynamoDBContext(client);
        semaphore = new Semaphore(0, int.MaxValue); // Initialize semaphore with 0 permits to block threads until initialized.
    }

    public void InitSemaphore(int maxPermits) {
        if (semaphore.CurrentCount > 0) return;
        semaphore.Release(maxPermits);
    }

    public string Decrypt(byte[] key, byte[] iv, PaddingMode padding, byte[] ciphertext) {
        using (Aes aes = Aes.Create()) {
            aes.Key = key;
            aes.IV = iv;
            aes.Padding = padding;

            semaphore.WaitOne(); // Acquire permit before accessing the resource.

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            byte[] plaintextBytes = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);
            string plaintext = System.Text.Encoding.UTF8.GetString(plaintextBytes);

            semaphore.Release(); // Release permit after accessing the resource.

            return plaintext;
        }
    }
}
```

