#include <string.h>

typedef struct State {
    int id;
    char* selector;
    struct State *next;
} State;

typedef struct FSA {
    int numStates;
    State *states;
} FSA;

int check_selector(char* element, char* selector) {
    // This is a placeholder for your own logic to compare the class or ID of an element against the given selector. 
    return strcmp(element, selector);
}

State *traverseFSA(State *states, int numStates, FSA *fsa, State *lastState) {
    if (numStates == 0 || states == NULL) {
        return NULL; // No match found. 
    }

    char* element = /* Retrieve the element for the current state */;

    if(check_selector(element, states->selector)) {
        State *matchedState = malloc(sizeof(State));

        if (matchedState == NULL) {
            return NULL; // Failed to allocate memory.
        }

        matchedState->id = states->id;
        matchedState->selector = strdup(states->selector);
        matchedState->next = traverseFSA(fsa->states, fsa->numStates, fsa, lastState); // Continue to the next state.

        if (lastState != NULL) {
            lastState->next = matchedState; 
        }

        return matchedState;
    } else {
        return traverseFSA(states + 1, numStates - 1, fsa, lastState); // Skip to the next state without adding anything.
    }
}
