```java
import java.io.*;
import java.security.MessageDigest;
import java.util.*;
import java.net.HttpURLConnection;
import java.net.URL;
import org.apache.commons.codec.binary.Hex;
import org.apache.commons.lang3.SerializationUtils;

public class RandomStringGenerator {
    private static final int CACHE_SIZE = 10000;
    // Use LRU cache to prevent memory overflow
    private Map<ByteArrayOutputStream, String> cache = Collections.synchronizedMap(new LinkedHashMap<ByteArrayOutputStream, String>() {
        protected boolean removeEldestEntry (Map.Entry<ByteArrayOutputStream, String> eldest) {
            return size() > CACHE_SIZE;
        }
    });

    public String generateRandomStringFromBytes(byte[] data, int length, String password) throws Exception {
        ByteArrayInputStream in = new ByteArrayInputStream(data);
        ObjectInput deserializer = null;
        try {
            deserializer = new java.io.ObjectInputStream(in);
            Object obj = deserializer.readObject();

            if (cache.containsKey((ByteArrayOutputStream) deserializer)) return cache.get((ByteArrayOutputStream) deserializer);

            String charsetUrl = "http://yourdatasource.com/charset";  // replace with your datasource URL
            String charset = getCharSetFromExternalSource(charsetUrl);

            Random rand = new Random();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < length; ++i) {
                int randomIndex = rand.nextInt(charset.length());  // generate a random number up to charset size
                sb.append(charset.charAt(randomIndex));
            }

            String resultString = sb.toString();
            cache.put((ByteArrayOutputStream) deserializer, resultString);

            return hashPassword(resultString, password);
        } finally {
            if (deserializer != null) deserializer.close();
        }
    }

    private String getCharSetFromExternalSource(String urlStr) throws Exception {
        URL url = new URL(urlStr);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
            throw new Exception("Failed to retrieve charset: HTTP error code : " + connection.getResponseCode());
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        String inputLine;
        StringBuilder response = new StringBuilder();

        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();

        return response.toString();
    }

    private String hashPassword(String password, String salt) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256"); // you can change it to other hashing algorithm like SHA1, MD5 etc based on requirement

        if (salt != null) {
            md.update(salt.getBytes());
        }

        byte[] bytes = md.digest(password.getBytes());

        return Hex.encodeHexString(bytes);
    }
}
```

