#include <stdio.h>
#include <string.h>
#include <ctype.h> // for isalnum function

// maximum length for the new filename
#define MAX_FILENAME_LEN 255

void modifyFilename(char *filename, char* prefixOrSuffix, int numDigits, const char *fileType) {
    if (filename == NULL || strlen(filename) == 0) {
        printf("Empty filename is not allowed.\n");
        return;
    }

    // check for invalid characters in the original filename
    for (int i = 0; i < strlen(filename); i++) {
        if (!isalnum((unsigned char)filename[i]) && filename[i] != '.' && filename[i] != '/') {
            printf("Filename contains invalid characters.\n");
            return;
        }
    }

    // create new filename with given prefix, digits and file type
    char new_filename[MAX_FILENAME_LEN];
    strcpy(new_filename, "");  // initialize new_filename to empty string

    if (prefixOrSuffix != NULL) {
        strcat(new_filename, prefixOrSuffix);
    }

    char *dot = strrchr(filename, '.');  // find the last dot in filename
    if (dot != NULL && dot != filename) {  // make sure it's not the first character and there is a valid extension
        size_t len_without_ext = dot - filename;

        char *new_base = (char*)malloc(len_without_ext + 1);  // allocate memory for new base name
        strncpy(new_base, filename, len_without_ext);  
        new_base[len_without_ext] = '\0';  // null terminate the string

        sprintf(filename, "%s.%.*d%s", new_base, numDigits, rand() % (int)pow(10,numDigits), fileType);
    } else {
        sprintf(filename, "%s.%.*d%s", filename, numDigits, rand() % (int)pow(10,numDigits), fileType);
    }

    free(new_base); // deallocate memory allocated for new base name

    // check if the length of the new filename doesn't exceed maximum limit
    if (strlen(filename) > MAX_FILENAME_LEN) {
        printf("New filename exceeds max length.\n");
        return;
    }
}
```
This function takes a filename, prefix/suffix, number of digits and file type as input. It first checks if the filename is not empty and does not contain invalid characters. Then it creates a new filename based on these parameters using `sprintf`. If an existing prefix/suffix is given, this gets added to the new filename. The base name (the part of the original filename without extension) is modified by appending a random number with a specific number of digits and the file type. The function also checks if the length of the new filename does not exceed the maximum limit.

