```python
import mysql.connector
from graphql import validate, parse

class DatabaseConnector:
    def __init__(self, config):
        self._db_type = config['database_type']
        self._conn_str = config['connection_string']
        self._timeout = config.get('timeout', 10)
        self._retries = config.get('retries', 3)
        self._connect()

    def _connect(self):
        if self._db_type == 'mysql':
            self._connection = mysql.connector.connect(host=self._conn_str, user=self._user, password=self._password, database=self._database)
        else:
            raise ValueError('Unsupported database type')

    def execute(self, query):
        cursor = self._connection.cursor()
        cursor.execute(query)
        result = []
        for row in cursor:
            result.append(row)
        return result

    def transaction(self, queries):
        cursor = self._connection.cursor()
        for query in queries:
            cursor.execute(query)
        self._connection.commit()

def update_user(schema, args):
    db = DatabaseConnector({'database_type': 'mysql', 'connection_string': "localhost",  # replace with your own connection info
                            'username': 'root', 'password': '', 'database': 'test'})
    errors = validate(schema, parse(args['query']))
    if not errors:
        db.transaction([f"UPDATE users SET {', '.join(f'{k}={repr(v)}' for k, v in args['set'].items())} WHERE id = {args['id']}"])
        return {'success': True}, []
    else:
        return {}, errors

def delete_user(schema, args):
    db = DatabaseConnector({'database_type': 'mysql', 'connection_string': "localhost",  # replace with your own connection info
