enum class LogLevel { DEBUG, INFO, WARN, ERROR };

class LogEntry {
public:
    std::string message;
    LogLevel level;
};

void insertLog(std::forward_list<std::shared_ptr<LogEntry>>& list, 
               const std::string& logMessage, 
               LogLevel desiredLevel,
               int times = 1) {
    bool inserted = false;
    for (auto it = list.begin(); it != list.end(); ++it) {
        if ((*it)->level == desiredLevel) {
            // Insert the log entry after the matching LogEntry
            ++it;  // Move to next element since we are inserting after current one
            for (int i = 0; i < times; ++i) {
                it = list.insert_after(it, std::make_shared<LogEntry>());
                (*it)->message = logMessage;
                (*it)->level = desiredLevel;
                ++it;  // Move to next inserted element
            }

            // External logging API call placeholder.
            // replace with real implementation or remove if not needed
            try {
              std::cout << "Sending log: " << (*it)->message << " via external logging API.";
            } catch (std::exception& e) {
              std::cerr << "Error sending log. Reason: " << e.what() << std::endl;
            }

            inserted = true;
        }
    }

    if (!inserted) {  // Log level not found, insert at the end of list
      list.push_front(std::make_shared<LogEntry>());
      auto it = list.begin();
      (*it)->message = logMessage;
      (*it)->level = desiredLevel;
    }
}
