import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import javax.json.Json;
import javax.json.JsonReader;
import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;
import java.util.*;

@ServerEndpoint(value = "/chat/{roomId}/{user}")
public class ChatService {
    private static final Logger auditLogger = LoggerFactory.getLogger("AuditLogger");
    private static final ObjectMapper objectMapper = new ObjectMapper();

    @OnOpen
    public void onOpen(Session session, EndpointConfig config) throws IOException {
        // Connect to room and add user to connection pool
        ConnectionPool.getInstance().borrowObject();
        auditLogger.info("User {} connected to room", session.getUserProperties().get("user"));
    }

    @OnMessage
    public void onMessage(String message, Session session) throws IOException {
        // Parse and validate JSON payload
        try {
            JsonNode jsonNode = objectMapper.readTree(message);

            if (!isValidUserInfoAndMessageContent(jsonNode)) {
                throw new InvalidPayloadException("Invalid user information or message content");
            }

            // Forward to all chat rooms
            String roomIds = (String) session.getUserProperties().get("roomId");

            for (String roomId : roomIds.split(",")) {
                Connection connection = ConnectionPool.getInstance().borrowObject();

                if (connection != null) {
                    connection.sendMessage(jsonNode, session);
                } else {
                    auditLogger.error("Failed to send message from user {} in room {}", 
                            session.getUserProperties().get("user"), roomId);
                }
            }
        } catch (InvalidPayloadException e) {
            // Log and return error message to client
            auditLogger.error("Invalid payload from user {}", session.getUserProperties().get("user"));
            session.getBasicRemote().sendText(e.getMessage());
        }
    }

    @OnClose
    public void onClose(Session session, CloseReason closeReason) {
        // Disconnect from room and return connection to pool
        ConnectionPool.getInstance().returnObject(((ChatConnection)session).getConnection());
        auditLogger.info("User {} disconnected from room", session.getUserProperties().get("user"));
    }

    private boolean isValidUserInfoAndMessageContent(JsonNode jsonNode) {
        // Validate user info and message content

        return true;
    }
}
```
