```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Text;

public class DynamicQueryExecutor
{
    private readonly string connectionString;

    public DynamicQueryExecutor(string connectionString)
    {
        this.connectionString = connectionString;
    }

    public DataTable ExecuteDynamicQuery(string baseSql, params SqlParameter[] parameters)
    {
        var query = new StringBuilder();

        // Build the final SQL command
        query.AppendLine("SET NOCOUNT ON;");
        query.AppendLine(baseSql);

        using (var connection = new SqlConnection(connectionString))
        {
            using (var command = new SqlCommand(query.ToString(), connection))
            {
                // Add parameters to the command
                foreach (var parameter in parameters)
                    command.Parameters.Add(parameter);

                try
                {
                    connection.Open();

                    var dataSet = new DataTable();

                    using (var adapter = new SqlDataAdapter(command))
                        adapter.Fill(dataSet);

                    return dataSet;
                }
                catch (Exception ex)
                {
                    // Log the exception
                    Console.WriteLine("An error occurred while executing the query: " + ex.Message);
                    throw;
                }
            }
        }
    }
}
``` 

