use std::{fs, io, path::PathBuf};
use tokio::sync::RwLock;
use log::{debug, error, info, trace, warn};

pub struct Compiler {
    cache: RwLock<Cache>,
}

impl Compiler {
    pub fn new() -> Self {
        let cache = Cache::new();
        Self {
            cache: RwLock::new(cache),
        }
    }

    pub async fn compile(&self, files: Vec<PathBuf>) -> Result<(), io::Error> {
        let cache_read = self.cache.read().await;
        for file in files {
            let path = file.as_path();
            if !path.exists() {
                error::err(format::NotFound, path)?;
                continue;
            }

            // read from cache
            if let Some(cached) = cache_read.get(&path) {
                debug::compilation("Using cached compilation for {}", path);
                continue;
            }

            info::compilation("Compiling {}", path);
            tokio::task::spawn(async move {
                let contents = fs::read(path).await?;

                // compile the file here...

                let lock = self.cache.write().await;
                lock.insert(&path, cached);
                trace::compilation("Cached compilation for {}", path)
            });
        }
        Ok(())
    }
}
```
