```java
import org.apache.commons.io.FileUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.File;
import java.lang.reflect.Constructor;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class FileValidator {
    private final Logger logger = LoggerFactory.getLogger(this.getClass());
    private ExecutorService executorService;

    public void processFileBatchWithValidation(String inputDirectory, String outputDirectory, List<Rule> validationRules) throws Exception {
        File[] files = new File(inputDirectory).listFiles();

        if (files == null) {
            return;
        }

        // Create a fixed thread pool with the number of available processors as the target size.
        executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (File file : files) {
            if (!file.isDirectory()) {
                executorService.execute(() -> validateFile(file, outputDirectory, validationRules));
            }
        }

        // Wait for all tasks to complete and shutdown the thread pool.
        executorService.shutdown();
        executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
    }

    private void validateFile(File file, String outputDirectory, List<Rule> validationRules) {
        for (Rule rule : validationRules) {
            logger.info("Starting validation of {} using {}", file.getName(), rule.getClass().getName());

            try {
                // Instantiate the rule class and validate the file.
                Constructor<?> ctor = Class.forName(rule.getRule()).getConstructor();
                Object object = ctor.newInstance();

                if (object instanceof Rule) {
                    ((Rule) object).validate(file, outputDirectory);
                }
            } catch (Exception e) {
                logger.error("Validation failed for {} using {}", file.getName(), rule.getClass().getName(), e);
            }

            logger.info("Completed validation of {} using {}", file.getName(), rule.getClass().getName());
        }
    }
}
```
