Implementing this in C++ is quite complex as it involves multiple threads, dynamic memory allocation for nodes, octree operations, condition variables, error handling, and so on. Here is a simple implementation of an OctreeNode class with methods to insert points and check if a point exists. Due to the complexity of the problem and restrictions like thread safety and performance optimizations, implementing it in detail would require much more than this code snippet:

```cpp
#include <array>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <stdexcept>

// A simple 3D point class.
struct Point {
    float x, y, z;
};

class OctreeNode {
public:
    // Constructor that takes bounds of the space this node covers.
    OctreeNode(float minX, float maxX, float minY, float maxY, float minZ, float maxZ) 
        : isLeaf_(true), children_{nullptr}, minX_(minX), maxX_(maxX), minY_(minY), maxY_(maxY), minZ_(minZ), maxZ_(maxZ) { }

    // Destructor to cleanup child nodes.
    ~OctreeNode() {
        if (!isLeaf_) {
            for (auto& child : children_) {
                delete child;
            }
        }
    }

    // Insert a point into the node.
    void insert(const Point& p) {
        std::lock_guard<std::mutex> lock(m_); 

        if (isLeaf_) {
            points_.push_back(p);

            // If we've exceeded our maximum capacity, split this node.
            if (points_.size() > MAX_CAPACITY) {
                split();
            }
        } else {
            getChildForPoint(p)->insert(p);
        }
    }

    // Check whether a point exists in the node.
    bool contains(const Point& p) const {
        std::lock_guard<std::mutex> lock(m_); 

        if (isLeaf_) {
            for (auto& point : points_) {
                if (point.x == p.x && point.y == p.y && point.z == p.z) {
                    return true;
                }
            }
            return false;
        } else {
            return getChildForPoint(p)->contains(p);
        }
    }

private:
    // Maximum capacity of a node before it splits.
    static constexpr size_t MAX_CAPACITY = 1024;

    std::mutex m_;
    bool isLeaf_;
    std::array<OctreeNode*, 8> children_;
    float minX_, maxX_, minY_, maxY_, minZ_, maxZ_;
    std::vector<Point> points_;

    void split() {
        isLeaf_ = false;

        // Create child nodes.
        for (int i = 0; i < 8; ++i) {
            float newMinX = minX_ + i % 2 * (maxX_ - minX_) / 2;
            float newMaxX = minX_ + (i % 2 + 1) * (maxX_ - minX_) / 2;
            float newMinY = minY_ + (i / 4) % 2 * (maxY_ - minY_) / 2;
            float newMaxY = minY_ + ((i / 4) % 2 + 1) * (maxY_ - minY_) / 2;
            float newMinZ = minZ_ + i / 2 * (maxZ_ - minZ_) / 2;
            float newMaxZ = minZ_ + (i / 2 + 1) * (maxZ_ - minZ_) / 2;

            children_[i] = new OctreeNode(newMinX, newMaxX, newMinY, newMaxY, newMinZ, newMaxZ);
        }

        // Distribute points to child nodes.
        for (auto& point : points_) {
            getChildForPoint(point)->insert(point);
        }
        points_.clear();
    }

    OctreeNode* getChildForPoint(const Point& p) const {
        int index = 0;

        if (p.x >= minX_ + (maxX_ - minX_) / 2) index += 1;
        if (p.y >= minY_ + (maxY_ - minY_) / 2) index += 2;
        if (p.z >= minZ_ + (maxZ_ - minZ_) / 2) index += 4;

        return children_[index];
    }
};
```

