// Define log levels
enum LogLevel {
    INFO, WARNING, ERROR
};

void log_message(const char *msg, enum LogLevel level) {
    const char* prefix;
    switch (level) {
        case INFO: 
            prefix = "INFO";
            break;
        case WARNING: 
            prefix = "WARNING";
            break;
        case ERROR: 
            prefix = "ERROR";
            break;
    }

    printf("%s: %s\n", prefix, msg);
}

double compute_average(const char* line) {
    double num = 0.0, sum = 0.0;
    int count = 0;
    char *token = strtok(line, " ");

    while (token != NULL && count < 3) {
        if (!sscanf(token, "%lf", &num)) {
            log_message("Non-numeric value found in line.", WARNING);
            return 0.0;
        }

        sum += num;
        token = strtok(NULL, " ");
        count++;
    }

    if (count < 3) {
        log_message("Less than three numerical values in line.", WARNING);
        return 0.0;
    }

    return sum / 3.0;
}

void process_line(FILE *input, FILE *output) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    double average;

    while ((read = getline(&line, &len, input)) != -1) {
        if (strcmp(line, "\n")) continue;  // Skip empty lines

        average = compute_average(line);
        fprintf(output, "%.2lf\n", average);
    }

    free(line);
}

int main() {
    FILE *inputFile = fopen("largefile.txt", "r");
    if (inputFile == NULL) {
        log_message("Unable to open input file.", ERROR);
        return EXIT_FAILURE;
    }

    FILE *outputFile = fopen("outfile.csv", "w");
    if (outputFile == NULL) {
        log_message("Unable to open output file.", ERROR);
        fclose(inputFile);
        return EXIT_FAILURE;
    }

    process_line(inputFile, outputFile);

    fclose(inputFile);
    fclose(outputFile);
    return 0;
}
```
