#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_REQUESTS 100 // Maximum number of requests to the external server per second
#define LOGFILE "logs.txt" // Name and path of log file

// Structure for holding thread data
typedef struct {
    sem_t *semaphore;
    int *dataArray;
    int arraySize;
} ThreadData;

// Structure to hold network socket information
struct SocketInfo {
    int sockfd;
};

FILE *logfile; // Global file pointer for logging 
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread-safe logging
sem_t rateSemaphore; // Semaphore for rate limiting
time_t startTime, endTime; // Time variables for calculating rate limit
int requests = 0; // Number of requests sent to the server

void *threadFunction(void *arg) {
    ThreadData *data = (ThreadData *) arg;

    while(1){
        sem_wait(data->semaphore);

        if(requests < MAX_REQUESTS){
            // Wait for the rate limit to expire 
            time(&endTime);
            double elapsedTime = difftime(endTime, startTime);

            if(elapsedTime < 1.0){
                sem_post(data->semaphore);
                continue;
            }

            // Reset the rate limit if it has expired 
            requests = 0;
            time(&startTime);
        }

        int max = getMaxIntegerFromArray(data->dataArray, data->arraySize);

        // Send request to external server
        struct SocketInfo si = connectToServer();
        if(sendDataToServer(si.sockfd, &max, sizeof(int)) < 0){
            sem_post(data->semaphore);
            continue;
        }

        int response = receiveResponseFromServer(si.sockfd);
        closeSocket(si.sockfd);

        if (response > 0) {
            logAction("Request sent to server");
        } else {
            logError("Failed to send request to server", errno);
        }

        sem_post(data->semaphore);
    }

    return NULL;
}

int main() {
