#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>

typedef struct {
  sem_t* sem;
  int initialValue;
} SemaphoreManager;

SemaphoreManager* createSemaphore(int initialValue) {
  SemaphoreManager* sm = (SemaphoreManager*) malloc(sizeof(SemaphoreManager));

  if (!sm) return NULL; // Handle memory allocation failure

  sem_t* sem = malloc(sizeof(sem_t));

  if (sem_init(sem, 0, initialValue)) {
    free(sem);
    free(sm);
    return NULL; // Handle semaphore initialization failure
  }

  sm->initialValue = initialValue;
  sm->sem = sem;

  return sm;
}

void deleteSemaphore(SemaphoreManager* sm) {
  if (sm && sm->sem) {
    sem_destroy(sm->sem);
    free(sm->sem);
    free(sm);
  }
}

