public class State {
    int id;
    ArrayList<State> nextStates = new ArrayList<>(); // The FSA

    public List<Integer> getReachableStates(int index, boolean[] visited) {
        if(!visited[index]) {
            List<Integer> reachableStates = new ArrayList<>();

            for(State state : this.nextStates) {
                reachableStates.addAll(state.getReachableStates(state.id, visited)); 
                visited[state.id] = true; // Mark node as visited
            }
            return reachableStates;
        } else {
            return new ArrayList<>();
        }
    }
}
