Here's a basic implementation of such a function in C. Please note that I have made some assumptions about the representation of the graph: the adjacency list is an array of lists, where each index represents a node and each element in the list represents its neighbors. Also, we assume nodes are represented by integers from 0 to n-1, where n is the total number of nodes.

```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a node in adjacency list
typedef struct AdjListNode {
    int dest;
    struct AdjListNode* next;
}AdjListNode;

// Define an array of lists which represents adjacency list
typedef struct Graph {
    struct AdjListNode* head;  
}Graph;

// A queue node to store node and minimum distance from source to the node.
typedef struct QueueNode {
    int node;
    int dist;
}QueueNode;

// Structure for dynamic size queue
struct Queue {
    int front, rear, size;
    unsigned capacity;
    struct QueueNode* array;
};

// Function to create a new graph
Graph* createGraph(int V) {
    Graph* graph = (Graph*) malloc(sizeof(Graph));

    // Create an array of adjacency lists. Size of array will be V
    graph->head = (AdjListNode*)malloc(V * sizeof(AdjListNode));

    return graph;
}

// Function to create a new node in adjacency list
AdjListNode* newAdjListNode(int dest) {
    AdjListNode* newNode = (AdjListNode*) malloc(sizeof(AdjListNode));
    newNode->dest = dest;
    newNode->next = NULL;
    return newNode;
}

// Function to add an edge to a graph. This function is needed since the graph is undirected, so we need to add edges in both directions.
void addEdge(Graph* graph, int src, int dest) {
    // Add an edge from src to dest and vice versa
    AdjListNode* newNode = newAdjListNode(dest);
    newNode->next = graph[src].head;
    graph[src].head = newNode;

    newNode = newAdjListNode(src);
    newNode->next = graph[dest].head;
    graph[dest].head = newNode;
}

// Function to create a new queue node.
QueueNode* newQueueNode(int node, int dist) {
    QueueNode* temp = (QueueNode*) malloc(sizeof(QueueNode));
    temp->node = node;
    temp->dist = dist;
    return temp; 
}

// Function to create a new queue.
struct Queue* createQueue(int capacity) {
    struct Queue* queue = (struct Queue*) malloc(sizeof(struct Queue));
    queue->capacity = capacity;
    queue->front = queue->size = 0; 
    queue->rear = capacity - 1;  
    queue->array = (QueueNode*) malloc(queue->capacity * sizeof(QueueNode));
    return queue;
}

// Queue is full when size equals the capacity
int isFull(struct Queue* queue) {  return (queue->size == queue->capacity); }

// Queue is empty when size is 0
int isEmpty(struct Queue* queue) {  return (queue->size == 0); }

// Function to add an item to the queue. It changes rear and size
void enqueue(struct Queue* queue, int node, int dist) {
    if (isFull(queue))
        return;

    queue->rear = (queue->rear + 1) % queue->capacity;
    queue->array[queue->rear] = *newQueueNode(node, dist);
    queue->size++;
}

// Function to remove an item from queue. It changes front and size
QueueNode* dequeue(struct Queue* queue) {
    if (isEmpty(queue))
        return NULL;

    QueueNode* item = &queue->array[queue->front];
    queue->front = (queue->front + 1) % queue->capacity;
    queue->size--;

    return item;
}

// Function to do BFS traversal from a given source 's'. It uses matrix representation of graph.
int* bfs(Graph* graph, int V, int s, int hops) {
    // Mark all the vertices as not visited and not part of recursion stack
    int *visited = (int*) calloc(V, sizeof(int));

    // Create a queue for BFS
    struct Queue* q = createQueue(V);

    // Enqueue source and initialize distance to zero
    enqueue(q, s, 0);

    int* result = (int*) malloc(V * sizeof(int));
    int count = 0;

    while (!isEmpty(q)) {
        // Dequeue a vertex from queue and print it
        QueueNode* node = dequeue(q);

        if(!visited[node->node] && node->dist <= hops) {
            visited[node->node] = 1;
            result[count++] = node->node;

            // Get all adjacent vertices of the dequeued vertex s. If an adjacent has not been visited, then mark it visited and enqueue it
            AdjListNode* crawl = graph[node->node].head;
            while(crawl) {
                if (!visited[crawl->dest]) {
                    enqueue(q, crawl->dest, node->dist + 1);
                }
                crawl = crawl->next;
            }
        }
    }

    result = (int*) realloc(result, count * sizeof(int));
    free(visited);
    return result;
}
```
The bfs function will return a dynamically allocated array of integers that represent all nodes that are reachable from the starting node within a specified number of hops. The adjacency list and graph creation functions are also implemented, as well as queue data structure for BFS algorithm. The isFull and isEmpty functions ensure we don't try to dequeue or enqueue from an empty or full queue.

