import asyncio
from concurrent.futures import ThreadPoolExecutor
import os
import json
import logging
import hashlib
from collections import OrderedDict, deque
from functools import lru_cache
from typing import List, Tuple, Deque, Union

logging.basicConfig(level=logging.INFO)

class JsonObject:
    _registry = {}

    @staticmethod
    def register(id: str):
        def decorator(func):
            JsonObject._registry[id] = func
            return func
        return decorator

    def __init__(self, data=None):
        self.data = data if data else {}

    @classmethod
    async def load_from_file(cls, filepath: str):
        with open(filepath, 'r') as f:
            try:
                json_str = await f.read()
                return cls(json.loads(json_str))
            except Exception as e:
                logging.error("Failed to load JSON file %s: %s", filepath, str(e))

    @classmethod
    async def load_multiple_files(cls, filepaths: List[str]):
        tasks = []

        with ThreadPoolExecutor() as executor:
            loop = asyncio.get_event_loop()

            for filepath in filepaths:
                task = loop.run_in_executor(executor, cls.load_from_file, filepath)
                tasks.append(task)

        return await asyncio.gather(*tasks)

    def to_json(self):
        try:
            return json.dumps(self.data)
        except Exception as e:
            logging.error("Failed to convert data to JSON string: %s", str(e))

    @classmethod
    def from_json(cls, json_str: str):
        try:
            return cls(json.loads(json_str))
        except Exception as e:
            logging.error("Failed to create new instance of class from JSON string: %s", str(e))

    def insert_strings(self, flist: Deque[str], target: str, new: str, index=0):
        count = flist.count(target)

        if not count:
            logging.warning("Target string %s not found in list", target)
            flist.append(new)
            return

        if index >= len(flist):
            logging.error("Position index out of bounds")
            return

        position = -1

        for _ in range(count):
            try:
                position = flist.index(target, position+1)
            except ValueError:
                break

            if position == index:
                flist.insert(position + 1, new)
