```cpp
#include <iostream>
#include <fstream>
#include <openssl/md5.h>
#include <string>
#include <map>
#include <cstdlib>

// Function prototypes
bool calculateHash(const std::string& inFilePath, unsigned char* outHash);
void convertJpgToPdf(const std::string& inFilePath, const std::string& outFilePath);
int processFile(const std::string& inFilePath, const std::string& outFilePath);

// A map to store previously computed hashes
std::map<std::string, unsigned char*> hashCache;

int main() {
    // Test the function with some files
    processFile("input.jpg", "output.pdf");
    return 0;
}

bool calculateHash(const std::string& inFilePath, unsigned char* outHash) {
    try {
        FILE *file = fopen(inFilePath.c_str(), "rb");
        if (!file) return false;

        MD5_CTX mdContext;
        int bytes;
        unsigned char data[1024];

        MD5_Init(&mdContext);
        while ((bytes = fread(data, 1, 1024, file)) != 0) {
            MD5_Update(&mdContext, data, bytes);
        }
        MD5_Final(outHash, &mdContext);

        // Clear the cache if we have more than 100 items
        if (hashCache.size() > 100) hashCache.clear();

        fclose(file);
    } catch (std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
        return false;
    }

    return true;
}

void convertJpgToPdf(const std::string& inFilePath, const std::string& outFilePath) {
    try {
        // Use system command to call the external tool for conversion.
        // This is a dummy command and would need to be replaced with the actual command of your third-party tool
        std::string cmd = "convert " + inFilePath + " " + outFilePath;
        if (std::system(cmd.c_str()) != 0) {
            throw std::runtime_error("Error: Failed to convert JPG to PDF");
        }
    } catch (std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }
}

int processFile(const std::string& inFilePath, const std::string& outFilePath) {
    // If the file is already cached, use it instead of calculating again
    if (hashCache[inFilePath]) {
        convertJpgToPdf(inFilePath, outFilePath);
        return 0;
    }

    unsigned char* hash = new unsigned char[MD5_DIGEST_LENGTH];
    bool success = calculateHash(inFilePath, hash);

    if (success) {
        convertJpgToPdf(inFilePath, outFilePath);

        // Cache the computed hash for future use
        hashCache[inFilePath] = hash;

        return 0;
    } else {
        delete[] hash;
        return 1;
    }
}
```
This is a very basic implementation and needs to be customized according to your project's requirements. Also, please note that you need to replace the dummy command in `convertJpgToPdf()` with the actual system call for converting from JPG to PDF using the third-party tool of your choice.

The following is a high-level skeleton of how you could structure your C++ program using modern techniques, including multi-threading support, efficient memory management, and streaming data processing, but it's worth noting that this task requires more in-depth planning and coding than can be presented here. 

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <thread>
#include <atomic>
#include <vector>
#include <algorithm>
#include <limits>
#include "Logger.h" // Assuming you have a logger module

class DataProcessor {
    std::vector<int> numbers;
    std::mutex mtx; 
public:
    void readData(const std::string& fileName) {
        std::ifstream inFile(fileName);
        if (inFile.fail()) {
            Logger::logError("Failed to open the file " + fileName);
            return;
        }
        int number;
        while (!inFile.eof()){
            inFile >> number;
            // Validate integer within specified range (-1000000 to 1000000)
            if(number >= -1000000 && number <= 1000000){  
                std::lock_guard<std::mutex> lock(mtx);
                numbers.push_back(number);
            } else {
                Logger::logError("Invalid data: " + std::to_string(number));
            }
        }
    }

    int getMax() const{
        return *std::max_element(numbers.begin(), numbers.end());
    }

    double getAverage(){
        long long sum = 0;
        for (const auto& number : numbers) {
            sum += number;
        }
        return static_cast<double>(sum) / numbers.size();
    }
};

int main(int argc, char* argv[]){
    std::vector<std::thread> threads;
    DataProcessor processor;

    for (int i = 1; i < argc; ++i) {
        threads.push_back(std::thread(&DataProcessor::readData, &processor, argv[i]));
    }

    for (auto& th : threads) {
        th.join();
    }

    std::cout << "Max: " << processor.getMax() << '\n';
    std::cout << "Average: " << processor.getAverage() << '\n';

    return 0;
}
```
