<?php
class SecureTokenManager {
    private $session;

    function __construct() {
        $this->session = new Session();
    }

    public function generateSecureRandomString($length = 32, $characterset = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ') {
        try {
            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $randomString .= $characterset[rand(0, strlen($characterset) - 1)];
            }

            return $randomString;
        } catch (Exception $e) {
            // Handle error: Log or display it.
        }
    }

    public function hashPassword($password, $algorithm = PASSWORD_BCRYPT) {
        try {
            $hashedPassword = password_hash($password, $algorithm);

            return $hashedPassword;
        } catch (Exception $e) {
            // Handle error: Log or display it.
        }
    }

    public function generateSessionToken() {
        $token = $this->generateSecureRandomString();
        $this->session->set('token', $token);

        return $token;
    }

    public function secureDelete($data) {
        try {
            if (is_string($data)) {
                sodium_memzero($data);
            } else if (is_array($data)) {
                foreach ($data as $value) {
                    $this->secureDelete($value);
                }
            } else {
                throw new Exception('Invalid data type for deletion.');
            }
        } catch (Exception $e) {
            // Handle error: Log or display it.
        }
    }
}
?>
