import json
from abc import ABCMeta, abstractmethod
from collections import deque
from threading import Thread, Lock
from queue import Queue
import logging

class BaseClass(metaclass=ABCMeta):
    _registry = {}

    @abstractmethod
    def to_json(self): pass

    @staticmethod
    def from_json(data): pass

    @classmethod
    def add_factory(cls, id, factory):
        cls._registry[id] = factory

    @classmethod
    def create_instance(cls, id, *args, **kwargs):
        if id not in cls._registry:
            raise ValueError("No factory function found for ID {}".format(id))
        return cls._registry[id](*args, **kwargs)

class SubClass(BaseClass):
    def __init__(self, data):
        self.data = data

    def to_json(self):
        return json.dumps({'data': self.data})

    @staticmethod
    def from_json(data):
        return SubClass(**json.loads(data))

BaseClass.add_factory("Sub", SubClass)
