```rust
use std::io;
use std::fs::{self, FileType};
use std::path::PathBuf;
use chrono::prelude::*;

fn create_directory(parent_dir: &str, dirname: Option<&str>) -> io::Result<()> {
    let mut dir = PathBuf::from(parent_dir);

    let timestamp = Utc::now().format("%Y%m%d%H%M%S").to_string();
    if let Some(name) = dirname {
        dir.push(format![{name}_{timestamp}]);
    } else {
        dir.push(timestamp);
    }

    fs::create_dir(&dir)?;

    Ok(())
}
```
