class Widget():
    def __init__(self, widget_type, size, content):
        self.widget_type = widget_type
        self.size = size
        self.content = content

def generate_html(widgets):
    html_str = ''

    for widget in widgets:
        if widget.widget_type == 'text':
            html_str += f'<p style="font-size:{widget.size}px;">{widget.content}</p>\n'

        elif widget.widget_type == 'image':
            html_str += f'<img src="{widget.content}" alt="Image" width="{widget.size}"/>\n'

        elif widget.widget_type == 'button':
            if 'onclick' not in widget.__dict__:
                print(f"Error: Button widget {widget.content} doesn't have an onclick action.")
                continue

            html_str += f'<button style="font-size:{widget.size}px;" onclick="{widget.onclick}">{widget.content}</button>\n'

        else:
            print(f"Error: Invalid widget type {widget.widget_type}. Skipping...")
            continue

    return html_str
```
