```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>

// Global Semaphore
sem_t sync;

void* thread(void* arg) {
    // Wait state on semaphore 
    printf("\nBefore the acquire\n");
    sem_wait(&sync);
    printf("\nInside critical section\n");

    // Critical section
    sleep(4);

    printf("\nOut of critical section\n");

    // Signal state on semaphore
    sem_post(&sync);
}

int main() {
    // Initialize Semaphore with value 1
    sem_init(&sync, 0, 1);

    pthread_t t1,t2;

    // Create two threads
    pthread_create(&t1,NULL,thread,NULL);
    sleep(2);
    pthread_create(&t2,NULL,thread,NULL);

    // Wait for both threads to finish
    pthread_join(t1,NULL);
    pthread_join(t2,NULL);

    // Destroy semaphore
    sem_destroy(&sync);

    return 0;
}
```
This is a simple example of how semaphores could be used in C. The `sem_wait` function acquires the semaphore and decreases its count, while `sem_post` increments it. If the value of the semaphore drops below zero, then threads waiting for this semaphore will block until it is available again. 

