Implementing this semaphore management system in C++ would require significant effort and might be too large to fit into a single code block here due to its complexity and size. However, I'll provide a high-level overview with some placeholder functions to illustrate the key concepts:

```cpp
#include <mutex> // std::mutex
#include <condition_variable> // std::condition_variable

// This is just an example class for illustrative purposes. 
// The actual implementation would depend on your specific use case and cloud service API.
class Semaphore {
public:
    explicit Semaphore(int count = 1) : count_(count){}

    void notify() {
        std::unique_lock<std::mutex> lock(mtx_);
        ++count_;
        cv_.notify_one();
    }

    void wait() {
        std::unique_lock<std::mutex> lock(mtx_);
        while(count_ == 0) {
            cv_.wait(lock);
        }
        --count_;
    }

    bool try_wait() {
        std::unique_lock<std::mutex> lock(mtx_);
        if(count_) {
            --count_;
            return true;
        }
        return false;
    }
private:
    std::mutex mtx_;
    std::condition_variable cv_;
    int count_;
};
```
