Here is a simplified version of your requested `StringHasher` class in C#. This only includes MD5, SHA256 hashing methods and parallel string hashing for simplicity. The actual implementation may vary based on the specific requirements and constraints of your project.

```CSharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using NLog;

public class StringHasher
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();

    public string ComputeHashMD5(string input)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));

            var sb = new StringBuilder();
            foreach (var bytes in hashBytes)
            {
                sb.Append(bytes.ToString("X2"));
            }

            return sb.ToString();
        }
    }

    public string ComputeHashSHA256(string input)
    {
        using (var sha256 = SHA256.Create())
        {
            var hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));

            var sb = new StringBuilder();
            foreach (var bytes in hashBytes)
            {
                sb.Append(bytes.ToString("X2"));
            }

            return sb.ToString();
        }
    }

    public async Task<string[]> ComputeParallelHashAsync(string[] inputs, Func<string, string> hasher)
    {
        var results = new string[inputs.Length];

        try
        {
            await Task.Run(() => Parallel.For(0, inputs.Length, i => 
            { 
                try 
                {
                    results[i] = hasher?.Invoke(inputs[i]);
                }
                catch (Exception ex)
                {
                    logger.Error(ex);
                }
            }));
        }
        catch (Exception ex)
        {
            logger.Fatal(ex);
            throw;
        }

        return results;
    }
}
```

