```python
import json
import asyncio
from collections import deque
from aiologger import Logger
import requests

class FileUploadManager:
    def __init__(self):
        self._factories = {}
        self._uploads_queue = deque()
        self._logger = Logger.with_default_handlers(name='file-upload')

    async def _process_next_item(self):
        if not self._uploads_queue:
            return  # No more items to process
        _, factory, file = self._uploads_queue[0]
        try:
            await factory(file)  # Process the item
        except Exception as e:
            self._logger.error(f"Failed to process {file} with error: {e}")
        finally:
            self._uploads_queue.popleft()  # Remove from queue whether processing was successful or not

    def add_factory(self, id_, factory):
        self._factories[id_] = factory

    async def upload_file(self, file, id_):
        if id_ in self._factories:
            # Schedule the item to be processed
            self._uploads_queue.append((len(self._uploads_queue), self._factories[id_], file))
            await self._process_next_item()  # Start processing this immediately
        else:
            raise ValueError("No factory found for this ID")

    def get_status(self):
        return {file: "Processing" if pos < len(self._uploads_queue) else "Done"
                for pos, _, file in self._uploads_queue}
```
