Here is a simple version of what such a JavaScript function might look like. It uses Promises to handle asynchronous operations, the Async library for managing parallel tasks, and Winston for logging. This example does not include actual unit tests or plugin loading logic, but you can easily replace those parts with your own implementation:

```javascript
const fs = require('fs');
const path = require('path');
const async = require('async');
const winston = require('winston');

// Set up logging service (Winston)
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
});

function runTests(label, f, plugins){
    return new Promise((resolve, reject) => {
        const startTime = Date.now();

        async.eachLimit(plugins, 5, (pluginName, callback) => {
            // Load plugin from external directory
            fs.readFile(path.join(__dirname, 'external', `${pluginName}.js`), 'utf8', (err, data) => {
                if (err){
                    logger.error(`Error loading plugin ${pluginName} -> ${err}`);
                    return callback(err); // Abort tests for this plugin and move to the next one
                }

                try {
                    eval(data);  // Dangerous, only use if you control the plugins' source code
                } catch (e) {
                    logger.error(`Error executing plugin ${pluginName} -> ${e}`);
                    return callback(e); // Abort tests for this plugin and move to the next one
                }

                try {
                    f();  // Execute test function
                    const duration = Date.now() - startTime;
                    logger.info(`Test passed for ${pluginName} in ${duration}ms`);
                    callback();  // Move to the next plugin
                } catch (e) {
                    logger.error(`Error testing plugin ${pluginName}: ${e}`);
                    return reject(e); // Abort all tests if a test fails
                }
            });
        }, err => {
            if (err){
              logger.error('An error occurred during the execution of tests:', err);
              return reject(err);  // Reject the promise on first error
            } else {
              const duration = Date.now() - startTime;
              logger.info(`All ${label} tests passed in ${duration}ms`);
              resolve();  // Resolve the promise if all plugins have been tested successfully
            }
        });
    });
}
```
