#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    FILE *inputFile;
    FILE *outputFile;
} FilePair;

void processLine(char *line, double *avg) {
    char *token = strtok(line, " ");
    int count = 0;
    double sum = 0.0;
    while (token != NULL && count < 3) { // only the last three numbers
        double value = atof(token);
        if (value == 0.0 && strcmp(token, "0") != 0) { // non-numeric value
            printf("Warning: Non-numeric value found in line.\n");
            return;
        } 
        sum += value;
        ++count;
        token = strtok(NULL, " ");
    }

    if (count < 3) { // less than three numerical values
        printf("Warning: Less than three numerical values found in line.\n");
        return;
    } 

    *avg = sum / 3.0;
}

int main(int argc, char **argv) {
    if (argc != 4) { // need input file, output file and log level as arguments
        printf("Usage: %s <input_file> <output_file> <log_level>\n", argv[0]);
        return 1;
    }

    char *inputFileName = argv[1];
    char *outputFileName = argv[2];
    int logLevel = atoi(argv[3]); // assuming log level is integer

    FILE *inputFile = fopen(inputFileName, "r");
    if (inputFile == NULL) {
        printf("Error: Could not open input file.\n");
        return 1;
    }

    FILE *outputFile = fopen(outputFileName, "w");
    if (outputFile == NULL) {
        printf("Error: Could not open output file.\n");
        return 1;
    }

    char line[256]; // assuming lines are no longer than this
    double avg = 0.0;
    while (fgets(line, sizeof(line), inputFile) != NULL) {
        processLine(line, &avg);
        fprintf(outputFile, "%.3lf\n", avg); // write average to output file
    }

    fclose(inputFile);
    fclose(outputFile);

    return 0;
}
```
