Here's an example in C using pthread mutexes for thread safety:

```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
} record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void allocate_memory(long **offsets, int **keys, record ***records, size_t size) {
    pthread_mutex_lock(&lock); // thread-safe

    *offsets = malloc(sizeof(**offsets) * size);
    if(*offsets == NULL) {
        fprintf(stderr, "Memory allocation for offset values failed.\n");
        pthread_mutex_unlock(&lock); // unlock before return to free resources
        return;
    }

    *keys = malloc(sizeof(**keys) * size);
    if(*keys == NULL) {
        fprintf(stderr, "Memory allocation for keys failed.\n");
        free(*offsets); // free allocated memory to prevent leak
        pthread_mutex_unlock(&lock);
        return;
    }

    *records = malloc(sizeof(***records) * size);
    if(*records == NULL) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        free(*offsets); // free allocated memory to prevent leak
        free(*keys); 
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize the arrays
    memset(*offsets, 0, sizeof(**offsets) * size);
    memset(*keys, 0, sizeof(**keys) * size);
    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation for record %zu failed.\n", i);
            while (--i > 0) // free previous allocations 
                free((*records)[i]);
            free(*offsets);
            free(*keys);
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    pthread_mutex_unlock(&lock); // unlock after successful allocation
}
``` 
This function takes the addresses of three pointers, `offsets`, `keys`, and `records`. It allocates memory for an array of 'long' offset values, an array of 'int' keys, and a pointer to an array of 'record' structures respectively. If any allocation fails, it frees all previously allocated memory before returning from the function, providing cleanup of resources and preventing leaks.
Please note that this code assumes you have a C99 or later compiler as it uses `size_t` for size parameters. Also ensure to use `free()` correctly after using these functions as they can potentially cause memory leaks if not used properly. For example, calling `free()` on each allocated memory block in the reverse order of their allocation is important to prevent double free errors and corruption.

