@Service
public class ContentManagementSystem {
    private static final Logger LOGGER = LoggerFactory.getLogger(ContentManagementSystem.class);

    @Autowired
    CacheManager cacheManager;

    public String updateElement(String pageId, String sectionId, String elementId, String jsonContent, String key, String iv) {
        try {
            byte[] decrypted = AESDecryptor.decrypt(jsonContent, key, iv);

            // Assuming you have a PageRepository and SectionRepository that extend JpaRepository
            EhCache cache = (EhCache) cacheManager.getEhCache("content");
            Page page = cache.get(pageId);
            if(page == null) {
                Optional<Page> optionalPage = pageRepository.findById(pageId);
                if(!optionalPage.isPresent()) throw new Exception("Invalid page ID");
                page = optionalPage.get();
                cache.put(new Element(pageId, page));
            }

            Section section = page.getSections().stream()
                    .filter(s -> s.getId().equals(sectionId))
                    .findFirst()
                    .orElseThrow(() -> new Exception("Invalid section ID"));

            Element element = section.getElements().stream()
                    .filter(e -> e.getId().equals(elementId))
                    .findFirst()
                    .orElseThrow(() -> new Exception("Invalid element ID"));

            // Assuming the JSON content contains updated properties of the element...
            ObjectMapper mapper = new ObjectMapper();
            Element newElement = mapper.readValue(decrypted, Element.class);

            section.getElements().remove(element);
            section.getElements().add(newElement);
            sectionRepository.save(section);

            return "Updated successfully";
        } catch (Exception e) {
            LOGGER.error("Error updating element", e);
            return e.getMessage();
        }
    }
}
```

