import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class ImageMetadataExtractor {
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static final ConcurrentHashMap<String, Boolean> cache = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception{
        Path dirPath = Paths.get("/path/to/images");

        try (DirectoryStream<Path> directoryStream = Files.newDirectoryStream(dirPath)) {
            for (Path path : directoryStream) {
                executor.submit(() -> processFile(path));
            }
        } catch (IOException ex) {
            // Handle exception...
        } finally {
            executor.shutdown();
        }

        while (!executor.isTerminated()) {}
    }

    private static void processFile(Path path) {
        String fileName = path.getFileName().toString();
        if (cache.containsKey(fileName)) {
            // File is already processed...
        } else {
            cache.putIfAbsent(fileName, true);  // mark as processed before processing

            // Extract and validate metadata here...
        }
    }
}
```
This code will create a thread pool of fixed size 10 (for example purposes), then process each file in the specified directory using an ExecutorService. Each task is submitted to the executor service, and each task processes a single file. This approach allows multiple files to be processed concurrently for improved performance. The processing results are cached using a ConcurrentHashMap for efficient access and thread-safe modification.

