// moduleLoader.js
const requireAll = require('require-all');
const config = require('./config.json');

let loadedModules = {};

function loadModule(modulePath) {
    if(!loadedModules[modulePath]) {
        try {
            console.log(`Loading module: ${modulePath}`);
            let newModule = require(modulePath);
            loadedModules[modulePath] = newModule;
            return newModule;
        } catch (error) {
            console.error(`Error loading module: ${modulePath}. Error: ${error}`);
            throw error;
        }
    } else {
        return loadedModules[modulePath];
    }
}

function loadAll() {
    config.modules.forEach(modulePath => {
        loadModule(modulePath);
    });
}

loadAll();
```
In this example, `require-all` is a package that loads all modules in a directory and `config.json` contains an array of module paths to be loaded. 

