    private readonly IDbConnection _connection;
    private static ILogger<QueryExecutor> _logger;
    private static ConnectionMultiplexer _redis;
    private static IDatabase _db;
    private readonly IConfiguration _config;

    public QueryExecutor(IDbConnection connection, ILogger<QueryExecutor> logger, IConfiguration config)
    {
        _connection = connection;
        _logger = logger;
        _redis = ConnectionMultiplexer.Connect("localhost");
        _db = _redis.GetDatabase();
        _config = config;
    }

    public async Task<IEnumerable<T>> ExecuteQueryAsync<T>(string query, object param)
    {
        try
        {
            var cacheKey = $"{query}_{param}";
            if (_db.HashExists("Cache", cacheKey))
            {
                _logger.LogInformation("Cache hit");
                return (await _db.HashGetAsync("Cache", cacheKey)).ToString().Split('|').Select(x => (T)Convert.ChangeType(x, typeof(T)));
            }

            var result = await _connection.QueryAsync<T>(query, param);
            _logger.LogInformation("New query executed");
            await _db.HashSetAsync("Cache", cacheKey, string.Join('|', result));
            return result;
        }
        catch (Exception ex)
        {
            // log and handle the exception appropriately
            _logger.LogError(ex, "An error occurred while executing query");
        }

        return null;
    }

