function BatchProcessElementsBySelector(startNode, selector, callback) {
    // Check if the start node exists and is of type Node. ECMAScript does not have built-in types for nodes or selectors.
    if (!startNode || typeof startNode !== 'object') {
        throw new TypeError('Start node must be a DOM node');
    }

    // Perform the actual traversal using an iterative depth-first search algorithm.
    const stack = [startNode];
    while (stack.length > 0) {
        const currentNode = stack.pop();

        if (callback(currentNode)) { 
            /* Process the node, possibly by calling another function or method here.
               Returning false from the callback will skip children of this node. */
        }

        // Add child nodes to the end of the stack for later processing.
        for (let i = 0; i < currentNode.childNodes.length; ++i) {
            stack.push(currentNode.childNodes[i]);
        }
    }
}
