```C#
using System;
using System.IO;
using System.Security.Cryptography;
using System.Xml;

public class Program
{
    public static void Main()
    {
        // Load configuration from XML file
        string configFilePath = Environment.GetEnvironmentVariable("CONFIG_FILE");

        XmlDocument doc = new XmlDocument();
        doc.Load(configFilePath);

        int tileSize = Int32.Parse(doc.SelectSingleNode("/Configuration/TileSize").InnerText);
        int worldWidth = Int32.Parse(doc.SelectSingleNode("/Configuration/WorldDimensions/width").InnerText);
        int worldHeight = Int32.Parse(doc.SelectSingleNode("/Configuration/WorldDimensions/height").InnerText);
        float cameraSpeed = float.Parse(doc.SelectSingleNode("/Configuration/CameraSpeed").InnerText);

        // Assuming we have two sets of encryption keys and IVs
        byte[] key1 = Convert.FromBase64String(doc.SelectSingleNode("/EncryptionKeys/Key[@id='key1']").InnerText);
        byte[] iv1 = Convert.FromBase64String(doc.SelectSingleNode("/EncryptionIVs/IV[@id='iv1']").InnerText);

        byte[] ciphertext1 = File.ReadAllBytes("ciphertext1"); // load the actual ciphertext
        DecryptCiphertext(key1, iv1, ciphertext1);
    }

    public static byte[] DecryptCiphertext(byte[] key, byte[] IV, byte[] cipherText)
    {
        if (key == null || key.Length <= 0)
            throw new ArgumentNullException("Key should not be empty");

        if (IV == null || IV.Length <= 0)
            throw new ArgumentNullException("Initialization Vector should not be empty");

        byte[] plainText = null;

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = IV;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(cipherText))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (BinaryReader br = new BinaryReader(csDecrypt))
                    {
                        plainText =  br.ReadBytes((int) msDecrypt.Length); 
                    }
                }
            }
        }

        return plainText;
    }    
}
```
