```java
import java.io.*;
import java.util.*;
import java.net.*;
import java.nio.channels.*;
import java.lang.*;
import java.awt.Point;
import org.apache.log4j.Logger;

public class GameCharacter {
  private static final Logger logger = Logger.getLogger(GameCharacter.class);

  private static final String ATTACK_ONE = "Attack One";
  private static final String ATTACK_TWO = "Attack Two";

  private Random rand;
  private InetSocketAddress address;

  private int maxRetries;
  private long retryDelayMillis;
  private long cooldownPeriod;

  public GameCharacter(String host, int port, int maxRetries, long retryDelayMillis, long cooldownPeriod) throws UnknownHostException {
    this.rand = new Random();
    this.address = new InetSocketAddress(host, port);
    this.maxRetries = maxRetries;
    this.retryDelayMillis = retryDelayMillis;
    this.cooldownPeriod = cooldownPeriod;
  }

  public void establishConnection() {
    int retries = 0;

    while(retries < maxRetries) {
      try (SocketChannel channel = SocketChannel.open()) {
        if(!channel.connect(address)) {
          throw new IOException("Connection failed");
        }

        logger.info("Connected to " + address);
        return;
      } catch (IOException e) {
        logger.error("Failed to connect", e);
        retries++;

        try {
          Thread.sleep(retryDelayMillis);
        } catch (InterruptedException ie) {
          Thread.currentThread().interrupt();
          return;
        }
      }
    }

    logger.error("Failed to connect after " + maxRetries + " retries");
  }

  public synchronized void attack() throws InterruptedException {
    long lastAttackTime = System.currentTimeMillis();
    if (System.currentTimeMillis() - lastAttackTime < cooldownPeriod) {
      Thread.sleep(cooldownPeriod);
    }

    String selectedAttack;
    int attackNumber = rand.nextInt(2);
    switch(attackNumber) {
      case 0: selectedAttack = ATTACK_ONE; break;
      case 1: selectedAttack = ATTACK_TWO; break;
      default: throw new IllegalStateException("Invalid attack number");
    }

    logger.info(selectedAttack + " used");
  }

  public static void main(String[] args) {
    if (args.length != 5) {
      System.out.println("Usage: GameCharacter <host> <port> <maxRetries> <retryDelayMillis> <cooldownPeriod>");
      return;
    }

    String host = args[0];
    int port = Integer.parseInt(args[1]);
    int maxRetries = Integer.parseInt(args[2]);
    long retryDelayMillis = Long.parseLong(args[3]);
    long cooldownPeriod = Long.parseLong(args[4]);

    GameCharacter gc;
    try {
      gc = new GameCharacter(host, port, maxRetries, retryDelayMillis, cooldownPeriod);
    } catch (UnknownHostException uhe) {
      System.out.println("Invalid host: " + args[0]);
      return;
    }

    gc.establishConnection();
  }
}
```
