class ClinicStatusUpdater {
    private $dbHandler;
    private $logger;

    public function __construct() {
        $this->dbHandler = new DatabaseHandler();
        $this->logger = new LoggerService();
    }

    // Main update function
    public function updateClinicStatus(int $clinicId, string $newStatus, string $lastModifiedIp) {
        try {
            $this->dbHandler->beginTransaction();   // Start transaction

            if (!$this->validateClinicId($clinicId)) {
                throw new Exception("Invalid clinic ID.");
            }

            $oldStatus = $this->getCurrentClinicStatus($clinicId);  // Get current status

            $data = [
                'status' => $newStatus,
                'ip_address' => $lastModifiedIp,
                'last_modified' => date('Y-m-d H:i:s')
            ];

            $this->dbHandler->updateClinic($clinicId, $data);  // Update clinic status

            $message = "Updated clinic status from '" . $oldStatus . "' to '" . $newStatus . "'.";
            $this->logger->logInfo($message, ['ip' => $lastModifiedIp]);   // Log update

            $this->dbHandler->commit();  // Commit transaction
        } catch (Exception $e) {
            $this->dbHandler->rollBack();  // Rollback on error
            throw new Exception("Failed to update clinic status: " . $e->getMessage());   // Rethrow with detailed message
        } finally {
            $this->dbHandler->closeConnection();  // Close connection
        }
    }

    private function validateClinicId(int $clinicId): bool {
        return is_numeric($clinicId) && $clinicId > 0;   // Add more validation as necessary
    }

