using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Distributed;
using Newtonsoft.Json;

public class PageSectionService : IPageSectionService 
{
    private readonly IDistributedCache _distributedCache;
    private static object _lock = new object(); // For locking mechanism to avoid race conditions

    public PageSectionService(IDistributedCache distributedCache)
    {
        _distributedCache = distributedCache;
    }

    [HttpPost]
    [Route("api/update-section")] 
    public async Task<IActionResult> UpdatePageSection([FromBody]UpdateModel model)
    {
        try 
        {
            if (!Validate(model)) 
                return BadRequest(); // Invalid data received

            var cacheKey = $"{model.pageId}-{model.elementId}";

            lock (_lock) // Optimistic concurrency control to avoid race conditions
            {
                var htmlContent = await _distributedCache.GetStringAsync(cacheKey);

                if (htmlContent == null) 
                    return NotFound(); // Section not found in cache

                await _distributedCache.SetStringAsync(cacheKey, model.updatedHtmlContent); // Save updated HTML content to cache
            }

            // Authenticate and update the external REST API with the new data... 
        }
        catch (Exception ex) 
        {
            Console.WriteLine(ex); // Replace it with proper logging
            return StatusCode(500, "An error has occurred"); // Logging the exception details for debugging purposes
        }

        return Ok();
    }

    private bool Validate(UpdateModel model) 
    {
        if (model == null || 
            string.IsNullOrWhiteSpace(model.pageId) ||
            string.IsNullOrWhiteSpace(model.elementId) ||
            string.IsNullOrWhiteSpace(model.updatedHtmlContent))
                return false;  // Validate input parameters

        try { JsonConvert.DeserializeObject<string>(model.updatedHtmlContent); }
        catch (JsonReaderException) { return false; } // Check for valid HTML content

        return true;
    }
}
