        }

        let data = await lambda.updateFunctionCode({
                FunctionName: req.params.id, 
                ZipFile: req.body.code // Assuming code is passed as zip file in request body
            }).promise();

        return res.status(200).json({message: 'Function updated successfully', data});
    }catch (e) {
        return res.status(500).json({ message: e.toString() });
    } 
});

// Delete function
