    try{
        let itemResponse = await dynamoDb.get({
            TableName : "metadataTable", 
            Key: {"functionId": req.params.id}
        }).promise();

        if (!itemResponse.Item || itemResponse.Item.version != req.query.version) { // Assuming version is passed in query param
            return res.status(412).json({message: "Function version mismatch"}); 
