T = TypeVar('T')

class ConnectionConfig(ABC):
    @abstractmethod
    def create_connection(self) -> T:
        pass

ConnectionPool = namedtuple("ConnectionPool", "min max timeout seed callback")
ResourceFactory = Dict[str, Callable[[], Any]]

class DynamicResourcePoolManager:
    def __init__(self):
        self._pools: Dict[str, ConnectionPool] = {}
        self._factories: ResourceFactory = {}

    @staticmethod
    def parse_json(data: str) -> Any:
        return json.loads(data)

    @staticmethod
    def create_json(obj: Dict[str, Any]) -> str:
        return json.dumps(obj)

    def register_factory(self, id_: str, factory: Callable[[], ConnectionConfig]):
        self._factories[id_] = factory

    def initializeResourcePool(self, id_: str, min_connections: int, max_connections: int, connection_timeout: int, seeded: bool = False, seed: Optional[int] = None, callback: Optional[Callable[[ConnectionConfig], ConnectionConfig]] = None):
        if id_ not in self._factories:
            raise ValueError(f"No factory function found for ID {id_}")

        pool = ConnectionPool(min_connections, max_connections, connection_timeout, seeded, seed, callback)
        self._pools[id_] = pool

    def getConnection(self, id_: str):
        if id_ not in self._factories or id_ not in self._pools:
