import java.util.concurrent.*;

public class DynamicFileProcessor {
    private int chunkSize;
    private ExecutorService threadPool;

    public DynamicFileProcessor(int chunkSize, int corePoolSize) {
        this.chunkSize = chunkSize;
        this.threadPool = Executors.newFixedThreadPool(corePoolSize);
    }

    public void setChunkSize(int newChunkSize) {
        this.chunkSize = newChunkSize;
    }

    // Method to read file chunks, supports sequential and parallel processing 
    public void processFileChunks(String path, boolean parallel) throws Exception {
        FileSystem fs = FileSystems.getDefault();
        Path p = fs.getPath(path);

        try (BufferedReader reader = Files.newBufferedReader(p)) {
            char[] buffer = new char[chunkSize];
            int charsRead;

            if (!parallel) {
                while ((charsRead = reader.read(buffer)) != -1) {
                    processChunk(Arrays.copyOfRange(buffer, 0, charsRead));
                }
            } else {
                Future<?> future = threadPool.submit(() -> {
                    try {
                        while ((charsRead = reader.read(buffer)) != -1) {
                            processChunkAsync(Arrays.copyOfRange(buffer, 0, charsRead));
                        }
                    } catch (Exception e) {
                        // Handle exception here
                    }
                });

                future.get();  // Wait for the operation to finish
            }
        } catch (IOException | InterruptedException | ExecutionException e) {
            throw new Exception("Error processing file chunks", e);
        }
    }

    private void processChunk(char[] chunk) throws IOException {
        // Implement your custom logic here
    }

    private void processChunkAsync(char[] chunk) throws IOException {
        CompletableFuture.runAsync(() -> {
            try {
                processChunk(chunk);
            } catch (IOException e) {
                // Handle exception here
            }
        }, threadPool);
    }
}
```
