```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>

class Semaphore {
    public:
        Semaphore(int count = 0) : count(count) {}

        inline void notify() {
            std::unique_lock<std::mutex> lock(mtx);
            ++count;
            cv.notify_one();
        }

        inline void wait() {
            std::unique_lock<std::mutex> lock(mtx);
            while(count == 0){
                cv.wait(lock);
            }
            --count;
        }

    private:
        std::mutex mtx;
        std::condition_variable cv;
        int count;
};
```
This is a simple semaphore implementation in C++ that uses condition variable to manage the state of the semaphore. It has `notify` and `wait` methods which are used to signal when resources become available or wait for them.

