    public async Task<string> DecryptAndValidateAsync(string encryptedMessage, string checksumOrSignature)
    {
        // Decrypt the message using Triple DES encryption.
        var decryptedBytes = await DecryptTripleDesAsync(encryptedMessage);
        var decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

        // Validate the decrypted message against a checksum or digital signature.
        if (!ValidateChecksumOrSignature(decryptedMessage, checksumOrSignature))
        {
            throw new InvalidOperationException("The decrypted message's integrity could not be validated.");
        }

        return decryptedMessage;
    }

    private async Task<byte[]> DecryptTripleDesAsync(string encryptedBase64)
    {
        using (var tripleDes = TripleDES.Create())
        {
            var cipherTextBytes = Convert.FromBase64String(encryptedBase64);

            // Create a decryptor to perform the stream transform.
            var decryptor = tripleDes.CreateDecryptor(_key, _iv);

            using (var msDecrypt = new MemoryStream(cipherTextBytes))
            {
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    var fromEncrypted = new byte[cipherTextBytes.Length];
                    await csDecrypt.ReadAsync(fromEncrypted, 0, fromEncrypted.Length);
                    return fromEncrypted;
                }
            }
        }
    }

    private bool ValidateChecksumOrSignature(string decryptedMessage, string checksumOrSignature)
    {
