```rust
use std::env;
use std::fs;
use std::path::PathBuf;
use tempfile::tempdir;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

// Environment Variable Validation and Directory Management
pub struct WorkingDirManager {
    dir: Arc<Mutex<Option<PathBuf>>>,
}

impl WorkingDirManager {
    pub fn new() -> Self {
        let mut temp_dir = None;
        if let Ok(work_dir) = env::var("WORK_DIR") {
            temp_dir = Some(PathBuf::from(work_dir));
        } else {
            // Create a temporary directory if WORK_DIR is not set.
            let dir = tempdir().unwrap();
            temp_dir = Some(dir.into_temp_path());
        }

        Self {
            dir: Arc::new(Mutex::new(temp_dir)),
        }
    }

    pub fn get_working_dir(&self) -> Option<PathBuf> {
        self.dir.lock().unwrap().clone()
    }
}

// Automated Directory Management
impl Drop for WorkingDirManager {
    fn drop(&mut self) {
        let dir = self.get_working_dir();

        // Delete the directory when this object is dropped.
        thread::spawn(move || {
            if let Some(ref dir) = dir {
                fs::remove_dir_all(dir).unwrap_or(());
            }
        });
    }
}
```
This code defines a `WorkingDirManager` struct that validates the `WORK_DIR` environment variable and manages a temporary directory if it is not set. The `Drop` trait ensures that the directory gets deleted when this object gets dropped, allowing for automatic cleanup after pipeline execution. 

