```javascript
const mongodb = require('mongodb');
let MongoClient = mongodb.MongoClient;
let url = 'mongodb://localhost:27017/'; // replace with your db's URL

async function copyBytes(chunks, startIndex, byteCount) {
  if (!Array.isArray(chunks)) throw new TypeError('Chunks should be an array');
  let data = Buffer.allocUnsafe(byteCount);
  let copiedByteCount = 0;
  let currentStartIndex = startIndex;

  for (let chunk of chunks) {
    if (!Buffer.isBuffer(chunk)) throw new TypeError('All elements in chunks should be Buffers');
    let endIndex = Math.min(currentStartIndex + byteCount, chunk.length);

    // Copy from current chunk
    while (copiedByteCount < byteCount && currentStartIndex < endIndex) {
      data[copiedByteCount] = chunk[currentStartIndex];
      ++copiedByteCount;
      ++currentStartIndex;
    }
  }

  if (byteCount > copiedByteCount) throw new Error('Requested byte count exceeds available data');

  // Logging to MongoDB
  let client = await MongoClient.connect(url);
  try {
    let db = client.db('logDB');
    let logCollection = db.collection('logging');
    await logCollection.insertOne({
      timestamp: new Date(),
      operation: 'copyBytes',
      status: 'success'
    });
  } catch (err) {
    // Handle DB logging error here
  } finally {
    client.close();
  }

  return data;
}
```
This function copies the specified number of bytes from a list of buffered data chunks into a new buffer. It handles errors for different cases such as incorrect chunk type, requesting more bytes than available, and logging operation details to a MongoDB database in case of successful execution.

