typedef struct SemaphoreManager {
    sem_t sem;
    pthread_mutex_t lock;
} SemaphoreManager;

void createSemaphore(int initialPermits, SemaphoreManager *manager) {
    // Initialize the mutex and semaphore.
    pthread_mutex_init(&(manager->lock), NULL);
    sem_init(&(manager->sem), 0, initialPermits);
}

void deleteSemaphore(SemaphoreManager *manager) {
    // Destroy the mutex and semaphore.
    pthread_mutex_destroy(&(manager->lock));
    sem_destroy(&(manager->sem));
}

void adjustPermits(int permits, SemaphoreManager *manager) {
    // Adjust the number of semaphore's permits.
    for (int i = 0; i < abs(permits); ++i) {
        if (permits > 0) {
            sem_post(&(manager->sem));
        } else {
            sem_wait(&(manager->sem));
        }
    }
}

void acquireSemaphore(SemaphoreManager *manager) {
    // Acquire a permit from the cloud service.
    int permits = get_permits_from_cloud();
    adjustPermits(permits, manager);
}

void releaseSemaphore(SemaphoreManager *manager) {
    // Release a permit to the cloud service.
    sem_wait(&(manager->sem));
    int permits = get_current_available_permit();
    set_permits_to_cloud(permits);
}

