```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using BCryptNet = BCrypt.Net.BCrypt;

public enum HashingAlgorithmType { Bcrypt, Sha256 }

public class SecurePasswordHasher : ISecurePasswordHasher
{
    private const int WorkFactor = 12; // Default value for bcrypt algorithm

    public string GenerateSalt()
    {
        return BCryptNet.GenerateSalt(WorkFactor);
    }

    public string HashWithBcryptAlgorithm(string plainText, string salt)
    {
        if (string.IsNullOrEmpty(plainText)) throw new ArgumentException("Plain text cannot be null or empty.", nameof(plainText));

        return BCryptNet.HashPassword(plainText, salt);
    }

    public string HashWithSha256Algorithm(string plainText)
    {
        if (string.IsNullOrEmpty(plainText)) throw new ArgumentException("Plain text cannot be null or empty.", nameof(plainText));

        using var sha256 = SHA256.Create();
        byte[] bytes = Encoding.UTF8.GetBytes(plainText);
        return Convert.ToBase64String(sha256.ComputeHash(bytes));
    }

    public bool VerifyBcryptPassword(string plainText, string hashedPassword)
    {
        if (string.IsNullOrEmpty(hashedPassword)) throw new ArgumentException("Hashed password cannot be null or empty.", nameof(hashedPassword));

        return BCryptNet.Verify(plainText, hashedPassword);
    }

    public bool VerifySha256Password(string plainText, string hashedPassword)
    {
        if (string.IsNullOrEmpty(hashedPassword)) throw new ArgumentException("Hashed password cannot be null or empty.", nameof(hashedPassword));

        var computedHash = HashWithSha256Algorithm(plainText);
        return hashedPassword == computedHash;
    }
}
