```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    char* url;
    FILE *fp;
} Resource;

size_t write_data(void *ptr, size_t size, size_t nmemb, void *stream) {
    return fwrite(ptr, size, nmemb, (FILE *)stream);
}

void* downloadFile(void* arg) {
    Resource *resource = (Resource*)arg;
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        char* filename = strrchr(resource->url, '/');
        resource->fp = fopen(filename ? filename + 1 : "default.out", "wb");
        curl_easy_setopt(curl, CURLOPT_URL, resource->url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, resource->fp);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize curl.");
    }

    return NULL;
}

int main(int argc, char** argv) {

    if (argc < 2) {
        printf("Usage: ./program <url1> <url2> ...\n");
        return 1;
    }

    pthread_t threads[argc-1];
    Resource resources[argc-1];

    for(int i=0; i<argc-1; ++i) {
        resources[i].url = argv[i+1];
        pthread_create(&threads[i], NULL, downloadFile, &resources[i]);
    }

    for(int i=0; i<argc-1; ++i) {
        pthread_join(threads[i], NULL);
        fclose(resources[i].fp);
    }

    curl_global_cleanup();

    return 0;
}
```
