#include <stdbool.h>
#include <string.h>
#include <json-c/json.h>

/* JSON Token validation */
static bool validate_token(const char *response) {
    struct json_object *parsed_json;
    struct json_object *access_token, *expires_in, *token_type, *refresh_token;
    bool has_error = false;

    parsed_json = json_tokener_parse(response);

    /* Retrieve all the fields */
    json_object_object_get_ex(parsed_json, "access_token", &access_token);
    json_object_object_get_ex(parsed_json, "expires_in", &expires_in);
    json_object_object_get_ex(parsed_json, "token_type", &token_type);
    json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token);

    /* Check that all fields exist and are of correct type */
    if (!json_object_is_type(access_token, json_type_string) ||
        !json_object_is_type(expires_in, json_type_int) ||
        strcmp(json_object_get_string(token_type), "Bearer") ||
        (!refresh_token && !json_object_is_type(refresh_token, json_type_string))) {
            has_error = true;
    } else if (json_object_get_int(expires_in) <= 0) {
        /* expires_in should be positive */
        has_error = true;
    }

    return !has_error;
}
