Here is a basic example using JavaScript with the async attribute and event listeners to load scripts dynamically:

```javascript
class ScriptLoader {
  constructor() {
    this.scripts = {}; // Key-value store for script sources, priorities, fallbacks etc.
    this.loadedScripts = new Set();
  }

  // Dynamically load a script and handle success/error callbacks
  loadScript(src) {
    return new Promise((resolve, reject) => {
      if (this.loadedScripts.has(src)) {
        resolve();
        return;
      }

      let script = document.createElement('script');
      script.type = 'text/javascript';
      script.async = true; // Asynchronous loading
      script.src = src;

      script.addEventListener('load', () => {
        this.loadedScripts.add(src);
        resolve();
      }, false);

      script.addEventListener('error', () => reject(), false);

      document.head.appendChild(script);
    });
  }

  // Load scripts based on their priority
  async loadScripts() {
    let sortedScripts = Object.values(this.scripts).sort((a, b) => a.priority - b.priority);

    for (let script of sortedScripts) {
      try {
        await this.loadScript(script.src);
      } catch (error) {
        if (script.fallback) {
          await this.loadScript(script.fallback);
        } else {
          console.error('Failed to load script: ' + script.src);
        }
      }
    }
  }

  // Add scripts with additional configuration options
  addScript({ src, priority = 0, fallback = null }) {
    this.scripts[src] = { src, priority, fallback };
  }
}
```
