```js
const mongoose = require('mongoose');
const glob = require("glob"); // To load all protocols dynamically
const fs = require('fs'); 

// Cache for loaded protocols to optimize performance
let protocolCache = {};

function loadProtocolsFromDirectory(directory) {
    const files = glob.sync(`${directory}/**/*.js`); // Load all .js files from the directory

    for (const file of files) {
        let pathArray = file.split("/");
        let protocolName = pathArray[pathArray.length - 1].slice(0, -3); // Get filename without extension

        try {
            const ProtocolImplementation = require(`./${file}`);

            if (typeof ProtocolImplementation === 'function') {
                protocolCache[protocolName] = { 
                    name: protocolName, 
                    implementation: new ProtocolImplementation(), // Create an instance of the class
                    description: ProtocolImplementation.description || "",
                    supportedFeatures: ProtocolImplementation.supportedFeatures || []
                };
            } else {
                console.log(`${protocolName} is not a valid protocol implementation.`);
            }
        } catch (error) {
            console.log(`Error while loading ${file}: ${error}`);
        }
    }

    return protocolCache;
}

// Function to load protocols from JSON file and cache them
function loadProtocolsFromJsonFile(jsonPath) {
    try {
        const data = fs.readFileSync(jsonPath, 'utf8');
        let protocols = JSON.parse(data);

        for (let protocol of protocols) {
            if (!protocolCache[protocol.name]) {
                console.log(`Protocol ${protocol.name} not found in directory. Skipping...`);
                continue;
            }

            // Add default settings and feature flags from JSON file to cache
            Object.assign(protocolCache[protocol.name], protocol); 
        }
    } catch (error) {
        console.log('Error loading protocols from JSON: ', error);
    }
}
```
