const axios = require('axios');
const cache = new Map(); // this could be replaced with an actual caching system for production
let loadingSpinner;

function showLoadingSpinner() {
    loadingSpinner = document.createElement("div");
    loadingSpinner.innerHTML = "Loading..."; // replace with your spinner html
    document.body.appendChild(loadingSpinner);
}

function hideLoadingSpinner() {
    if (loadingSpinner) {
        loadingSpinner.remove();
        loadingSpinner = null;
    }
}

async function fetchScriptWithCache(scriptObj, cacheExpirationSeconds = 300) {
    // check cache first
    const cachedData = cache.get(scriptObj.src);
    if (cachedData && Date.now() - cachedData.timestamp < cacheExpirationSeconds * 1000) {
        return cachedData.data;
    }

    // fetch from server and update cache
    try {
        const response = await axios.get(scriptObj.src);
        if (response.status !== 200 || typeof response.data !== 'string') {
            throw new Error("Invalid script source");
        }

        // update cache
        cache.set(scriptObj.src, { data: response.data, timestamp: Date.now() });
        return response.data;
    } catch (err) {
        console.error(`Error fetching script from ${scriptObj.src}: ${err}`);
        return null;
    }
}

function renderScripts(scriptObjs, shouldLoadSequentially = false) {
    showLoadingSpinner();

    const promises = scriptObjs.map(async (scriptObj, i) => {
        if (!scriptObj.src && !scriptObj.code) {
            console.error("Script object is missing essential properties: ", scriptObj);
            return;
        }

        // fetch from cache or external server
        const code = scriptObj.code || await fetchScriptWithCache(scriptObj);
        if (!code) return;

        let scriptTag = document.createElement('script');
        scriptTag.type = scriptObj.type || 'text/javascript'; // default to JavaScript if type is not provided
        scriptTag.innerHTML = code;

        const parentNode = shouldLoadSequentially ? document.body : document.head;
        parentNode.appendChild(scriptTag);

        if (shouldLoadSequentially && i < scriptObjs.length - 1) {
            await new Promise(resolve => setTimeout(resolve, 50)); // delay between sequential loads
        }
    });

    // load scripts in parallel by default
    Promise.all(promises).then(() => hideLoadingSpinner());
}
