// Initialize cache object
const scriptCache = {};

async function fetchScripts(apiUrl) {
  try {
    const response = await fetch(apiUrl);

    if (!response.ok) throw new Error('Network response was not ok');

    return response.json();
  } catch (error) {
    console.log("Error fetching scripts", error);
    // Retry after a delay
    await new Promise(resolve => setTimeout(resolve, 500));
    return fetchScripts(apiUrl);
  }
}

function isExpired(script) {
  const now = Date.now();

  if (!scriptCache[script.src]) return true; // script not cached

  const cacheEntry = scriptCache[script.src];
  const timeElapsed = (now - cacheEntry.fetchedAt);

  // Consider as expired after 10 mins
  if ((timeElapsed / 60000) > 10) return true;

  return false;
}

async function getScripts(apiUrl) {
  let scripts = scriptCache[apiUrl];

  // Check if we already have cached copy and it's not expired
  if (scripts && !isExpired(scripts)) {
    console.log('Using cached version of scripts');
  } else {
    scripts = await fetchScripts(apiUrl);

    scriptCache[apiUrl] = { scripts, fetchedAt: Date.now() };

    // Log cache update
    console.log("Cached scripts updated");
  }

  return scripts;
}

function renderScriptTags(scripts) {
  const fragment = document.createDocumentFragment();

  for (let script of scripts) {
    if (!script.code && !script.src) {
      console.log('Missing code or src property in script object');
      continue;
    }

    const tag = document.createElement('script');
    tag.innerHTML = script.code || '';
    tag.type = script.type ? script.type : 'text/javascript';
    tag.src = script.src ? script.src : null;

    fragment.appendChild(tag);
  }

  return fragment.innerHTML;
}

async function renderFooter() {
  const scripts = await getScripts('/api/scripts');
  const footerHtml = renderScriptTags(scripts);

  document.body.appendChild(footerHtml);
}
