Here's how you can implement this function in C. In this example, I use `fopen`, `fprintf` and `fclose` to open a file, write into it, and close it after each call of the function. If there are any errors while opening or writing to the log file, these functions will return NULL and we'll handle it accordingly in our code.

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

char* trimAndAppendSlash(const char *str, size_t limit) {
    if (limit <= 0) {
        // Handle error: invalid size limits
        return NULL;
    }

    FILE *fp = fopen("logfile.txt", "a");
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%d-%m-%Y %H:%M:%S", tm);

    if (fp == NULL) {
        // Handle error: cannot open file
        return NULL;
    } else {
        fprintf(fp, "[%s] Function called with string \"%s\" and limit %zu\n", timestamp, str, limit);

        size_t len = strlen(str);
        if (len > limit) {
            // Handle error: string exceeds the size limit
            fprintf(fp, "[%s] String exceeds limit. Returning NULL.\n", timestamp);
            fclose(fp);
            return NULL;
        } else {
            char *trimmed = malloc(len + 2);  // +1 for slash, +1 for null terminator
            if (trimmed == NULL) {
                // Handle error: allocation failed
                fprintf(fp, "[%s] Memory allocation failed. Returning NULL.\n", timestamp);
                fclose(fp);
                return NULL;
            }

            size_t start = 0, end = len - 1;
            while (isspace((unsigned char)str[start])) ++start;
            while (end > start && isspace((unsigned char)str[end])) --end;

            strncpy(trimmed, &str[start], end-start+2);
            trimmed[end-start+1] = '/';  // Append slash
            trimmed[end-start+2] = 0;     // Null terminate the string
            fprintf(fp, "[%s] String \"%s\" trimmed. Length: %zu\n", timestamp, trimmed, end-start);

            if (strlen(trimmed) <= limit) {
                fprintf(fp, "[%s] Slash appended successfully.\n", timestamp);
            } else {
                // Handle error: string exceeds the size limit after slash appending
                fprintf(fp, "[%s] String still exceeds limit. Returning NULL.\n", timestamp);
                free(trimmed);
                trimmed = NULL;
            }

            fclose(fp);
            return trimmed;
        }
    }
}
``` 
