```C++
#include <openssl/evp.h>
#include <openssl/err.h>
#include <stdio.h>

void FileSessionEncryptor(const char* file_path, const EVP_CIPHER *cipher, BIO *out) {
    FILE *in;
    int inl;
    unsigned char inbuf[1024];
    unsigned char outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
    int outl;

    // Validate input
    if (!file_path || !cipher) {
        printf("Invalid file path or cipher\n");
        return;
    }

    in = fopen(file_path, "rb");
    if(!in) {
        printf("Could not open file %s for reading\n", file_path);
        return;
    }

    EVP_CIPHER_CTX *ctx;

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);

    for (;;) {
        inl = fread(inbuf, 1, sizeof(inbuf), in);
        if (inl <= 0) break;
        if (!EVP_EncryptUpdate(ctx, outbuf, &outl, inbuf, inl)) {
            /* Error */
            return;
        }
        BIO_write(out, outbuf, outl);
    }
    if (!EVP_EncryptFinal_ex(ctx, outbuf, &outl)) {
        /* Error */
        return;
    }
    BIO_write(out, outbuf, outl);

    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
}
```
