  ],
});

// Setup Express server
const app = express();
app.use(express.json());

// Establish Websocket connection
const websocketConnections = [];
const wsServer = new WebSocket.Server({ noServer: true });
wsServer.on('connection', (socket, request) => {
  socket.isAlive = true;
  socket.on('pong', () => {
    socket.isAlive = true;
  });

  websocketConnections.push(socket);
});

// Establish MQTT connection
const mqttClient  = mqtt.connect(process.env.MQTT_URL)
mqttClient.on('connect', function () {
    console.log("connected");
    mqttClient.subscribe(process.env.TOPIC);
});

// Handle HTTP requests
app.get('/data', async (req, res) => {
  try {
    const response = await axios.get(process.env.DATA_URL);
    websocketConnections.forEach((socket) => socket.send(JSON.stringify(response.data)));
    mqttClient.publish(process.env.TOPIC, JSON.stringify(response.data));

    res.json({ message: 'Data has been pushed' });
  } catch (error) {
    logger.log('error', error); // Log the error
    res.status(500).json({ error: 'An unexpected error occurred' });
  }
});

// Handle errors
app.use((err, req, res, next) => {
  logger.log('error', err); // Log the error

  res.status(err.status || 500).json({ error: 'An unexpected error occurred' });
});

// Handle Websocket Pings
setInterval(() => {
  websocketConnections.forEach((socket) => {
    if (socket.isAlive === false) return socket.terminate();

    socket.isAlive = false;
    socket.ping(null, false);
  });
}, 10000); // Ping every 10s to check for websocket health

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```
