void runModuleTests(std::string moduleLabel, 
                   std::vector<AttackFunction> testSuite, 
                   std::string loggingLevel,
                   int cooldown, 
                   ResourceManager& resourceManager,
                   DatabaseConnection& databaseConnection) {
    // Get configurations from the database
