            testSuite[testNumber](moduleLabel, configurations[testNumber]);
            auto end = std::chrono::high_resolution_clock::now();

            // Calculate execution time and report it based on the loggingLevel
            if (loggingLevel == "info") {
                std::cout << "Test #" << testNumber << " executed in: " 
                          << std::chrono::duration_cast<std::chrono::milliseconds>(end-start).count() << "ms\n";
            } else if (loggingLevel == "warn") {
                // Warn about long execution time
                if ((end-start) > std::chrono::seconds(cooldown)) {
                    std::cerr << "Warning: Test #" << testNumber 
                              << " took longer than the cooldown period\n";
                }
            } else if (loggingLevel == "error") {
                // Only report execution time on error level
                std::cerr << "Test #" << testNumber << " executed in: " 
                          << std::chrono::duration_cast<std::chrono::milliseconds>(end-start).count() << "ms\n";
            }

        } catch (const std::exception& e) {
            // Handle errors and report them with a detailed message
            std::cerr << "Test #" << testNumber << " failed: " << e.what() << "\n";
        }

        // Clean up after each test using resourceManager
        resourceManager.resetMockEnvironment();
    }
}
