```rust
use std::sync::Arc;
use reqwest::header::HeaderMap;
use reqwest::ClientBuilder;
use openssl::ssl::{SslConnector, SslMethod};
use tokio::net::TcpStream;
use futures_util::future::join_all;

pub struct CustomHttpClient {
    client: reqwest::Client,
}

impl CustomHttpClient {
    pub fn new(certificate: Option<&str>) -> Self {
        let ssl = if let Some(cert) = certificate {
            let mut ssl_connector = SslConnector::mozilla_modern(SslMethod::tls()).unwrap();
            ssl_connector.set_verify_subject_alt_dns(vec![&format_args::<String>![cert]]);
            Some(Arc::new(ssl_connector))
        } else { None };

        let client = ClientBuilder::new()
                    .tcp_connector(TcpStream::connector())
                    .ssl_connector(ssl)
                    .build().unwrap();

        Self { client }
    }

    pub fn request(&self, url: &str) -> RequestBuilder {
        RequestBuilder::new(url.to_string(), self.client.clone())
    }
}

pub struct RequestBuilder<'a> {
    url: String,
    headers: Option<HeaderMap>,
    client: reqwest::Client,
}

impl<'a> RequestBuilder<'a> {
    fn new(url: String, client: reqwest::Client) -> Self {
        Self {
            url,
            headers: None,
            client,
        }
    }

    pub fn header(mut self, key: &str, value: &str) -> Self {
        let mut headers = match self.headers {
            Some(ref hdr) => hdr.clone(),
            None => HeaderMap::new(),
        };
        headers.insert(key, value.parse().unwrap());
        self.headers = Some(headers);
        self
    }

    pub async fn get(&self) -> Result<reqwest::Response, reqwest::Error> {
        let client = &self.client;
        client.get(self.url.clone())
              .headers(match self.headers {
                  Some(ref hdr) => *hdr,
                  None => HeaderMap::new(),
              })
              .send()
              .await
    }

    pub async fn post(&self) -> Result<reqwest::Response, reqwest::Error> {
        let client = &self.client;
        client.post(self.url.clone())
              .headers(match self.headers {
                  Some(ref hdr) => *hdr,
                  None => HeaderMap::new(),
              })
              .send()
              .await
    }
}
