public class AccountController : Controller
{
    private readonly MyDbContext _db;

    public AccountController(MyDbContext db) => _db = db;

    [HttpPost]
    public async Task<IActionResult> UpdateAccountStatus([FromBody]UpdateStatusModel model)
    {
        var account = await _db.Accounts.FindAsync(model.Id);

        if (account == null) return NotFound();

        // If the row has changed since we fetched it, someone else must have updated it and we should let them win.
        if (_db.Entry(account).OriginalValues["RowVersion"] != model.RowVersion)
            throw new DbUpdateConcurrencyException("Account was updated by another user.");

        account.Status = model.NewStatus;

        await _db.SaveChangesAsync();

        return Ok();
    }
}
