// Define a module loader class
class ModuleLoader {
    constructor(){
        this.modules = {};
        this.moduleCache = {};
        this.context = {}; // Set your custom context here.
    }

    async loadModule(id){
        if (this.moduleCache[id]) return this.moduleCache[id];

        const module = this.modules[id];

        if (!module) throw new Error(`Module ${id} not found`);
        if (module.loaded) return this.moduleCache[id].exports;

        for (let dependency of module.dependencies){
            await this.loadModule(dependency);
        }

        try {
            const loadedModule = require(id); // Adjust according to your package manager and context setup
            if (!module.asyncLoad) loadedModule();

            this.moduleCache[id] = module;
            module.loaded = true;
            return loadedModule;
        } catch (err){
            console.error(`Failed to load or execute module ${id}: ${err}`);
            throw err;
        }
    }

    registerModule(module){
        if (!(module instanceof Module)) throw new Error('Invalid module type');

        if (this.modules[module.id]){
            console.warn(`Module ${module.id} already registered, overwriting...`);
        }

        this.modules[module.id] = module;
    }
}
