Here's an example of how you might implement this in C. Note that error checking, database storage, and other advanced functionalities are not included due to space limitations but can be added as per requirement. This code only provides a skeleton for DFS traversal and state list creation using dynamically allocated memory:

```c
#include <stdlib.h>

typedef struct {
    int *states; /* pointer to integer array representing states */
    int num_states; /* number of states in the FSA */
} FSA;

/* Structure for a node in state list */
struct StateNode {
    int state; 
    struct StateNode* next; 
};

typedef struct {
    struct StateNode *head; 
} StateList;

void dfs(int v, int visited[], FSA *fsa, StateList *state_list) {
    visited[v] = 1; /* Mark the current node as visited */

    /* Create a new state list node with the current state and add it to the end of the list */
    struct StateNode* newState = (struct StateNode*) malloc(sizeof(struct StateNode)); 
    if(newState == NULL) exit(-1); /* handle error if out-of-memory occurs */

    newState->state = fsa->states[v]; 
    newState->next = NULL; 
    if (state_list->head == NULL){
        state_list->head = newState;
    } else {
        struct StateNode* last = state_list->head;
        while(last->next != NULL) {
            last = last->next;
        }
        last->next = newState;
    }

    int i; 
    for (i = 0; i < fsa->num_states; ++i) {
        if (!visited[i]) { /* Visit all the unvisited neighboring nodes */
            dfs(i, visited, fsa, state_list); 
        }
    }
}

StateList* createStateListFromFSA(FSA *fsa) {
    StateList *state_list = (StateList*) malloc(sizeof(StateList));
    if(state_list == NULL) exit(-1); /* handle error if out-of-memory occurs */

    state_list->head = NULL; 

    int *visited = calloc(fsa->num_states, sizeof(int));
    if(visited == NULL) exit(-1); /* handle error if out-of-memory occurs */

    dfs(0, visited, fsa, state_list); 

    free(visited); 

    return state_list; 
}
```

This C program first defines a data structure for representing an FSA and for storing states in a linked list. The function `dfs` performs depth-first search on the given FSA, adding visited states to the `state_list`. Then, the function `createStateListFromFSA` initializes a new state list, calls the DFS function, and returns the completed state list. 

Remember that this is a simplified version of what you asked for, including error handling, integration with an external database or file storage system to persist the state lists between function calls, and advanced optimization techniques. If your use case requires more complex functionality, such as multiple FSAs, multi-threading support, etc., additional code will be required.

