using System;
using System.Collections.Generic;
using System.IO;
using System.Xml;
using System.Xml.Schema;
using System.Configuration;

public class XmlManager : IXmlManager, IDisposable 
{
    private Dictionary<string, XmlDocument> cache = new Dictionary<string, XmlDocument>();
    private bool loggingEnabled = Convert.ToBoolean(ConfigurationManager.AppSettings["Logging"]);

    public void Dispose()
    {
        cache.Clear();
    }

    public void ValidateXmlWithXsd(string xmlPath, string xsdPath)
    {
        try
        {
            var schema = new XmlSchemaSet();
            schema.Add("", XmlReader.Create(new StringReader(xsdPath)));

            var settings = new XmlReaderSettings();
            settings.Schemas = schema;
            settings.ValidationType = ValidationType.Schema;

            using (var reader = XmlReader.Create(xmlPath, settings)) 
            {
                while (reader.Read()) {}
            }
        }
        catch (Exception ex) when (loggingEnabled) 
        {
            Console.WriteLine("Validation failed: " + ex);
        }
    }

    public XmlNode GetFirstMatchingElement(string xpath, string xmlPath)
    {
        try
        {
            if (!cache.ContainsKey(xmlPath)) 
            {
                cache[xmlPath] = new XmlDocument();
                cache[xmlPath].Load(xmlPath);
            }

            var nodeList = cache[xmlPath].SelectNodes(xpath);
            if (nodeList.Count != 1) throw new Exception("Expected 1 element, found " + nodeList.Count);
            return nodeList[0];
        }
        catch (Exception ex) when (loggingEnabled)
        {
            Console.WriteLine("Element retrieval failed: " + ex);
        }

        return null;
    }

    public void InvalidateCache(string xmlPath)
    {
        if (cache.ContainsKey(xmlPath)) cache.Remove(xmlPath);
    }
}
