using System;
using System.Threading;
using UnityEngine;

public enum RangeType { Closed, Open, HalfOpen }

public delegate void SeedCallback(int seed);

public class CustomInterval<T> where T : IComparable<T>
{
    public T Min { get; set; }
    public T Max { get; set; }
}

public class AdvancedRandomGenerator
{
    private static readonly object _lock = new object();
    private int seed;
    private SeedCallback seedCallback;

    public void SetSeed(int seed)
    {
        lock (_lock)
        {
            this.seed = seed;
            UnityEngine.Random.InitState(this.seed);
            seedCallback?.Invoke(this.seed);
        }
    }

    public void RegisterSeedCallback(SeedCallback callback)
    {
        lock (_lock)
        {
            this.seedCallback += callback;
            if (this.seed != default(int))
                this.seedCallback?.Invoke(this.seed);
        }
    }

    public T CustomRange<T>(CustomInterval<T> range, RangeType type) where T : IComparable<T>
    {
        switch (type)
        {
            case RangeType.Closed:
                return GenerateRandomValueInclusive(range);
            case RangeType.Open:
                return GenerateRandomValueExclusive(range);
            case RangeType.HalfOpen:
                return GenerateRandomValueHalfOpen(range);
        }

        throw new NotImplementedException("Unknown range type");
    }

    private T GenerateRandomValueInclusive<T>(CustomInterval<T> range) where T : IComparable<T>
    {
        if (typeof(T) == typeof(float))
            return (T)(object)UnityEngine.Random.Range((float)(range.Min as dynamic), (float)(range.Max as dynamic));

        throw new NotImplementedException("Only float range type is supported");
    }

    private T GenerateRandomValueExclusive<T>(CustomInterval<T> range) where T : IComparable<T>
    {
        if (typeof(T) == typeof(float))
            return (T)(object)UnityEngine.Random.Range((float)(range.Min as dynamic + 0.01f), (float)(range.Max as dynamic - 0.01f));

        throw new NotImplementedException("Only float range type is supported");
    }

    private T GenerateRandomValueHalfOpen<T>(CustomInterval<T> range) where T : IComparable<T>
    {
        if (typeof(T) == typeof(float))
            return (T)(object)UnityEngine.Random.Range((float)(range.Min as dynamic + 0.01f), (float)(range.Max as dynamic));

        throw new NotImplementedException("Only float range type is supported");
    }
}
```
