const fs = require('fs');
const path = require('path');
const mongoose = require('mongoose');
const protoLoader = require('@grpc/proto-loader');
const grpc = require('grpc');
const async = require('async');
const sinon = require('sinon');
const winston = require('winston');
const mocha = require('mocha');
const chai = require('chai');

class DroneFleetManager {
    constructor(config) {
        this.config = config;
        // Initialize MongoDB connection
        mongoose.connect(this.config.dbUrl, { useNewUrlParser: true, useUnifiedTopology: true });

        const db = mongoose.connection;
        db.on('error', console.error.bind(console, 'connection error:'));
        db.once('open', function() {
            console.log("MongoDB connected!");
        });

        // Initialize protocol buffer package definition
        const PROTO_PATH = path.resolve(__dirname, this.config.protoPath);
        var packageDefinition = protoLoader.loadSync(PROTO_PATH, {
            keepCase: true,
            longs: String,
            enums: String,
            defaults: true,
            oneofs: true
        });
        const protoDescriptor = grpc.loadPackageDefinition(packageDefinition);
        this.protoService = new protoDescriptor[this.config.protoPackage][this.config.protoService]('localhost:' + config.controlServerPort,
            grpc.credentials.createInsecure());

        // Initialize logger 
        const myFormat = winston.format.printf(({ level, message, label, timestamp }) => {
            return `${timestamp} [${label}] ${level}: ${message}`;
        });
        this.logger = winston.createLogger({
            format: winston.format.combine(
                winston.format.label({ label: 'DRONE_FLEET' }),
                winston.format.timestamp(),
                myFormat
            ),
            transports: [new winston.transports.Console()]
        });
    }

    startMission(droneConfig, priority) {
        // Check battery level and handle low battery alerts
        if (droneConfig.batteryLevel < 10) this.logger.warn('Low battery alert for drone: ' + droneConfig.name);

        const callback = (err, response) => {
            if(err){
                this.logger.error("Error while communicating with control server", err);
                return;  // Handle error scenarios such as connection failures etc.
            } else {
               // Update drone status via the control server API
               this.protoService.updateStatus({ name: droneConfig.name, status: 'executing'}, (err, response) => {
                   if(err){
                       this.logger.error("Error updating drone status", err);
                   } else {
                      // Log mission events to a remote service 
                      this.protoService.logEvent({ name: droneConfig.name, eventType:'missionStarted'}, (err, response) => {
                          if(err){
                              this.logger.error("Error logging mission start event", err);
                          } else {
                             this.logger.info('Mission started for drone: ' + droneConfig.name);
                          }
                      });
                   }
               });
            }
        };

        async.waterfall([
          (callback) => {
              // Collect data from a network stream using non-blocking I/O operations 
              this.networkStream.read(droneConfig, callback);
          },
          (data, callback) => {
            // Save collected data to MongoDB database using asynchronous operations for performance 
            const droneData = new DroneData({ data: data });
            droneData.save((err) => {
              if(err){
                this.logger.error("Error saving data to MongoDB", err);
                callback(err, null);
              } else {
                 // Log mission events after successful save 
                 this.protoService.logEvent({ name: droneConfig.name, eventType:'dataSaved'}, (err, response) => {
                   if(err){
                       this.logger.error("Error logging data saved event", err);
                       callback(err, null);
                   } else {
                      this.logger.info('Data saved for drone: ' + droneConfig.name);
                      callback(null, response);
                   }
                 });
              }
            }); 
          },
        ], (error) => {
          if(err){
            // Error handling logic here
          } else {
             this.logger.info('Mission completed for drone: ' + droneConfig.name);
          }
        });
    }

    loadProtocolImplementationFromDirectory(directoryPath) {
        const files = fs.readdirSync(directoryPath);
        files.forEach((file) => {
            // Dynamically load protocol implementations from the directory and cache them 
            if (path.extname(file) === '.proto') {
                const PROTO_PATH = path.resolve(__dirname, file);
                var packageDefinition = protoLoader.loadSync(PROTO_PATH, { ... });
                this.loadedProtocolImplementations[file] = grpc.loadPackageDefinition(packageDefinition);
            } 
        });
    }
}

