Here is a basic implementation of the `DatabaseConnectionManager` class using C# .NET:

```csharp
using System;
using System.Data;
using System.Threading.Tasks;
using Dapper; // An ORM library

namespace MyApp.DataAccessLayer
{
    public class DatabaseConnectionManager : IDisposable
    {
        private readonly string connectionStringTemplate;
        private readonly Dictionary<string, string> tenantIdentifierMapping;
        private IDbConnection connection;

        public DatabaseConnectionManager(string template, Dictionary<string, string> mapping)
        {
            this.connectionStringTemplate = template;
            this.tenantIdentifierMapping = mapping;
        }

        public async Task EstablishConnectionAsync(string tenantId)
        {
            if (this.connection != null && this.connection.State == ConnectionState.Open)
                return;

            var connectionString = GetTenantConnectionString(tenantId);
            if (string.IsNullOrEmpty(connectionString))
                throw new Exception("No connection string found for the provided tenant.");

            this.connection = new SqlConnection(connectionString);
            await this.connection.OpenAsync();
        }

        public async Task<IEnumerable<T>> ExecuteQueryAsync<T>(string query, object parameters)
        {
            return await this.connection.QueryAsync<T>(query, parameters);
        }

        // Other methods omitted for brevity...

        private string GetTenantConnectionString(string tenantId)
        {
            if (!this.tenantIdentifierMapping.TryGetValue(tenantId, out var connectionString))
                throw new Exception("No connection string found for the provided tenant.");

            return string.Format(connectionStringTemplate, connectionString);
        }

        public void Dispose()
        {
            this.connection?.Dispose();
        }
    }
}
```
