import json
import random
import string
import hashlib
from abc import ABC, abstractmethod
from concurrent.futures import ThreadPoolExecutor
import logging

class BaseClass(ABC):
    _factories = {}

    @abstractmethod
    def to_json(self):
        pass

    @staticmethod
    def from_json(json_str):
        pass

    @classmethod
    def add_factory(cls, id_, factory):
        cls._factories[id_] = factory

    @classmethod
    def create(cls, id_):
        return cls._factories[id_]() if id_ in cls._factories else None


def load_and_execute():
    with ThreadPoolExecutor() as executor:
        for file in files:  # assuming `files` is a list of json files to be loaded.
            future = executor.submit(load_json, file)

def load_json(file):
    try:
        with open(file, 'r') as f:
            data = f.read()
            obj = BaseClass.from_json(data)  # Assuming a from_json method is defined in the subclass of BaseClass
            return obj

    except FileNotFoundError:
        logging.error("File not found: %s", file)

    except json.JSONDecodeError:
        logging.error("Failed to decode JSON data from: %s", file)

def deserialize_and_hash(byte_array, password):
    try:
        obj = BaseClass.from_json(byte_array)  # Assuming a from_json method is defined in the subclass of BaseClass

        random_string = ''.join(random.choices(string.ascii_uppercase + string.digits, k=10))
        hashed_password = hashlib.sha256((random_string+password).encode()).hexdigest()

        return obj, random_string, hashed_password

    except json.JSONDecodeError:
        logging.error("Failed to deserialize and hash the data")
