class FactoryClass:
    def __init__(self):
        self._registry = {}

    def register_factory(self, id_, factory_func):
        if not isinstance(id_, str) or not callable(factory_func):
            raise TypeError('Invalid types')

        self._registry[id_] = factory_func

    def create_new_instance(self, id_):
        if id_ not in self._registry:
            logging.error('Factory function not found for the provided ID')
            return None

        try:
            new_inst = self._registry[id_]()
            logging.info(f'New instance of {type(new_inst).__name__} created successfully')
            return new_inst
        except Exception as e:
            logging.error('Error creating a new instance', exc_info=True)
            return None

    def to_json(self):
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)

        new_inst = cls()
