To build this system in AngularJS, you'll need to incorporate several key components including HTTP services for API requests, a queue manager for handling multiple concurrent requests, and error handling mechanisms. Here is an example of what the code might look like:

```javascript
angular.module('myApp', [])
    .factory('FieldRefreshService', ['$http', '$q', function ($http, $q) {
        var queue = [];
        var processingQueue = false;

        // Function to refresh fields dynamically
        this.refreshFields = function (resourceId, url, fieldNames) {
            var deferred = $q.defer();

            // Push the current promise into the queue
            queue.push({
                resourceId: resourceId,
                url: url,
                fieldNames: fieldNames,
                deferred: deferred
            });

            if (!processingQueue) {
                processQueue();
            }

            return deferred.promise;
        };

        // Function to handle the queue of requests
        var processQueue = function () {
            processingQueue = true;

            while (queue.length > 0) {
                var currentRequest = queue[0];

                $http({
                    method: 'GET',
                    url: currentRequest.url,
                    params: { fields: currentRequest.fieldNames.join(',') }  // Convert field names to a comma-separated string
                })
                .then(function (response) {
                    var updatedFields = response.data;

                    // Update the fields in the UI based on the 'updatedFields' object here

                    currentRequest.deferred.resolve();  // Resolve the promise associated with this request
                })
                .catch(function (error) {
                    // Handle error and retry logic here

                    currentRequest.deferred.reject(error);  // Reject the promise if there's an error
                })
                .finally(function () {
                    queue.shift();  // Remove this request from the queue after processing

                    // Process the next request in the queue
                    if (queue.length > 0) {
                        processQueue();
                    } else {
                        processingQueue = false;
                    }
                });
            }
        };

        return this;
    }]);
```
