public class UserAccountUpgradeController {
    @Autowired
    private UserService userService;

    @Autowired
    private NotificationService notificationService;

    @Autowired
    private BillingService billingService;

    Logger logger = Logger.getLogger(UserAccountUpgradeController.class.getName());

    @Transactional
    @PutMapping("/users/{userId}/tenants/{tenantId}")
    public ResponseEntity<String> upgradeAccount(@PathVariable("userId") Long userId, 
                                                @PathVariable("tenantId") Long tenantId,
                                                @RequestBody UpgradePlanDetails details) {
        try {
            User user = validateUser(userId);
            Tenant tenant = validateTenant(tenantId);

            if(!isValidUpgrade(details)) {
                return ResponseEntity.badRequest().body("Invalid upgrade plan details");
            }

            synchronized (this) {  // Simplified form of concurrency control
                userService.updateUserPlanDetails(user, details);
                notificationService.notifyUpgrade(tenant, userId, details);
                billingService.processBilling(tenant, details);
            }

            return ResponseEntity.ok().body("Account upgraded successfully");
        } catch (OptimisticLockException e) {
            logger.severe("Error while upgrading account: " + e.getMessage());
            return ResponseEntity.status(HttpStatus.CONFLICT).body("Version conflict occurred, please retry!");
        } catch (Exception e) {
            logger.severe("Error during upgrade: " + e.getMessage());
            return ResponseEntity.internalServerError().body("Something went wrong");
        }
    }

    private User validateUser(Long userId) {
        Optional<User> optionalUser = userService.findById(userId);

        if(!optionalUser.isPresent()) {
            throw new IllegalArgumentException("Invalid User ID");
        }
        return optionalUser.get();
    }

    private Tenant validateTenant(Long tenantId) {
        Optional<Tenant> optionalTenant = userService.findById(tenantId);  // Assuming service named as 'userService' (should be named according to its responsibility)

        if(!optionalTenant.isPresent()) {
            throw new IllegalArgumentException("Invalid Tenant ID");
        }
        return optionalTenant.get();
    }

    private boolean isValidUpgrade(UpgradePlanDetails details) {
