// AES decryption function
void aesDecrypt(unsigned char* ciphertext, int cipherLength, unsigned char* key, 
                unsigned char *iv, std::string& plaintext) {
    AES_KEY decKey;
    AES_set_decrypt_key(key, 128, &decKey);

    /* Will be filled with the recovered text */
    unsigned char* decrypted = new unsigned char[cipherLength];
    AES_cbc_encrypt(ciphertext, decrypted, cipherLength, &decKey, iv, AESt_DECRYPT);

    plaintext.assign((char*)decrypted, cipherLength);
    delete[] decrypted;
}

