Here's an example of how you could design this system in Java using Netty and Hystrix as libraries for non-blocking I/O channels and fault tolerance respectively:

```java
import io.netty.bootstrap.Bootstrap;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.codec.LengthFieldBasedFrameDecoder;
import io.netty.handler.codec.string.StringDecoder;
import io.netty.handler.codec.string.StringEncoder;
import com.netflix.hystrix.HystrixCommand;
import com.netflix.hystrix.HystrixCommandGroupKey;
import com.netflix.hystrix.HystrixCommandProperties;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class NonBlockingIOConnectionPool {
    private final String host;
    private final int port;
    private EventLoopGroup group = new NioEventLoopGroup();
    private Bootstrap bootstrap = new Bootstrap();
    private ConcurrentHashMap<Channel, ChannelFuture> channelPool = new ConcurrentHashMap<>();
    private static final HystrixCommand.Setter defaultHystrixSettings = HystrixCommand.Setter.withGroupKey(HystrixCommandGroupKey.Factory.asKey("ConnectionPool"))
            .andCommandPropertiesDefaults(HystrixCommandProperties.Setter().withExecutionIsolationStrategy(HystrixCommandProperties.ExecutionIsolationStrategy.THREAD));
    private volatile boolean shutdown = false;

    public NonBlockingIOConnectionPool(String host, int port) {
        this.host = host;
        this.port = port;

        bootstrap.group(group);
        bootstrap.channel(NioSocketChannel.class);
        bootstrap.handler(new ChannelInitializer<Channel>() {
            @Override
            protected void initChannel(Channel ch) throws Exception {
                ChannelPipeline pipeline = ch.pipeline();

                // Add necessary handlers for the pipeline
                pipeline.addLast("frameDecoder", new LengthFieldBasedFrameDecoder(Integer.MAX_VALUE, 0, 4, 0, 4));
                pipeline.addLast("stringDecoder", new StringDecoder());
                pipeline.addLast("stringEncoder", new StringEncoder());
            }
        });
    }

    public ChannelFuture getChannel() {
        if (shutdown) throw new IllegalStateException();

        return new HystrixCommand<ChannelFuture>(defaultHystrixSettings) {
            @Override
            protected ChannelFuture run() throws Exception {
                while (!Thread.currentThread().isInterrupted()) {
                    for (Map.Entry<Channel, ChannelFuture> entry : channelPool.entrySet()) {
                        if (entry.getValue().isDone()) {
                            channelPool.remove(entry.getKey());
                        } else {
                            return entry.getValue();
                        }
                    }

                    // If pool is full, add a new channel to the pool
                    ChannelFuture future = bootstrap.connect(host, port).syncUninterruptibly();
                    if (future.isSuccess()) {
                        channelPool.putIfAbsent(future.channel(), future);
                        return future;
                    } else {
                        future.channel().close();
                        future.cancel(true);
                    }
                }

                return null; // Should never reach here if thread is not interrupted
            }
        }.execute();
    }

    public synchronized void shutdown() {
        shutdown = true;

        for (Channel channel : new HashSet<>(channelPool.keySet())) {
            channel.close().syncUninterruptibly();
        }

        group.shutdownGracefully();
    }
}
```

