```c
#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define MAX_PATH 4096
#define BUFFER_SIZE 128

void convertJpgToPdf(char* configPath, char** filePaths, int numFiles) {
    // Validate paths
    if (access(configPath, F_OK | R_OK) != 0 || access(configPath, W_OK) != 0) {
        fprintf(stderr, "Config path doesn't exist or is not accessible: %s\n", configPath);
        return;
    }

    for (int i = 0; i < numFiles; ++i) {
        if (access(filePaths[i], F_OK | R_OK) != 0 || access(configPath, W_OK) != 0) {
            fprintf(stderr, "File doesn't exist or is not accessible: %s\n", filePaths[i]);
            continue;
        }
    }

    char command[MAX_PATH];
    snprintf(command, MAX_PATH, "/path/to/externalTool --config=%s", configPath);

    // Fork a new process for each image
    for (int i = 0; i < numFiles; ++i) {
        if (!fork()) {
            execl("/bin/sh", "sh", "-c", command, filePaths[i], (char *) NULL);
            fprintf(stderr, "Failed to execute conversion command for %s: %s\n", filePaths[i], strerror(errno));
        }
    }

    // Wait for all child processes
    int status;
    pid_t pid;
    while ((pid = wait(&status)) > 0);
}
```
This code uses the fork-exec pattern to create a new process for each image conversion. It validates that the paths exist and are accessible before attempting to convert images. The error handling is minimal and will just print errors to stderr, but it can be expanded according to your requirements. 

It doesn't handle edge cases like file format validation or performance constraints due to the complexity of these tasks. Also, this code assumes that you have a command line tool capable of converting JPEGs to PDFs and that this command is the same for all files. 

