Here's a basic implementation of such an authentication module using PHP OAuth 2 client library (`league/oauth2-client`) and `symfony/cache` for caching functionality. This will need to be adapted to meet specific requirements of your application.

```php
<?php
use Symfony\Component\Cache\Adapter\FilesystemAdapter;
use League\OAuth2\Client\Provider\GenericProvider;
use League\OAuth2\Client\Token\AccessToken;

class OauthAuthenticationModule {
    private $provider;
    private $cache;

    public function __construct(array $options = [], $namespace = '', $defaultLifetime = 0, $directory = null)
    {
        $this->provider = new GenericProvider([
            'clientId'                => $options['clientId'],
            'clientSecret'            => $options['clientSecret'],
            'redirectUri'             => $options['redirectUri'],
            'urlAuthorize'            => $options['urlAuthorize'],
            'urlAccessToken'          => $options['urlAccessToken'],
            'urlResourceOwnerDetails' => $options['urlResourceOwnerDetails']
        ]);

        $this->cache = new FilesystemAdapter($namespace, $defaultLifetime, $directory);
    }

    public function authenticateUser(string $code) {
        try {
            $accessToken = $this->provider->getAccessToken('authorization_code', ['code' => $code]);

            // Store the token in session securely.
            $_SESSION['access_token'] = serialize($accessToken);

            return true;
        } catch (Exception $e) {
            error_log("Authentication failed: " . $e->getMessage());
            return false;
        }
    }

    public function getAuthenticatedUser() {
        $token = $this->getAccessToken();

        if (!$token) {
            throw new Exception('Not authenticated');
        }

        $userCacheItem = $this->cache->getItem(md5(serialize($token)));

        // If user info not in cache, get it from API.
        if (!$userCacheItem->isHit()) {
            $resourceOwner = $this->provider->getResourceOwner($token);

            // Save user data to cache.
            $userCacheItem->set($resourceOwner->toArray());
            $this->cache->save($userCacheItem);
        }

        return $userCacheItem->get();
    }

    public function getAccessToken() {
        if (isset($_SESSION['access_token'])) {
            return unserialize($_SESSION['access_token']);
        }

        return null;
    }
}
?>
```

