from hashlib import sha256

class JsonObjectFactory(object):
    _registry = {}

    @staticmethod
    def register_factory(id, factory):
        if id not in JsonObjectFactory._registry:
            JsonObjectFactory._registry[id] = factory

    @staticmethod
    def create_object(id, data):
        try:
            return JsonObjectFactory._registry[id](data)
        except KeyError:
            print("No factory for object with id {}".format(id))

class JsonObject(JsonObjectFactory):
    def __init__(self, json_str):
        self.data = json.loads(json_str)

    @staticmethod
    def create_from_bytes(b):
        str_to_hash = os.urandom(16).hex()
        return sha256(str_to_hash.encode()).hexdigest(), str_to_hash

    def __str__(self):
        return json.dumps(self.data)

JsonObjectFactory.register_factory("json", JsonObject)
