                // Failed to connect
            }
        });
    }

    // Extract bits per sample and samples per pixel from TIFF image
    public void extractImageInfo() throws Exception {
        BufferedImage image = ImageIO.read(new File("image.tif"));
        int bps = 0, spp = 0; 

        if (image.getColorModel().getPixelSize() == 8)
            bps = 1; // for 8-bit images
        else if (image.getColorModel().getPixelSize() == 16)
            bps = 2; // for 16-bit images

        spp = image.getWidth();

        if(bps != 0 && spp != 0){
            System.out.println("Bits per sample: " + bps);
            System.out.println("Samples per pixel: " + spp);
        } else {
            throw new Exception("Unsupported bits per sample.");
        }
    }
}
