#include <stdio.h>
#include <limits.h>
#include <stdlib.h>

void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int get_maximum(int* array, int size){
    int max = INT_MIN;
    for (int i = 0; i < size; ++i) {
        if(array[i] > max){
            max = array[i];
        }
    }
    return max;
}

void readInput() {
    int* numbers = NULL;  // start with empty list
    int number, count = 0;

    while (scanf("%d", &number) == 1) {
        if(count * sizeof(*numbers) > 50UL * 1024 * 1024){  // limit to approx. 50MB
            printf("Error: Maximum memory usage exceeded.\n");
            break;
        }
        ++count;
        numbers = safe_malloc(sizeof(*numbers) * count);
        numbers[count - 1] = number;
    }

    if (!feof(stdin)) {
        printf("Error: Invalid input.\n");
        return;
    }

    int max_number = get_maximum(numbers, count);
    printf("Maximum number in array is %d\n", max_number);

    free(numbers);  // Free allocated memory
}
```
This code first reads input as integers one by one and dynamically allocates more space for the next integer until an invalid input or the maximum allowed memory usage is reached. If either of these conditions is met, it stops reading further inputs and outputs an error message. Finally, it finds and prints out the maximum number in the array.

