use std::{env, fs, io, path, thread, time};
use std::sync::{Arc, Mutex};
use std::time::Duration;
use log::info;
use chrono::prelude::*;

#[derive(Debug)]
struct FileProcessingDirectory {
    dir: String,
    cleanup_duration: Duration,
}

impl FileProcessingDirectory {
    fn new() -> Self {
        let workdir = env::var("WORK_DIR_PREFIX")
            .unwrap_or(String::from("/tmp/file_processing_dir"));

        fs::create_dir_all(&workdir).expect("Unable to create working directory");
        info::<String, io::Error>(!["Directory creation", &: workdir]);

        Self {
            dir: workdir,
            cleanup_duration: Duration::from_secs(60), // Replace this with your own duration
        }
    }

    fn check_disk(&self) {
        let disk = fs::metadata(&self.dir).expect("Failed to read metadata");
        info::<String, io::Error>(!["Disk information", &: format args: "{}", disk.free_space]]);

        if disk.available_space < (disk.total_space * 0.2) { // Threshold is 20% free space
            self.cleanup();
        }
    }

    fn cleanup(&self) {
        info::<String, io::Error>(!["Starting Cleanup"]);

        thread::spawn(move || {
            loop {
                thread::sleep(self.cleanup_duration);

                // Place actual file cleanup logic here. For simplicity, just print a log message
                info::<String, io::Error>(!["Cleaning up old files in", &: self.dir]);
            }
        });
    }
}

fn main() {
    let fpd = Arc::new(Mutex::new(FileProcessingDirectory::new()));

    loop {
        thread::sleep(Duration::from_secs(1));

        // This needs to be a separate thread due to blocking operations in Rust. 
        // You may want to use an asynchronous version of the fs methods here instead.
        let fpd = match Arc::try_clone(&fpd).unwrap() {
            Ok(fpd) => fpd,
            Err(_e) => continue,
        };

        thread::spawn({
            move || {
                let mut fpd = fpd.lock().unwrap();
                fpd.check_disk();
            }
        });
    }
}
```
In this Rust code, we create a `FileProcessingDirectory` structure that encapsulates directory operations. It gets the working directory from an environment variable (or defaults to "/tmp/file_processing_dir" if not set) and creates it if necessary. The `check_disk` method checks available disk space and triggers a cleanup if usage is below 20%.
The actual file cleanup logic is not included in this code snippet, but you can implement that by adding custom logic to the `cleanup` function or replacing it with an appropriate fs operation. The logging mechanism has been simplified here and does not include all the features you may want (like log rotation), but should give you a good starting point.
The main loop in the `main()` function checks disk usage every second, creating a new thread to perform cleanup if necessary. This is done within an Arc<Mutex> wrapper to ensure that only one thread can access and modify the directory at a time, preventing race conditions.
