```python
import os
from time import sleep
import logging 
import threading
import queue
from abc import ABC, abstractmethod

class DirectoryCreationError(Exception):
    pass

class RetryStrategy(ABC):
    @abstractmethod
    def should_retry(self, error: Exception) -> bool:
        pass

class SimpleRetryStrategy(RetryStrategy):
    def __init__(self, max_retries: int = 5):
        self.max_retries = max_retries
        self.current_retry = 0

    def should_retry(self, error: Exception) -> bool:
        if not isinstance(error, DirectoryCreationError):
            return False

        if self.current_retry < self.max_retries:
            self.current_retry += 1
            return True

        return False

class WorkerManager():
    def __init__(self, retry_strategy=SimpleRetryStrategy()):
        self.queue = queue.Queue()
        self.workers = []
        self.logger = logging.getLogger(__name__)
        self.retry_strategy = retry_strategy

    def add_task(self, task: callable):
        self.queue.put(task)

    def start(self, num_workers=10):
        for _ in range(num_workers):
            worker = threading.Thread(target=self._worker)
            worker.start()
            self.workers.append(worker)

    def _worker(self):
        while not self.queue.empty():
            task = self.queue.get()
            try:
                task()
            except Exception as e:
                if self.retry_strategy.should_retry(e):
                    self._notify("Retrying task due to error.")
                    sleep(5)  # Add some delay before retry
                    self.queue.put(task)
                else:
                    self._notify("Task failed permanently, manual intervention required.", logging.ERROR)

    def _notify(self, message: str, level=logging.INFO):
        self.logger.log(level, message)
```

