class ScriptLoader {
  constructor(apiUrl) {
    this.scriptCache = {};
    this.apiUrl = apiUrl;
  }

  async fetchAndRenderScripts() {
    try {
      const response = await fetch(this.apiUrl); // Fetch scripts from API endpoint
      if (!response.ok) throw new Error('Network response was not ok');

      const scripts = await response.json(); // Parse script objects from response

      this.renderScripts(scripts); // Render the fetched scripts
    } catch (error) {
      console.error('Error:', error);
      this.renderFallbackScript(); // Fallback to a critical script in case of errors
    }
  }

  renderScripts(scripts) {
    const scriptElements = scripts.map(script => {
      if (!script.code || !script.type) throw new Error('Missing essential properties');

      const element = document.createElement('script'); // Create a script tag for each script object
      element.innerHTML = script.code;

      // Apply custom metadata to the script tag
      if (script.async) {
        element.setAttribute('async', '');
      }
      if (script.defer) {
        element.setAttribute('defer', '');
      }
      if (script.crossorigin) {
        element.setAttribute('crossorigin', script.crossorigin);
      }

      return element; // Return an array of rendered script tags
    });

    document.body.append(...scriptElements); // Append the rendered scripts to the page body
  }

  renderFallbackScript() {
    const fallbackScript = /*...*/; // Define a critical fallback script
    this.renderScripts([fallbackScript]);
  }
}
```
