            element.innerHTML = '<div class="loading-indicator">Loading...</div>';

            let response = await fetchWithRetries(urlForFetching, apiToUse);

            if (!response.ok) {
                throw new Error('Network response was not ok');
            }

            // Process response based on API
            let content;
            switch (apiToUse) {
                case 'api1': 
                    // handle text responses from api1
                    break;
                case 'api2': 
                    // handle image responses from api2
                    break;
                case 'api3': 
                    // handle video responses from api3
                    break;
            }

            element.innerHTML = content;
        } catch(error) {
            console.log('Error fetching dynamic content: ', error);
            // Show fallback content or message to the user
            element.innerHTML = '<div class="error-message">Failed to load content :(</div>';
        } 
    }
}

async function fetchWithRetries(url, apiToUse) {
    let retries = 3; // number of times to retry the request before failing

    while (retries > 0) {
        try {
            return await callAPI(apiToUse, url);  // callApi is a function that selects the appropriate API and makes the fetch call.
        } catch (error) {
            retries--;

            if (error instanceof RateLimitError && retries > 0) {
                console.log('Rate limit exceeded on API, retrying...');

                // Wait for a bit before retrying
                await new Promise(resolve => setTimeout(resolve, 1000));
            } else {
                throw error;
            }
        }
    }

    throw new Error('Failed to fetch content after multiple retries');
}
```
