Here's an implementation of the method `downloadImageResources` in Java using the popular libraries Apache HttpClient, OkHttp for HTTP requests, Guava for caching, and Picasso or Glide for image processing. Note that this is a simplified implementation and does not cover all the functional requirements listed above. For example, it lacks an API rate limit handling mechanism and retry scheduling after a failed download. 

```java
import com.squareup.picasso.Picasso;
import okhttp3.*;
import org.apache.commons.validator.routines.UrlValidator;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

import java.io.IOException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.logging.*;

public class ImageDownloader {
    private static final Logger logger = Logger.getLogger(ImageDownloader.class.getName());
    private static final String[] schemes = {"http", "https"};
    private static final UrlValidator urlValidator = new UrlValidator(schemes);
    private static OkHttpClient okHttpClient;
    private static Picasso picasso;
    private static LoadingCache<String, byte[]> imageCache;

    public ImageDownloader() {
        this.okHttpClient = new OkHttpClient().newBuilder()
                .connectTimeout(20, TimeUnit.SECONDS)
                .readTimeout(30, TimeUnit.SECONDS)
                .writeTimeout(30, TimeUnit.SECONDS)
                .retryOnConnectionFailure(true)
                .build();
        this.picasso = new Picasso.Builder(context).downloader(new OkHttp3Downloader(okHttpClient)).build();

        imageCache = CacheBuilder.newBuilder()
                .maximumSize(10_000)
                .expireAfterAccess(1, TimeUnit.HOURS)
                .build(new CacheLoader<String, byte[]>(){
                    @Override
                    public byte[] load(String url) throws Exception {
                        return downloadImageFromUrl(url);
                    }
                });
    }

    private byte[] downloadImageFromUrl(String imageUrl) throws IOException{
        Request request = new Request.Builder()
          .url(imageUrl)
          .build();

        try (Response response = okHttpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) throw new IOException("Unexpected code " + response);

            byte[] imageBytes = response.body().bytes();
            return imageBytes;
        }
    }

    public void downloadImageResources(String[] urls, ImageView target) {
        for (String url : urls) {
            if (!urlValidator.isValid(url)) {
                logger.log(Level.SEVERE, "Invalid URL: " + url);
                continue;
            }

            byte[] imageBytes;
            try {
                imageBytes = imageCache.get(url);
            } catch (ExecutionException e) {
                logger.log(Level.SEVERE, "Failed to download image from: " + url, e);
                continue;
            }

            picasso.load(imageBytes).into(target);
        }
    }
}
```
