```javascript
const fs = require('fs');
const configPath = './modules.json';
let modules = {}; // Cache loaded modules

function loadModule(path) {
  if (!modules[path]) {
    try {
      const module = require(path);
      modules[path] = module;
    } catch (err) {
      console.error(`Failed to load module at ${path}: ${err}`);
    }
  }

  return modules[path];
}

function executeModules() {
  const config = JSON.parse(fs.readFileSync(configPath));

  for (let path of config) {
    let module = loadModule(path);

    if (module && typeof module === 'function') {
      try {
        module();
      } catch (err) {
        console.error(`Failed to execute module at ${path}: ${err}`);
      }
    } else {
      console.warn(`Module at ${path} is not a function, skipping execution`);
    }
  }
}

executeModules();
```
