Please note that implementing features like JSON-PATCH requires server support and it could vary based on your backend implementation. The following code snippet provides a basic idea of how you can approach this:

```javascript
angular.module('app', [])
    .factory('DataRefreshService', ['$http', '$q', function($http, $q) {
        var fieldsToUpdate = {};

        // Add field to the update queue
        this.addFieldToUpdate = function(fieldName, url) {
            fieldsToUpdate[fieldName] = {
                url: url,
                data: null,
                isFetching: false
            };
        }

        // Remove field from the update queue
        this.removeFieldFromUpdate = function(fieldName) {
            delete fieldsToUpdate[fieldName];
        }

        // Refresh all fields in the update queue
        this.refreshAllFields = function() {
            var promises = [];

            for (var fieldName in fieldsToUpdate) {
                if (!fieldsToUpdate.hasOwnProperty(fieldName)) continue;

                var fieldData = fieldsToUpdate[fieldName];
                if (fieldData.isFetching || !_.isEmpty(fieldData.data)) continue; // Skip already fetching or filled data fields

                fieldData.isFetching = true;
                promises.push($http.get(fieldData.url)
                    .then(function successCallback(response) {
                        fieldData.isFetching = false;
                        fieldData.data = response.data;
                        console.log('Successfully fetched data for ' + fieldName);
                    }, function errorCallback(response) {
                        fieldData.isFetching = false;
                        console.error('Failed to fetch data for ' + fieldName, response);
                    }));
            }

            return $q.all(promises);
        }

        // Get the fetched data for a specific field
        this.getFieldData = function(fieldName) {
            var fieldData = fieldsToUpdate[fieldName];
            if (!_.isUndefined(fieldData)) {
                return fieldData.data;
            } else {
                console.warn('No data found for ' + fieldName);
                return null;
            }
        }

        return this;
    }]);
```
