```csharp
using System;
using UnityEngine;

public static class CustomRandomGenerator
{
    private static readonly object lockObject = new object();

    public static int GenerateInt(int min, int max)
    {
        return GenerateInt(min, max, true);
    }

    public static int GenerateInt(int min, int max, bool inclusive)
    {
        lock (lockObject)
        {
            if (inclusive)
                return UnityEngine.Random.Range(min, max + 1);
            else
                return UnityEngine.Random.Range(min + 1, max);
        }
    }

    public static float GenerateFloat(float min, float max)
    {
        return GenerateFloat(min, max, true);
    }

    public static float GenerateFloat(float min, float max, bool inclusive)
    {
        lock (lockObject)
        {
            if (inclusive)
                return UnityEngine.Random.Range(min, max);
            else
                return UnityEngine.Random.value * (max - min) + min;
        }
    }
}
```

