#define MAX_LINE 256
#define MAX_FIELD 10

typedef struct {
    char *fields[MAX_FIELD];
    int count;
} logEntry_t;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *logFile, *outputFile;
float average = 0.0;
int connectionStatus = 1; // 1 for active, 0 for inactive

void *processEntry(void *entry) {
    logEntry_t *e = (logEntry_t *) entry;
    int i, numFields = e->count;
    float sum = 0.0;
    char line[MAX_LINE];

    for (i = numFields - 3; i < numFields; ++i) {
        if (!e->fields[i]) continue; // skip malformed entries
        sum += atof(e->fields[i]);
    }
    average = sum / 3.0;

    pthread_mutex_lock(&mutex);
    sprintf(line, "%s,%f", e->line, average);
    fprintf(outputFile, "%s\n", line);
    if (connectionStatus) {
        // store in database
    } else {
        // switch to backup connection and try again
    }
    pthread_mutex_unlock(&mutex);

    free(e->fields);
    free(e);

    return NULL;
}

logEntry_t *parseLine(char *line) {
    char *token, *str, *tofree;
    tofree = str = strdup(line);
    logEntry_t *entry = malloc(sizeof(logEntry_t));

    for (int i = 0; i < MAX_FIELD && ((token = strsep(&str," ,")) != NULL); ++i) {
        entry->fields[i] = token;
    }
    entry->count = MAX_FIELD; // need a better way to count fields

    free(tofree);
    return entry;
}

int main() {
    char line[MAX_LINE];
    logFile = fopen("log.txt", "r");
    outputFile = fopen("output.csv", "w");
    pthread_t thread;

    if (!logFile || !outputFile) {
        perror("Failed to open file(s)");
        return 1;
    }

    while (fgets(line, MAX_LINE, logFile)) {
        line[strcspn(line, "\n")] = 0; // remove trailing newline
        logEntry_t *entry = parseLine(line);

        if (pthread_create(&thread, NULL, processEntry, entry) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    fclose(logFile);
    fclose(outputFile);

    return 0;
}
```
