```javascript
function FindElementsBySelector(startingNode, selector) {
  var elements = [];

  // Create a queue to manage nodes we need to visit.
  var queue = [startingNode];

  while (queue.length > 0) {
    var node = queue.shift();

    if (/* Node matches the selector */) {
      elements.push(node);
    }

    for (var i = 0; i < node.childNodes.length; ++i) {
      queue.push(node.childNodes[i]);
    }
  }

  return elements;
}
```

