import json
from collections import OrderedDict
from hashlib import sha256
import os
import random
from concurrent.futures import ThreadPoolExecutor

class BaseJsonObject:
    _factories = {}

    def __init__(self, **kwargs):
        self.__dict__ = kwargs

    @classmethod
    def add_factory(cls, id, factory):
        cls._factories[id] = factory

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        if 'id' in data:
            if data['id'] in cls._factories:
                return cls._factories[data['id']](**data)
            else:
                raise ValueError('Unknown ID')
        else:
            return cls(**data)

    def to_json(self):
        return json.dumps(self, default=lambda o: o.__dict__)

class MyJsonObject(BaseJsonObject):
    def __init__(self, id, data):
        super().__init__(id=id)
        self.data = data

def load_json_file(filename):
    with open(filename, 'r') as f:
        json_str = f.read()
    return BaseJsonObject.from_json(json_str)

# Register factory for MyJsonObject
BaseJsonObject.add_factory('MyJsonObject', MyJsonObject)

def process_files(filenames, max_workers=5):
    if len(filenames) > max_workers:
        with ThreadPoolExecutor(max_workers) as executor:
            return list(executor.map(load_json_file, filenames))
    else:
        # Less files than workers available for threading, use simple synchronous loading 
        return [load_json_file(filename) for filename in filenames]

def deserialize(byte_array):
    str = byte_array.decode('utf-8')
    password_hash = sha256(str.encode()).hexdigest()  # Example of hashing with sha256, you can choose any hash function
    return str, password_hash

def manipulate_forward_list(lst, target, new_item, position):
    try:
        idx = lst.index(target, position) if len(lst[position:]) > 0 else -1
        if idx != -1:  # found the string in list at given index
            lst.insert(idx + 1, new_item)
        else:  # string not found in list after provided position
            lst.append(new_item)
    except IndexError:
        print("Position out of bounds")

def read_from_file(filename):
    with open(filename, 'r') as f:
        lines = f.readlines()
    for line in lines:
        target, new_item, position = line.split(' ')  # Splitting the line into parts
        manipulate_forward_list(my_forward_list, target, new_item, int(position))
```
In this example, `MyJsonObject` is a subclass of `BaseJsonObject` that takes an id and some data. When we load JSON files, we use the factory method to create instances based on the 'id' field in the JSON file. We add this factory function for 'MyJsonObject' using `add_factory` class method.

The `manipulate_forward_list` function takes a forward list-like structure (Python list), a target string, new string to insert and position index as arguments. It finds the first occurrence of the target after the given position, if it exists, otherwise appends the new string at the end of the list.

The `read_from_file` function reads lines from an external text file with space-separated strings. It splits each line into three parts: target string, new string and position index, and calls `manipulate_forward_list` to perform the insertion based on these parts for each line in the file.

