```cpp
#include <rapidjson/document.h>
#include <fstream>
#include <iostream>

class Node {
public:
    int key;
    std::string value;
};

class NodeArray {
private:
    int size = 0, capacity = 16;
    Node *nodes = new Node[capacity];

public:
    void add(Node node) {
        if (size == capacity) resize();
        nodes[size++] = node;
    }

    void remove() {
        // Implement your logic here to remove a node.
    }

    void update(int index, Node node) {
        if (index < size && index >= 0) {
            nodes[index] = node;
        } else {
            std::cout << "Index out of bounds." << std::endl;
        }
    }

    void resize() {
        capacity *= 2;
        Node* newNodes = new Node[capacity];
        for (int i = 0; i < size; ++i) 
            newNodes[i] = nodes[i];

        delete[] nodes;
        nodes = newNodes;
    }

    std::string toJSON() {
        rapidjson::Document doc(rapidjson::kArrayType);
        for (int i = 0; i < size; ++i) {
            rapidjson::Value nv(rapidjson::kObjectType);
            nv.AddMember("key", nodes[i].key, doc.GetAllocator());
            nv.AddMember("value", nodes[i].value, doc.GetAllocator());
            doc.PushBack(nv, doc.GetAllocator());
        }

        rapidjson::StringBuffer buffer;
        rapidjson::Writer<rapidjson::StringBuffer> writer(buffer);
        doc.Accept(writer);
        return buffer.GetString();
    }
};
```
