async function loadScriptsFromApi(apiUrl, callback) {
  try {
    const scripts = await fetchJson(apiUrl);

    for (let script of scripts) {
        if (!loadedScripts[script.key]) { // only load non-loaded scripts to avoid reloads
            let tag = document.createElement('script');

            // set attributes common to all script tags
            tag.setAttribute('id', script.key);
            tag.textContent = script.code;

            for (let attr in script) { 
                if (!['key', 'code'].includes(attr)) { // add custom attributes
                    tag.setAttribute(attr, script[attr]);
                }
            }

            loadedScripts[script.key] = true; // mark as loaded
            cachedScripts[script.key] = script; // cache for later use
            document.body.appendChild(tag); // render to DOM

            if (callback) callback(); 
        }
    }

  } catch(error) {
      logger.error('Error fetching scripts from API: ', error);
  }
}

function removeScript(key) {
    let tag = document.getElementById(key);

    if (tag) { // only try to remove a script that exists in DOM
        delete loadedScripts[key];
        delete cachedScripts[key];
        tag.parentElement.removeChild(tag);
        logger.info('Removed script with key: ', key);
    } else {
        logger.warn('Tried to remove non-existent script with key: ', key);
    }
}
