    def add_mission(self, mission):
        heapq.heappush(self.mission_queue, (-mission.priority, mission))

    def get_next_mission(self):
        if not self.mission_queue:
            return None
        priority, mission = heapq.heappop(self.mission_queue)  # Get highest priority task
        return mission

class DroneManager:
    def __init__(self, drones):
        self.drones = drones  # List of Drones
        self.drone_control_server_client = DroneControlServerClient()
        self.mission_scheduler = MissionScheduler()

    async def handle_missions(self):
        while True:
            for drone in self.drones:
                mission = self.mission_scheduler.get_next_mission()
                if mission is not None and drone.battery > 0:  # If there's a mission to execute
                    asyncio.ensure_future(self.drone_control_server_client.send_mission(drone, mission))

            await asyncio.sleep(1)  # Check every second

    async def handle_low_battery_alerts(self):
        while True:
            for drone in self.drones:
                if drone.battery < 20:  # If battery is low
                    logging.warning(f'Drone {drone} has low battery')
            await asyncio.sleep(60)  # Check every minute

    def run(self):
        loop = asyncio.get_event_loop()

        try:
            asyncio.ensure_future(self.handle_missions())
            asyncio.ensure_future(self.handle_low_battery_alerts())
            loop.run_forever()  # Run until Ctrl+C is pressed
        except (KeyboardInterrupt, SystemExit):
            pass
```
