    Session(net::io_context& ioc, ssl::context& ctx)
      : resolver_(ioc), stream_(ioc, ctx) {}
    ~Session() = default;

    void run(const std::string host, const std::string target) {
        host_ = host;
        req_.version(11);
        req_.method(http::verb::get);
        req_.target(target);
        req_.set(http::field::host, host);
        req_.prepare_payload();

        resolver_.async_resolve(host, "https",
            std::bind(&Session::onResolve, shared_from_this(),
                std::placeholders::_1, std::placeholders::_2));
    }
private:
    void onResolve(boost::system::error_code ec, tcp::resolver::results_type results) {
        //... handle error

        net::async_connect(stream_.next_layer(), results.begin(), results.end(),
            std::bind(&Session::onConnect, shared_from_this(), std::placeholders::_1));
    }

    void onConnect(boost::system::error_code ec) {
        //... handle error

        stream_.async_handshake(ssl::stream_base::client,
            std::bind(&Session::onHandshake, shared_from_this(), std::placeholders::_1));
    }

    void onHandshake(boost::system::error_code ec) {
        //... handle error

        http::async_write(stream_, req_,
            std::bind(&Session::onWrite, shared_from_this(), std::placeholders::_1, std::placeholders::_2));
    }

    void onWrite(boost::system::error_code ec, std::size_t bytesTransferred) {
        //... handle error

        http::async_read(stream_, buffer_, res_,
            std::bind(&Session::onRead, shared_from_this(), std::placeholders::_1, std::placeholders::_2));
    }

    void onRead(boost::system::error_code ec, std::size_t bytesTransferred) {
        //... handle error

        InterfaceTable it;
        it.FindVmUuidFromMetadataIp("192.168.0.1");  // Just an example
    }

private:
    tcp::resolver resolver_;
    ssl::stream<tcp::socket> stream_;
    http::request<http::empty_body> req_;
    beast::flat_buffer buffer_;
    http::response<http::string_body> res_;
    std::string host_;
};

int main() {
