    ssl::context ctx{ssl::context::tlsv12_client};

    //... load certificate

    std::vector<std::thread> v;
    for(int i = 0; i < 4; ++i) {  // Run with 4 threads to simulate high concurrency
        v.emplace_back([&ioc, &ctx]{
            auto s = std::make_shared<Session>(ioc, ctx);
            s->run("example.com", "/");  // host and target
        });
    }

    for(auto& thread : v) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}
