public class AdvancedRandomGenerator
{
    private static readonly ThreadLocal<Random> Random = new ThreadLocal<Random>(() => new Random());
    private int minLimit, maxLimit;

    public AdvancedRandomGenerator(int minRange, int maxRange)
    {
        if (minRange > maxRange) throw new ArgumentException("Minimum range cannot be greater than maximum");
        this.minLimit = minRange;
        this.maxLimit = maxRange;
    }

    public void SetDynamicRanges(int minRange, int maxRange)
    {
        if (minRange > maxRange) throw new ArgumentException("Minimum range cannot be greater than maximum");
        Interlocked.Exchange(ref this.minLimit, minRange);
        Interlocked.Exchange(ref this.maxLimit, maxRange);
    }

    public int Next()
    {
        lock (Random)
        {
            return Random.Value.Next(this.minLimit, this.maxLimit + 1);
        }
    }

    // Implement other methods for float and custom distribution...
}
