const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

// Function to execute shell commands safely
async function safeShellExec(command) {
  // Sanitize input to prevent command injection attacks
  if (/[;&|*`<>(){}\[\]"'\s]/.test(command)) throw new Error('Invalid characters in command.');

  return new Promise((resolve, reject) => {
    exec(command, (error, stdout, stderr) => {
      // Log errors to separate file for later analysis
      if (error) {
        fs.appendFileSync(path.join(__dirname, 'errors.log'), `${new Date()} - ${error}\n`);
        reject('Error executing command');
      } else resolve(stdout);
    });
  });
}

// Function to filter output based on a pattern and integrate with DB (assuming the web application uses MongoDB)
async function processOutput(command, db, pattern){

  // Fetch data from DB
  const collection = db.collection('myCollection');
  const data = await collection.find({}).toArray();

  try {
    const output = await safeShellExec(command);

    // Filter output based on pattern and integrate with DB
    const filteredOutput = output.match(pattern);
    if (filteredOutput) {
      for (let entry of filteredOutput){
        collection.insertOne({output:entry});
      } 
    } else throw new Error('Pattern not found in output');

  } catch (error) {
    fs.appendFileSync(path.join(__dirname, 'errors.log'), `${new Date()} - ${error}\n`);
    console.error("Error processing command", error);
  }  
}
```

