```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Serilog; // replace with any logger you like, such as NLog

public class DynamicFileMetadataAnalyzer
{
    private readonly ILogger _logger = Log.Logger; // use your preferred logger here
    private DirectoryInfo _directory;
    private int _minimumThresholdKB;
    private int _maximumThresholdKB;
    private int _batchSize;

    public DynamicFileMetadataAnalyzer(string directoryPath, int minimumThresholdKB, 
        int maximumThresholdKB, int batchSize)
    {
        if (!Directory.Exists(directoryPath))
            throw new ArgumentException("Invalid Directory Path", nameof(directoryPath));

        _directory = new DirectoryInfo(directoryPath);

        if (minimumThresholdKB > maximumThresholdKB || minimumThresholdKB < 0 || 
            maximumThresholdKB <= 0)
            throw new ArgumentOutOfRangeException("Size thresholds not valid");

        _minimumThresholdKB = minimumThresholdKB;
        _maximumThresholdKB = maximumThresholdKB;

        if (batchSize < 1) 
            throw new ArgumentOutOfRangeException(nameof(batchSize));

        _batchSize = batchSize;
    }

    public async IAsyncEnumerable<ProcessedMetadata> ProcessFilesAsync(Func<FileInfo, Task<bool>> metadataProcessor)
    {
        var files = _directory.GetFiles()
            .Where(f => f.Length >= _minimumThresholdKB * 1024 && 
                        f.Length <= _maximumThresholdKB * 1024);

        foreach (var batch in Partition(files, _batchSize))
        {
            var tasks = batch.Select(metadataProcessor).ToArray();

            try
            {
                await Task.WhenAll(tasks);

                foreach (var task in tasks)
                    if (task.Result) // check if processing was successful
                        yield return new ProcessedMetadata(/* construct with file info */);
            }
            catch (Exception e)
            {
                _logger.Error(e, "An error occurred while processing a batch of files");
            }
        }
    }

    private static IEnumerable<IEnumerable<T>> Partition<T>(IEnumerable<T> sequence, int size)
    {
        List<T> partition = new List<T>(size);

        foreach (var item in sequence)
        {
            partition.Add(item);

            if (partition.Count == size)
            {
                yield return partition;
                partition = new List<T>(size);
            }
        }

        if (partition.Any()) 
            yield return partition;
    }
}
```
