```C
#include <stdlib.h>
#define MAX_TRANSACTIONS 1024

typedef struct {
    int state;
    unsigned long timestamp;
} FsaState;

typedef struct {
    float weightSum;
    char transactionID[64];
} Transaction;

typedef struct {
    FsaState* states;
    size_t numStates;
    Transaction transactions[MAX_TRANSACTIONS];
} Metrics;

void dfs(FsaState *state, int lastState, unsigned long currentTime, 
         Transaction criteria, Metrics *metrics) {

    // perform a depth-first search on the FSA here
    if (state->timestamp <= currentTime && state->state < lastState){
        metrics->states[metrics->numStates++] = *state;

        // filter transactions based on the criteria 
        for(int i = 0; i< MAX_TRANSACTIONS; ++i) {
            if (metrics->transactions[i].weightSum > criteria.weightSum){
                metrics->transactions[i] = (Transaction){ .weightSum = -1 }; // marks as filtered
            } 
        }
    } else {
        // continue traversal
    }
}

FsaState* filterAndCollectStates(int *states, int numStates, FsaState *fsa, int lastState, unsigned long currentTime, 
                                 Transaction criteria, Metrics *metrics) {

    if (!states || !fsa || !metrics) {
        return NULL; // invalid pointers
    }

    metrics->states = malloc(sizeof(FsaState)*numStates);
    if(!metrics->states){
      return NULL; // out of memory error
    }

    for (int i = 0; i < numStates; ++i) {
        dfs(&fsa[i], lastState, currentTime, criteria, metrics);
    }

    return metrics->states;
}
