from joblib import Parallel, delayed
import time
import cachetools

cache = cachetools.TTLCache(maxsize=100, ttl=300)  # Cache for last 5 minutes

def convert_temperature(temps, from_scale, to_scale):
    """Converts temperatures in parallel."""
    if isinstance(temps, (int, float)):  # Single temperature conversion
        temps = [temps]

    results = Parallel(n_jobs=-1)(delayed(_convert_single)(temp, from_scale, to_scale) for temp in temps)

    return results if len(results) > 1 else results[0]  # Return single value or list

@cache.cache
def _convert_single(temp, from_scale, to_scale):
    """Converts a single temperature."""
    time.sleep(.1)  # Simulate a long calculation

    if from_scale == 'Celsius':
        if to_scale == 'Fahrenheit':
            return temp * 9/5 + 32
        elif to_scale == 'Kelvin':
            return temp + 273.15
    # Add other conversions...

    raise ValueError(f'Unknown conversion: {from_scale} to {to_scale}')
