```javascript
async function dynamicDOMQuery(rootElement, selector, ...filterCriteria) {
  const elements = [];
  const queue = [rootElement];

  while (queue.length > 0) {
    const currentNode = queue.shift();

    if (currentNode.nodeType === Node.ELEMENT_NODE && currentNode.matches(selector)) {
      let match = true;

      for (const filter of filterCriteria) {
        for (const [attr, value] of Object.entries(filter)) {
          if (currentNode.getAttribute(attr) !== value) {
            match = false;
            break;
          }
        }

        if (!match) break;
      }

      if (match) elements.push(currentNode);
    }

    queue.push(...Array.from(currentNode.children));
  }

  return elements;
}
```

