        filename = secure_filename(f.filename)
        content_type = f.content_type
        if self.validate_image(filename, content_type):
            gcs.blob.upload_from_string(bucket_handler, data=f.read(), 
                                       destination_blob_name=filename)
            return jsonify({'message': 'File successfully uploaded!'})
        else:
            return jsonify({'error': 'Invalid image format or size!'})

    @cached(cache)
    def get(self, filename):
        blob = gcs.blob.Blob(filename, bucket_handler)
        contents = blob.download_as_text()
        return send_file(contents, mimetype='image/png')

    @staticmethod
    def validate_image(filename, content_type):
        if not ('.' in filename and filename.rsplit('.', 1)[1].lower() == 'jpg'):
            return False
        elif content_type != 'image/jpeg':
            return False
        else:
            return True
