Here is a basic implementation of `AdvancedRandomGenerator` that meets your requirements. It uses the Unity `System.Random` class for its random number generation, which should be sufficient for most purposes. However, keep in mind that this solution does not include any thread synchronization or exception handling that would be necessary to fully meet all the requirements listed above:

```csharp
using System;
using UnityEngine;
using System.Collections.Generic;

public enum RangeType { Closed, Open, HalfOpen }

public class AdvancedRandomGenerator 
{
    private System.Random rand;
    private int seed;
    private Dictionary<int, Action> callbacks = new Dictionary<int, Action>();

    public AdvancedRandomGenerator(int seed)
    {
        this.seed = seed;
        rand = new System.Random(this.seed);
    }

    public float CustomRange(float min, float max, RangeType type) 
    {
        if (min > max)
            throw new ArgumentException("Invalid range");

        switch (type)
        {
            case RangeType.Closed:
                return (float)(rand.NextDouble() * (max - min) + min);
            case RangeType.Open:
                return (float)((rand.NextDouble() * (max - min)) + min + 1);
            case RangeType.HalfOpen:
                if (min > 0 && max < 1)
                    return (float)(rand.NextDouble() * (max - min) + min);
                else
                    throw new ArgumentException("Invalid range for Half-open interval");
        }
        throw new ArgumentException("Unknown RangeType: " + type);
    }

    public int CustomRange(int min, int max, RangeType type) 
    {
        if (min > max)
            throw new ArgumentException("Invalid range");

        switch (type)
        {
            case RangeType.Closed:
                return rand.Next(min, max + 1);
            case RangeType.Open:
                return rand.Next(min + 1, max);
            case RangeType.HalfOpen:
                if (min > 0 && max < 2)
                    return rand.Next(min, max + 1);
                else
                    throw new ArgumentException("Invalid range for Half-open interval");
        }
        throw new ArgumentException("Unknown RangeType: " + type);
    }

    public void SetSeed(int seed) 
    {
        this.seed = seed;
        rand = new System.Random(this.seed);

        if (callbacks.ContainsKey(seed))
            callbacks[seed]();
    }

    public delegate void SeedCallback(int seed);

    public void RegisterSeedCallback(int key, Action action) 
    {
        if (!callbacks.ContainsKey(key))
            callbacks.Add(key, action);
        else
            callbacks[key] += action;
    }
}
```
Please note that you would need to fill in the details for automatic reseeding and error handling as described in your requirements. This class assumes a single thread of execution and does not handle race conditions between threads or seed management, which are important aspects of a robust random number generation system.

