import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import org.apache.commons.io.IOUtils;
import com.github.rholder.retry.*;
import java.util.concurrent.TimeUnit;
import java.util.logging.*;

public class ImageDownloader {
    private LoadingCache<String, byte[]> cache;
    private Retryer<Void> retryer = RetryerBuilder.<Void>newBuilder()
        .retryIfExceptionOfType(IOException.class)
        .withWaitStrategy(WaitStrategies.exponentialWait())
        .build();

    public ImageDownloader() {
        this.cache = CacheBuilder.newBuilder()
            .maximumSize(10_000) // Set cache size limit
            .expireAfterWrite(24, TimeUnit.HOURS) // Images expire after 24 hours
            .build(new CacheLoader<String, byte[]>(){
                @Override
                public byte[] load(String url) throws Exception {
                    return downloadImageResource(url);
                }});
    }

    private static final Logger LOGGER = Logger.getLogger(ImageDownloader.class.getName());

    public byte[] downloadImageResources(String imageUrl) {
        try{
            URL url = new URL(imageUrl);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setConnectTimeout(5000); // Set timeout to 5 seconds
            connection.setReadTimeout(5000);
            int responseCode = connection.getResponseCode();

            LOGGER.log(Level.INFO, "Downloading image from: {0}, Response Code: {1}", new Object[] {imageUrl, responseCode});

            if (responseCode == HttpURLConnection.HTTP_OK) {
                byte[] bytes = retryer.call(() -> IOUtils.toByteArray(connection));
                return resizeAndConvertImage(bytes); // Assume this method exists for resizing and converting images
            } else{
                LOGGER.log(Level.WARNING, "Failed to download image from: {0}, Response Code: {1}", new Object[] {imageUrl, responseCode});
            }
        }catch (Exception e){
            LOGGER.log(Level.SEVERE, "Error downloading image from: {0}, Message: {1}", new Object[] {imageUrl, e.getMessage()});
        }

        return null; // If download fails or times out, return null
    }

    public byte[] resizeAndConvertImage(byte[] bytes){
      // Implement image resizing and conversion here
    }
}
