```C#
using System;
using System.Data;
using System.Collections.Generic;
using System.Threading;
using System.Diagnostics;
using Microsoft.Extensions.Configuration;

public interface IDatabaseConnectionManager
{
    IDbConnection GetConnection(string provider, string connectionString);
    void ReleaseConnection(IDbConnection connection);
    void InitializeFromConfiguration(string configSource);
}

public class DatabaseConnectionManager : IDatabaseConnectionManager
{
    private readonly Dictionary<string, IList<IDbConnection>> _pools = new Dictionary<string, IList<IDbConnection>>();
    private readonly object _locker = new object();
    private int _connectionCount = 0;
    public const int MaxConnections = 100; // example value, should be configured

    public IDbConnection GetConnection(string provider, string connectionString)
    {
        lock (_locker)
        {
            if (!_pools.TryGetValue(provider + "_" + connectionString, out var pool))
                return CreateNewConnection(provider, connectionString);

            if (pool.Count > 0)
            {
                var conn = pool[0];
                pool.RemoveAt(0);
                Interlocked.Decrement(ref _connectionCount);
                return conn;
            }

            if (_connectionCount >= MaxConnections)
                throw new InvalidOperationException("Max connections reached.");
        }

        return CreateNewConnection(provider, connectionString);
    }

    private IDbConnection CreateNewConnection(string provider, string connectionString)
    {
        // create a new connection based on the provider and connection string
        // use a factory pattern or similar to avoid hard-coding supported providers 
        throw new NotImplementedException();
    }

    public void ReleaseConnection(IDbConnection connection)
    {
        lock (_locker)
        {
            var poolKey = connection.Database + "_" + connection.DataSource;
            if (!_pools.TryGetValue(poolKey, out var pool))
                _pools[poolKey] = pool = new List<IDbConnection>();

            if (pool.Count < MaxConnections)
            {
                pool.Add(connection);
                Interlocked.Increment(ref _connectionCount);
            }
            else
            {
                // close the connection instead of adding it to the pool if pool is full
                connection.Close();
            }
        }
    }

    public void InitializeFromConfiguration(string configSource)
    {
        var configuration = new ConfigurationBuilder()
            .AddJsonFile(configSource, optional: true, reloadOnChange: true)
            .Build();

        // load configurations and setup connection pool accordingly
        throw new NotImplementedException();
    }
}
