```rust
use std::env;
use std::fs::{self, DirBuilder};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use simple_logger::SimpleLogger;

static LOGGER: SimpleLogger = SimpleLogger::new().with_level(log::LevelFilter::Info).init().unwrap();

struct MyDir {
    path: Arc<Mutex<PathBuf>>,
}

impl MyDir {
    fn new(path: PathBuf) -> Self {
        let my_dir_path = env::var("MY_DIR_PATH").unwrap_or_else(|_| "/tmp/my_dir".to_string());

        if fs::metadata(&my_dir_path).is_err() || !fs::read_dir(&my_dir_path).unwrap().next().is_some(){
            let dir = DirBuilder::new().recursive(true).create(my_dir_path).unwrap();
            LOGGER.info("Directory created: {}", &dir);
        } else {
            LOGGER.info("Existing directory found: {}", my_dir_path);
        }

        env::set_var("MY_DIR_PATH", dir.path().display().to_string());
        MyDir{ path: Arc::new(Mutex::new(PathBuf::from(my_dir_path))) }
    }

    fn cleanup(&self) {
        let _ = thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(10));
            if env::var("MY_DIR_PATH").is_none() && fs::metadata(&self.path).is_err(){
                LOGGER.info("Directory cleaned up: {}", &self.path);
            } else {
                LOGGER.error("Failed to cleanup directory: {}", &self.path);
            }
        });
    }
}
``` 

In this Rust code, the `MyDir` struct is created that represents a persistent working directory in your system. When you call the `new()` function, it will check if an environment variable `MY_DIR_PATH` is set and point to an existing directory or not. If the directory does not exist, it creates one at the specified location. It also sets the `MY_DIR_PATH` environment variable with this new directory path.

The `cleanup()` method starts a separate thread that checks every 10 seconds whether the environment variable is unset and if the directory still exists or not. If they both are true, it means that your program is no longer running and hence cleans up the directory by logging the action. Otherwise, it logs an error message stating why the cleanup operation failed.

