```C
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct NestedSubNode {
    char* str;
    float val;
} NestedSubNode;

typedef struct SubNode {
    char* str;
    double val;
    NestedSubNode* next_node;
} SubNode;

typedef struct Node {
    int value;
    SubNode* sub_node;
} Node;

#define MAX_LENGTH 100

Node* create_nodes(int num_nodes, int min_value, int max_value) {
     if (num_nodes <= 0 || min_value > max_value) return NULL;

    srand((unsigned int)time(NULL));
    Node* nodes = malloc(sizeof(Node) * num_nodes); 
    if (nodes == NULL) return NULL; // memory allocation failed

    for (int i = 0; i < num_nodes; ++i) {
        nodes[i].value = rand() % (max_value - min_value + 1) + min_value; 

        SubNode* sub_node = malloc(sizeof(SubNode));
        if (sub_node == NULL) return NULL; // memory allocation failed

        char* str = malloc(MAX_LENGTH + 1);
        if (str == NULL) return NULL; // memory allocation failed
        for (int j = 0; j < MAX_LENGTH; ++j) { 
            str[j] = 'a' + rand() % ('z'-'a'); 
        }
        str[MAX_LENGTH] = '\0'; 

        sub_node->str = str;
        sub_node->val = (double)rand() / (double)RAND_MAX; // random double value in [0,1)

        NestedSubNode* nested_sub_node = malloc(sizeof(NestedSubNode));
        if (nested_sub_node == NULL) return NULL; // memory allocation failed

        char* str2 = malloc(MAX_LENGTH + 1);
        if (str2 == NULL) return NULL; // memory allocation failed
        for (int j = 0; j < MAX_LENGTH; ++j) { 
            str2[j] = 'a' + rand() % ('z'-'a');
        }
        str2[MAX_LENGTH] = '\0'; 

        nested_sub_node->str = str2;
        nested_sub_node->val = (float)rand() / (float)RAND_MAX; // random float value in [0,1)

        sub_node->next_node = nested_sub_node;
        nodes[i].sub_node = sub_node;
    }

    return nodes;
}
```
