function FindElementsBySelector(rootNode, selector, testFunc) {
    const nodes = [];
    let stack = [rootNode];

    while (stack.length > 0) {
        let node = stack.pop();

        if (testFunc(node)) nodes.push(node);

        let children = Array.from(node.childNodes);
        for (let i = 0; i < children.length; ++i) {
            stack.push(children[i]);
        }
    }

    return nodes;
}
```

