```c
#include <stdio.h>
#include <pthread.h>

typedef struct resource_bundle {
    void *data;  // pointer to actual data in memory, type depends on format
    char *path;  // path to file
    int format;  // JSON or binary
} ResourceBundle;

ResourceBundle* load_resource(char* file_path, int format) {
    FILE *file = fopen(file_path, "rb");  // open the file in binary mode

    if (file == NULL) {
        printf("Error: Could not open file %s\n", file_path);
        return NULL;
    }

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));  // allocate memory for bundle

    bundle->data = NULL;
    bundle->format = format;
    bundle->path = strdup(file_path);  // deep copy of file path

    switch (format) {
        case FORMAT_JSON:
            bundle->data = load_json(file);
            break;
        case FORMAT_BINARY:
            bundle->data = load_binary(file);
            break;
        default:
            printf("Error: Unknown format\n");
            return NULL;
    }

    fclose(file);  // close the file

    if (bundle->data == NULL) {
        free(bundle->path);
        free(bundle);
        printf("Error: Could not load resource from %s\n", file_path);
        return NULL;
    }

    return bundle;
}
