    // Read the file into a buffer
    fseek(file, 0L, SEEK_END);
    long numbytes = ftell(file);
    char *buffer = (char *)calloc(numbytes + 1, sizeof(char)); 
    if(buffer == NULL) {
        return "{'status': 'error', 'message': 'Failed to allocate memory'}";
    }
    fseek(file, 0L, SEEK_SET);  
    fread(buffer, sizeof(char), numbytes, file);
    fclose(file);

    // Parse the JSON data using json-c library
    struct json_object *json = json_tokener_parse(buffer);
    free(buffer);
    if (json == NULL) {
        return "{'status': 'error', 'message': 'Failed to parse JSON'}";
