}

public interface IRepository<T> where T : class
{
    Task<IEnumerable<T>> ExecuteStoredProcAsync(string storedProcedureName, params object[] parameters);
}

public class Repository<T> : IRepository<T> where T : class
{
    private readonly MyDbContext _context;

    public Repository(MyDbContext context)
    {
        _context = context;
    }

    public async Task<IEnumerable<T>> ExecuteStoredProcAsync(string storedProcedureName, params object[] parameters)
    {
        // Validate input parameters to prevent SQL injection

        var result = await _context.MyCustomObjects
            .FromSqlRaw(storedProcedureName + " {0}", parameters)
            .ToListAsync();

        return result;
    }
}
