#[derive(Debug)]
pub struct Dir {
    path: PathBuf,
}

impl Dir {
    fn new() -> Self {
        let dir_path = env::var("MY_DIR_PATH")
            .unwrap_or_else(|_| "/tmp/my_dir".to_string());
        let path = PathBuf::from(dir_path);
        info::<PathBuf, _>(&format_args_1, &[&path], |v| v.into()) ;
        Dir { path }
    }

    fn check_and_create(&self) -> std::io::Result<()> {
        fs::create_dir_all(&self.path)?;
        Ok(())
    }

    fn cleanup(&self, interval: Duration) {
        let mut should_stop = false;

        thread::spawn(move || loop {
            if should_stop {
                break;
            }

            info::<Duration, _>(&format_args_2, &[&interval], |v| v.into()) ;
            thread::sleep(interval);

        });
    }
}
