DependencyManager:
```javascript
class DependencyManager {
  constructor() {
    this.resolvedDependencies = new Set();
  }

  async resolveDependencies(module) {
    if (this.resolvedDependencies.has(module)) return; // avoid resolving the same dependency twice

    await Promise.all(Object.values(module.dependencies).map(async (dependency) => {
      const resolvedDependency = require(dependency); // Resolve dependencies recursively
      this.resolvedDependencies.add(resolvedDependency);

      return this.resolveDependencies(resolvedDependency);
    }));
  }
}
```
TIFF Parser:
```c
#include <stdio.h>
#include <tiffio.h>

typedef struct {
  uint16 bps; /* bits per sample */
  uint16 spp; /* samples per pixel */
  uint32 num_samples;
} TIFFInfo;

TIFFInfo parse_tiff(char *filename) {
    TIFF* tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Could not open file %s\n", filename);
        exit(1);
    }

    TIFFInfo info;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &info.bps);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &info.spp);

    /* calculate number of samples */
    info.num_samples = spp * bps;

    return info;
}
```
