Here's an example of the `StringHasher` class that meets your specifications in C#:

```csharp
using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Serilog;

public class StringHasher
{
    private readonly LoggerConfiguration _loggerConfig;

    public enum HashAlgorithmType { MD5, SHA256, Custom }

    public StringHasher(LoggerConfiguration loggerConfig)
    {
        this._loggerConfig = loggerConfig;
    }

    public string ComputeHash(string inputString, HashAlgorithmType hashAlgorithmType)
    {
        switch (hashAlgorithmType)
        {
            case HashAlgorithmType.MD5:
                return CreateMD5(inputString);
            case HashAlgorithmType.SHA256:
                return CreateSha256(inputString);
            default: // Custom algorithm
                throw new NotImplementedException("Custom hashing algorithm not implemented yet.");
        }
    }

    public string[] ComputeHashInParallel(string[] inputStrings, HashAlgorithmType hashAlgorithmType)
    {
        return ParallelEnumerable.AsParallel(inputStrings).Select(str => ComputeHash(str, hashAlgorithmType)).ToArray();
    }

    public void ValidateHashes(string[] originalHashes, string[] calculatedHashes)
    {
        if (originalHashes.Length != calculatedHashes.Length)
            throw new ArgumentException("Original and Calculated Hashes must be of same length.");

        for (int i = 0; i < originalHashes.Length; i++)
        {
            if (!string.Equals(originalHashes[i], calculatedHashes[i]))
                throw new InvalidDataException($"Hash mismatch at index: {i}");
        }
    }

    private string CreateMD5(string inputString)
    {
        using (var md5 = MD5.Create())
            return GetHashString(md5, inputString);
    }

    private string CreateSha256(string inputString)
    {
        using (var sha256 = SHA256.Create())
            return GetHashString(sha256, inputString);
    }

    private string GetHashString(HashAlgorithm hashAlgorithm, string inputString)
    {
        var bytes = Encoding.UTF8.GetBytes(inputString);
        var byteResult = hashAlgorithm.ComputeHash(bytes);
        return BitConverter.ToString(byteResult).Replace("-", "").ToLowerInvariant();
    }
}
```

