```javascript
const { require } = global; // Node's require module to load modules dynamically 
const blueslip = require('blueslip'); // Mocking library, assuming it has been installed and required in advance.
const mocha = require('mocha'); // Assuming Mocha is used as the test framework.

async function runTestsAsync(moduleLabel, testSuite) {
    let module;
    try {
        module = await blueslip.import(moduleLabel);
    } catch (error) {
        console.log('Failed to load module', error);
        return;
    }

    const mochaInstance = new mocha({ bail: true }); // Bail ensures that on the first failed test, Mocha stops and returns control flow to this function.

    for(const test of testSuite) {
        try {
            await test(moduleLabel, async () => {
                await blueslip.resetMock(); // Reset mocked objects before each test.
                return module;
            });
            console.log('Test', test.name, 'succeeded');
        } catch (error) {
            console.warn('Test', test.name, 'failed with error:', error);
        } finally {
            blueslip.verify(); // Ensure that all expectations are met.
        }
    }

    try {
        await mochaInstance.run();
        console.log('All tests have passed successfully');
    } catch (error) {
        console.warn(`Tests failed with error: ${error}`);
    } finally {
        blueslip.restore(); // Reset the mocking library for next run.
    }
}
```

