```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.IO;

public class DatabaseInteractor {
    private SqlConnection connection = new SqlConnection("your_connection_string");

    public DataTableReader ExecuteQueryAndReturnReader(byte[] query) {
        string sqlCommandText = ConvertByteArrayToUTF8String(query);

        try {
            // Open the SQL connection.
            this.connection.Open();

            // Create a new command and pass in our query.
            SqlCommand command = new SqlCommand(sqlCommandText, this.connection);

            // Execute the command and return the DataReader.
            using (SqlDataReader reader = command.ExecuteReader()) {
                return reader;
            }
        } catch (Exception ex) {
            Console.WriteLine("Error executing query: " + ex.Message);
        } finally {
            // Always close your connection when done.
            this.connection.Close();
        }

        return null;
    }

    private string ConvertByteArrayToUTF8String(byte[] byteArray) {
        using (MemoryStream memoryStream = new MemoryStream(byteArray)) {
            using (StreamReader reader = new StreamReader(memoryStream, System.Text.Encoding.UTF8)) {
                return reader.ReadToEnd();
            }
        }
    }
}
```
