Below is a basic framework for such a function in JavaScript using Fetch API for data fetching from external sources and `<script>` element creation with dynamic attributes. The caching mechanism is very rudimentary and needs refining depending on the real use case, same goes to retries and backoff strategies.

```javascript
class FooterScriptLoader {
    constructor() {
        this.cache = {}; // Simple caching mechanism for API responses
        this.scripts = []; // Array of created script elements
        this.logger; // External logger instance
    }

    setLogger(logger) {
        this.logger = logger;
    }

    fetchScripts() {
        const url = "external_api_endpoint";

        if (this.cache[url]) return Promise.resolve(this.cache[url]);

        return fetch(url)
            .then((response) => response.json())
            .then((data) => { 
                this.cache[url] = data;
                return data;
            })
            .catch((err) => {
                this.logger?.error("Failed to fetch scripts", err);
                throw err;
            });
    }

    createScript(attrs) {
        const script = document.createElement('script');

        for (let attr in attrs) {
            if (!['async', 'defer', 'src', 'type'].includes(attr)) continue; // Skip unsupported attributes

            script[attr] = attrs[attr];
        }

        document.body.appendChild(script); // Append to body or where you want the scripts
        this.scripts.push(script);
    }

    removeScript(index) {
        const [script] = this.scripts.splice(index, 1);

        if (script?.parentNode) script.parentNode.removeChild(script); // Remove from DOM
    }

    updateScript(index, attrs) {
        const script = this.scripts[index];
        for (let attr in attrs) {
            if (!['async', 'defer', 'src', 'type'].includes(attr)) continue; // Skip unsupported attributes

            script[attr] = attrs[attr];
        }
    }

    loadScripts() {
        this.fetchScripts().then((scripts) => scripts.forEach((script) => this.createScript(script)));
    }
}
```
This is a minimal, abstract version of the script loading logic. In a real-world application, you would probably need to fine tune it further according to your specific use case and requirements: add caching mechanisms for scripts themselves; add more complex error handling strategies with retries etc. Please note that this function doesn't handle script dependencies and order - these are advanced topics which require careful consideration especially in real-world applications.

