```java
import org.apache.commons.codec.binary.Base64;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import java.nio.ByteBuffer;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.InvalidKeySpecException;
import java.util.*;

public class RandomStringGenerator {
    private static final int ITERATIONS = 1024;
    private static final int KEY_LENGTH = 256;
    private String passwordCharacterSetAPI = "http://example.com/api";

    public String getRandomString(byte[] salt, String password, int length) {
        SecureRandom random;

        if (salt != null && salt.length > 0) {
            random = new SecureRandom(salt);
        } else {
            random = new SecureRandom();
        }

        char[] chars = getAllowedCharacters().toCharArray();
        StringBuilder stringBuilder = new StringBuilder(length);

        for (int i = 0; i < length; i++) {
            stringBuilder.append(chars[random.nextInt(chars.length)]);
        }

        return hashPassword(stringBuilder.toString(), password, random).toString();
    }

    private String getAllowedCharacters() {
        // Replace this with actual API call and character set retrieval
        return "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz1234567890";
    }

    private String hashPassword(String password, String salt, SecureRandom random) {
        char[] chars = password.toCharArray();

        PBEKeySpec spec = new PBEKeySpec(chars, salt.toCharArray(), ITERATIONS, KEY_LENGTH);
        SecretKeyFactory skf;

        try {
            skf = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
            Base64 base64 = new Base64();

            return base64.encodeToString(skf.generateSecret(spec).getEncoded());
        } catch (NoSuchAlgorithmException | InvalidKeySpecException e) {
            throw new AssertionError("Error hashing password: " + e.getMessage(), e);
        } finally {
            spec.clearPassword();
        }
    }
}
```
