    vector<Node*> next;
};

// The recursive function that performs traversal
vector<int> findStates(Node* root, const string& selector) {
    if (!root) return {};

    vector<int> states;
    if (testSelector(root->state, selector))
        states.push_back(root->state);

    for (auto next : root->next) {
        auto newStates = findStates(next, selector);
        states.insert(states.end(), newStates.begin(), newStates.end());
    }

    return states;
}
