```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.IO;
using System.Net.Http;
using System.Xml.XPath;
using System.Xml.Schema;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json;
using Serilog;

public class MyClass
{
    private readonly HttpClient _client = new HttpClient();
    private static readonly MemoryCache cache = new MemoryCache(new MemoryCacheOptions());

    public async Task<XPathNavigator> GetXmlElementAsync(string xmlUri, string elementName)
    {
        var watch = System.Diagnostics.Stopwatch.StartNew();

        if (!cache.TryGetValue(xmlUri, out string xmlContent))
        {
            Log.Information("Cache miss for {0}", xmlUri);
            xmlContent = await _client.GetStringAsync(xmlUri);

            var settings = new XmlReaderSettings() 
            { 
                Async = true, 
                ConformanceLevel = ConformanceLevel.Fragment 
            };

            using (var reader = XmlReader.Create(new StringReader(xmlContent), settings))
            {
                while (await reader.ReadAsync())
                {
                    if (reader.NodeType == XmlNodeType.Element)
                    {
                        Log.Information("Reading XML");
                    }
                }
            }

            var schemaSet = new XmlSchemaSet();
            schemaSet.Add(null, await _client.GetStreamAsync("schema-uri")); // Fetch and validate against provided schemas

            var xmlDoc = new XPathDocument(new StringReader(xmlContent), settings);
            xmlDoc.Validate(schemaSet, (o, e) => Log.Error(e.Message)); // Log schema validation results

            cache.Set(xmlUri, xmlContent, TimeSpan.FromHours(1)); // Store in cache
        }

        watch.Stop();
        Log.Information("Query execution time: {0} ms", watch.ElapsedMilliseconds);

        var navigator = xmlDoc.CreateNavigator();
        var iterator = navigator.Select(elementName);

        if (!iterator.MoveNext())
            throw new Exception("No matching element found");

        if (iterator.Current != null && iterator.MoveNext()) // Check for multiple matches
            throw new Exception("Multiple matching elements found");

        return iterator.Current;
    }
}
