function asyncReduce(array, initialValue, callback) {
    return new Promise((resolve, reject) => {
        const reducer = (accumulator, currentValue, index, array) => {
            if (index === array.length - 1) {
                resolve(accumulator);
            } else {
                setImmediate(() => reducer(callback(accumulator, currentValue), array[index + 1], index + 1, array));
            }
        };
        reducer(initialValue, array[0], 0, array);
    });
}
