```javascript
const CACHE_KEY = 'scriptsCache';
const RETRY_INTERVAL = 2000; // retry interval in ms
const MAX_RETRIES = 5;

function fetchScript(script, onSuccess, onError) {
    const scriptElement = document.createElement('script');
    if (script.src) {
        scriptElement.src = script.src;
    }
    if (script.type) {
        scriptElement.type = script.type;
    } else {
        scriptElement.type = 'text/javascript';
    }
    scriptElement.async = script.async || false;

    const errorCallback = () => {
        onError('Script load failed: ' + script.src);
    };

    scriptElement.onload = () => {
        onSuccess(script.src);
    }

    scriptElement.onerror = errorCallback;
    document.head.appendChild(scriptElement);
}

function loadScriptsWithRetry(scripts, currentIndex = 0, numTries = 1) {
    if (currentIndex === scripts.length) return; // done loading all scripts

    const script = scripts[currentIndex];
    let cacheEntry = JSON.parse(localStorage.getItem(CACHE_KEY)) || {};

    fetchScript(script, () => {
        cacheEntry[script.src] = true; // mark as loaded in local cache
        localStorage.setItem(CACHE_KEY, JSON.stringify(cacheEntry));
        loadScriptsWithRetry(scripts, currentIndex + 1);
    }, (error) => {
        if (numTries >= MAX_RETRIES) {
            console.error(`Failed to load script after ${MAX_RETRIES} attempts: ${script.src}, Error: ${error}`);
            return;
        }

        setTimeout(() => {
            loadScriptsWithRetry(scripts, currentIndex, numTries + 1); // retry
        }, RETRY_INTERVAL * numTries);
    });
}

function fetchAndLoadScripts(scripts) {
    const cacheEntry = JSON.parse(localStorage.getItem(CACHE_KEY)) || {};
    const scriptsToFetch = [];

    // check which scripts are already loaded in local storage and should not be fetched again
    for (let i = 0; i < scripts.length; i++) {
        if (!cacheEntry[scripts[i].src]) {
            scriptsToFetch.push(scripts[i]);
        }
    }

    loadScriptsWithRetry(scriptsToFetch);
}
```
