from flask import Flask, render_template, request, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, logout_user, current_user, login_required
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config['SECRET_KEY'] = 'my-secret-key'  # Replace with your secret key
login_manager = LoginManager(app)
login_manager.login_view = 'login'

class User(UserMixin):
    def __init__(self, id, username, password):
        self.id = id
        self.username = username
        self.password = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password, password)

# Normally you'd fetch these from a database or some external source. 
users = [User(1, 'user1', 'pass'), User(2, 'user2', 'pass')]
username_table = {u.username: u for u in users}

@login_manager.user_loader
def load_user(user_id):
    return username_table.get(user_id)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        # Process registration form data here, then create a new User object and add it to `users`
        username = request.form['username']
        password = request.form['password']

        users.append(User(len(users) + 1, username, password))
        return redirect(url_for('login'))
    else:
        return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        # Process login form data here, then get the User object from `users` and log them in with Flask-Login
        username = request.form['username']
        password = request.form['password']

        user = username_table.get(username)
        if user is not None and user.check_password(password):
            login_user(user)
            return redirect(url_for('home'))
    else:
        return render_template('login.html')

@app.route('/logout', methods=['GET'])
def logout():
    # Log out the current user with Flask-Login
    logout_user()
    return redirect(url_for('home'))

@app.route('/')
def home():
    if current_user.is_authenticated:
        return render_template('home.html', username=current_user.username)
    else:
        return render_template('home.html')
