namespace fs = std::filesystem;

class TokenProcessor {
public:
    void processFiles(const std::vector<std::string>& filenames) {
        for (auto& filename : filenames) {
            fileProcessingThreads.emplace_back(&TokenProcessor::processFile, this, filename);
        }

        for (auto& thread : fileProcessingThreads) {
            thread.join();
        }
    }

private:
    void processFile(const std::string& filename) {
        if (!fs::exists(filename)) {
            logging::trivial::error("The specified file does not exist");
            return;
        }

        // Reading large JSON files chunk by chunk is a good idea for performance.
        std::ifstream inputFileStream(filename);
        std::string jsonChunk, line;
        while (std::getline(inputFileStream, line)) {
            jsonChunk += line;

            // Assuming each JSON object in the file is separated by a new line.
            Document document;
            if (!document.Parse(jsonChunk.c_str()).HasParseError()) {
                processJsonDocument(document);

                // Clear json chunk after processing.
                jsonChunk.clear();
            }
        }

        inputFileStream.close();
    }

    void processJsonDocument(const Document& document) {
        // Check if required fields exist in the JSON object. 
        if (document.HasMember("access_token") && document.HasMember("expires_in") && document["expires_in"].IsInt() && document["expires_in"].GetInt() > 0 &&
            document.HasMember("token_type") && document["token_type"].IsString()) {

            // If refresh_token exists, check it too.
            if (document.HasMember("refresh_token")) {
                // Processing logic for access_token and optional fields here...
            }
        } else {
            logging::trivial::error("Invalid JSON format");
        }
    }

    std::vector<std::thread> fileProcessingThreads;
};
