```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "jansson.h"

typedef struct Review {
    int rating;
    char *comment;
    struct Review *next;
} Review;

typedef struct Product {
    char *name;
    double price;
    Review *reviews;
} Product;

Product* create_product(char *name, double price) {
    if (price < 0 || name == NULL) return NULL;

    Product *newProd = malloc(sizeof(Product));
    newProd->name = strdup(name);
    newProd->price = price;
    newProd->reviews = NULL;

    return newProd;
}

void add_review(Product *product, int rating, char *comment) {
    if (rating < 1 || rating > 5 || comment == NULL || product == NULL) return;

    Review *newReview = malloc(sizeof(Review));
    newReview->rating = rating;
    newReview->comment = strdup(comment);
    newReview->next = product->reviews;

    product->reviews = newReview;
}

double average_review(Product *product) {
    if (product == NULL || product->reviews == NULL) return -1.0;

    int count = 0;
    double sum = 0.0;

    for (Review *r = product->reviews; r != NULL; r = r->next) {
        sum += r->rating;
        count++;
    }
    return (count > 0) ? sum / count : 0.0;
}

void serialize_to_json(Product *product, FILE *f){
    if(product == NULL || f == NULL) return;

    json_t *obj = json_object();
    json_object_set_new(obj, "name", json_string(product->name));
    json_object_set_new(obj, "price", json_real(product->price));

    json_t *reviews = json_array();
    for (Review *r = product->reviews; r != NULL; r = r->next) {
        json_t *review = json_object();
        json_object_set_new(review, "rating", json_integer(r->rating));
        json_object_set_new(review, "comment", json_string(r->comment));

        json_array_append_new(reviews, review);
    }

    json_object_set_new(obj, "reviews", reviews);

    json_dumpf(obj, f, JSON_INDENT(4) | JSON_COMPACT);
}

void destroy_product(Product *product){
    if (product == NULL) return;

    free(product->name);
    Review *r = product->reviews;

    while(r != NULL) {
        Review *tmp = r;
        r = r->next;

        free(tmp->comment);
        free(tmp);
    }

    free(product);
}
```

