        String randomString = generateRandomString(characterSet, length);
        String hashedPassword = hashPassword(password.toCharArray(), Base64.getDecoder().decode("your_salt")); // Replace "your_salt" with your actual salt

        return new String[] {randomString, hashedPassword};
    }

    public static String generateRandomString(String characterSet, int length) {
        Random random = new SecureRandom();
        char[] result = new char[length];
        for (int i = 0; i < length; ++i) {
            result[i] = characterSet.charAt(random.nextInt(characterSet.length()));
        }

        return new String(result);
    }

    public static String hashPassword( char[] password, byte[] salt ) throws NoSuchAlgorithmException, InvalidKeySpecException {
        PBEKeySpec spec = new PBEKeySpec(password, salt, 1000, 256 * 8);
        SecretKeyFactory skf = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");

        return Base64.getEncoder().encodeToString(skf.generateSecret(spec).getEncoded());
    }
}
```
Please note: 
- Make sure you replace `"your_salt"` with your actual salt in the Java code.
