#include <stdlib.h>
#include <string.h>
#include <jansson.h>  /* For JSON serialization */

/* Structure for Review node in linked list */
typedef struct review {
    double rating;
    char* text;
    struct review* next;
} Review;

/* Structure for Product structure */
typedef struct product {
    char* name;
    double price;
    Review* reviews;
    int num_reviews;
} Product;

Product* create_product(const char* name, double price) {
    if (name == NULL || price < 0.0) {
        fprintf(stderr, "Invalid product creation parameters\n");
        return NULL;
    }

    Product* new_product = malloc(sizeof(Product));
    if (!new_product) {
        perror("Failed to allocate memory for product");
        exit(EXIT_FAILURE);
    }

    new_product->name = strdup(name);
    new_product->price = price;
    new_product->reviews = NULL;
    new_product->num_reviews = 0;

    return new_product;
}

void add_review(Product* product, double rating, const char* text) {
    if (product == NULL || rating < 1.0 || rating > 5.0 || text == NULL) {
        fprintf(stderr, "Invalid review parameters\n");
        return;
    }

    Review* new_review = malloc(sizeof(Review));
    if (!new_review) {
        perror("Failed to allocate memory for review");
        exit(EXIT_FAILURE);
    }

    new_review->rating = rating;
    new_review->text = strdup(text);
    new_review->next = product->reviews;
    product->reviews = new_review;
    product->num_reviews++;
}

double average_rating(Product* product) {
    if (product == NULL || product->num_reviews == 0) return 0.0;

    double sum = 0.0;
    Review* current = product->reviews;
    while (current != NULL) {
        sum += current->rating;
        current = current->next;
    }

    return sum / product->num_reviews;
}
```
In the above code, we define a `Review` structure as a node in a linked list. Each product can have zero or more reviews, which are stored as a linked list. The `create_product` function creates a new product with a given name and price, and the `add_review` function adds a review to an existing product. 

