#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

EVP_CIPHER_CTX* create_aes_context(int key_size, const char* cipher_name, const unsigned char* salt) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        /* Error handling */
        return NULL;
    }

    int cipher_type = 0;
    const EVP_CIPHER *cipher;
    if (!strcmp(cipher_name, "aes-128-gcm")) {
      cipher = EVP_aes_128_gcm(); 
    } else if (!strcmp(cipher_name, "aes-192-cbc")) {
      cipher = EVP_aes_192_cbc();
    } else if (!strcmp(cipher_name, "aes-256-gcm")) {
      cipher = EVP_aes_256_gcm(); 
    } else {
        /* Error handling */
        return NULL;
    }

    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];

    if (!RAND_bytes(key, key_size/8) || !RAND_bytes(iv, EVP_CIPHER_CTX_iv_length(ctx))) {
        /* Error handling */
        return NULL;
    }

    if (salt && !EVP_BytesToKey(cipher, EVP_sha256(), salt, key, key_size/8, 1, iv, EVP_CIPHER_CTX_iv_length(ctx))) {
        /* Error handling */
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        /* Error handling */
        return NULL;
    }

    return ctx;
}
```

The function `create_aes_context` creates a new EVP_CIPHER_CTX context with the specified cipher mode and size. It also generates a random key and IV, and optionally derives them from a salt. If any of these steps fail, it returns NULL and the caller is responsible for checking the return value and handling errors appropriately.

