public class FileHashCalculator {

    private static final Logger logger = LogManager.getLogger(FileHashCalculator.class);

    private Map<String, String> cacheMap = new ConcurrentHashMap<>();

    public FileHashCalculator() {
        Configurator.initialize("log4j2", "config/log4j2.xml");  // Setup log4j configuration from XML file.
    }

    public String calculateMD5(String filename) throws IOException {
        if (cacheMap.containsKey(filename)) {
            logger.debug("Cache hit for {}", filename);
            return cacheMap.get(filename);  // If hash is already computed, return from cache map.
        }

        String md5 = DigestUtils.md5Hex(new FileInputStream(filename));  // Calculate MD5 hash.
        cacheMap.put(filename, md5);  // Store the result in the cache.

        logger.info("MD5 Hash for file {} is: {}", filename, md5);
        return md5;
    }

    public void cleanupOldLogs() {
        File logDirectory = new File(System.getProperty("logPath"));  // Get path from system properties set by log4j2 configuration.
        try {
            FileUtils.cleanDirectory(logDirectory);  // Clean old logs without deleting the directory itself.
            logger.info("Old logs cleaned successfully");
        } catch (IOException e) {
            logger.error("Failed to clean up old logs", e);
        }
    }

    public void compareWithExternalAPI(String hash) {
        // Implement your external API call here, then compare the received hash with provided one.
        // Log the results of the comparison.
    }
}
