using System;
using System.Threading;
using System.Collections.Concurrent;
using System.IO;
using System.Net;
using Amazon.S3;
using Amazon.S3.Model;

public class MediaAssetManager : IDisposable
{
    private AmazonS3Config s3Config;
    private IAmazonS3 client;
    private readonly ConcurrentQueue<UploadRequest> _uploadQueue = new ConcurrentQueue<UploadRequest>();

    public MediaAssetManager(string accessKey, string secretKey) 
    {
        this.s3Config = new AmazonS3Config
        {
            RegionEndpoint = Amazon.RegionEndpoint.USWest2 // Or wherever your bucket is
        };

        this.client = new AmazonS3Client(accessKey, secretKey, s3Config);
    }

    public async Task<UploadResult> UploadAsync(string bucketName, string key, Stream stream) 
    {
        var request = new PutObjectRequest()
        {
            BucketName = bucketName,
            Key  = key,
            InputStream = stream
        };

        try
        {
            await client.PutObjectAsync(request);
            return new UploadResult(true); // Successful upload
        }
        catch (AmazonS3Exception s3Exception) 
        {
            if (s3Exception.ErrorCode != null && (s3Exception.ErrorCode.Equals("RequestTimeout") || s3Exception.ErrorCode.Equals("InternalError")))
            {
                // Retry the request
                return await UploadAsync(bucketName, key, stream);
            }

            return new UploadResult(false, s3Exception.Message); // Error occurred during upload
        }
    }

    public void Dispose() 
    {
        client.Dispose();
    }
}
```

