public class NetworkService {
    private static final Logger logger = Logger.getLogger(NetworkService.class.getName());
    private AsynchronousSocketChannel channel;
    private ByteBuffer buffer;

    public void connectToServer() throws IOException {
        InetSocketAddress hostAddress = new InetSocketAddress("localhost", 4000);

        channel = AsynchronousSocketChannel.open();
        channel.connect(hostAddress).get(); // blocks until connection established or failed
    }

    public void handleServerConnection() {
        try {
            connectToServer();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to connect to server: ", e);
        }

        // Keep trying to reconnect if failed
        while(!channel.isOpen()){
            try{
                Thread.sleep(5000);
                connectToServer();
            } catch (InterruptedException | IOException ex) {
                logger.log(Level.SEVERE, "Failed to sleep: ", ex);
            }
        }

        // Handle server communication once connected here...
    }
}
