    private $throttleSvc;
    private $cacheSvc;

    function __construct() {
        $this->db = new DatabaseManager();
        $this->notificationSvc = new ExternalNotificationService();
        $this->throttleSvc = new ThrottlingService();
        $this->cacheSvc = new CacheService();
    }

    public function processClinicUpdates($updates, $userId) {
        // Start transaction
        $this->db->beginTransaction();

        try{
            foreach ($updates as $clinicId => $newStatus) {
                // Check if clinic exists
                $this->db->checkClinicExists($clinicId);

                // Throttle updates
                $this->throttleSvc->throttleUpdate($userId, $clinicId);

                // Get the old status
                $oldStatus = $this->db->getClinicStatus($clinicId);

                // Update clinic status
                $this->db->updateClinicStatus($clinicId, $newStatus);

                // Log update
                $this->db->logUpdate($userId, $oldStatus, $newStatus);

                // Invalidate cache for clinic status
                $this->cacheSvc->invalidateClinicCache($clinicId);
            }

            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollback();
            throw new Exception("Failed to update clinic statuses: " . $e->getMessage());
        }

        // Send notifications
