        if (file_put_contents($this->storagePath . '/' . $filename, $fileContent)) {
            return true;
        } else {
            throw new Exception('Failed to upload the file.');
        }
    }

    public function downloadFile($filename) {
        $filepath = $this->storagePath . '/' . $filename;
        if (file_exists($filepath)) {
            $content = file_get_contents($filepath);
            return $content ?: '';
        } else {
            throw new Exception('File does not exist.');
        }
    }

    public function listFiles() {
        $filesList = scandir($this->storagePath);
        if (is_array($filesList)) {
            $filteredFiles = array_filter($filesList, function ($file) {
                return !in_array($file, ['.', '..']);  // Remove . and .. from the list
            });
            return $filteredFiles;
        } else {
            throw new Exception('Failed to get files list.');
        }
    }

    public function deleteFile($filename) {
        $filepath = $this->storagePath . '/' . $filename;
        if (file_exists($filepath)) {
            if (!unlink($filepath)) {
                throw new Exception('Failed to delete the file.');
            }
        } else {
            // Ignore this error, as it might occur when the file doesn't exist
        }
    }

    public function renameFile($oldFilename, $newFilename) {
        $oldPath = $this->storagePath . '/' . $oldFilename;
        $newPath = $this->storagePath . '/' . $newFilename;

        if (file_exists($oldPath)) {
            if (file_exists($newPath)) {
                throw new Exception('New filename already exists.');
            } else {
                if (!rename($oldPath, $newPath)) {
                    throw new Exception('Failed to rename the file.');
                }
            }
        } else {
            throw new Exception('Old filename does not exist.');
        }
    }
}
```
