import com.amazonaws.auth.DefaultAWSCredentialsProviderChain;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3ClientBuilder;
import com.amazonaws.services.s3.model.*;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

public class FileTransferManager {
    private final AmazonS3 s3 = AmazonS3ClientBuilder.standard()
            .withCredentials(new DefaultAWSCredentialsProviderChain())
            .build();

    private final int DEFAULT_CHUNK_SIZE = 5 * 1024 * 1024; // 5MB chunk size
    private final List<String> cachedFiles = new ArrayList<>(); // local cache for frequently accessed files.

    public void startSyncTransfer(File directory, String bucketName) {
        File[] files = directory.listFiles();

        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    // Recursively process sub-directories
                    startSyncTransfer(file, bucketName);
                } else {
                    // Check cache before making API call to S3
                    if (!cachedFiles.contains(file.getName())){
                        cachedFiles.add(file.getName());

                        System.out.println("Uploading " + file.getName() + " to S3 bucket " + bucketName);
                        PutObjectRequest request = new PutObjectRequest(bucketName, file.getName(), file)
                            .withChunkedTransfer(true) // Enable multipart upload for large files.
                            .withChunkSize(DEFAULT_CHUNK_SIZE); 

                        s3.putObject(request); // Upload the file to S3 bucket
                    } else {
                        System.out.println("Using cached version of " + file.getName());

                        GetObjectRequest rangeObjectRequest = new GetObjectRequest(bucketName, file.getName());
                        s3.getObject(rangeObjectRequest, new File(file.getAbsolutePath())); // Download the file from S3 bucket to local directory
                    }
                }
            }
        } else {
            System.out.println("No files found in the specified directory.");
        }
    }
}
