class ScriptManager {
    constructor() {
        this.cache = {};
        this.scripts = [];
    }

    async loadScripts(apiUrl) {
        try {
            const response = await fetch(apiUrl);
            if (response.ok) {
                const scriptsData = await response.json();
                for (const script of scriptsData) {
                    if (!this.cache[script.src]) { // only load new scripts, cache others
                        this.scripts.push(`<script key=${Math.random()} src="${script.src}"></script>`);
                        this.cache[script.src] = true;
