            }
        } catch (err) {
            console.log('Error: ', err);
        }
    }

    renderScripts() {
        const scriptTags = this.scripts.join('\n');
        return `<div>${scriptTags}</div>`;
    }

    // Add error handling, logging and other necessary features here...
}
