<?php
// Function to generate a secure random string of a specified length using given character set
function generateSecureRandomString($length = 10, $charset = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ') {
    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $index = random_int(0, strlen($charset) - 1);
        $randomString .= $charset[$index];
    }

    return $randomString;
}

// Function to hash a password with customizable algorithm and salting
function hashPassword($password, $algorithm = PASSWORD_DEFAULT) {
    $salt = generateSecureRandomString(); // Generate unique salt for each password
    return password_hash($password . $salt, $algorithm); // Add salt to password before hashing
}
?>
