public class ImageResizer {
    // Define your JNI functions here to call C++ functions

    static {
        System.loadLibrary("your_jni");
    }

    private native long startTimer();
    private native double stopTimer(long startTime);
    private native void resizeImage(String inputFile, String outputFile, int width, int height, ProgressCallback callback);

    public interface ProgressCallback {
        void onProgressUpdate(double progress);
    }

    public void processImages(String directoryPath, String outputFile) throws IOException {
        Path dir = Paths.get(directoryPath);

        // Validate the command line options and input file paths
        if (!Files.isDirectory(dir)) {
            throw new IllegalArgumentException("Invalid directory path");
        }

        Files.walkFileTree(dir, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                String filename = file.getFileName().toString();

                // Check if the file is an image file to exclude specific formats
                if (filename.endsWith(".svg") || filename.endsWith(".psd")) {
                    return FileVisitResult.CONTINUE;
                }

                long startTime = startTimer();

                resizeImage(file.toString(), outputFile, 800, 600, new ProgressCallback() {
                    @Override
                    public void onProgressUpdate(double progress) {
                        System.out.println("Resizing progress: " + progress);
                    }
                });

                double elapsedTime = stopTimer(startTime);
                System.out.println("Elapsed time for resizing image " + filename + ": " + elapsedTime + "ms");

                return FileVisitResult.CONTINUE;
            }
        });
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: java ImageResizer <directoryPath> <outputFile>");
            return;
        }

        String directoryPath = args[0];
        String outputFile = args[1];

        try {
            new ImageResizer().processImages(directoryPath, outputFile);
        } catch (IOException e) {
            System.err.println("An error occurred while processing images: " + e.getMessage());
        }
    }
}
