struct Result {
    string data;
    chrono::time_point<chrono::system_clock> timestamp;
};

static map<string, Result> cacheMap;

Result getCachedData(string key) {
    if (cacheMap.find(key) == cacheMap.end()) return {"", chrono::system_clock::now()};
    else return cacheMap[key];
}

void setCacheData(string key, string data) {
    Result r;
    r.data = data;
    r.timestamp = chrono::system_clock::now();
    cacheMap[key] = r;
}

void backgroundCommandExecution(string cmd) {
    pid_t childPIDorZero = fork();

    if (childPIDorZero == 0) { // Child process
        execl("/bin/sh", "sh", "-c", cmd.c_str(), (char *) NULL);
        _exit(127);  // exec failed, use the error code 127
    } else if (childPIDorZero < 0) {
        cout << "Forking child process failed" << endl;
    } else {
        int status = 0;
        waitpid(childPIDorZero, &status, 0); // Wait for the child process to finish
        if (WIFEXITED(status))
            cout << "Child exited with status: " << WEXITSTATUS(status) << endl;
        else if (WIFSIGNALED(status))
            cout << "Child terminated by signal: " << WTERMSIG(status) << endl;
    }
}

