Here is a high-level implementation in Java using Spring's `@Async` for parallel processing and `ServiceLoader` for loading rule plugins dynamically:

```java
import org.springframework.scheduling.annotation.Async;
import java.io.*;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.stream.Stream;

public class FileProcessor {
    private final Executor executor;

    public FileProcessor(Executor executor) {
        this.executor = executor;
    }

    @Async("fileProcessingExecutor")
    public void processFileBatchWithValidation(String inputDirectory, String outputDirectory, List<Class<? extends Rule>> validationRulesClasses) throws IOException {
        File[] files = new File(inputDirectory).listFiles();

        if (files != null) {
            Stream.of(files)
                .parallel()
                .forEach((file -> validateFile(file, outputDirectory, validationRulesClasses)));
        }
    }

    private void validateFile(File file, String outputDirectory, List<Class<? extends Rule>> validationRuleClasses) {
        // Load and instantiate validation rules using reflection
        ServiceLoader<Rule> serviceLoader = ServiceLoader.load(Rule.class);

        for (Rule rule : serviceLoader) {
            if (validationRuleClasses.contains(rule.getClass())) {
                try {
                    BufferedReader reader = new BufferedReader(new FileReader(file));

                    // Validate file contents against the loaded validation rules
                    String line;
                    while ((line = reader.readLine()) != null) {
                        rule.validate(line);
                    }

                    reader.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        // Write validated file to output directory
        try {
            Files.move(file.toPath(), new File(outputDirectory + "/" + file.getName()).toPath());
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```
