    try:
        if cache.currsize >= (0.8 * cache.maxsize):  # If the cache is more than 80% full
            refresh_cache()  # Refresh transactions
        transaction_id = make_payment(payment)  # Make payment using PayPal API
        cache[transaction_id] = 'pending'  # Cache the transaction while it is being processed
    except Exception as e:
        logging.error('Failed to process payment', exc_info=True)
        return {'status': 'failed', 'message': str(e)}, 500
    else:
        return {'transactionId': transaction_id, 'status': 'success'}, 200

@retry(Exception, delay=1, backoff=2, max_delay=60)  # Retry mechanism with exponential backoff
