    payment = pp.Payment({...})  # Configure your PayPal payment here
    if payment.create():  # If the transaction is successful
        return payment.id
    else:
        raise Exception('Failed to create a payment')

def refresh_cache():
    for transaction_id, status in cache.items():
        try:
            pp.Payment.find(transaction_id)  # Retrieve the transaction from PayPal API
            if pp.Payment.state == 'processed':
                cache[transaction_id] = 'success'
            else:
                cache[transaction_id] = 'pending'
