    cached_data = cache.get(location)
    if cached_data:
        app.logger.info('Serving data from cache for {}'.format(location))
        return jsonify(cached_data), 200

    try:
        # Replace with your API endpoint and headers, etc
        response = requests.get('http://api.example.com/weather', params={'q': location}, headers={...})
        app.logger.info('API call made for {}'.format(location))

        response.raise_for_status()  # Raise exception if status is not OK (200)
    except requests.exceptions.HTTPError as errh:
        return jsonify({'error': 'Http Error: {}'.format(errh)}), 500
    except requests.exceptions.ConnectionError as errc:
        return jsonify({'error': 'Error Connecting: {}'.format(errc)}), 500
    except requests.exceptions.Timeout as errt:
        return jsonify({'error': 'Timeout Error: {}'.format(errt)}), 500
    except requests.exceptions.RequestException as err:
        return jsonify({'error': 'OOps: Something Else: {}'.format(err)}), 500

    data = response.json()

    # Store the new weather data into cache with a timeout (in seconds)
    cache.set(location, data, timeout=60*60*24)  # Cache for 1 day

    return jsonify(data), 200
