```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import javax.net.ssl.*;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.util.EntityUtils;
import com.google.gson.*;

public class SecureHighPerformanceNIOConnection {
    private static final String OAUTH_URL = "https://your-oauth-server/token";
    private static final String CLIENT_ID = "YourClientId";
    private static final String CLIENT_SECRET = "YourClientSecret";
    private SocketChannel socketChannel;
    private SSLSocketFactory sslSocketFactory;
    private CloseableHttpClient httpClient;
    private Gson gson;

    public SecureHighPerformanceNIOConnection() throws IOException {
        this.gson = new Gson();
        initializeSSLContext();
        initializeHttpClient();
        connectToServer();
    }

    private void initializeSSLContext() throws IOException {
        try {
            SSLContext sslContext = SSLContext.getDefault();
            this.sslSocketFactory = sslContext.getSocketFactory();
        } catch (Exception e) {
            // Handle exception
        }
    }

    private void initializeHttpClient() {
        this.httpClient = HttpClients.createDefault();
    }

    private String authenticateWithOAuth2Server() throws IOException {
        HttpPost postRequest = new HttpPost(OAUTH_URL);
        postRequest.addHeader("content-type", "application/x-www-form-urlencoded");

        try (CloseableHttpResponse response = httpClient.execute(postRequest)) {
            String responseBody = EntityUtils.toString(response.getEntity());
            JsonObject jsonResponse = gson.fromJson(responseBody, JsonObject.class);

            return jsonResponse.get("access_token").getAsString();
        } catch (IOException e) {
            // Handle exception
        }

        return null;
    }

    private void connectToServer() throws IOException {
        String token = authenticateWithOAuth2Server();
        if(token == null) {
            throw new RuntimeException("Failed to authenticate with Oauth Server");
        }

        SSLSocket sslSocket = (SSLSocket) sslSocketFactory.createSocket();
        this.socketChannel = sslSocket.getChannel();
        InetSocketAddress address = new InetSocketAddress("your-server-address", 443);

        try {
            socketChannel.connect(address);
        } catch (IOException e) {
            // Handle exception
        }
    }

    public void sendMessage(String message) throws IOException {
        ByteBuffer buffer = ByteBuffer.wrap(message.getBytes());
        socketChannel.write(buffer);

        // Handle response from server
    }
}
```
In this code, we use Apache HttpClient for OAuth2 authentication and Gson to parse the JSON response from the server. The `connectToServer` method is responsible for authenticating with the OAuth2 server, and then creating an SSL socket and connecting it to the remote server using Java NIO channels.

