using System;
using System.Security.Cryptography;
using System.Threading;
using System.Collections.Generic;
using StackExchange.Redis;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json.Schema;

public class UserProfileService : IUserProfileService
{
    private readonly IApiClient apiClient;
    private readonly IDistributedCache cache;
    private readonly ILogger logger;
    private static SemaphoreSlim semaphore = new SemaphoreSlim(1, 1);
    private const string CacheKeyPrefix = "UserProfile_";

    public UserProfileService(IApiClient apiClient, IDistributedCache cache, ILogger<UserProfileService> logger)
    {
        this.apiClient = apiClient;
        this.cache = cache;
        this.logger = logger;
    }

    // Method to fetch user profiles and perform SHA256 hashing for log files
    public async Task FetchAndHashUserProfiles(IEnumerable<string> userIds, ApiCredentials credentials, TimeSpan? cacheExpirationTime)
    {
        var failedRequests = new List<FailedApiRequest>();
        foreach (var userId in userIds)
        {
            try
            {
                // Fetch profile from cache or external API
                var userProfile = await GetUserProfileFromCacheOrExternal(userId, credentials);

                // Create SHA256 hash of log files
                string hashValue = ComputeSHA256Hash(userProfile.LogFiles);

                // Store the hash value in cache with expiration time if specified
                await semaphore.WaitAsync();
                try
                {
                    var cacheKey = $"{CacheKeyPrefix}{hashValue}";
                    if (await this.cache.GetStringAsync(cacheKey) == null && cacheExpirationTime != null)
                        await this.cache.SetStringAsync(cacheKey, hashValue, cacheExpirationTime);
                }
                finally
                {
                    semaphore.Release();
                }
            }
            catch (ApiException ex) when (ex.IsRateLimited)
            {
                // Handle rate limit exception by delaying the next request and retry
                await Task.Delay(TimeSpan.FromSeconds((double)ex.RetryAfter));
                failedRequests.Add(new FailedApiRequest{UserId = userId, AttemptCount = 1});
            }
        }

        // Retry failed requests up to three times before marking them as failures
        foreach (var failedRequest in failedRequests)
        {
            if (failedRequest.AttemptCount < 3)
                await FetchAndHashUserProfiles(new[] {failedRequest.UserId}, credentials, cacheExpirationTime);
            else
                logger.LogError("Failed to fetch and hash user profile for user id: " + failedRequest.UserId);
        }
    }

    // Method to get user profile from cache or external API
    private async Task<UserProfile> GetUserProfileFromCacheOrExternal(string userId, ApiCredentials credentials)
    {
        UserProfile userProfile;

        var cacheKey = $"{CacheKeyPrefix}{userId}";
        var cachedProfile = await this.cache.GetStringAsync(cacheKey);
        if (cachedProfile != null)
            return JsonConvert.DeserializeObject<UserProfile>(cachedProfile);

        userProfile = await apiClient.FetchUserProfile(userId, credentials);

        // Update cache with the fetched profile
        await this.cache.SetStringAsync(cacheKey, JsonConvert.SerializeObject(userProfile));

        return userProfile;
    }

    // Method to compute SHA256 hash of log files
    private string ComputeSHA256Hash(IEnumerable<LogFile> logFiles)
    {
        using (var sha256 = SHA256.Create())
        {
            foreach (var logFile in logFiles)
            {
                var logContentBytes = Encoding.UTF8.GetBytes(logFile.Content);
                var hashBytes = sha256.ComputeHash(logContentBytes);

                var sb = new StringBuilder();
                foreach (var b in hashBytes)
                    sb.Append(b.ToString("x2"));

                logFile.Sha256Hash = sb.ToString();
            }
        }
    }
}
```

