    for (int i = 0; i < 3; ++i) {
        records[i] = malloc(sizeof(Record));  
        records[i]->value = rand() % 100;   // set value to a random number between 0 and 99
        records[i]->dependencies = NULL;    // start with no dependencies
    }

    load_and_execute_js("myscript.js");  // example of loading and executing JavaScript file

    free(offsets);  // don't forget to free allocated memory when you're done
    free(keys);
    for (int i = 0; i < 3; ++i) {
        while (records[i]->dependencies != NULL) {
            ListNode* next = records[i]->dependencies->next;  // store reference to the next node before freeing current
            free(records[i]->dependencies);                   // free current node
            records[i]->dependencies = next;                   // move to the next node
        }

        free(records[i]);  // free each record structure after all dependencies are freed
