// Assume this is your FSA structure and transition function
typedef struct { /* Actual definition of FSA */ } FSA;
int* transition_callback(FSA *fsa, int state, char input) { /* Implementation of callback*/}

int* new_state_list(int* init_states, int num_init_states, 
                    FSA* fsa, int last_state, int termination_id){

    // Assume that the transition function returns a NULL terminated array.
    int *last_transition = NULL;
    int state_list_size = 0;

    for(int i=0; i<num_init_states; ++i) {
        int curr_state = init_states[i];

        while(curr_state != last_state && curr_state != termination_id) {
            // Assume input symbol is 'a' for simplicity
            char input_symb = 'a'; 

            int *next_states = transition_callback(fsa, curr_state, input_symb);

            if (!next_states || !*next_states) {
                free(last_transition);
                return NULL; // No available transitions or error occurred
            } 

            curr_state = *next_states;
            free(next_states); // Clean up memory after usage
        }

        if (curr_state == termination_id) {
            break;
        } else if (last_transition && last_transition[0] != curr_state){ 
            // Check for duplication and add to the list only when needed.
            state_list_size++;
            int *temp = realloc(last_transition, state_list_size*sizeof(int));

            if (!temp) {
                free(last_transition);
                return NULL; // Out of memory
            }

            last_transition = temp;
            last_transition[state_list_size-1] = curr_state;
        } 
    }

    if (state_list_size == 0) {
        free(last_transition); // No transitions, free the memory and return NULL
        return NULL;
    }

    int *new_states_list = malloc(state_list_size*sizeof(int));

    if (!new_states_list) {
        free(last_transition);
        return NULL; // Out of memory
    }

    for (int i = 0; i < state_list_size; ++i){
       new_states_list[i] = last_transition[i]; 
    }

    free(last_transition); // Clean up after usage.

    return new_states_list;
}
