public class DynamicXPathProcessor
{
    private readonly IExternalApiClient _externalApiClient;
    private readonly ISchemaValidator _schemaValidator;
    private readonly ILogger<DynamicXPathProcessor> _logger;
    private readonly XmlNamespaceManager _namespaceManager;

    public DynamicXPathProcessor(IExternalApiClient externalApiClient, 
        ISchemaValidator schemaValidator, 
        ILogger<DynamicXPathProcessor> logger)
    {
        _externalApiClient = externalApiClient;
        _schemaValidator = schemaValidator;
        _logger = logger;

        // Initialize namespace manager with default namespaces if needed.
        _namespaceManager = new XmlNamespaceManager(new NameTable());
        _namespaceManager.AddNamespace("default", "http://www.example.com");
    }

    public async Task<XPathNavigator> GetElementByNameAsync(string name)
    {
        var xmlDocument = await _externalApiClient.GetXmlAsync();

        if (!_schemaValidator.Validate(xmlDocument)) 
        {
            throw new InvalidDataException("XML document doesn't match the schema.");
        }

        // Parse XML using XPath
        var xmlReader = new XmlNodeReader(xmlDocument);

        while (await xmlReader.ReadAsync())
        {
            if (xmlReader.LocalName == name)
            {
                return xmlReader;
            }
        }

        throw new InvalidOperationException("Element not found.");
    } 
}
```

