use std::process::exit;

// Validate WORK_DIR environment variable
fn validate_dir() -> io::Result<PathBuf> {
    let work_dir = var("WORK_DIR").unwrap();

    if work_dir.is_empty() || !fs::metadata(&work_dir).is_ok() {
        // create a new unique temp directory and set it as WORK_DIR
        let tmp_path = fs::temp_dir().join(format::fmt::format("{:?}", thread::current()) + &work_dir);
        try_fs(|| {
            fs::create_dir(&tmp_path)?;
            set_var("WORK_DIR", tmp_path);
            Ok(())
        })?;
    } else if !PathBuf::from(&work_dir).exists() || PathBuf::from(&work_dir).is_file(){
        return Err(io::Error::new(io::ErrorKind::NotFound, "Directory not found"));
    } 

    Ok(PathBuf::from(&work_dir))
}

// cleanup thread-safe directory management
struct DirCleaner {
    dir: PathBuf,
    cleaner: Mutex<Option<Box<dyn Fn() + Send>>>,
}
impl Drop for DirCleaner {
    fn drop(&mut self) {
        let _ = *self.cleaner.lock().unwrap(); // run cleanup function
    }
}
fn manage_dir(path: PathBuf) -> DirCleaner {
    let cleaner = Mutex::new(Some(Box::new({
        move || { 
            if path.exists() { fs::remove_dir_all(&path).unwrap(); } 
        }
    }) as Box<dyn Fn() + Send>));
    DirCleaner { dir: path, cleaner }
}

// Dummy plugin system for external CI/CD integration
fn execute_plugin(url: &str) -> io::Result<TcpStream> {
    match TcpStream::connect(&format::fmt::format("{}:80", url)) {
        Ok(s) => s,
        Err(e) => Err(io::Error::new(io::ErrorKind::Other, e)),
    }
}

fn main() {
    let path = validate_dir().unwrap(); // validate WORK_DIR

    // manage directory until dropped 
    let _ = manage_dir(path);
    thread::sleep(Duration::from_secs(1));

    // dummy plugin execution
    if let Err(_) = execute_plugin("dummy.com") {
        println::fmt::format("Plugin failed", &[]);
    }
}
```
