import java.util.*;

class State {
    String name;
    List<State> transitions = new ArrayList<>();
}

public class FSA {
    Set<String> visitedStates = new HashSet<>();

    public void DFS(State curr) {
        if (curr == null || visitedStates.contains(curr.name)) return;

        // Visit the state...
        System.out.println("Visiting " + curr.name);
        visitedStates.add(curr.name);

        for (State next : curr.transitions) {
            DFS(next);
        }
    }

    public static void main(String[] args) {
        FSA fsa = new FSA();
        State initialState = new State(); // define your states and transitions here...

        fsa.DFS(initialState);
    }
}
