#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <stdio.h>

EVP_CIPHER_CTX *createContext(const unsigned char* key, const unsigned char* iv, int keysize) {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;

    /* Create and initialise the context */
    if(!(ctx = EVP_CIPHER_CTX_new())) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    switch (keysize) {
        case 128:
            cipher = EVP_aes_128_cbc();
            break;
        case 192:
            cipher = EVP_aes_192_cbc();
            break;
        case 256:
            cipher = EVP_aes_256_cbc();
            break;
        default:
            fprintf(stderr, "Invalid key size\n");
            return NULL;
    }

    /* Initialise the encryption operation. */
    if(1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    return ctx;
}

int main() {
    unsigned char key[EVP_MAX_KEY_LENGTH] = {0}; 
    unsigned char iv[EVP_MAX_IV_LENGTH] = {0};
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    EVP_CIPHER_CTX *ctx = createContext(key, iv, 256);
    if (ctx != NULL) {
        printf("Successfully created the context\n");
        EVP_CIPHER_CTX_free(ctx);
    } else {
        printf("Failed to create the context\n");
    }

    return 0;
}
```
