```javascript
const AWS = require('aws-sdk');
const crypto = require('crypto');
const winston = require('winston');

class ConfigManager {
  constructor() {
    this.configFactoryRegistry = {};
    this.ssmClient = new AWS.SSM();
    this.logger = winston.createLogger({});
  }

  addConfigFactory(environmentId, factoryFn) {
    this.configFactoryRegistry[environmentId] = factoryFn;
  }

  async createInstanceFromService(environmentId, token) {
    try {
      const data = await this.ssmClient.getParameter({
        Name: environmentId,
        WithDecryption: true
      }).promise();

      if (!this.configFactoryRegistry[environmentId]) {
        throw new Error(`No factory function for ${environmentId} found in registry`);
      }

      const config = JSON.parse(data.Parameter.Value);
      this.logger.info(`Deserialized config data from SSM: ${config}`);

      const hashedKey = crypto.createHash('sha256').update(token).digest('hex');
      return { token, hashedKey };
    } catch (error) {
      this.logger.error(`Error loading and executing config for ${environmentId}: ${error}`);
      throw error;
    }
  }
}
```
This code uses AWS SDK to fetch configuration from the SSM Parameter Store, JSON to parse the configuration data and crypto module to hash the token. Winston is used for logging. Note that you need to handle the circular dependency in your config files or service as well which this doesn't cover. Also, it's worth noting that in a real-world scenario, you should use secure methods to protect your sensitive information such as tokens and keys.

