#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

/* Define your semaphore and cloud service API here */
extern void acquire_cloud_resource(void);
extern void release_cloud_resource(void);

typedef struct {
    sem_t *sem;
    int permitCount;
} SemaphoreManager;

SemaphoreManager *initializeSemaphore() {
    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    manager->permitCount = 0;
    return manager;
}

void createSemaphore(SemaphoreManager *manager) {
    sem_init(&manager->sem, 0, manager->permitCount);
}

void setPermitCount(SemaphoreManager *manager, int count) {
    if (count >= 0 && count <= 100000) {
        acquire_cloud_resource(); /* Assume this function handles the request */
        manager->permitCount = count;
        sem_init(&manager->sem, 0, manager->permitCount);
    } else {
        fprintf(stderr, "Invalid permit count.\n");
        exit(EXIT_FAILURE);
    }
}

void acquireSemaphore(SemaphoreManager *manager) {
    sem_wait(&manager->sem);
}

void releaseSemaphore(SemaphoreManager *manager) {
    sem_post(&manager->sem);
}

void deleteSemaphore(SemaphoreManager *manager) {
    sem_destroy(&manager->sem);
    free(manager);
    manager = NULL;
    release_cloud_resource(); /* Assume this function handles the request */
}
```
