The problem is quite complex and requires good understanding of JavaScript, its modules, promises, async/await and error handling. The following is a simplified example on how you can achieve dynamic script loading and error handling in JavaScript. 

```javascript
const LOADING_SPINNER = 'Loading...';
const FALLBACK_SCRIPT = `alert('Fallback Script');`;
let cache = {}; // Cache for scripts

function loadScripts(scripts) {
    let spinnerElement = document.getElementById('spinner');

    function fetchScript(src) {
        return new Promise((resolve, reject) => {
            if (cache[src]) {
                resolve(cache[src]);
            } else {
                const scriptTag = document.createElement("script");
                scriptTag.type = "text/javascript";
                scriptTag.onload = () => {
                    cache[src] = true;
                    resolve();
                };
                scriptTag.onerror = () => reject(new Error(`Failed to load ${src}`));
                scriptTag.src = src;
                document.body.appendChild(scriptTag);
            }
        });
    }

    function showSpinner() {
        spinnerElement.textContent = LOADING_SPINNER;
    }

    function hideSpinner() {
        spinnerElement.textContent = '';
    }

    async function loadScriptsSequentially(scripts) {
        showSpinner();
        for (let script of scripts) {
            try {
                await fetchScript(script);
            } catch (error) {
                console.log('Error:', error);
            }
        }
        hideSpinner();
    }

    function handleFallback() {
        return new Promise((resolve, reject) => {
            const fallbackScriptTag = document.createElement("script");
            fallbackScriptTag.type = "text/javascript";
            fallbackScriptTag.textContent = FALLBACK_SCRIPT;
            document.body.appendChild(fallbackScriptTag);
        });
    }

    if (!scripts || scripts.length === 0) {
        return handleFallback(); // Load a default script or show an error message
    } else {
        return loadScriptsSequentially(scripts);
    }
}
```

