// Declare cache object for scripts
const scriptCache = {};
let isFetchingScripts = false;

async function fetchScripts(url, retry = 3) {
  if (isFetchingScripts) return; // Prevent redundant network requests
  isFetchingScripts = true;

  try {
    const response = await fetch(url);
    const scripts = await response.json();

    isFetchingScripts = false;
    return scripts;
  } catch (error) {
    if (retry > 0) {
      setTimeout(() => fetchScripts(url, retry - 1), 2000); // Retry after a delay
    } else {
      console.log('Failed to fetch scripts: ', error.message);
    }
  }
}

// Function to render script tags in HTML string
function renderScripts(scripts) {
  let html = '';

  // Iterate over each script and create a script tag
  for (const script of scripts) {
    const code = script.code || 'console.log("Missing script code.")';
    const type = script.type || "text/javascript";

    html += `<script type="${type}">${code}</script>`;
  }

  return html;
}

// Function to update DOM with rendered scripts
async function updateDomWithScripts(url) {
  const scripts = await fetchScripts(url);
  if (scripts) {
    // Append script tags to document body
    document.body.insertAdjacentHTML('beforeend', renderScripts(scripts));
  } else {
    console.log('Unable to update DOM with scripts.');
  }
}
```

