```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public class SecurePasswordHasher : IDisposable
{
    private SHA256 _sha256 = SHA256.Create();

    public void Dispose()
    {
        ((IDisposable)_sha256)?.Dispose();
    }

    // Method to generate salt
    public string GenerateSalt(int length)
    {
        const string valid = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";
        StringBuilder res = new StringBuilder();
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] uintBuffer = new byte[sizeof(uint)];
            while (length-- > 0)
            {
                rng.GetBytes(uintBuffer);
                uint num = BitConverter.ToUInt32(uintBuffer, 0);
                res.Append(valid[(int)(num % (uint)valid.Length)]);
            }
        }
        return res.ToString();
    }

    // Method to hash password using SHA-256
    public string HashPasswordWithSHA256(string plainText, string salt = null)
    {
        if (salt == null)
            salt = GenerateSalt(10);

        byte[] bytes = Encoding.Unicode.GetBytes(plainText + salt);
        byte[] inArray = _sha256.ComputeHash(bytes);

        return Convert.ToBase64String(inArray) + ":" + salt; 
    }

    // Method to verify password against hashed password
    public bool VerifyPasswordWithSHA256(string plainText, string hashedPasswordAndSalt)
    {
        var splitted = hashedPasswordAndSalt.Split(':');
        if (splitted.Length != 2) return false;

        var salt = splitted[1];
        var hash = HashPasswordWithSHA256(plainText, salt);

        return hash == hashedPasswordAndSalt;
    }
}
```
