#include <stdlib.h>
#include <gdk-pixbuf/gdk-pixbuf.h>
#include <poppler.h>

typedef struct {
    char* toolPath;
    // Add other configuration fields as necessary
} Configuration;

int convertImageToPdf(const char *inputFile, const char *outputFile, Configuration *config) {
    GError *error = NULL;
    gchar command[512];

    // Load image to check dimensions
    GdkPixbuf *pixbuf = gdk_pixbuf_new_from_file(inputFile, &error);
    if (pixbuf == NULL) {
        fprintf(stderr, "Error loading input file: %s\n", error->message);
        return 1;
    }

    // Check image dimensions
    int width = gdk_pixbuf_get_width(pixbuf);
    int height = gdk_pixbuf_get_height(pixbuf);
    if (width < 100 || width > 5000 || height < 100 || height > 5000) {
        fprintf(stderr, "Image dimensions are not within limits. Width: %d Height: %d\n", width, height);
        return 1;
    }

    // Convert image to PDF using third-party tool
    sprintf(command, "%s %s output %s", config->toolPath, inputFile, outputFile);
    int result = system(command);

    if (result != 0) {
        fprintf(stderr, "Conversion failed with status code: %d\n", WEXITSTATUS(result));
        return 1;
    }

    // Cleanup and close file handles
    g_object_unref(pixbuf);

    return 0;
}
