```csharp
using System;
using System.Diagnostics;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Collections.Generic;
using Microsoft.Extensions.Caching.Memory;

public class XmlDocumentManager : IXmlDocumentManager
{
    private readonly IExternalDataSource _externalDataSource;
    private readonly IXsdValidator _xsdValidator;
    private readonly ILogger<XmlDocumentManager> _logger;
    private readonly IMemoryCache _cache;

    public XmlDocumentManager(IExternalDataSource externalDataSource, IXsdValidator xsdValidator, ILogger<XmlDocumentManager> logger, IMemoryCache cache)
    {
        _externalDataSource = externalDataSource;
        _xsdValidator = xsdValidator;
        _logger = logger;
        _cache = cache;
    }

    public async Task<XDocument> GetXmlAsync(string key, string xpathQuery)
    {
        XDocument xmlDoc;

        if (!_cache.TryGetValue(key, out xmlDoc)) //try to get from cache
        {
            var watch = Stopwatch.StartNew();

            try
            {
                //get document from external source 
                string rawXml = await _externalDataSource.FetchDocumentAsync();

                //validate the xml against XSD schema
                bool isValid = await _xsdValidator.ValidateAgainstSchemaAsync(rawXml);

                if (isValid)
                {
                    //parse the xml document 
                    xmlDoc = XDocument.Parse(rawXml);

                    var cacheEntryOptions = new MemoryCacheEntryOptions()
                        .SetSlidingExpiration(TimeSpan.FromMinutes(5));//configure as per your needs for varying update frequencies

                    _cache.Set(key, xmlDoc, cacheEntryOptions); //store in cache
                }

            }
            catch (Exception ex)
            {
                //log errors 
                _logger.LogError(ex, "An error occurred while fetching or validating the document");
            }

            watch.Stop();
            _logger.LogInformation($"Fetching and parsing XML took : {watch.ElapsedMilliseconds} ms");
        } 

        if (!string.IsNullOrEmpty(xpathQuery))
        {
            //execute xpath query on the document
            IEnumerable<XElement> selectedElements = xmlDoc.XPathSelectElements(xpathQuery);

            var watch2 = Stopwatch.StartNew();

            foreach (var element in selectedElements)
            {
                _logger.LogInformation(element.ToString());
            } 

            //log query execution time
            watch2.Stop();
            _logger.LogInformation($"Executing XPath Query took : {watch2.ElapsedMilliseconds} ms");
        }

        return xmlDoc;
    }
}
```

This `XmlDocumentManager` class leverages dependency injection for the external data source, XML schema validator and logging services (using Microsoft's built-in ILogger interface). The documents are cached in memory using Microsoft's MemoryCache. It fetches the XML document from an external data source, validates it against a provided XSD Schema, parses it to an `XDocument` object, stores it into the cache and executes any provided XPath queries on it. Each action is logged for auditing purposes.

