class Configuration:
    def __init__(self):
        self.configs = []

    def add(self, pos, string, config_data):
        if pos < 0 or pos >= len(self.configs):
            return 'Out of bound position'

        index = 0
        for i in range(len(self.configs)):
            if self.configs[i] == string:
                index = i + 1  # Insert after the found string
                break

        self.configs.insert(index + pos, config_data)

    def save_to_redis(self):
