const async = require('async');
const EventEmitter = require('events').EventEmitter;
let config = require('./config.json'); // configuration file defining module sequence and options

class App extends EventEmitter {
    constructor() {
        super();
        this.modules = [];
    }

    loadModule(modulePath) {
        try{
            let m = require(modulePath);
            if (this.checkDependencies(m)) this.modules.push(m);
            else console.error('Circular dependency detected');
        }catch(e){
            console.error('Failed to load module: ' + e);
        }   
    }

    checkDependencies(module) {
        // Check for circular dependencies
        if (this.modules.indexOf(module) > -1) return false;
        else return true;
    }

    executeModules() {
        async.eachSeries(config, (task, callback) => {
            let m = this.modules[task];
            try{
                m();
                callback();
            }catch(e){
                console.error('Failed to execute module: ' + e);
                callback('stop'); // stop the sequence on error
            }
        }, err => { if (err) console.log('Module execution stopped with error', err)}); // log any errors
    }
}
```
