#include <stdio.h>
#include <netdb.h> 
#include <sys/socket.h> 
#include <arpa/inet.h>
#include <tiffio.h>

void* resolveDNS(char *hostname) { 
    struct hostent *he;     
    struct in_addr **addr_list;     

    if ((he = gethostbyname(hostname)) == NULL) return NULL; // error handling omitted for brevity

    addr_list = (struct in_addr **) he->h_addr_list; 
    u_char* ip = (u_char*) malloc(he->h_length);

    for(int i = 0; addr_list[i] != NULL; i++) strcpy((char *)ip, inet_ntoa(*addr_list[i])); 

    return (void *) ip;
} 

TIFF* openImage(const char* filename){
    TIFF* tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        fprintf(stderr, "Can't open file %s\n", filename);
        return NULL;
    } 

    uint16 bps, spp; // bits per sample and samples per pixel
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bps);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &spp);

    if( bps != 1 && bps != 2 && bps != 4 && bps !=8 && bps != 16 ) {
        fprintf(stderr, "Unsupported bits per sample %d\n", bps);
        return NULL;
    }

    uint32 width, length;  // image dimensions
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &length);

    printf("Image size: %lux%lu\n", width, length); 

    return tif;
}
```
