namespace MyApp {
  class SessionIdGenerator {
    std::mt1937_64 gen;
    Database db;

    public:
      SessionIdGenerator() : gen(std::random_device{}()), db("/path/to/database") {}

      ~SessionIdGenerator() = default; // Trivial destructor

      std::string generateUniqueSessionID() {
        while (true) {
          std::string sessionID = base64encode(std::to_string(gen()));
          if (sessionID.size() > 22) sessionID.resize(22); // Ensure ID length is 22 characters max
          if (!db.isSessionIdUsed(sessionID)) return sessionID; // If unique, return
        }
      }
  };
}
