Here is a simplified PHP code for generating secure random string and token generation with rate limiting using Redis, password hashing with Argon2id and logging error activity. 

```php
<?php
use Redis;

class SecureRandomGenerator {
    private $redis;
    private $tokenExpirationTime = 300; // 5 minutes

    public function __construct() {
        $this->redis = new Redis();
        $this->redis->connect('127.0.0.1', 6379); // assuming redis is running on localhost
    }

    public function generateRandomString($length = 10) {
        return bin2hex(random_bytes($length));
    }

    public function createToken() {
        $ip = $_SERVER['REMOTE_ADDR'];

        if ($this->redis->exists("rate:{$ip}")) {
            error_log("Rate limit exceeded by $ip");
            return false;
        } 

        $token = $this->generateRandomString(30);

        $this->redis->setex("token:{$token}", $this->tokenExpirationTime, '1');
        $this->redis->setex("rate:{$ip}", 10, '1'); // allow one token creation every 10 secs

        return $token;
    }

    public function verifyToken($token) {
        $data = $this->redis->get("token:{$token}");

        if (empty($data)) {
            error_log("Invalid or expired token $token");
            return false;
        } 

        return true;
    }

    public function hashPassword($password) {
        $hash = password_hash($password, PASSWORD_ARGON2ID);

        if (empty($hash)) {
            error_log("Error hashing password");
            return false;
        } 

        return $hash;
    }

    public function verifyPassword($password, $hash) {
        $result = password_verify($password, $hash);

        if (empty($result)) {
            error_log("Error verifying password");
            return false;
        } 

        return true;
    }
}
?>
```

