public class MersenneTwister : IDisposable {
    private static readonly Random Global = new Random();

    [ThreadStatic] 
    private static Random _local;

    public MersenneTwister() {
        int seed;

        lock (Global) {
            seed = Global.Next();
        }

        _local = new Random(seed);
    }

    public int Next() => _local.Next();

    public void Dispose() {}
