Here is an example of how you might go about implementing such a method:

```Java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ConnectionPool {
    private final ConcurrentLinkedQueue<SocketChannel> pool = new ConcurrentLinkedQueue<>();
    private final ScheduledExecutorService executorService = Executors.newSingleThreadScheduledExecutor();

    public void initConnection(int port, int initialSize) throws IOException {
        ServerSocketChannel serverSocket = ServerSocketChannel.open();
        serverSocket.bind(new InetSocketAddress(port));
        serverSocket.configureBlocking(false);
        Selector selector = Selector.open();
        serverSocket.register(selector, SelectionKey.OP_ACCEPT);

        executorService.scheduleAtFixedRate(() -> {
            try {
                if (selector.selectNow() > 0) {
                    Set<SelectionKey> selectedKeys = selector.selectedKeys();
                    Iterator<SelectionKey> iterator = selectedKeys.iterator();
                    while (iterator.hasNext()) {
                        SelectionKey key = iterator.next();
                        if (key.isAcceptable()) {
                            SocketChannel client = serverSocket.accept();
                            client.configureBlocking(false);
                            pool.add(client);
                        }
                        iterator.remove();
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }, 0, 100, TimeUnit.MILLISECONDS);

        for (int i = 0; i < initialSize; i++) {
            SocketChannel channel = serverSocket.accept();
            channel.configureBlocking(false);
            pool.add(channel);
        }
    }

    public void sendMessage(byte[] msg) throws IOException {
        for (SocketChannel socketChannel : pool) {
            ByteBuffer buffer = ByteBuffer.wrap(msg);
            socketChannel.write(buffer);
        }
    }
}
```

This is a basic example of how you can create and manage a connection pool using NIO Channels in Java. This code does not include the integration with an existing messaging system, error handling or health checking mechanisms for connections. Also this simple implementation doesn't consider network failures. For fault-tolerance and load balancing strategies we would need more specific requirements.

