Here's a simplified implementation in JavaScript using promises and async/await for concurrency:

```javascript
class ScriptLoader {
  constructor() {
    this.loadedScripts = {};
    this.loadingScripts = {};
  }

  load(url) {
    if (this.loadedScripts[url]) return Promise.resolve();
    if (this.loadingScripts[url]) return this.loadingScripts[url];

    const scriptPromise = new Promise((resolve, reject) => {
      const scriptElement = document.createElement('script');
      scriptElement.src = url;
      scriptElement.async = true;

      scriptElement.onload = () => {
        this.loadedScripts[url] = true;
        delete this.loadingScripts[url];
        resolve();
      };

      scriptElement.onerror = () => {
        delete this.loadingScripts[url];
        reject(new Error(`Failed to load ${url}`));
      };

      document.head.appendChild(scriptElement);
    });

    this.loadingScripts[url] = scriptPromise;
    return scriptPromise;
  }

  async loadAllInOrder(urls) {
    for (let url of urls) {
      try {
        await this.load(url);
      } catch (error) {
        console.error(`Error loading ${url}: ${error}`);
        return false; // Stop the process if one script fails to load
      }
    }

    return true;
  }

  remove(url) {
    if (this.loadedScripts[url]) {
      delete this.loadedScripts[url];
      const scriptElement = document.querySelector(`script[src="${url}"]`);
      if (scriptElement) scriptElement.remove();
    } else if (this.loadingScripts[url]) {
      // Cancel the loading of a script that hasn't started yet
      const scriptPromise = this.loadingScripts[url];
      delete this.loadingScripts[url];
      scriptPromise.cancelLoading = true;
    }
  }
}
```

