import json
from collections import defaultdict

class JsonObject:
    _registry = {}

    @staticmethod
    def register(id, factory_func):
        JsonObject._registry[id] = factory_func

    @staticmethod
    def create(id, json_str):
        if id not in JsonObject._registry:
            raise ValueError("No factory function registered for this ID")
        return JsonObject._registry[id](json.loads(json_str))

    def __init__(self, data):
        self.data = data

    def to_string(self):
        return json.dumps(self.data)

class ForwardList:
    def __init__(self, list):
        self.list = list

    @staticmethod  
    def insert(forward_list, first_str, second_str, position=None):
        if not isinstance(forward_list, ForwardList):
            raise TypeError("First argument must be an instance of ForwardList")

        try:
            index = forward_list.list.index(first_str, position) if position else 0
        except ValueError:
            index = -1

        if index == -1:
            forward_list.list.append(second_str)
        else:
            forward_list.list.insert(index + 1, second_str)
