```python
import jsonschema
from collections import defaultdict
from typing import Callable, Dict

class MqttHandler:
    def __init__(self):
        self.topic_handlers = defaultdict(list)
        self.dedup_cache = set()
        self.rate_limits = {}

    def register_handler(self, topic: str, handler: Callable, schema: Dict):
        self.topic_handlers[topic].append((handler, schema))

    def handle_message(self, topic: str, payload: str, qos: int):
        if (topic, payload) in self.dedup_cache:
            return  # duplicate message, ignore

        if topic not in self.rate_limits or self.rate_limits[topic] > 0:
            for handler, schema in self.topic_handlers[topic]:
                try:
                    jsonschema.validate(payload, schema)
                    handler(payload, qos)  # message is validated and processed by the registered handlers
                except Exception as e:
                    print(f"Error processing message on topic {topic}: {e}")
            self.dedup_cache.add((topic, payload))  # mark the message as handled

            if topic in self.rate_limits:
                self.rate_limits[topic] -= 1  # reduce remaining rate limit for this topic
        else:
            print(f"Rate limited on topic {topic}, skipping message")
