const cache = {};
let executingCount = 0;

function executeScripts(scripts) {
  scripts.forEach((script) => {
    if (cache[script.id] && !script.forceReload) {
      return cache[script.id]; // Return cached result if available and not forced to reload
    } else if (!script.url) {
      const scriptFunction = new Function(script.content);
      cache[script.id] = scriptFunction(); // Execute inline scripts and cache the result
    } else {
      fetchScript(script.url).then((result) => {
        cache[script.id] = result; // Fetch and execute remote scripts, cache the result
      });
    }
  });
}

async function fetchScript(url) {
  try {
    const response = await fetch(url);
    const scriptContent = await response.text();
    return new Function(scriptContent);
  } catch (error) {
    console.log("Error fetching script:", error);
    throw error; // Propagate the error to caller for handling
  }
}

function fetchAndExecuteScripts(scripts) {
  if (executingCount > 0) {
    return Promise.reject('Already executing scripts'); // Prevent multiple script fetches from queueing up
  }

  loadingSpinner.style.display = 'block'; // Display a loading spinner while scripts are being fetched and executed

  executingCount++;
  executeScripts(scripts)
    .then(() => {
      loadingSpinner.style.display = 'none'; // Hide the loading spinner after all scripts have been executed
    })
    .catch((error) => {
      console.log('Error occurred while fetching and executing scripts:', error);
    })
    .finally(() => {
      executingCount--;
    });
}
