    va_list args;
    va_start(args, format);

    int fd = -1;
    if (strcmp(level, "ERROR") == 0)
        fd = open(ERROR_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    else if (strcmp(level, "WARNING") == 0)
        fd = open(WARNING_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    else if (strcmp(level, "INFO") == 0)
        fd = open(INFO_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);

    char timestamp[50];
    time_t t = time(NULL);
    struct tm *tmp = localtime(&t);
    if (tmp == NULL) {
        perror("localtime");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%d-%m-%Y %H:%M:%S", tmp);

    char msg[MAX_LOG_MSG_LEN];
    if (vsnprintf(msg, MAX_LOG_MSG_LEN, format, args) < 0) {
        perror("vsnprintf");
        return;
    }

    if (write(fd, timestamp, strlen(timestamp)) == -1 ||
        write(fd, " [", 2) == -1 || 
        write(fd, level, strlen(level)) == -1 ||
        write(fd, "] ", 2) == -1 ||
        write(fd, msg, strlen(msg)) == -1 ||
        write(fd, "\n", 1) == -1) {
        perror("write");
    }

    if (close(fd) == -1) {
        perror("close");
    }
}
```
This function uses `vsnprintf` to format the message based on the provided format string and arguments. It opens the corresponding log file for writing, writes a formatted timestamp followed by the severity level and then the actual log message. Error handling is done using POSIX APIs such as `open`, `write`, and `close` which can report errors through the `errno` global variable. The use of `strftime` allows for custom formatting of the timestamp.

