```php
use Predis\Client as Redis;
use GuzzleHttp\Client as HttpClient;
use GuzzleHttp\Exception\RequestException;

class OAuthAuthenticator {
    private $redis;
    private $httpClient;

    public function __construct(Redis $redis, HttpClient $httpClient) {
        $this->redis = $redis;
        $this->httpClient = $httpClient;
    }

    public function authenticateUser($providerName, $authParams) {
        // Check for rate limiting before proceeding.

        if (!$this->checkRateLimit($providerName)) {
            throw new Exception('Rate limit exceeded');
        }

        $accessToken = $this->getAccessToken($providerName, $authParams);

        // Store the access token securely in a Redis cache with a TTL.

        $this->redis->setex('access_token:' . session_id(), 3600, $accessToken);

        // Retrieve user information from remote API using the access token.

        $userInfo = $this->getUserInformation($providerName, $accessToken);

        return $userInfo;
    }

    private function getAccessToken($providerName, $authParams) {
        try {
            // Make a request to the OAuth provider to get access token.

            $response = $this->httpClient->post('/oauth/token', [
                'form_params' => [
                    'grant_type' => 'password',
                    'client_id' => $providerName,
                    'username' => $authParams['username'],
                    'password' => $authParams['password']
                ]
            ]);

            $data = json_decode($response->getBody()->getContents(), true);

            return $data['access_token'];
        } catch (RequestException $e) {
            // Handle network issues or server downtime.

            throw new Exception('Failed to authenticate user: ' . $e->getMessage());
        }
    }

    private function getUserInformation($providerName, $accessToken) {
        try {
            // Make a request to the OAuth provider to retrieve user information.

            $response = $this->httpClient->get('/userinfo', [
                'headers' => [
                    'Authorization' => 'Bearer ' . $accessToken
                ]
            ]);

            return json_decode($response->getBody()->getContents(), true);
        } catch (RequestException $e) {
            // Handle network issues or server downtime.

            throw new Exception('Failed to fetch user info: ' . $e->getMessage());
        }
    }

    private function checkRateLimit($providerName) {
        // Implement rate limiting logic for both the provider and user level.

        $rateLimiterKey = 'ratelimit:' . session_id() . ':' . $providerName;

        if ($this->redis->exists($rateLimiterKey)) {
            // If rate limit is exceeded, return false.

            $remainingRequests = $this->redis->decr($rateLimiterKey);

            if ($remainingRequests < 0) {
                $this->redis->incr($rateLimiterKey);
                return false;
            }
        } else {
            $this->redis->setex($rateLimiterKey, 3600, 100); // Max requests per hour.
        }

        return true;
    }
}
```

