    public ModuleTester()
    {
        // Initialize the cache
        _cache = new MemoryCache(new MemoryCacheOptions());
    }

    public async Task RunModuleTestsAsync(string moduleName, List<string> testFunctions)
    {
        try
        {
            Assembly assembly = Assembly.LoadFrom(moduleName);

            foreach (var function in testFunctions)
            {
                MethodInfo method = assembly.GetType("TestClass").GetMethod(function);

                // Check if the rate limit has been hit
                string cacheKey = $"{method}_{DateTime.UtcNow:yyyyMMdd_hh}";
                int requestCount = 0;

                if (_cache.TryGetValue(cacheKey, out requestCount))
                {
                    // If we hit the rate limit for this hour and method, throw an exception
                    if (requestCount >= 100)
                        throw new Exception("Rate limit exceeded");

                    _cache.Set(cacheKey, ++requestCount);
                }

                await Task.Run(() => {method.Invoke(null, null);});
            }
        }
        catch (Exception ex)
        {
            // Log exception details for auditing purposes
            Console.WriteLine($"An error occurred at {DateTime.Now} with message: {ex.Message}");

            // Rethrow the exception to be handled upstream
            throw;
        }
