This task is complex and involves many concepts including cryptography, asynchronous programming, distributed systems, hardware security modules (HSMs), and more. Here is a sample code snippet of the proposed functionalities using Bouncy Castle library for C# which implements AES-GCM. The complexity of the problem necessitates a lot more than just this code. This code represents only a small portion of what you are asking:

```csharp
using System;
using System.Security.Cryptography;
using Org.BouncyCastle.Crypto.Engines;
using Org.BouncyCastle.Crypto.Modes;
using Org.BouncyCastle.Crypto.Parameters;

public class AESGCM
{
    private const int NonceSize = 12; // In bytes (96 bits)
    private const int TagSize = 16; // In bytes (128 bits)

    public byte[] Encrypt(byte[] plaintext, byte[] key, byte[] salt)
    {
        var aes = new AesGcmEngine();

        var nonce = GenerateRandomBytes(NonceSize);
        var initializationVector = GenerateRandomBytes(Aes.BlockSize / 8); //128 bits

        byte[] ciphertext;
        using (var encryptor = new GcmBlockCipher(aes))
        {
            encryptor.Init(true, new AeadParameters(new KeyParameter(key), TagSize * 8, nonce, initializationVector));

            var encryptedDataLength = encryptor.GetOutputSize(plaintext.Length);
            ciphertext = new byte[encryptedDataLength];
            var len = encryptor.ProcessBytes(plaintext, 0, plaintext.Length, ciphertext, 0);

            try
            {
                encryptor.DoFinal(ciphertext, len);
            }
            catch (InvalidCipherTextException)
            {
                // Handle error here
            }
        }

        return ConcatenateByteArrays(nonce, initializationVector, ciphertext);
    }

    public byte[] Decrypt(byte[] encryptedData, byte[] key)
    {
        var aes = new AesGcmEngine();

        var nonce = new byte[NonceSize]; //12 bytes
        Array.Copy(encryptedData, 0, nonce, 0, NonceSize);

        var initializationVector = new byte[Aes.BlockSize / 8]; //16 bytes
        Array.Copy(encryptedData, NonceSize, initializationVector, 0, Aes.BlockSize / 8);

        var ciphertextLength = encryptedData.Length - (NonceSize + Aes.BlockSize / 8);
        var ciphertext = new byte[ciphertextLength];
        Array.Copy(encryptedData, NonceSize + Aes.BlockSize / 8, ciphertext, 0, ciphertextLength);

        byte[] plaintext;
        using (var decryptor = new GcmBlockCipher(aes))
        {
            decryptor.Init(false, new AeadParameters(new KeyParameter(key), TagSize * 8, nonce, initializationVector));

            var decryptedDataLength = decryptor.GetOutputSize(ciphertext.Length);
            plaintext = new byte[decryptedDataLength];
            var len = decryptor.ProcessBytes(ciphertext, 0, ciphertext.Length, plaintext, 0);

            try
            {
                decryptor.DoFinal(plaintext, len);
            }
            catch (InvalidCipherTextException)
            {
                // Handle error here
            }
        }

        return plaintext;
    }

    private byte[] GenerateRandomBytes(int length)
    {
        using (var rng = new RNGCryptoServiceProvider())
        {
            var bytes = new byte[length];
            rng.GetBytes(bytes);
            return bytes;
        }
    }

    private byte[] ConcatenateByteArrays(params byte[][] arrays)
    {
        var resultLength = 0;

        foreach (var array in arrays)
        {
            resultLength += array.Length;
        }

        var result = new byte[resultLength];
        var offset = 0;

        foreach (var array in arrays)
        {
            Buffer.BlockCopy(array, 0, result, offset, array.Length);
            offset += array.Length;
        }

        return result;
    }
}
```
