Implementing this in pure C with all these functionalities would be quite challenging due to the complexity of the language itself and the lack of dynamic memory management, exceptions handling and multi-threading capabilities which are typically found in higher level languages. However, here is a basic example that shows how you might implement a recursive function to traverse an FSA.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Assuming we have the following structs
typedef struct State { 
    char *id; 
    int next[10]; // for simplicity, assuming max 10 pointers to next states
} State;

typedef struct FSA {
    int size;
    State *states;
} FSA;

// A dummy selector testing function. In real world scenario this would be more complex.
int matchSelector(char* stateId, char* selector) { 
    return strstr(stateId, selector) != NULL; 
}

// Recursive traversal and matching function
int* traverseFSA(State *currentState, FSA *fsa, char* selector, int nextIndex) {
    if (currentState == NULL || fsa == NULL) {
        return NULL; // End of tree or invalid input
    }

    // Check if current state matches the selector
    int match = matchSelector(currentState->id, selector);
    int* resultList = malloc(sizeof(int) * (match + fsa->size));
    int i = 0;

    if (match) { // If it does - add to the resulting list and continue with next states
        resultList[i++] = nextIndex;

        for (int j = 0; j < 10; j++) { // For simplicity, assuming max 10 pointers to next states
            if (currentState->next[j] != -1) { 
                State* nextState = &fsa->states[currentState->next[j]];

                int* sublist = traverseFSA(nextState, fsa, selector, currentState->next[j]);
                if (sublist != NULL) {
                    for (int k = 0; k < fsa->size && sublist[k] != -1; k++, i++) {
                        resultList[i] = sublist[k]; // Append the sublist to the main list
                    } 
                    free(sublist); // Free memory allocated for the sublist
                }   
            }
        }
    } else { // If it doesn't match - continue with next states without adding current state
        traverseFSA(&fsa->states[nextIndex + 1], fsa, selector, nextIndex + 1); 
    }    

    return resultList;
}
```

This function would recursively search the FSA and append matching state indexes to a dynamically allocated list. It uses a dummy `matchSelector` for simplicity but in a real-world scenario it would be more complex, considering different types of selectors (attribute, pseudo-class, user-defined) and handling of parsing errors or exceptions.

