void decompress_gzip(const char* in, const char* out) {
    FILE *input = fopen(in, "rb");
    gzFile output = gzopen(out, "wb");

    unsigned char buffer[1024];
    int num_read = 0;

    while((num_read = gzread(input, buffer, sizeof(buffer))) > 0) {
        fwrite(buffer, 1, num_read, output);
    }

    gzclose(output);
    fclose(input);
}

void process_logs(struct LogFile *log_files, int num_files) {
