    int num_files = sizeof(log_files) / sizeof(struct LogFile);

    for (int i = 0; i < num_files; i++) {
        decompress_gzip(log_files[i].filename, "temp.txt"); // decompress each file to a temporary location

        log_files[i].file = fopen("temp.txt", "r");
