        // Check if the user is authorized to update preferences
        if (!authResponse.getBody().isAuthorized()) {
            throw new RuntimeException("Unauthorized");
        }

        // Get current preference data from database
        String dbUrl = DB_SERVICE_URL + "/" + tenantId + "/preferences/" + userId;
        ResponseEntity<Preference> dbResponse = restTemplate.getForEntity(dbUrl, Preference.class);

        // Merge current preference data with the updates
