int validate_token(const char *json_string) {
    json_object *jobj = json_tokener_parse(json_string);

    if (jobj == NULL) return -1; // JSON parsing error

    json_object *token_type, *expires_in, *access_token, *refresh_token;
    json_bool token_type_exists = json_object_object_get_ex(jobj, "token_type", &token_type);
    json_bool expires_in_exists = json_object_object_get_ex(jobj, "expires_in", &expires_in);
    json_bool access_token_exists = json_object_object_get_ex(jobj, "access_token", &access_token);
    json_bool refresh_token_exists = json_object_object_get_ex(jobj, "refresh_token", &refresh_token);

    if (!token_type_exists || !expires_in_exists || !access_token_exists || 
        strcmp(json_object_get_string(token_type), "Bearer") || json_object_get_int(expires_in) <= 0 || 
        strlen(json_object_get_string(access_token)) == 0 || 
        (refresh_token_exists && strlen(json_object_get_string(refresh_token)) == 0)){
            json_object_put(jobj); // Clean up JSON object memory
            return -1; // Invalid token
    }

    // Token is validated successfully
    json_object_put(jobj); // Clean up JSON object memory
    return 0;
}
