using System;
using Azure.Storage.Blobs;
using System.Collections.Generic;

public class FileManagementSystem
{
    private readonly string storageAccountCredentials;
    private readonly string containerName;
    private BlobServiceClient blobServiceClient;
    private BlobContainerClient blobContainerClient;

    private Dictionary<string, CustomFileInfo> cache = new Dictionary<string, CustomFileInfo>();

    public FileManagementSystem(string storageAccountCredentials, string containerName)
    {
        this.storageAccountCredentials = storageAccountCredentials;
        this.containerName = containerName;

        InitializeClients();
    }

    private void InitializeClients()
    {
        blobServiceClient = new BlobServiceClient(storageAccountCredentials);
        blobContainerClient = blobServiceClient.GetBlobContainerClient(containerName);
    }

    public async Task UploadFileAsync(string filePath, string blobName, bool encrypt = false)
    {
        var blobClient = blobContainerClient.GetBlobClient(blobName);

        using FileStream uploadFileStream = File.OpenRead(filePath);
        await blobClient.UploadAsync(uploadFileStream, true);
        uploadFileStream.Close();
    }

    public async Task DownloadFileAsync(string filePath, string blobName)
    {
        var blobClient = blobContainerClient.GetBlobClient(blobName);

        BlobDownloadInfo download = await blobClient.DownloadAsync();

        using (FileStream downloadFileStream = File.OpenWrite(filePath))
        {
            await download.Content.CopyToAsync(downloadFileStream);
            downloadFileStream.Close();
        }
    }

    public async Task DeleteFileAsync(string blobName)
    {
        var blobClient = blobContainerClient.GetBlobClient(blobName);

        await blobClient.DeleteIfExistsAsync();
    }

    // ... other methods omitted for brevity

    public override string ToString()
    {
        return $"Storage Account: {storageAccountCredentials}, Container Name: {containerName}";
    }
}
```
