```python
import paramiko
import threading
from scp import SCPClient

class DeploymentManager:
    def __init__(self, hostnames):
        self.hosts = [{'ip': ip, 'client': paramiko.SSHClient()} for ip in hostnames]
        self.scps = []

    # connect to hosts and transfer files
    def deploy(self, jar_file):
        threads = []
        for host in self.hosts:
            t = threading.Thread(target=self._deploy, args=(host, jar_file))
            threads.append(t)
            t.start()

        # wait until all hosts have been updated
        for t in threads:
            t.join()

    def _deploy(self, host, jar_file):
        client = host['client']
        try:
            client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            client.connect(hostname=host['ip'], username='username', password='password')

            with SCPClient(client.get_transport()) as scp:
                scp.put(jar_file, '~/deployed-cache.jar')
        finally:
            client.close()
```
