Here's a code snippet that tries to achieve what you are asking for in C:

```C
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

FILE *logFile;
char logFileName[] = "logfile.txt";
pthread_mutex_t lock;

char* secureTrimAndAppendSlash(char* str, int limit){

    if (str == NULL || limit < 0) {
        return NULL;
    }

    pthread_mutex_lock(&lock);

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

    logFile = fopen(logFileName, "a");

    int len = strlen(str);
    char *end;

    for (end = str + strlen(str) - 1; end > str && isspace((unsigned char)*end); end--);
    end[1] = '\0';

    for (;isspace((unsigned char)*str); str++);

    int trimmed_length = end + 1 - str;

    if (trimmed_length > limit){
        fprintf(logFile, "[%s][ERROR]: Original string: '%s', size limit: %d, length of the trimmed string: %d, slash appended: no\n", timestamp, str, limit, trimmed_length);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char* result = malloc(trimmed_length + 2);
    strcpy(result, str);
    result[trimmed_length] = '/';
    result[trimmed_length + 1] = '\0';

    fprintf(logFile, "[%s][INFO]: Original string: '%s', size limit: %d, length of the trimmed string: %d, slash appended: yes\n", timestamp, str, limit, trimmed_length);

    pthread_mutex_unlock(&lock);
    fclose(logFile);

    return result;
}
```

The function secureTrimAndAppendSlash takes in a string and size limit as input. It first checks if the string or the limit is null or negative, returning NULL accordingly. Then it locks the thread to ensure only one thread can access the shared resource at a time (the log file). The trimming process then occurs by locating the end of the string (ignoring trailing whitespace), copying this part into another buffer (result) and appending '/' and '\0' characters. The function returns NULL if the length of the resulting string is greater than the specified limit, otherwise it returns the resultant trimmed string. After each operation, a message is written to the log file indicating whether a slash was appended or not along with the original string, size limit, and timestamp.

