typedef struct Token {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;  // may be NULL if not present in the response
} Token;

int validateToken(const char* jsonStr) {
    size_t flags = 0;
    json_error_t error;

    json_t *root = json_loads(jsonStr, 0, &error);
    if(!root) {
        fprintf(stderr, "error: on line %d: %s\n", error.line, error.text);
        return EXIT_FAILURE;
    }

    Token token = {NULL, 0, NULL, NULL};

    json_t *access_token, *expires_in, *token_type, *refresh_token;

    if(!json_unpack_ex(root, &error, flags, "{s:o, s:o, s:o, s?o}",
                      "access_token", &access_token,
                      "expires_in", &expires_in,
                      "token_type", &token_type,
                      "refresh_token", &refresh_token)) {
        fprintf(stderr, "error: on line %d: %s\n", error.line, error.text);
        json_decref(root);
        return EXIT_FAILURE;
    }

    token.access_token = (char*)json_string_value(access_token);
    if(!strcmp("Bearer", (char*)json_string_value(token_type))){
       printf("Invalid Token Type\n");
       json_decref(root);
       return EXIT_FAILURE; 
    }

    token.expires_in = (int)json_integer_value(expires_in);
    if(token.expires_in <= 0){
        printf("Invalid expires_in value\n");
       json_decref(root);
       return EXIT_FAILURE; 
    }

    token.token_type = (char*)json_string_value(token_type);
    if(!strcmp("Bearer", (char*)json_string_value(token_type))){
        printf("Invalid Token Type\n");
       json_decref(root);
       return EXIT_FAILURE; 
    }

    if(refresh_token) {
        token.refresh_token = (char*)json_string_value(refresh_token);
        if(!strlen(token.refresh_token)) {
            printf("Invalid refresh_token\n");
           json_decref(root);
           return EXIT_FAILURE; 
        }
    }

    // Further validation of token can be added here...

    json_decref(root);

    return EXIT_SUCCESS;
}
```
