```C#
using System;
using System.Collections.Generic;

public enum RangeType { Closed, Open, HalfOpen }

public class DynamicValueGenerator<T> where T : IComparable<T>
{
    private static readonly object Lock = new object();
    private Random _random = new Random();

    public T GenerateValue(RangeConfig<T> range)
    {
        lock (Lock) // Thread-safe seeding mechanism
        {
            switch (range.Type)
            {
                case RangeType.Closed: 
                    return (T)Convert.ChangeType(_random.Next((int)(dynamic)range.Min, (int)(dynamic)range.Max + 1), typeof(T));

                case RangeType.Open: 
                    return (T)Convert.ChangeType(_random.Next((int)(dynamic)range.Min + 1, (int)(dynamic)range.Max), typeof(T));

                case RangeType.HalfOpen: 
                    return (T)Convert.ChangeType(_random.Next((int)(dynamic)range.Min + 1, (int)(dynamic)range.Max + 1), typeof(T));
            }
        }

        throw new NotImplementedException("Unhandled range type");
    }
}

public class RangeConfig<T> where T : IComparable<T>
{
    public T Min { get; set; }
    public T Max { get; set; }
    public RangeType Type { get; set; }
}
```
This code defines a `DynamicValueGenerator` class that accepts a range configuration and generates a random value within the specified range. The generated values are thread-safe, preventing race conditions when accessing the random number generator. 

