using System;
using System.Xml;
using System.IO;

namespace XMLParsing
{
    public class XmlParser
    {
        private readonly string _xmlContent;

        public XmlParser(string xmlContent)
        {
            if (string.IsNullOrEmpty(xmlContent)) 
                throw new ArgumentException("XML content cannot be null or empty.");

            try
            {
                // Validate the XML document for well-formedness before parsing.
                var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Parse };
                using (var reader = XmlReader.Create(new StringReader(xmlContent), settings)) {}
            }
            catch (XmlException ex) 
            {
                throw new ArgumentException("Invalid XML content.", ex);
            }

            _xmlContent = xmlContent;
        }

        public XmlNode ParseWithXPath(string xpathExpression)
        {
            if (string.IsNullOrEmpty(xpathExpression)) 
                throw new ArgumentException("XPath expression cannot be null or empty.");

            var xmlDocument = new XmlDocument();
            try
            {
                // Load the XML document into an XmlDocument object for parsing with XPath.
                xmlDocument.LoadXml(_xmlContent);

                var nodes = xmlDocument.SelectNodes(xpathExpression);

                if (nodes == null || nodes.Count == 0) 
                    throw new ArgumentException("No element found.");

                if (nodes.Count > 1) 
                    throw new ArgumentException("Multiple elements found with the given name.");

                return nodes[0];
            }
            catch (XmlException ex) 
            {
                // Handle cases where the XPath expression is invalid.
                throw new ArgumentException("Invalid XPath expression.", ex);
            }
        }
    }
}
```
