```python
from flask import Flask, request, jsonify
from collections import defaultdict
import requests

app = Flask(__name__)
transaction_fields = defaultdict(list)
payment_gateways = ["Gateway1", "Gateway2"]  # Add other gateways as needed.

@app.route('/add-transaction', methods=['POST'])
def add_transaction():
    data = request.get_json()
    transaction_id = data["transaction_id"]
    field_name = data["field_name"]
    gateway = data["gateway"]

    if gateway in payment_gateways:
        transaction_fields[gateway].append({"transaction_id": transaction_id, "field_name": field_name})
        return jsonify({"message": f"Transaction {transaction_id} added with field {field_name}"}), 201
    else:
        return jsonify({"error": "Invalid payment gateway."}), 400

@app.route('/remove-transaction', methods=['DELETE'])
def remove_transaction():
    data = request.get_json()
    transaction_id = data["transaction_id"]
    field_name = data["field_name"]
    gateway = data["gateway"]

    if gateway in payment_gateways:
        for i, t in enumerate(transaction_fields[gateway]):
            if t["transaction_id"] == transaction_id and t["field_name"] == field_name:
                del transaction_fields[gateway][i]
                return jsonify({"message": f"Transaction {transaction_id} removed from {gateway}"}), 200
        return jsonify({"error": "No such transaction."}), 404
    else:
        return jsonify({"error": "Invalid payment gateway."}), 400

@app.route('/process-transaction', methods=['POST'])
def process_transaction():
    data = request.get_json()
    transaction_id = data["transaction_id"]
    field_name = data["field_name"]
    gateway = data["gateway"]

    if gateway in payment_gateways:
        for t in transaction_fields[gateway]:
            if t["transaction_id"] == transaction_id and t["field_name"] == field_name:
                # Process the transaction according to your specifications here.
                return jsonify({"message": f"Transaction {transaction_id} processed."}), 200
        return jsonify({"error": "No such transaction."}), 404
    else:
        return jsonify({"error": "Invalid payment gateway."}), 400

if __name__ == '__main__':
    app.run(debug=True)
```
