#include <iostream>
#include <vector>
#include <string>
#include <random>

// SubNode structure definition
struct SubNode {
    std::string str;
    double value;
};

// Node structure definition
struct Node {
    int value;
    std::vector<SubNode*> subNodes;
};

void initializeAndTestCharacterAttack(std::string moduleLabel, 
                                     // Assume testSuite is a vector of functions that take no arguments and return void.
                                     const std::vector<std::function<void()>>& testSuite,
                                     std::string loggingLevel, int cooldown, int memorySize) {
    try {
        // Dynamic memory allocation for Node array
        Node* nodeArray = new Node[memorySize];

        // Initialize random number generator
        std::random_device rd; 
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> disInt(-100, 100);
        std::uniform_real_distribution<double> disDouble(-1.0, 1.0);

        // Populate Node array with random integer values and initialize linked lists
        for (int i = 0; i < memorySize; ++i) {
            nodeArray[i].value = disInt(gen);

            // Allocate memory for linked list
            SubNode* subNodesList = new SubNode[1];
            subNodesList->str = "RandomString";
            subNodesList->value = disDouble(gen);

            nodeArray[i].subNodes.push_back(subNodesList);
        }

        // Run tests
        for (int i = 0; i < testSuite.size(); ++i) {
            try {
                if (loggingLevel == "info") std::cout << "Running test " << i+1 << "\n";

                testSuite[i](); // Call the ith test function
            } catch(const std::exception& e) {
                std::cerr << "Test failed: " << e.what() << '\n';
            }
        }

        // Free allocated memory
        for (int i = 0; i < memorySize; ++i) {
            delete[] nodeArray[i].subNodes[0];
        }

        delete[] nodeArray;
    } catch(const std::bad_alloc& e) {
        // Handle memory allocation errors gracefully
        std::cerr << "Memory allocation failed: " << e.what() << '\n';
    }
}
```

The above function initializes an array of `Node` structures with dynamically allocated memory, populates the array with random integer values and linked lists with a randomly generated string and double value using std::random library in C++11. It then runs each test from a vector of test functions. After the tests are complete, it frees all allocated memory to prevent leaks.

