Here's the code for `dynamicFileNameUpdate` function in C. 

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#define MAX_FILENAME_LEN 255

char* dynamicFileNameUpdate(const char *filename, const char *fileType, int version) {
    // Check if filename is null or empty
    if (filename == NULL || strlen(filename) == 0) {
        return NULL;
    }

    // Check if file type is valid
    if (fileType == NULL || strlen(fileType) == 0) {
        return NULL;
    }

    char* newFilename = malloc(MAX_FILENAME_LEN);
    if (newFilename == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Copy the filename to a buffer to manipulate it
    strncpy(newFilename, filename, MAX_FILENAME_LEN - 1);
    newFilename[MAX_FILENAME_LEN - 1] = '\0';

    char* lastDot = strrchr(newFilename, '.');
    if (lastDot != NULL) { // If a dot exists in the filename
        *lastDot = '\0';   // temporarily remove it

        // Check for versioning suffixes and update
        int hasVersion = 0;
        char* lastDigit = strrchr(newFilename, 'v');
        if (lastDigit != NULL && isdigit((unsigned char)*++lastDigit)) { 
            // If a version number exists, increment it
            *--lastDot = '\0'; // remove the filename extension temporarily for strstr operation

            long vNum = strtol(lastDigit, &lastDigit, 10);
            if (vNum > 0 && lastDigit != NULL && isdigit((unsigned char)*lastDigit)) { // validate version number
                hasVersion = 1;
                ++vNum;
            }
        }

        strcat(newFilename, "."); 
        if (hasVersion) {
            sprintf(lastDot, "v%ld", vNum);
        }
    }

    // Append the file type and terminate string
    strncat(newFilename, fileType, MAX_FILENAME_LEN - 1 - strlen(newFilename));
    newFilename[MAX_FILENAME_LEN - 1] = '\0';

    return newFilename;
}
```
This function allocates a string buffer and copies the filename into it. It then checks for an existing file extension, removes it temporarily to check for versioning suffixes, increments the version number if one exists, re-adds the file extension and terminates the string with null character at the end. 

Please remember that this function will only work properly when the filename is in the format of `filename.extension.vX` where X is a digit. If it doesn't fit this pattern, versioning or extension handling might not be accurate. Error checking and validation can be added to handle edge cases appropriately. 

Also note that you need to manually free() the memory allocated by malloc once it's no longer needed to prevent memory leaks.

