import asyncio
from abc import ABCMeta, abstractmethod
from collections import deque
import time

class PaymentGateway(metaclass=ABCMeta):
    @abstractmethod
    def process_transaction(self, amount, currency, details):
        pass

# Concrete implementation for Stripe payment gateway
class StripePayment(PaymentGateway):
    def __init__(self):
        self.stripe = StripeAPI()  # Assume this is the actual API provided by Stripe

    def process_transaction(self, amount, currency, details):
        return self.stripe.charge(amount=amount, currency=currency, source=details['source'])

# Concrete implementation for PayPal payment gateway
class PayPalPayment(PaymentGateway):
    def __init__(self):
        self.paypal = PayPalAPI()  # Assume this is the actual API provided by PayPal

    def process_transaction(self, amount, currency, details):
        return self.paypal.charge(amount=amount, currency=currency, source=details['source'])

# A rate-limiting middleware for payment gateways
class RateLimiter:
    def __init__(self, limit, period):
        self._window = deque(maxlen=period)
        self._limit = limit

    def hit(self):
        now = time.time()
        while self._window and self._window[0] <= (now - 1):
            self._window.popleft()
        if len(self._window) >= self._limit:
            raise Exception("Rate limit exceeded")
        else:
            self._window.append(now)

# An asynchronous payment processor
class AsyncPaymentProcessor:
    def __init__(self, gateway):
        self._gateway = gateway

    async def process_payment(self, amount, currency, details):
        return await asyncio.get_running_loop().run_in_executor(None, self._gateway.process_transaction, amount, currency, details)
