<?php
function generateSecureToken($length = 32, $characterset = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ', $hashAlgo = "bcrypt", $password = null) {
    if ($length <= 0 || empty($characterset)) {
        throw new Exception('Invalid parameters');
    }

    $token = '';
    $maxIndex = strlen($characterset) - 1;

    for ($i = 0; $i < $length; $i++) {
        $token .= $characterset[random_int(0, $maxIndex)];
    }

    // Store the token into a session variable
    if (!isset($_SESSION)) { 
        session_start(); 
    } 
    $_SESSION['secureToken'] = $token;

    // Also handle password hashing if provided
    if ($password !== null) {
        $options = [];

        switch($hashAlgo){
            case 'bcrypt':
                $options['cost'] = 12;
                break;
            case 'Argon2id':
                $options['memory_cost'] = 65536; // 64Mb
                $options['time_cost']   = 4;
                $options['threads']    = 1;
                break;
        }

        $hashedPassword = password_hash($password, constant("PASSWORD_" . strtoupper($hashAlgo)), $options);
        $_SESSION['hashedPassword'] = $hashedPassword;
    }

    return $token;
}
?>
