```python
import json
import threading
from abc import ABC, abstractmethod
from functools import lru_cache

class ProductSerializable(ABC):
    @abstractmethod
    def __init__(self, data):
        pass

    @staticmethod
    def parse_json(json_string):
        data = json.loads(json_string)
        product_type = data['productType']

        if product_type not in ProductSerializable._registry:
            raise ValueError("Unsupported product type")

        return ProductSerializable._registry[product_type](data)

    @staticmethod
    def register(product_type, factory):
        if product_type in ProductSerializable._registry:
            print("Warning: overriding existing class for", product_type)

        ProductSerializable._registry[product_type] = factory

    @staticmethod
    def _class_register():
        return {}

ProductSerializable.register('Electronics', ElectronicsFactory)
# Similar register statements for other product types

@lru_cache(maxsize=None)
def load_product(file_name):
    try:
        with open(file_name, 'r') as file:
            data = json.load(file)
            return ProductSerializable.parse_json(data)
    except Exception as e:
        print("Error while loading product", file_name, ":", str(e))

def load_products(*files):
    threads = [threading.Thread(target=load_product, args=[file]) for file in files]

    for thread in threads:
        thread.start()

    # Handle errors and fallback mechanism for failed products
    for thread in threads:
        thread.join()
```
