```csharp
using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Diagnostics;
using System.Net.Http;
using Newtonsoft.Json;
using RestSharp;

public abstract class RandomGeneratorBase<T> where T : IComparable, IConvertible, IEquatable<T>, IFormattable
{
    protected static HttpClient httpClient = new HttpClient();

    private const string API_URL = "http://config.server/api";
    private static RestClient restClient;
    private static readonly ConcurrentDictionary<Type, object> Locks = new ConcurrentDictionary<Type, object>();

    protected abstract T GenerateValue(Random random);

    public T Next()
    {
        var typeLock = Locks.GetOrAdd(typeof(T), new object());

        lock (typeLock)
        {
            return GenerateValue(new Random());
        }
    }
}

public class DynamicRandomGenerator<T> : RandomGeneratorBase<T> where T: IComparable, IConvertible, IEquatable<T>, IFormattable 
{
    private static readonly Stopwatch stopwatch = new Stopwatch();

    private const int CACHE_LIFETIME = 1000; // ms
    private T cachedValue;
    private DateTime lastComputedTime = DateTime.MinValue;

    protected override T GenerateValue(Random random)
    {
        if (lastComputedTime != null && stopwatch.ElapsedMilliseconds - lastComputedTime.Ticks < CACHE_LIFETIME)
            return cachedValue;

        // Call the configuration server to get updated values here...
        var request = new RestRequest(API_URL, Method.GET);

        var response = restClient.Execute<JsonData>(request);

        if (response.IsSuccessful)
        {
            var data = JsonConvert.DeserializeObject<Tuple<T, T>>(response.Content); // Range specification here

            cachedValue = RandomInRange(random, data.Item1, data.Item2);
            lastComputedTime = DateTime.Now;
        }

        return cachedValue;
    }

    private static T RandomInRange(Random random, T minValue, T maxValue) 
    {
        var minValueDouble = Convert.ToDouble(minValue);
        var maxValueDouble = Convert.ToDouble(maxValue);

        var range = maxValueDouble - minValueDouble;  

        var sample = random.NextDouble();
        var scaled = sample * range;
        var shifted = scaled + minValueDouble; 

        return (T)Convert.ChangeType(shifted, typeof(T));
    }
}
```
