    private final SSLSocketFactory sslSocketFactory;

    public RemoteServerConnectionManager(SSLSocketFactory sslSocketFactory) {
        this.sslSocketFactory = sslSocketFactory;
    }

    public void connectToRemoteServer(String host, int port) throws IOException {
