use clap::Parser;
use log::{info, warn};
use std::fs::File;
use std::io::prelude::*;
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[clap(author, version, about, long_about = None)]
struct Args {
    /// Path to the directory to traverse.
    #[clap(short, long)]
    dir: String,
    /// Output file name.
    #[clap(short, long)]
    output: String,
    /// File extension to process.
    #[clap(short, long)]
    ext: String,
}

fn main() {
    let args = Args::parse();
    generate_llvm(&args);
}

fn generate_llvm(args: &Args) {
    for entry in WalkDir::new(&args.dir).into_iter().filter_map(Result::ok) {
        if let Some(ext) = entry.extension() {
            if ext == args.ext {
                info![entry.path];
                match File::open(entry.path()) {
                    Ok(mut file) => {
                        let mut s = String::new();
                        match file.read_to_string(&mut s) {
                            Err(_e) => warn![format!"Error reading {}", entry.path().display()],
                            Ok(_n) => todo![s contains the content of the file, you would parse it here and generate LLVM IR]
                        }
                    },
                    Err(err) => warn![format!"Failed to open {}: {}", entry.path().display(), err],
                }
            }
        }
    }
}
