```python
import threading
from queue import Queue
import requests
import time

class Task:
    def __init__(self, id):
        self.id = id

class DynamicTaskQueueManager(threading.Thread):
    def __init__(self, task_queue, rest_api_url, auth_header):
        threading.Thread.__init__(self)
        self.task_queue = task_queue
        self.rest_api_url = rest_api_url
        self.auth_header = auth_header
        # Add more attributes as necessary for your system requirements

    def run(self):
        while True:
            if not self.task_queue.empty():
                task = self.task_queue.get()
                try:
                    response = requests.post(f'{self.rest_api_url}/tasks/{task.id}', headers=self.auth_header)
                    if response.status_code != 200:
                        raise Exception('Failed to process task')
                except Exception as e:
                    print(f'Error processing task {task.id}: {str(e)}')
            time.sleep(1)  # Sleep for a while to avoid making too many requests in a short period

    def add_task(self, task):
        self.task_queue.put(task)

# Usage:
queue = Queue()
manager = DynamicTaskQueueManager(queue, 'http://your-rest-api-url', {'Authorization': 'Bearer your-token'})
manager.start()  # Start the task processing thread

for i in range(10):
    manager.add_task(Task(i))
```
