Creating a full-fledged JSON validator in C that parses the schema from string representation involves many factors like memory management, error handling, efficiency of validation algorithm, etc., which is beyond the scope of this platform. However, I can provide you an example of how you could begin to approach it using a library such as cJSON:

```C
#include "cjson/cJSON.h"
#include <string.h>
#include <stdbool.h>

// Predefined schema fields
const char* REQUIRED_FIELDS[] = { "access_token", "expires_in", "token_type" };
const size_t NUMBER_OF_REQUIRED_FIELDS = sizeof(REQUIRED_FIELDS) / sizeof(char*);

bool validateToken(const char *jsonString) {
    // Parse the json string
    cJSON *parsedJson = cJSON_Parse(jsonString);
    if (parsedJson == NULL) {
        printf("Failed to parse JSON: %s\n", cJSON_GetErrorPtr());
        return false;
    }

    // Validate the required fields
    for (size_t i = 0; i < NUMBER_OF_REQUIRED_FIELDS; ++i) {
        cJSON *field = cJSON_GetObjectItemCaseSensitive(parsedJson, REQUIRED_FIELDS[i]);
        if (!cJSON_IsString(field) || (field->valuestring == NULL)) {
            printf("Missing or invalid '%s' field\n", REQUIRED_FIELDS[i]);
            cJSON_Delete(parsedJson);
            return false;
        }
    }

    // Additional constraints checks
    const char *accessToken = cJSON_GetObjectItemCaseSensitive(parsedJson, "access_token")->valuestring;
    if (strlen(accessToken) < 8) {
        printf("'access_token' must be at least 8 characters long\n");
        cJSON_Delete(parsedJson);
        return false;
    }

    // Check if 'refresh_token' is present and it is not null
    cJSON *refreshTokenField = cJSON_GetObjectItemCaseSensitive(parsedJson, "refresh_token");
    if (cJSON_IsString(refreshTokenField) && refreshTokenField->valuestring != NULL) {
        const char* refreshToken = refreshTokenField->valuestring;
        if (strlen(refreshToken) < 16) {
            printf("'refresh_token' must be at least 16 characters long\n");
            cJSON_Delete(parsedJson);
            return false;
        }
    } else if (!cJSON_IsNull(refreshTokenField)) {
        printf("Invalid 'refresh_token' field\n");
        cJSON_Delete(parsedJson);
        return false;
    }

    // Check expires_in value
    int expiresIn = cJSON_GetObjectItemCaseSensitive(parsedJson, "expires_in")->valueint;
    if (expiresIn > 3600) {
        printf("'expires_in' must be less than or equal to 3600 seconds\n");
        cJSON_Delete(parsedJson);
        return false;
    }

    // Clean up and return true if everything is fine
    cJSON_Delete(parsedJson);
    return true;
}
```
This code does a basic job of validating JSON objects against the specified schema in C. However, this may need to be enhanced for production-level use cases considering performance implications, error handling and edge case scenarios. It also assumes that the library cJSON is available and correctly linked in your build environment.

