```java
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class FileProcessor {
    private final static int CHUNK_SIZE = 8 * 1024 * 1024; // Adjust as needed, this is just an example

    public CompletableFuture<Void> processLargeFileAsync(String filePath, Function<byte[], Object> customFunction) {
        return CompletableFuture.runAsync(() -> {
            try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(filePath))) {
                byte[] buffer = new byte[CHUNK_SIZE];
                int bytesRead;

                while ((bytesRead = bis.read(buffer)) != -1) {
                    // Process each chunk with custom function
                    Object result = customFunction.apply(Arrays.copyOfRange(buffer, 0, bytesRead));

                    // Call external REST API for metadata lookup and handle errors
                    try {
                        URL url = new URL("http://your_api_url");
                        HttpURLConnection conn = (HttpURLConnection) url.openConnection();

                        conn.setRequestMethod("POST");
                        conn.setDoOutput(true);

                        // Write chunk data to request body
                        try (DataOutputStream wr = new DataOutputStream(conn.getOutputStream())) {
                            wr.write(Arrays.copyOfRange(buffer, 0, bytesRead));
                        }

                        if (conn.getResponseCode() == 429) { // Rate limit exceeded error
                            throw new IOException("Rate limit exceeded");
                        } else if (conn.getResponseCode() != HttpURLConnection.HTTP_OK) { 
                            throw new IOException("Metadata lookup failed with response code: " + conn.getResponseCode());
                        }
                    } catch (IOException e) {
                        // Handle error appropriately - logging, retry logic, etc.
                        System.err.println("Error processing file chunk: " + e);
                    }
                }
            } catch (FileNotFoundException fnf) {
                // Handle invalid file path here
            } catch (IOException io) {
                // Handle other IO errors here
            }
        });
    }
}
```
