```python
import json
import yaml
import os
from threading import Lock
from multiprocessing import Manager, Process
import time
import requests
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class ConfigManager:
    def __init__(self):
        self.lock = Lock()
        manager = Manager()
        self.config_cache = manager.dict()
        self.file_paths = [] # add your file paths here

    def load_from_env(self, key):
        value = os.getenv(key)
        if not value:
            raise KeyError(f'Environment variable {key} not set')
        return value

    def load_config(self, filepath):
        with self.lock:
            extension = os.path.splitext(filepath)[1].lower()
            if extension == '.json':
                loader = json
            elif extension in ('.yaml', '.yml'):
                loader = yaml
            else:
                raise ValueError(f"Unsupported file format {extension}")

        try:
            with open(filepath) as f:
                return loader.load(f)
        except FileNotFoundError:
            raise
        except Exception as e:
            raise RuntimeError(f'Failed to load config from {filepath}: {str(e)}')

    def get_config(self, key):
        try:
            return self.load_from_env(key)
        except KeyError:
            pass

        with self.lock:
            if key in self.config_cache:
                print("Loading config from cache...")
                return self.config_cache[key]

        for filepath in self.file_paths:
            try:
                config = self.load_config(filepath)
                with self.lock:
                    self.config_cache[key] = config
                print("Loaded config from file...")
                return config
            except Exception as e:
                print(f"Failed to load config from {filepath}: {str(e)}")

        try:
            response = requests.get('API_GATEWAY') # replace with your API Gateway URL
            if response.status_code == 200:
                return response.json()
        except Exception as e:
            print(f"Failed to load config from API gateway: {str(e)}")

        raise KeyError(f'Config for key {key} not found')

    def start_observer(self):
        class ConfigHandler(FileSystemEventHandler):
            def on_modified(self, event):
                print(f"Detected changes in file: {event.src_path}, reloading...")
                self.config_cache.clear() # remove all entries from cache after modification

        observer = Observer()
        for filepath in self.file_paths:
            observer.schedule(ConfigHandler(), path=filepath, recursive=False)
        observer.start()

    def cleanup(self):
        print("Cleaning up...")
        with self.lock:
            self.config_cache.clear() # clear cache on exit

if __name__ == "__main__":
    manager = ConfigManager()
    worker1 = Process(target=manager.get_config, args=('mykey',))
    worker2 = Process(target=manager.get_config, args=('mykey',))

    worker1.start()
    time.sleep(5) # wait for modifications in config files
    worker2.start()

    worker1.join()
    worker2.join()
``` 

