use std::fs;
use std::time::{Duration, Instant};
use rustc_driver::session::Session;
use hyper::Client;
use serde::Serialize;

#[derive(Debug, Serialize)]
pub struct CompilationResult {
    pub name: String,
    pub exit_code: i32,
    pub duration: Duration,
    pub peak_rss: u64, // in bytes
}

fn compile(src: &str) -> Result<CompilationResult, Box<dyn std::error::Error>> {
    let start = Instant::now();

    // create a new rustc session for this submodule
    let mut session = Session::new();

    let output_dir = "/path/to/output";
    fs::create_dir_all(output_dir)?;
    session.set_libroot("/path/to/rustc");
    session.run_compiled_filenamed_stdin(src, output_dir)
        .map_err(|e| format_err("Failed to compile submodule", e))?;

    let duration = start.elapsed();

    // get peak resident set size (RSS) from system
    let peak_rss = sysinfo::SystemExt::new().unwrap().memory().peak_rss();

    Ok(CompilationResult {
        name: src.to_string(),
        exit_code: session.exit_code,
        duration,
        peak_rss,
    })
}

