        Generator() {
            // seed the random number generator with current time and additional entropy
            auto now = std::chrono::high_resolution_clock::now();
            auto duration = now.time_since_epoch();
            uint64_t secs = std::chrono::duration_cast<std::chrono::seconds>(duration).count();
            rng.seed((uint32_t)secs);
        }
        ~Generator() {}

        static void regenerateSessionID() {
            uint64_t random_value = rng();
            std::string new_session_id = base64_encode(random_value, 22); // Assuming a function to convert long to base64 string of certain length

            while (cache.find(new_session_id) != cache.end()) {
                random_value = rng();
                new_session_id = base64_encode(random_value, 22);
            }

            // Add the generated session id to the cache
