                    regenerateSessionID();
                }
            } catch (std::exception& e) {
                std::cerr << "Failed to generate unique session id: " << e.what() << "\n";
            }
        }

        static void switchToAlternativeStrategy() {
            // Implement a fallback strategy if the primary method fails (like using UUIDs)
            boost::uuids::uuid uuid = boost::uuids::random_generator()(); 
            std::string alternative_id = boost::uuids::to_string(uuid);

