                uuid = boost::uuids::random_generator()();
                alternative_id = boost::uuids::to_string(uuid);
            }

            // Add the generated session id to the cache
            cache.insert(alternative_id);
        }

    };

    std::mt19937_64 Generator::rng; 
    std::set<std::string> Generator::cache;
