        return -EINVAL;
    }

    int res = sem_wait(&(wrapper->sem));
    if (res != 0) 
    {
        perror("Semaphore acquire failed");
        return errno;
    }

    // Log the operation. This needs to be replaced with actual logging system calls
    printf("Semaphore acquired\n");
    return 0;
}

int releaseSemaphore(semaphoreWrapper* wrapper) 
{
    if (wrapper == NULL) 
