using System;
using System.Text;
using Newtonsoft.Json;
using BCrypt.Net;
using Konscious.Security.Cryptography;
using System.IO;

public class PasswordHasher
{
    private Argon2id argon2 = new Argon2id(Encoding.UTF8.GetBytes("randomsalt"));

    public string HashPasswordSHA256(string password)
    {
        using (var sha256 = System.Security.Cryptography.SHA256.Create())
        {
            var hashedBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
            return BitConverter.ToString(hashedBytes).Replace("-", "").ToLower();
        }
    }

    public string HashPasswordBCrypt(string password)
    {
        return BCrypt.Net.BCrypt.HashPassword(password);
    }

    public string HashPasswordArgon2id(string password, out byte[] saltBytes)
    {
        // Generate a 16 bytes salt
        saltBytes = new byte[16];
        using (var rng = new System.Security.Cryptography.RNGCryptoServiceProvider())
            rng.GetBytes(saltBytes);

        return Convert.ToBase64String(argon2.GetBytes(16, password, saltBytes));
    }
}
