Below is an example implementation of the `AdvancedCustomRandomGenerator` class in C#. It's important to note that this code doesn't fully meet all requirements mentioned because Unity doesn't provide a .Net random number generator equivalent to `UnityEngine.Random.Seed`. The following class provides a simple solution for floating-point and integer types:

```csharp
using System;
using System.Threading;
using System.Collections.Generic;

public class AdvancedCustomRandomGenerator<T> where T : struct, IComparable<T>
{
    private Random _random;

    public AdvancedCustomRandomGenerator(int seed)
    {
        _random = new Random(seed);
    }

    // For integer types
    public T Next()
    {
        if (typeof(T) == typeof(int))
            return (T)(object)_random.Next();
        else if (typeof(T) == typeof(float))
            return (T)(object)_random.NextDouble();

        throw new NotImplementedException("Type not implemented");
    }

    // For multi-dimensional ranges
    public T[] CustomRange(List<List<T>> rangeLimits) 
    {
        List<T> result = new List<T>();

        foreach (var limit in rangeLimits)
            result.Add((T)(dynamic)NextInRange(limit));

        return result.ToArray();
    }

    private T NextInRange(List<T> rangeLimit) 
    {
        if (rangeLimit[0].CompareTo(rangeLimit[1]) > 0)
            throw new ArgumentException("Invalid range limits");

        double sample = _random.NextDouble();
        double scaledSample = sample * (dynamic)rangeLimit[1] + (1 - sample) * (dynamic)rangeLimit[0];

        return (T)(object)scaledSample;
    }
}
```
This code uses a generic type parameter `<T>` for the random number type. The class initializes an instance of `System.Random` with the provided seed, and then provides methods to generate random values within a specified range based on this instance. For multi-dimensional ranges, it generates multiple random values and returns them as an array.

Here is a PHP implementation for the first part of your task. It generates a secure random string using the cryptographically secure `random_bytes` function and then hashes it using `password_hash` with bcrypt algorithm for storing in session system. 

```php
<?php
class TokenGenerator {
    private $tokenLength;
    private $charSet;
    private $sessionTime;

    public function __construct(int $len, string $set = 'alphanumeric', int $time = 3600) {
        $this->tokenLength = $len;
        $this->charSet = $set;
        $this->sessionTime = $time;
    }

    public function generateToken() : array {
        if ($this->charSet === 'alphanumeric') $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
        elseif ($this->charSet === 'alphanumeric_special') $characters = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ@#%&*';
        else throw new Exception('Invalid character set.');

        $randomString = '';

        for ($i = 0; $i < $this->tokenLength; $i++) {
            $index = random_int(0, strlen($characters) - 1);
            $randomString .= $characters[$index];
        }

        $hashedToken = password_hash($randomString, PASSWORD_BCRYPT);

        return ['token' => $randomString, 'hashedToken' => $hashedToken, 'sessionTime' => time() + $this->sessionTime];
    }
}
?>
