const fs = require('fs');

function readAsync(filePath) {
    return new Promise((resolve, reject) => {
        fs.readFile(filePath, 'utf8', (err, data) => {
            if (err) {
                switch (err.code) {
                    case 'ENOENT':
                        reject('File not found');
                        break;
                    case 'EACCES':
                        reject('Permission denied');
                        break;
                    default:
                        reject('Unknown error while reading the file');
                }
            } else {
                resolve(data);
            }
        });
    });
}
