async function processConfigFiles(dir, defaultValues = {}, fileTypes = ['.json']) {
  let configs = {};

  try {
    const files = await fs.readdir(dir);

    for (let i = 0; i < files.length; i++) {
      const filePath = path.join(dir, files[i]);

      if (!fileTypes.includes(path.extname(files[i]))) continue; //skip non-json files

      try {
        const fileData = await readFile(filePath);
        configs = _.merge(configs, fileData);
      } catch (err) {
        logger.error(`Failed to process file: ${filePath} with error: ${err}`);
      }
    }
  } catch (err) {
    logger.error(`Failed to read directory: ${dir} with error: ${err}`);
    throw err;
  }

  return _.merge({}, defaultValues, configs); //merge default values into the configuration object
}

module.exports = processConfigFiles;
```

This module reads all files in a directory asynchronously and merges them into a single object. It uses lodash's `_.merge` function to merge objects, which is safe for deep nested configurations. 

