```c
#include <stdio.h>
#include <string.h>
#include <curl/curl.h>

size_t writeCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((size*)userp)->write = (char*)realloc(((size*)userp)->response, ((size*)userp)->size + size + 1);
    if(((size*)userp)->write == NULL) {
        printf("Not enough memory\n");
        return 0;
    }
    ((size*)userp)->response = ((size*)userp)->write;
    memcpy(&((size*)userp)->response[((size*)userp)->size], contents, size * nmemb);
    ((size*)userp)->size += size * nmemb;
    ((size*)userp)->response[((size*)userp)->size] = '\0';
    return size * nmemb;
}

int main() {
    CURL* curl;
    CURLcode res;

    struct curl_slist* headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "charsets: utf-8");

    curl = curl_easy_init();

    if(curl) {
        struct size s;
        s.response = malloc(1);
        s.size = 0;

        curl_easy_setopt(curl, CURLOPT_URL, "https://api.github.com/some/endpoint");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("%lu bytes retrieved\n%s", (long)s.size, s.response);
        }

        free(s.response);
        curl_easy_cleanup(curl);
    }

    return 0;
}
```
