#include <forward_list>
#include <string>

void insertAndAttack(std::forward_list<std::string>& fwdList, std::string str1, 
                      std::string str2, int times = 1) {
    auto it = std::find(fwdList.begin(), fwdList.end(), str1);

    if (it != fwdList.end()) { // string found in list
        for (int i = 0; i < times; ++i) 
            fwdList.insert_after(it, str2);  
    } else { //string not found in list
         fwdList.push_front(str2); // assuming you want to insert at the end of the list
     }    
}
