```rust
use std::fs;
use std::sync::{Mutex};
use std::time::Instant;
use git2::Repository;
use std::process::Command;

static LOGGER: Mutex<Vec<String>> = Mutex::new(vec![""]);

fn compile_report(dir: &str) -> Result<(), Box<dyn std::error::Error>> {
    let start = Instant::now();

    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        if let Some(file_type) = entry.path().extension() {
            if file_type == "rs" {
                let file_name = &entry.path();

                // Compile the Rust file using cargo command and collect its output
                let compilation_output = Command::new("cargo")
                    .args(&["build", "--release", "--message-format=json"])
                    .current_dir(dir)
                    .output()?;

                // Check if there is an error while compiling the file 
                if !compilation_output.status.success() {
                    let error = match String::from_utf8(compilation_output.stderr) {
                        Ok(s) => s,
                        Err(_) => "Compilation failed with invalid UTF-8".to_string(),
                    };

                    LOGGER.lock().unwrap().push(error);
                }
            }
        }
    }

    let repo = Repository::discover(&dir)?;
    match repo.head() {
        Ok(head) => head.peel_to_commit().map(|c| c.summary()),
        Err(_) => String::new(),
    };

    // Measure the compilation time and memory usage 
    let duration = start.elapsed();
    let mem_usage: u64 = std::mem::size_of_val(repo);

    println_report(&duration, mem_usage, &LOGGER.lock().unwrap());

    Ok(())
}

fn print_report(duration: &std::time::Duration, memory: u64, logger: &Vec<String>) {
    println_logger(&logger);

    println_duration(&duration);

    println_memory(&memory);
}

// Helper function to print the details of compilation 
fn println_report(duration: &std::time::Duration, memory: u64, logger: &Vec<String>) {
    for log in logger {
        println_logger(log);
    }

    println_duration(&duration);

    println_memory(&memory);
}

// Helper function to print compilation duration 
fn println_duration(duration: &std::time::Duration) {
    println_string("Compilation Duration :", &format_args_duration(&duration));
}

// Helper function to print memory usage 
fn println_memory(memory: &u64) {
    println_string("Memory Usage :", &format_args_u64(&memory));
}

// Helper function to print logger details 
fn println_logger(logs: &Vec<String>){
    for log in logs{
        println_string("Compilation Log :", &log.as_str());
    }
}

```
