using UnityEngine;
using System;
using System.Threading.Tasks;
using System.Collections.Generic;

public class AdvancedCustomRandomGenerator
{
    private Dictionary<int, int> cache = new Dictionary<int, int>();
    private static readonly object _lock = new object();
    private const int MAX_CACHE = 1000;
    private bool useExternalSystems = false; // Set this to true if you want to integrate with an external system.

    public Tuple<int, int>[] CustomRange(Tuple<int, int>[] ranges)
    {
        if (ranges == null || ranges.Length == 0) throw new ArgumentException("Invalid range provided");

        var result = new Tuple<int, int>[ranges.Length];
        for (var i = 0; i < ranges.Length; ++i)
        {
            if (ranges[i] == null || ranges[i].Item1 > ranges[i].Item2) throw new ArgumentException($"Invalid range at index: {i}");

            result[i] = GetRandomIntInRange(ranges[i]);
        }

        return result;
    }

    private Tuple<int, int> GetRandomIntInRange((int min, int max) range)
    {
        var cacheKey = new[] {range.min, range.max}.GetHashCode(); // Use a hash of the range as the key for caching.

        lock (_lock)
        {
            if (cache.ContainsKey(cacheKey)) return new Tuple<int, int>(cache[cacheKey], cache[cacheKey]); // Return cached value if exists.

            var randomValue = UnityEngine.Random.Range(range.min, range.max); // Generate a new random value.

            cache[cacheKey] = randomValue;
        }

        return new Tuple<int, int>(randomValue, randomValue);
    }

    public void ClearCache() => cache.Clear();

    private async Task RotateSeedAsync()
    {
        var currentSeed = UnityEngine.Random.seed; // Get the current seed value.

        while (true)
        {
            if (cache.Count >= MAX_CACHE) ClearCache(); // If cache reaches max size, clear it.

            await Task.Delay(TimeSpan.FromMinutes(1)); // Wait for 1 minute before rotating seed.

            UnityEngine.Random.InitState((int)(DateTime.UtcNow - new DateTime(1970, 1, 1)).TotalSeconds); // Rotate the seed value using current time as a seed.
        }
    }
}
```
This class uses dictionary to store previously generated values and UnityEngine's Random.Range function for random number generation. It also has a mechanism to clear cache after reaching a certain size limit, and rotates the seed periodically. Note that this is a basic implementation which doesn't include external system integration, XML configuration file handling and custom distribution functions as mentioned in your requirements.

