const axios = require('axios');
const morgan = require('morgan');
const express = require('express');
const bodyParser = require('body-parser');
const app = express();

// Middleware for logging
app.use(morgan('combined'));

app.use(bodyParser.json());

let bufferArray = [];

app.post('/aggregate', async (req, res) => {
    const sources = req.body.sources; // This should be an array of URLs or any other sources

    try{
        for(const source of sources){
            let response = await axios({url:source, method:'GET',responseType:'stream'});

            response.data.on('data', (chunk) => { 
                bufferArray.push(Buffer.from(chunk)); // Here you can manage concurrency through the 'bufferArray' synchronization
            });
        }

        let concatenatedBuffers = Buffer.concat(bufferArray);
        res.send({data: concatenatedBuffers});
    }catch(error){
        console.log('Error during data aggregation', error); // You can use more sophisticated logging and monitoring system here
    }
});

app.listen(3000, () => {
  console.log("Data aggregation service running on port 3000");
});
