<?php 
require 'RateLimiter.class.php'; // assuming you have a RateLimiter library
require 'Database.class.php';   // assuming you have a Database class
require 'LoggingService.class.php';  // assuming you have a LoggingService class
require 'EmailNotificationService.class.php'; // assuming you have an EmailNotificationService class
require 'CacheManager.class.php'; // assuming you have a CacheManager class

function updateClinicStatus($clinicId, $newStatus, $lastModifiedIp) {
    try{
        $limiter = new RateLimiter(); 
        if(!$limiter->validateRequest("update_status", $lastModifiedIp)) {
            throw new Exception('Rate limit exceeded for this IP');
        }

        $db = new Database(); // assuming you have a Database class with methods like beginTransaction(), commit(), rollback() etc.
        $logService = new LoggingService();
        $emailNotifier = new EmailNotificationService();
        $cacheManager = new CacheManager();

        $oldStatus = $db->getClinicStatus($clinicId); // Get current status from database 
        if (empty($oldStatus)) {
            throw new Exception('Invalid clinic ID');
        }

        $logService->info("Updating status for clinic $clinicId. Old status: $oldStatus, New status: $newStatus.");

        // Begin transaction 
        $db->beginTransaction();
        try{
            $updateResult = $db->updateClinicStatus($clinicId, $newStatus);
            if(!$updateResult){
                throw new Exception('Update failed');
            }

            $emailNotifier->notifyAdminOnChange($clinicId, $oldStatus, $newStatus, 'status_change', $lastModifiedIp); // Send email notification to clinic admin 
            $cacheManager->invalidateCacheForClinic($clinicId); // Invalidate cache for this clinic

            // Commit transaction
            $db->commit();

        } catch(Exception $e){
            $db->rollback(); // Roll back if there was an error
            throw new Exception('Update failed: ' . $e->getMessage());
        }   

    } catch(Exception $e) {
        $logService->error("Failed to update clinic status. Error: " . $e->getMessage());
        throw new Exception('An error occurred while updating clinic status.'); // Rethrow with better message 
    } finally {
        $limiter->incrementRequestCount("update_status", $lastModifiedIp);
    }
}
?>
```

