```jsx
import React, { Component } from 'react';
import socketIOClient from "socket.io-client";
const ENDPOINT = "http://localhost:4001";
let socket;

class App extends Component {
  constructor() {
    super();
    this.state = {
      endpoint: ENDPOINT,
      color: 'info',
      users: [],
      messages: [],
      message: ""
    };

    this.sendMessage = this.sendMessage.bind(this);
  }

  componentDidMount() {
    // Connect to the WebSocket server
    socket = socketIOClient(ENDPOINT);

    socket.on("message", (data) => {
      console.log('Data: ', JSON.parse(data));
      this.setState({ messages: [...this.state.messages, data] });
    })
  }

  sendMessage() {
    const newMessages = this.state.message;
    socket.emit("sendMessage", newMessages);
  }

  render() {
    return (
      <div>
        <input type='text' onChange={e => this.setState({ message: e.target.value })} />
        <button onClick={this.sendMessage}>Send</button>
        {this.state.messages.map((item, index) => 
          <p key={index}>{item}</p>
        )}
      </div>
    );
  }
};
export default App;
```
This is a very basic example of how you can set up WebSockets in React. In this case, each time the user types something and presses send, it gets sent to all other connected clients.

