#include <openssl/evp.h> //OpenSSL library
#include <stdlib.h>
#include <string.h>

typedef struct {
    const char *name;
    const EVP_MD *(*func)();
} HashFunction;

HashFunction* getAvailableHashFunctions() {
    OpenSSL_add_all_digests(); //Initializes all hash functions

    int num_functions = EVP_get_digestnum(); //Gets the number of available hash functions

    HashFunction *functions = malloc(sizeof(HashFunction) * num_functions);
    if (functions == NULL) {
        return NULL;
    }

    int i = 0;
    for (; i < num_functions; ++i) { //Iterates over each hash function
        const EVP_MD *md = EVP_get_digestbyname(OBJ_nid2sn(EVP_get_digestbynumber(i))); 

        if (md != NULL) {
            functions[i].name = OBJ_nid2ln(EVP_MD_type(md)); //Gets the name of the hash function
            functions[i].func = md; //Assigns the implementation function to the struct
        } else {
            --num_functions; 
            continue;
        }
    }

    return functions;
}
```
