    private readonly XmlSchemaSet _xmlSchemaSet;
    private readonly MemoryCache _cache = new(new MemoryCacheOptions());

    public DynamicXmlManager(IExternalDataSource externalDataSource, XmlSchemaSet xmlSchemaSet)
    {
