        _xmlSchemaSet = xmlSchemaSet ?? throw new ArgumentNullException(nameof(xmlSchemaSet));
    }

    public async Task<XmlDocument> ParseAndCacheAsync(string uri)
    {
        var stopwatch = Stopwatch.StartNew();

        if (!_cache.TryGetValue(uri, out XmlDocument xmlDoc))
        {
            xmlDoc = await _externalDataSource.LoadXmlFromExternalApiAsync(uri);

            var validationResult = ValidateAgainstSchemaSet(xmlDoc);
            Console.WriteLine($"Validation result: {validationResult}");

            if (validationResult)
