            }
        }

        stopwatch.Stop();
        Console.WriteLine($"Execution time: {stopwatch.ElapsedMilliseconds} ms");

        return xmlDoc;
    }

    private bool ValidateAgainstSchemaSet(XmlDocument doc) => doc.Schemas.Count == 0 || _xmlSchemaSet.IsValid(doc, null);
}
