```javascript
const fs = require('fs');

function processFile(filePath, chunkSize) {
  const readStream = fs.createReadStream(filePath);

  let chunkCount = 0;
  let chunks = [];

  readStream.on('data', (chunk) => {
    if (chunk.length >= chunkSize) {
      const workerResult = loadModule(modulePath, chunk);

      if (!workerResult) return;

      chunks[chunkCount++] = workerResult;
    } else {
      console.error('Failed to process file: Chunk is too small');
    }
  });

  readStream.on('end', () => {
    console.log(`Successfully processed ${chunkCount} chunks of the file`);
  });
}
```

