```CSharp
using System;
using System.Xml;
using System.Xml.Schema;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class XmlManager
{
    private readonly ILogger<XmlManager> _logger;
    private readonly string _schemaPath;
    private static Dictionary<string, Tuple<int, XmlDocument>> _cache = new Dictionary<string, Tuple<int, XmlDocument>>();
    private static object _locker = new object();

    public XmlManager(ILogger<XmlManager> logger, string schemaPath)
    {
        _logger = logger;
        _schemaPath = schemaPath;
    }

    public async Task<XmlDocument> GetAsync(string url, int version)
    {
        if (_cache.TryGetValue(url, out var cachedData) && cachedData.Item1 == version)
        {
            return cachedData.Item2; // Cache hit
        }

        _logger.LogInformation("Cache miss for URL: " + url);

        XmlDocument doc = await LoadXmlAsync(url);
        ValidateSchema(doc, _schemaPath);

        lock (_locker)
        {
            if (!_cache.ContainsKey(url))
                _cache[url] = Tuple.Create(version, doc); // Cache miss
        }

        return doc;
    }

    private async Task<XmlDocument> LoadXmlAsync(string url)
    {
        using (var client = new HttpClient())
        {
            var response = await client.GetStringAsync(url);
            var doc = new XmlDocument();
            doc.LoadXml(response);

            return doc;
        }
    }

    private void ValidateSchema(XmlDocument doc, string schemaPath)
    {
        doc.Schemas.Add(_schemaPath, null); // Add schema for validation

        // Run validation
        doc.Validate((sender, e) => throw new Exception("Invalid XML data"));
    }
}
```
Remember to install `Microsoft.Extensions.Logging` and `System.Net.Http` namespaces for this solution to work correctly. 

