public class HashCalculator {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final MessageDigest md5Digester;
    private Map<String, String> cachedHashes = new ConcurrentHashMap<>();

    public HashCalculator() throws Exception{
        this.md5Digester = MessageDigest.getInstance("MD5");
    }

    public void calculate(List<Path> paths) {
        List<Future<String>> futures = new ArrayList<>();
        for (Path path : paths) {
            Future<String> future = executor.submit(() -> {
                String hash = cachedHashes.getOrDefault(path.toString(), calculateHash(path));
                if (!hash.equals(callApiServiceAndGetHash(path))) {
                    throw new HashMismatchException("File " + path + " hash mismatches");
                }
                return path.toString() + ": " + hash;
            });
