Here is an implementation of `execute_module_tests` based on your requirements using the Python's asyncio library:

```python
import importlib
import logging
from concurrent.futures import ThreadPoolExecutor
import time
from functools import partial, wraps
import os

# Define a decorator for timing functions
def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        logging.info(f"Function {func.__name__} took {end - start} seconds")
        if (end - start) > 5: # consider as slow if it takes more than 5 secs
            logging.warning(f"Function {func.__name__} is slow. Took {end - start} seconds")
        return result
    return wrapper

# Define a decorator for retrying functions in case of failure
def retry_on_failure(max_retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            retries = 0
            while retries < max_retries:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    logging.error(f"Error in function {func.__name__}: {e}. Retrying...")
                    retries += 1
            raise Exception(f"Function {func.__name__} failed after {max_retries} attempts")
        return wrapper
    return decorator

# Apply the timing and retry decorators to all functions in a module
def apply_decorators(module):
    for attr_name in dir(module):
        if callable(getattr(module, attr_name)):
            setattr(module, attr_name, timer(retry_on_failure()(getattr(module, attr_name))))

def execute_module_tests(module_name, test_functions, resource_limits, external_services):
    # Dynamically import the specified module using importlib.import_module
    module = importlib.import_module(module_name)

    # Apply timing and retry decorators to all functions in the module
    apply_decorators(module)

    # Use a ThreadPoolExecutor for concurrent execution of tests
    with ThreadPoolExecutor(max_workers=resource_limits.get('cpu_cores', os.cpu_count())) as executor:
        for test in test_functions:
            logging.info(f"Starting test {test.__name__}")

            # Submit each test function to the ThreadPoolExecutor and store the future objects
            futures = [executor.submit(partial(getattr(module, test), external_services=external_services)) for _ in range(resource_limits['concurrent_tests'])]

            # Wait for all tests to complete
            for future in futures:
                try:
                    result = future.result() # This will raise an exception if the function failed
                    logging.info(f"Test {test.__name__} completed successfully with result: {result}")
                except Exception as e:
                    logging.error(f"Error in test {test.__name__}: {e}")

    logging.info("All tests completed")
```
This implementation uses the `concurrent.futures` module for concurrency and `functools` for function decorators to add timing and retry functionality to all functions in a module. It also logs detailed information about test execution, including start times, end times, errors, slow tests, and overall completion of all tests.

