static int messageCount = 0;
static FILE *logFile = NULL;
static const char *configFilePath = "/path/to/config.txt";  // Path to your config file.

typedef struct {
    const char *fileNameFormat;
    size_t maxMessageCount;
    int loggingLevelThreshold;
} Config;

Config readConfig() {
    Config config = {"log-%Y%m%d%H%M%S.txt", 1000, 2};  // Default values if config file not found or in error.

    FILE *configFile = fopen(configFilePath, "r");
    if (configFile == NULL) {
        printf("Failed to open configuration file. Using default settings.\n");
        return config;
    }

    // Read the format and other settings from your config file here.
    // If error encountered while reading, revert back to defaults.

    fclose(configFile);
    return config;
}

void logCondition(const char *level, const char *messageFormat, ...) {
    pthread_mutex_lock(&lock);  // Enter critical section.

    static Config config = readConfig();

    if (logFile == NULL || messageCount >= config.maxMessageCount) {
        if (logFile != NULL) {
            fclose(logFile);
        }

        time_t now = time(NULL);
        char fileName[256];
        strftime(fileName, sizeof(fileName), config.fileNameFormat, localtime(&now));

        logFile = fopen(fileName, "w");  // Open new or existing log file for writing.
        if (logFile == NULL) {
            printf("Failed to open/create log file.\n");
            pthread_mutex_unlock(&lock);  // Leave critical section.
            return;
        }

        messageCount = 0;
    }

    int levelIndex = -1;
    for (size_t i = 0; i < sizeof(levels) / sizeof(*levels); ++i) {
        if (strcmp(level, levels[i]) == 0) {
            levelIndex = i;
            break;
        }
    }

    if (levelIndex < 0 || levelIndex > config.loggingLevelThreshold) {
        pthread_mutex_unlock(&lock);  // Leave critical section.
        return;
    }

    va_list args;
    va_start(args, messageFormat);

    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), messageFormat, args);

    fprintf(logFile, "[%s] %s\n", level, buffer);  // Write to log file.
    fflush(logFile);  // Flush immediately for real-time logging.

    va_end(args);

    ++messageCount;
    pthread_mutex_unlock(&lock);  // Leave critical section.
}
```

