```cpp
#include <fstream>
#include "rapidjson/document.h"
#include "rapidjson/istreamwrapper.h"
#include <unordered_map>
#include <variant>
#include <stdexcept>

std::unordered_map<std::string, std::variant<int, double, std::string, bool>> loadConfig(const std::string &path) {
    // Open file and create IStreamWrapper for rapidjson to read from it
    std::ifstream ifs(path);
    if(!ifs.is_open()){
        throw std::runtime_error("Could not open the JSON configuration file.");
    }
    rapidjson::IStreamWrapper isw(ifs);

    // Parse the JSON document
    rapidjson::Document d;
    d.ParseStream<rapidjson::kParseNoFlags>(isw);

    if (d.HasParseError()) {
        throw std::runtime_error("Failed to parse JSON configuration.");
    }

    // Create and fill the unordered map from the parsed document
    std::unordered_map<std::string, std::variant<int, double, std::string, bool>> config;
    for (auto itr = d.MemberBegin(); itr != d.MemberEnd(); ++itr) {
        if(itr->value.IsInt()) {
            config[itr->name.GetString()] = itr->value.GetInt();
        } else if (itr->value.IsDouble()) {
            config[itr->name.GetString()] = itr->value.GetDouble();
        } else if(itr->value.IsBool()) {
            config[itr->name.GetString()] = itr->value.GetBool();
        } else if (itr->value.IsString()) {
            config[itr->name.GetString()] = itr->value.GetString();
        }
    }

    return config;
}
```
This function will read a JSON file and parse its content into an unordered map with std::variant types for values, which can be either integer, double, string or bool. It uses rapidjson to efficiently read the file and parse it, minimizing memory usage. If there is any error during parsing (file not found, bad JSON format), a runtime_error exception will be thrown.

