import java.util.Base64;

public class ByteArrayToRandomString {
    // load character set from external data source
    private String charSet = "...";  

    public String convert(byte[] array, int length) throws IOException, ClassNotFoundException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(array); 
             ObjectInputStream in = new ObjectInputStream(bais)) {
            // deserialize object from byte array
            Object obj = in.readObject();

            // generate random string based on the deserialized object
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = md.digest(charSet.getBytes());
            return Base64.getEncoder().encodeToString(hashBytes).substring(0, length);
        } 
    }
}
