typedef struct {
    int key_length;
    char* hash_algorithm;
} ConfigFile;

ConfigFile config_file; // Load from external configuration file
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
EVP_CIPHER_CTX *ctx; 

void load_config() {
    /* Load configurations from the file */
}

int initialize_cipher(char* password) {
    // Locking to ensure thread safety
    pthread_mutex_lock(&lock);

    int key_length = config_file.key_length; // Get from configuration file 
    char* hash_algorithm = config_file.hash_algorithm;

    unsigned char *hashed_password = malloc(SHA256_DIGEST_LENGTH); // Assuming SHA-256 as the hashing algorithm
    unsigned char *key = malloc(key_length/8); // Key length in bytes 
    unsigned char *iv = malloc(config_file.key_length/8); // IV length will be same as key length

    if (!hashed_password || !key || !iv) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Compute the hash of the password
    SHA256(password, strlen(password), hashed_password); 

    /* Split the hashed password into key and IV depending on their lengths */
    memcpy(key, hashed_password, key_length/8); // Copy first part of the hash to key
    memcpy(iv, hashed_password + (key_length/8), config_file.key_length/8); // Next part is IV 

    /* Initialize cipher */
    ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) <= 0) {
        pthread_mutex_unlock(&lock);
        return -1;  // Error handling for cryptographic operations
    }

    free(hashed_password);
    pthread_mutex_unlock(&lock);
    return 0;  // Cipher initialization successful
}

void cleanup_cipher() {
    /* Clean up and disable cipher */
    EVP_CIPHER_CTX_cleanup(ctx);
    EVP_CIPHER_CTX_free(ctx);
    pthread_mutex_unlock(&lock); // Unlock the mutex 
}
