```python
import random
import string
import networkx as nx
from sqlite3 import connect, Error, OperationalError

class GraphDatabase:
    def __init__(self):
        self.db_conn = None
        try:
            self.db_conn = connect('propertyStore.sqlite') # assuming a local SQLite db file for the property store
            print("Connected to Property Store successfully")
        except Error as e:
            print(f"Error connecting to property store: {str(e)}")

    def close(self):
        if self.db_conn is not None:
            self.db_conn.close()

    def add_random_vertices_and_edges(self, graph, num_vertices=10, num_edges=20):
        try:
            for i in range(num_vertices):
                vertex = ''.join(random.choice(string.ascii_uppercase + string.digits) for _ in range(5)) # generating random string as a vertex name
                graph.add_node(vertex, prop=random.randint(0,100)) # setting a property on the vertex with a random value between 0 and 100
            edges = [frozenset({''.join(random.choice(string.ascii_uppercase + string.digits) for _ in range(5)), 
                                ''.join(random.choice(string.ascii_uppercase + string.digits) for _ in range(5))}) # generating a random edge as a pair of vertices
                     for j in range(num_edges)]
            graph.add_edges_from(edges, prop=random.randint(0,100)) # setting a property on the edge with a random value between 0 and 100
        except OperationalError as e:
            print(f"Failed to add vertices or edges due to an error in Property Store: {str(e)}")

    def persist_properties(self, graph):
        if self.db_conn is None:
            print("Property store not connected. Skipping property persistence.")
            return

        cursor = self.db_conn.cursor()
        for node in graph.nodes:
            try:
                cursor.execute('INSERT INTO nodes (name, prop) VALUES (?, ?)', 
                               (node, graph.nodes[node]['prop'])) # assuming a 'nodes' table with columns: name and prop
            except Error as e:
                print(f"Error persisting node property to database: {str(e)}")
        for edge in graph.edges:
            try:
                cursor.execute('INSERT INTO edges (node1, node2, prop) VALUES (?, ?, ?)', 
                               (edge[0], edge[1], graph.edges[edge]['prop'])) # assuming an 'edges' table with columns: node1, node2 and prop
            except Error as e:
                print(f"Error persisting edge property to database: {str(e)}")
        self.db_conn.commit()

if __name__ == "__main__":
    db = GraphDatabase()
    graph = nx.Graph() # creating a new empty graph object
    db.add_random_vertices_and_edges(graph)
    db.persist_properties(graph)
    db.close()
```
