```javascript
// Define cache object
const scriptCache = {};

// Script fetching function
async function fetchScript(scriptObject) {
    const { src, type } = scriptObject;

    // Check if script is already cached
    if (scriptCache[src]) return scriptCache[src];

    try {
        const response = await fetch(src);

        // Validate status code and content type of the response
        if (!response.ok || !response.headers.get('content-type').includes(type)) throw new Error("Invalid script source or type");

        const code = await response.text();
        return (scriptCache[src] = { src, type, code });
    } catch (error) {
        console.log(`Failed to fetch the script: ${error}`);
        return null;
    }
}

// Function for rendering scripts
async function renderScripts(scripts) {
    const footer = document.querySelector('footer');

    // Remove existing scripts
    while (footer.firstChild) {
        footer.removeChild(footer.lastChild);
    }

    scripts.forEach(async scriptObject => {
        const cachedScript = await fetchScript(scriptObject);

        if (!cachedScript) return;

        // Create new script element
        const scriptElement = document.createElement('script');
        scriptElement.type = cachedScript.type;
        scriptElement.textContent = cachedScript.code;

        // Add the script to footer
        footer.appendChild(scriptElement);
    });
}
```

