```python
import psycopg2
import logging
from sqlalchemy import create_engine, text

class DatabaseConnectionManager:
    def __init__(self):
        self._connections = []
        self._max_pool_size = 10
        self.logging = logging.getLogger(__name__)

    def establish_connection(self, db_type, db_config):
        try:
            if len(self._connections) >= self._max_pool_size:
                raise Exception('Connection pool is full')

            if db_type.lower() == 'postgres':
                conn = psycopg2.connect(**db_config)
                self._connections.append(conn)
            elif db_type.lower() in ['mysql', 'sqlite']:
                engine = create_engine(f"{db_type}://{db_config['user']}:{db_config['password']}@{db_config['host']}/{db_config['database']}")
                self._connections.append(engine)
            else:
                raise Exception('Unsupported database type')
        except Exception as e:
            self.logging.error(f"Connection establishment failed due to: {str(e)}")

    def execute_query(self, query, params=None):
        try:
            if len(self._connections) == 0:
                raise Exception('No active connections')

            conn = self._connections[-1]  # Use the latest connection

            if isinstance(conn, psycopg2.extensions.connection):
                cur = conn.cursor()
                cur.execute(query, params)
                results = cur.fetchall()
                cur.close()
            elif str(type(conn)) == "<class 'sqlalchemy.engine.base.Engine'>":
                result_proxy = conn.execute(text(query), **params) if params else conn.execute(text(query))
                results = [dict(row) for row in result_proxy]
            return results
        except Exception as e:
            self.logging.error(f"Query execution failed due to: {str(e)}")

    def start_transaction(self):
        try:
            conn = self._connections[-1]  # Use the latest connection

            if isinstance(conn, psycopg2.extensions.connection):
                cur = conn.cursor()
                cur.execute('BEGIN')
            elif str(type(conn)) == "<class 'sqlalchemy.engine.base.Engine'>":
                raise Exception('Transactions are not supported with SQLAlchemy backend')
        except Exception as e:
            self.logging.error(f"Transaction start failed due to: {str(e)}")

    def commit_transaction(self):
        try:
            conn = self._connections[-1]  # Use the latest connection

            if isinstance(conn, psycopg2.extensions.connection):
                cur = conn.cursor()
                cur.execute('COMMIT')
            elif str(type(conn)) == "<class 'sqlalchemy.engine.base.Engine'>":
                raise Exception('Transactions are not supported with SQLAlchemy backend')
        except Exception as e:
            self.logging.error(f"Transaction commit failed due to: {str(e)}")

    def rollback_transaction(self):
        try:
            conn = self._connections[-1]  # Use the latest connection

            if isinstance(conn, psycopg2.extensions.connection):
                cur = conn.cursor()
                cur.execute('ROLLBACK')
            elif str(type(conn)) == "<class 'sqlalchemy.engine.base.Engine'>":
                raise Exception('Transactions are not supported with SQLAlchemy backend')
        except Exception as e:
            self.logging.error(f"Transaction rollback failed due to: {str(e)}")

    def get_pool_size(self):
        return len(self._connections)

    def set_pool_size(self, size):
        self._max_pool_size = size
``` 

Note: This implementation currently supports PostgreSQL and SQLAlchemy which includes MySQL and SQLite. Transactions are supported for PostgreSQL only. For other databases like MongoDB or Cassandra you may need to use different libraries that support these features.

