Here's an example implementation using the OpenSSL library:

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
} AES256_GCM_Context;

AES256_GCM_Context* initialize_cipher(const char* password, int iv_length, int tag_length) {
    assert(password != NULL && strlen(password) > 0);  // Ensure valid password.

    AES256_GCM_Context* context = (AES256_GCM_Context*)malloc(sizeof(AES256_GCM_Context));
    if(!context) {
        return NULL;
    }

    // Initialize the encryption context.
    context->ctx = EVP_CIPHER_CTX_new();
    if(!context->ctx) {
        free(context);
        return NULL;
    }

    int rc;

    // Derive a key from the password using SHA-256.
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    if(!EVP_BytesToKey(EVP_aes_256_gcm(), EVP_sha256(), (unsigned char*)password, strlen(password), 1, key, iv)) {
        goto error;
    }

    // Set the encryption algorithm.
    rc = EVP_EncryptInit_ex(context->ctx, EVP_aes_256_gcm(), NULL, key, iv);
    if(rc != 1) {
        goto error;
    }

    // Set the IV length.
    rc = EVP_CIPHER_CTX_ctrl(context->ctx, EVP_CTRL_GCM_SET_IVLEN, iv_length, NULL);
    if(rc != 1) {
        goto error;
    }

    // Set the tag length.
    rc = EVP_CIPHER_CTX_ctrl(context->ctx, EVP_CTRL_GCM_SET_TAG, tag_length, NULL);
    if(rc != 1) {
        goto error;
    }

    return context;

error:
    // Clean up and disable the cipher.
    EVP_CIPHER_CTX_free(context->ctx);
    free(context);
    return NULL;
}

void cleanup_cipher(AES256_GCM_Context* context) {
    if(!context) {
        return;
    }

    // Clean up and disable the cipher.
    EVP_CIPHER_CTX_free(context->ctx);
    free(context);
}
```
In this code, you can initialize an AES256_GCM_Context using `initialize_cipher` with a password string and the IV and tag lengths. Afterwards, you can clean up resources associated with the context with `cleanup_cipher`. Note that the actual encryption and decryption of data is not implemented here due to the complexity involved in providing generic code without specifics about how this function will be used.

